  public init(
    cli: Org2CLI? = nil,
    defaults: UserDefaults = .standard,
    openClawTranscriptURL: URL? = nil,
    openClawFallbackTranscriptURL: URL? = nil,
    openClawSendHandler: (@Sendable ([OpenClawChatMessage], String, String, OpenClawWorkspaceContext?) async throws -> String)? = nil,
    openClawRecoveryHandler: (@Sendable (OpenClawPendingTurn, String) async throws -> String)? = nil,
    codexSendHandlerForTesting: (@Sendable ([OpenClawChatMessage], UUID, OpenClawWorkspaceContext) async throws -> String)? = nil,
    claudeSendHandlerForTesting: (@Sendable ([OpenClawChatMessage], UUID, OpenClawWorkspaceContext) async throws -> ClaudeCodeTurnResult)? = nil,
    legacyDefaultsDomains: [String]? = nil
  ) {
    self.defaults = defaults
    sourceScheduleStateStore = WorkspaceSourceScheduleStateStore(defaults: defaults)
    mountedCorpora = Self.shouldIgnoreStandardDefaultsForTests(defaults)
      ? []
      : Self.restoreCorpusMounts(from: defaults, key: corpusMountsKey)
    let fallbackTranscriptURL = openClawFallbackTranscriptURL ?? Self.defaultOpenClawTranscriptURL()
    usesFixedOpenClawTranscriptURL = openClawTranscriptURL != nil
    appOpenClawTranscriptURL = fallbackTranscriptURL
    self.openClawTranscriptURL = openClawTranscriptURL ?? fallbackTranscriptURL
    self.openClawSendHandler = openClawSendHandler
    self.openClawRecoveryHandler = openClawRecoveryHandler
    self.codexSendHandlerForTesting = codexSendHandlerForTesting
    self.claudeSendHandlerForTesting = claudeSendHandlerForTesting
    self.cli = cli
      ?? (try? Org2CLI(repoRoot: Org2CLI.defaultRepoRoot()))
      ?? Org2CLI(repoRoot: URL(fileURLWithPath: FileManager.default.currentDirectoryPath))
    let settings = OpenClawGatewaySettings.resolve()
    let migrationDomains = legacyDefaultsDomains
      ?? (
        defaults === UserDefaults.standard
          && !Self.shouldIgnoreStandardDefaultsForTests(defaults)
          && Self.shouldMigrateLegacyDefaultsForCurrentBundle()
          ? Self.legacyDefaultsDomains
          : []
      )
    migrateLegacyDefaultsIfNeeded(
      legacyDomains: migrationDomains,
      defaultOpenClawEndpoint: settings.endpoint.absoluteString
    )
    agendaMode = Self.shouldIgnoreStandardDefaultsForTests(defaults)
      ? .focus
      : Self.restoreAgendaMode(from: defaults, key: agendaModeKey)
    agendaOverdueOrder = defaults.string(forKey: agendaOverdueOrderKey)
      .flatMap(AgendaOverdueOrder.init(rawValue:)) ?? .priority
    openClawEndpointText = defaults.string(forKey: openClawEndpointKey) ?? settings.endpoint.absoluteString
    openClawAgentID = defaults.string(forKey: openClawAgentKey) ?? "main"
    agentHandoffAssignee = defaults.string(forKey: agentHandoffAssigneeKey) ?? Self.defaultAgentHandoffAssignee
    personalAssigneeNamesText = defaults.string(forKey: personalAssigneeNamesKey) ?? ""
    openClawRemoteCorpusPath = defaults.string(forKey: openClawRemoteCorpusPathKey) ?? ""
    aiChatCorpusAccessScope = defaults.string(forKey: aiChatCorpusAccessScopeKey)
      .flatMap(WorkspaceReadScope.init(rawValue:)) ?? .activeCorpus
    aiChatCustomInstructions = defaults.string(forKey: aiChatCustomInstructionsKey) ?? ""
    aiChatDestinations = Self.restoreAIChatDestinations(
      from: defaults,
      key: aiChatDestinationsKey
    )
    codexSandboxAccess = defaults.string(forKey: codexSandboxAccessKey)
      .flatMap(CodexSandboxAccess.init(rawValue:)) ?? .workspaceWrite
    aiChatMessageSound = defaults.string(forKey: aiChatMessageSoundKey)
      .flatMap(AIChatMessageSound.init(rawValue:)) ?? .org2
    openClawIncomingMessageSoundPlayer = Self.messageSoundPlayer(for: aiChatMessageSound)
    appearanceMode = defaults.string(forKey: appearanceModeKey)
      .flatMap(WorkspaceAppearanceMode.init(rawValue:)) ?? .system
    openClawBriefsStartNewThread = defaults.object(forKey: openClawBriefsStartNewThreadKey) as? Bool ?? true
    openClawLocalEditsEnabled = defaults.bool(forKey: openClawLocalEditsEnabledKey)
    renderedDocumentWidth = defaults.string(forKey: renderedDocumentWidthKey)
      .flatMap(RenderedDocumentWidth.init(rawValue:)) ?? .comfortable
    renderedDocumentMargin = defaults.string(forKey: renderedDocumentMarginKey)
      .flatMap(RenderedDocumentMargin.init(rawValue:)) ?? .standard
    meetingTranscriptionProvider = defaults.string(forKey: meetingTranscriptionProviderKey)
      .flatMap(MeetingTranscriptionProvider.init(rawValue:)) ?? .automatic
    fluidVoiceEndpointText = defaults.string(forKey: fluidVoiceEndpointKey)
      ?? MeetingTranscriptionConfiguration.defaultFluidVoiceEndpoint
    customTranscriptionCommandText = defaults.string(forKey: customTranscriptionCommandKey) ?? ""
    whisperModelPathText = defaults.string(forKey: whisperModelPathKey) ?? ""
    transcriptionLanguageText = defaults.string(forKey: transcriptionLanguageKey) ?? "en"
    propertyDrawersExpandedByDefault = defaults.object(forKey: propertyDrawersExpandedByDefaultKey) as? Bool ?? true
    formatOrgFilesOnSave = defaults.object(forKey: formatOrgFilesOnSaveKey) as? Bool ?? true
    sourceEditorPresentation = defaults.string(forKey: sourceEditorPresentationKey)
      .flatMap(SourceEditorPresentation.init(rawValue:)) ?? .source
    documentPreviewOverrides = Self.restoreDocumentPreviewOverrides(
      from: defaults,
      key: documentPreviewOverridesKey
    )
    documentViewportSourceLines = Self.restoreDocumentViewportSourceLines(
      from: defaults,
      key: documentViewportSourceLinesKey
    )
    documentSlidePageIndexes = Self.restoreDocumentViewportSourceLines(
      from: defaults,
      key: documentSlidePageIndexesKey,
      minimumValue: 0
    )
    orgCryptEncryptOnSave = defaults.object(forKey: orgCryptEncryptOnSaveKey) as? Bool ?? true
    orgCryptRecipientsText = OrgCryptSettings.listText(defaults.stringArray(forKey: orgCryptRecipientsKey) ?? [])
    orgCryptRecipientFilesText = OrgCryptSettings.listText(defaults.stringArray(forKey: orgCryptRecipientFilesKey) ?? [])
    orgCryptUseDefaultGpgKey = defaults.object(forKey: orgCryptUseDefaultGpgKeyKey) as? Bool ?? true
    if defaults.object(forKey: orgCryptUseDefaultGpgKeyMigrationKey) == nil {
      orgCryptUseDefaultGpgKey = true
      defaults.set(true, forKey: orgCryptUseDefaultGpgKeyKey)
      defaults.set(true, forKey: orgCryptUseDefaultGpgKeyMigrationKey)
    }
    orgCryptGpgProgram = defaults.string(forKey: orgCryptGpgProgramKey) ?? "gpg"
    if usesFixedOpenClawTranscriptURL {
      applyOpenClawTranscript(Self.loadOpenClawTranscript(from: self.openClawTranscriptURL), shouldPersist: false)
    }
    shouldPersistOpenClawMessages = true
    openClawHasStoredToken = OpenClawKeychain.containsToken()
    orgCryptHasStoredPassphrase = OrgCryptKeychain.containsPassphrase()
    scarfMetabaseHasStoredAPIKey = DataSourceCredentialsKeychain.containsScarfMetabaseAPIKey()
    openClawStatusText = Self.openClawStatusText(settings: currentOpenClawSettings())
    restoreInterruptedOpenClawSendStatusIfNeeded()
  }

  public func bootstrap() async {
    await refreshAudioSettingsStatusAsync()
    if corpusRoot == nil {
      if let screenshotCorpusRoot = screenshotCorpusRootFromEnvironment() {
        setCorpusRoot(screenshotCorpusRoot, persistsDefault: false)
      } else {
        if let restoredRoot = restoreCorpusRoot() {
          setCorpusRoot(
            restoredRoot,
            persistsDefault: false,
            openClawMigrationSource: appOpenClawTranscriptURL
          )
        }
      }
    }

    startPendingOpenClawTurnRecovery()
    if openClawLocalEditsEnabled {
      startOpenClawLocalEditNode()
    }

    if corpusRoot != nil {
      if selectedSurface == .home {
        ensureHomeDetailReady()
      }
      await refreshAgenda()
      await refreshMeetings()
      await refreshSourceConnections()
      await refreshCorpusFiles()
      await refreshAssignedWork()
      await refreshRunReviewData()
      refreshOrgCryptManagedRecipientFiles()
      if screenshotModeFromEnvironment() == nil {
        Task { await refreshOpenClawThreads() }
      } else {
        await refreshOpenClawThreads()
        await applyScreenshotModeFromEnvironment()
      }
    } else {
      statusText = "No corpus selected"
    }
  }

  private func screenshotCorpusRootFromEnvironment() -> URL? {
    guard let raw = ProcessInfo.processInfo.environment["ORG2_WORKSPACE_SCREENSHOT_CORPUS"]?
      .trimmingCharacters(in: .whitespacesAndNewlines),
      !raw.isEmpty
    else {
      return nil
    }
    let url = URL(fileURLWithPath: raw).standardizedFileURL
    return isDirectory(url.path) ? url : nil
  }

  private func screenshotModeFromEnvironment() -> String? {
    let raw = ProcessInfo.processInfo.environment["ORG2_WORKSPACE_SCREENSHOT_MODE"]?
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased()
    return raw?.isEmpty == false ? raw : nil
  }

  private func applyScreenshotModeFromEnvironment() async {
    guard let mode = screenshotModeFromEnvironment() else { return }
    let target = ProcessInfo.processInfo.environment["ORG2_WORKSPACE_SCREENSHOT_TARGET"]?
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased()

    switch mode {
    case "home":
      openHome()
    case "agenda":
      selectedSurface = .agenda
      agendaMode = .focus
      if let item = visibleAgendaItems.first(where: { item in
        guard let target, !target.isEmpty else { return false }
        return item.headline.lowercased().contains(target)
      }) ?? visibleAgendaItems.first {
        selectAgendaItem(item)
      }
    case "assigned":
      selectedSurface = .agenda
      agendaMode = .assigned
      if let item = visibleAssignedWorkItems.first(where: { item in
        guard let target, !target.isEmpty else { return true }
        return item.headline.lowercased().contains(target)
          || item.status.lowercased().contains(target)
      }) ?? visibleAssignedWorkItems.first {
        selectAssignedWorkItem(item)
      }
    case "approvals":
      selectedSurface = .approvals
      if let item = visibleApprovalItems.first(where: { item in
        guard let target, !target.isEmpty else { return true }
        return item.title.lowercased().contains(target)
          || item.status.lowercased().contains(target)
          || item.file.lowercased().contains(target)
      }) ?? visibleApprovalItems.first {
        selectApprovalItem(item)
      }
    case "review":
      selectedSurface = .approvals
      runsAndReviewPage = .review
      if let item = visibleApprovalItems.first(where: { item in
        guard let target, !target.isEmpty else { return true }
        return item.title.lowercased().contains(target)
          || item.status.lowercased().contains(target)
          || item.file.lowercased().contains(target)
      }) ?? visibleApprovalItems.first {
        selectApprovalItem(item)
      }
    case "workflows":
      selectedSurface = .approvals
      runsAndReviewPage = .workflows
      if let workflow = agentWorkflows.first(where: { workflow in
        guard let target, !target.isEmpty else { return true }
        return workflow.title.lowercased().contains(target)
          || workflow.file.lowercased().contains(target)
      }) ?? agentWorkflows.first {
        selectAgentWorkflow(workflow)
      }
    case "goals":
      selectedSurface = .approvals
      runsAndReviewPage = .goals
      if let goal = agentGoals.first(where: { goal in
        guard let target, !target.isEmpty else { return true }
        return goal.title.lowercased().contains(target)
          || goal.id.lowercased().contains(target)
      }) ?? agentGoals.first {
        selectAgentGoal(goal)
      }
    case "agents":
      selectedSurface = .approvals
      runsAndReviewPage = .agents
      if let profile = agentProfiles.first(where: { profile in
        guard let target, !target.isEmpty else { return true }
        return profile.name.lowercased().contains(target)
          || profile.id.lowercased().contains(target)
      }) ?? agentProfiles.first {
        selectAgentProfile(profile)
      }
    case "search":
      selectedSurface = .search
      searchQuery = target ?? ""
      if !searchQuery.isEmpty {
        await runSearch()
      }
    case "ai-room":
      expandSurface(.openClaw)
      openClawStatusText = "Ready for an @mention or thread post"
    case "openclaw", "chat":
      selectedSurface = .openClaw
      publishOpenClawComposerDraft("Summarize the current launch plan and call out open risks.")
    case "brief":
      selectedSurface = .files
      if let thread = openClawThreads.first(where: { thread in
        guard let target, !target.isEmpty else {
          return thread.title.lowercased().contains("brief")
        }
        return thread.title.lowercased().contains(target)
      }) ?? openClawThreads.first {
        openOpenClawThread(thread, surface: .files, mode: .page)
      }
    case "meetings":
      selectedSurface = .meetings
      if let meeting = meetings.first(where: { meeting in
        guard let target, !target.isEmpty else { return true }
        return meeting.title.lowercased().contains(target)
      }) {
        selectMeeting(meeting)
      }
    case "sources":
      selectedSurface = .sources
    case "files":
      selectedSurface = .files
      if let file = filteredCorpusFiles.first(where: { file in
        guard let target, !target.isEmpty else { return true }
        return file.relativePath.lowercased().contains(target)
          || file.name.lowercased().contains(target)
      }) {
        selectCorpusFile(file)
      }
    default:
      openHome()
    }

    if let selectedLocation {
      await loadEntrySource(for: selectedLocation)
    }
  }

  public func chooseCorpus() {
    let panel = NSOpenPanel()
    panel.canChooseFiles = false
    panel.canChooseDirectories = true
    panel.allowsMultipleSelection = false
    panel.prompt = "Open"
    panel.message = "Choose an Org2 corpus directory"

    if panel.runModal() == .OK, let url = panel.url {
      setCorpusRoot(url)
      Task {
        await refreshWorkspace()
        presentLaunchGuideIfNeeded()
      }
    }
  }

  public func presentLaunchGuide() {
    isLaunchGuidePresented = true
  }

  public func dismissLaunchGuide() {
    isLaunchGuidePresented = false
  }

  public func completeLaunchGuide() {
    defaults.set(true, forKey: launchGuideCompletedKey)
    isLaunchGuidePresented = false
  }

  public func launchGuideCaptureItem() {
    isLaunchGuidePresented = false
    Task { @MainActor in
      await Task.yield()
      isCapturePanelPresented = true
    }
  }

  public func launchGuideOpenAgenda() {
    isLaunchGuidePresented = false
    selectedSurface = .agenda
  }

  public func launchGuideAskAgent() {
    isLaunchGuidePresented = false
    makeSurfacePrimary(.openClaw)
  }

  public func launchGuideOpenAgentWork() {
    isLaunchGuidePresented = false
    runsAndReviewPage = .review
    selectedSurface = .approvals
  }

  public func launchGuideRevealWorkspace() {
    isLaunchGuidePresented = false
    guard let corpusRoot else { return }
    NSWorkspace.shared.activateFileViewerSelecting([corpusRoot])
  }

  private func presentLaunchGuideIfNeeded() {
    guard !defaults.bool(forKey: launchGuideCompletedKey) else { return }
    isLaunchGuidePresented = true
  }

  public func createCorpus() {
    createCorpus(kind: "personal")
  }

  public func createSharedCorpus() {
    createCorpus(kind: "shared")
  }

  private func createCorpus(kind: String) {
    let panel = NSOpenPanel()
    panel.canChooseFiles = false
    panel.canChooseDirectories = true
    panel.canCreateDirectories = true
    panel.allowsMultipleSelection = false
    panel.prompt = kind == "shared" ? "Create Shared Corpus" : "Create Corpus"
    panel.message = kind == "shared"
      ? "Choose or create an empty folder or repository for the shared Org2 corpus"
      : "Choose or create an empty folder for the new Org2 corpus"

    guard panel.runModal() == .OK, let url = panel.url else { return }

    do {
      let welcomeURL = try Self.initializeStarterCorpus(at: url, kind: kind)
      setCorpusRoot(url)
      selectedSurface = .files
      statusText = "Created starter corpus at \(url.standardizedFileURL.path)"
      Task {
        await refreshWorkspace()
        if let welcome = corpusFiles.filter({ $0.path == welcomeURL.path }).first {
          selectCorpusFile(welcome)
        }
        presentLaunchGuideIfNeeded()
      }
    } catch {
      statusText = error.localizedDescription
      errorText = error.localizedDescription
    }
  }

  nonisolated static func initializeStarterCorpus(at url: URL, kind: String = "personal") throws -> URL {
    let fileManager = FileManager.default
    let root = url.standardizedFileURL
    var isDirectory: ObjCBool = false

    if fileManager.fileExists(atPath: root.path, isDirectory: &isDirectory) {
      guard isDirectory.boolValue else {
        throw StarterCorpusCreationError.notDirectory(root.path)
      }
    } else {
      try fileManager.createDirectory(at: root, withIntermediateDirectories: true)
    }

    let visibleEntries = try fileManager.contentsOfDirectory(
      at: root,
      includingPropertiesForKeys: nil,
      options: [.skipsHiddenFiles]
    )
    guard visibleEntries.isEmpty else {
      throw StarterCorpusCreationError.notEmpty(root.path)
    }

    for directory in ["notes", "daily", "views", "compiled", "workflows"] {
      try fileManager.createDirectory(
        at: root.appendingPathComponent(directory, isDirectory: true),
        withIntermediateDirectories: true
      )
    }

    let name = root.lastPathComponent.isEmpty ? "Org2 Corpus" : root.lastPathComponent
    let normalizedKind = kind == "shared" ? "shared" : kind == "project" ? "project" : "personal"
    let suffix = UUID().uuidString.lowercased().replacingOccurrences(of: "-", with: "").prefix(12)
    let identity = CorpusIdentity(
      schema: "org2:corpus:v1",
      id: "\(normalizedKind)-\(suffix)",
      name: name,
      kind: normalizedKind
    )
    let identityData = try JSONEncoder().encode(identity)
    let identityObject = try JSONSerialization.jsonObject(with: identityData)
    let config: [String: Any] = [
      "corpus": identityObject,
      "agendaFiles": ["inbox.org2", "notes/**/*.org2", "notes/**/*.org", "daily/**/*.org2", "daily/**/*.org"],
      "recursive": true,
      "ignorePatterns": [".git/**", ".#*", "compiled/**"],
      "roam": ["indexDir": "notes", "nodesDir": "notes", "dailiesDir": "daily"]
    ]
    let configData = try JSONSerialization.data(withJSONObject: config, options: [.prettyPrinted, .sortedKeys])
    try (configData + Data("\n".utf8)).write(to: root.appendingPathComponent("org2.json"), options: .atomic)

    let inbox = """
    #+TITLE: Inbox

    * Inbox

    This optional intake buffer is for importers or sync clients that cannot safely append to an actively edited daily note. Mac capture appends to today's daily note.
    """
    try (inbox + "\n").write(
      to: root.appendingPathComponent("inbox.org2"),
      atomically: true,
      encoding: .utf8
    )

    let welcomeURL = root.appendingPathComponent("notes/welcome.org2")
    let welcome = """
    #+TITLE: Welcome to OpenOrg

    * Start here

    OpenOrg is a local-first workspace built on the open Org2 format. This folder is an Org2 corpus: its plain-text files are the source of truth, while Agenda, search, graph, agent context, and published views are derived from them.

    * TODO Capture your first real commitment

    Use Capture to add a scheduled task, then open Agenda to see it appear with the context that created it.

    * Five-minute path

    1. Capture one scheduled commitment.
    2. Open Agenda and select it.
    3. Ask a configured agent to perform one bounded task using the local context.
    4. Open Agent Work to inspect citations, output, and anything awaiting approval.
    5. Open this file in another editor to confirm the work remains ordinary text you control.

    * Next steps

    - Open =Help → Getting Started= whenever you want the guided path again.
    - Use Capture to append a note or TODO to today's daily note.
    - Use daily notes for quick capture and =notes/= for durable knowledge.
    - Keep =inbox.org2= as an optional transport/import buffer when a sync client cannot safely append to the active daily note.
    - Put generated, reviewable work in =views/= or =compiled/= before promoting it into canonical notes.
    - Keep reusable processes as editable Org2 files in =workflows/=.
    - Open any file in source mode whenever you want full-fidelity text editing.
    """
    try (welcome + "\n").write(to: welcomeURL, atomically: true, encoding: .utf8)
    return welcomeURL
  }

