    agentRuns = runs
  }

  func replaceExternalThreadsForTesting(_ threads: [ExternalThreadSummary]) {
    externalThreads = threads
  }

  func replaceApprovalItemsForTesting(_ items: [ApprovalItem]) {
    approvalItems = items
