      _ = try await cli.run([
        "agent-profile", "update", profile.id,
        "--status", status,
        "--apply",
        "--dir", corpusRoot.path,
        "--json"
      ])
      await refreshAgentProfiles()
      if let refreshed = agentProfiles.first(where: { $0.id == profile.id }) {
