      errorText = error.localizedDescription
      statusText = "Agent update failed"
    }
  }

  private func selectCoordinationRecord(file path: String) {
    let url = URL(fileURLWithPath: path)
    let file = CorpusFile(
      path: url.path,
      relativePath: relativePath(url.path),
      modifiedAt: (try? url.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate,
      byteCount: (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize.map(Int64.init)
    )
    selectCorpusFile(file, surface: .approvals)
  }

  public func selectAgentWorkflow(_ workflow: AgentWorkflowItem) {
    selectedAgentWorkflowID = workflow.id
    let url = URL(fileURLWithPath: workflow.file)
    let file = CorpusFile(
      path: url.path,
      relativePath: relativePath(url.path),
      modifiedAt: (try? url.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate,
      byteCount: (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize.map(Int64.init)
    )
    selectCorpusFile(file, surface: .approvals)
  }

  public func setAgentWorkflowState(_ workflow: AgentWorkflowItem, state: String) async {
    guard let corpusRoot, ["active", "paused", "draft"].contains(state),
          !mutatingAgentWorkflowIDs.contains(workflow.id) else { return }
    mutatingAgentWorkflowIDs.insert(workflow.id)
    defer { mutatingAgentWorkflowIDs.remove(workflow.id) }
    do {
      let action = state == "active" ? "activate" : state == "paused" ? "pause" : "draft"
      _ = try await cli.run(["workflow", action, workflow.id, "--dir", corpusRoot.path, "--json"])
      await refreshAgentWorkflows()
      do {
        try await syncAgentWorkflowsWithOpenClaw()
        statusText = "\(workflow.title): \(state)"
      } catch {
        statusText = "\(workflow.title): \(state); OpenClaw sync pending"
      }
      if let refreshed = agentWorkflows.first(where: { $0.id == workflow.id }) { selectAgentWorkflow(refreshed) }
    } catch {
      errorText = error.localizedDescription
      statusText = "Workflow update failed"
    }
  }

  public func validateAgentWorkflow(_ workflow: AgentWorkflowItem) async {
    guard let corpusRoot else { return }
    do {
      _ = try await cli.run(["workflow", "validate", workflow.id, "--dir", corpusRoot.path, "--json"])
      statusText = "\(workflow.title) is valid"
    } catch {
      errorText = error.localizedDescription
      statusText = "Workflow validation failed"
    }
  }

  public func setAgentWorkflowSchedule(
    _ workflow: AgentWorkflowItem,
    cron: String,
    timezone: String,
    enabled: Bool
  ) async {
    guard let corpusRoot, !mutatingAgentWorkflowIDs.contains(workflow.id) else { return }
    mutatingAgentWorkflowIDs.insert(workflow.id)
    defer { mutatingAgentWorkflowIDs.remove(workflow.id) }
    do {
      var arguments = ["workflow", "schedule", workflow.id, "--dir", corpusRoot.path, "--json"]
      if enabled {
        arguments += ["--cron", cron.trimmingCharacters(in: .whitespacesAndNewlines)]
        let timezone = timezone.trimmingCharacters(in: .whitespacesAndNewlines)
        if !timezone.isEmpty { arguments += ["--timezone", timezone] }
      } else {
        arguments.append("--disable")
      }
      _ = try await cli.run(arguments)
      await refreshAgentWorkflows()
      do {
        try await syncAgentWorkflowsWithOpenClaw()
        statusText = enabled ? "Scheduled \(workflow.title)" : "Disabled \(workflow.title) schedule"
      } catch {
        statusText = enabled ? "Saved schedule; OpenClaw sync pending" : "Disabled schedule; OpenClaw sync pending"
      }
      if let refreshed = agentWorkflows.first(where: { $0.id == workflow.id }) { selectAgentWorkflow(refreshed) }
    } catch {
      errorText = error.localizedDescription
      statusText = "Workflow schedule failed"
    }
  }

  public func runAgentWorkflow(_ workflow: AgentWorkflowItem, inputs: [String: String]) async {
    guard !mutatingAgentWorkflowIDs.contains(workflow.id) else { return }
    mutatingAgentWorkflowIDs.insert(workflow.id)
    defer { mutatingAgentWorkflowIDs.remove(workflow.id) }
    do {
      let settings = currentOpenClawSettings(allowKeychainRead: true)
      let gateway = OpenClawGatewayClient(settings: settings)
      let prepared = try await gateway.prepareWorkflowRun(
        workflowID: workflow.id,
        inputs: inputs,
        corpusID: activeCorpusIdentity?.id
      )
      let thread = createOpenClawChatThread(
        title: "Workflow: \(workflow.title)",
        statusText: "Starting \(workflow.title)"
      )
      navigateToSurface(.openClaw)
      selectOpenClawChatThread(thread.id)
      let pointer = OpenClawContextPointer(
        kind: "workflow action",
        displayTitle: workflow.title,
        reference: "\(mappedPathForOpenClaw(workflow.file)):1",
        displayReference: "\(workflow.file):1",
        threadTitle: "Workflow: \(workflow.title)"
      )
      await sendOpenClawMessage(
        text: automaticOpenClawActionText(pointer, prompt: prepared.prompt)
      )
      await refreshAgentRuns()
    } catch {
      errorText = error.localizedDescription
      statusText = "Workflow run failed"
    }
  }

  public func syncAgentWorkflowsWithOpenClaw() async throws {
    let gateway = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
    try await gateway.syncWorkflows(corpusID: activeCorpusIdentity?.id)
  }

  public func mutateAgentRun(_ run: AgentRunItem, action: String, reason: String? = nil) async {
    guard let corpusRoot, !mutatingAgentRunIDs.contains(run.id) else { return }
    mutatingAgentRunIDs.insert(run.id)
    defer { mutatingAgentRunIDs.remove(run.id) }
    do {
      var arguments = ["run", action, run.id, "--dir", corpusRoot.path, "--json", "--actor", "Org2Workspace"]
      if let reason, !reason.isEmpty { arguments.append(contentsOf: ["--reason", reason]) }
      let updated: AgentRunItem = try await cli.runJSON(arguments)
      if let index = agentRuns.firstIndex(where: { $0.id == updated.id }) {
        agentRuns[index] = updated
      } else {
        agentRuns.insert(updated, at: 0)
      }
      statusText = "\(updated.goal): \(updated.status)"
    } catch {
      errorText = error.localizedDescription
      statusText = "Run update failed"
    }
  }

  public func completeAgentRun(_ run: AgentRunItem, summary: String) async {
    guard let corpusRoot, run.status == "running", !mutatingAgentRunIDs.contains(run.id) else { return }
    let normalizedSummary = summary.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedSummary.isEmpty else {
      errorText = "Describe what happened before completing this run."
      statusText = "Outcome summary required"
      return
    }
    mutatingAgentRunIDs.insert(run.id)
    defer { mutatingAgentRunIDs.remove(run.id) }
    do {
      let updated: AgentRunItem = try await cli.runJSON([
        "run", "complete", run.id,
        "--summary", normalizedSummary,
        "--actor", "Org2Workspace",
        "--dir", corpusRoot.path,
        "--json"
      ])
      if let index = agentRuns.firstIndex(where: { $0.id == updated.id }) {
        agentRuns[index] = updated
      }
      statusText = "Completed \(updated.goal)"
    } catch {
      errorText = error.localizedDescription
      statusText = "Run completion failed"
    }
  }

  public func completeAgentRunExternally(_ run: AgentRunItem, summary: String) async {
    guard corpusRoot != nil, run.canMarkDoneElsewhere, !mutatingAgentRunIDs.contains(run.id) else { return }
    let normalizedSummary = summary.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedSummary.isEmpty else {
      errorText = "Describe where or how the work was completed."
      statusText = "External completion note required"
      return
    }
    mutatingAgentRunIDs.insert(run.id)
    defer { mutatingAgentRunIDs.remove(run.id) }
    do {
      let updated = try await performAgentRunExternalCompletion(
        runID: run.id,
        summary: normalizedSummary
      )
      recordAgentRunExternalCompletion(updated)
      statusText = "Recorded external completion for \(updated.goal)"
    } catch {
      errorText = error.localizedDescription
      statusText = "External completion failed"
    }
  }

  private func performAgentRunExternalCompletion(
    runID: String,
    summary: String
  ) async throws -> AgentRunItem {
    guard let corpusRoot else {
      throw CocoaError(.fileNoSuchFile, userInfo: [NSLocalizedDescriptionKey: "No corpus is selected."])
    }
    if let agentRunExternalCompletionForTesting {
      return try await agentRunExternalCompletionForTesting(runID, summary)
    }
    return try await cli.runJSON([
      "run", "complete-external", runID,
      "--summary", summary,
      "--actor", "Org2Workspace",
      "--dir", corpusRoot.path,
      "--json"
    ])
  }

  private func recordAgentRunExternalCompletion(_ updated: AgentRunItem) {
    if let index = agentRuns.firstIndex(where: { $0.id == updated.id }) {
      agentRuns[index] = updated
    } else {
      agentRuns.insert(updated, at: 0)
    }
    removeFinishedRunApprovalsFromQueue(updated.id)
    scheduleApprovalsRefresh()
  }

  public func decideAgentRunApproval(
    _ run: AgentRunItem,
    approval: AgentRunApprovalItem,
    decision: String,
    note: String? = nil
  ) async {
    guard corpusRoot != nil else { return }
    let queueItemID = Self.runApprovalQueueItemID(runID: run.id, approvalID: approval.id)
    guard !isApprovalActionInProgress(queueItemID) else { return }
    let actionKind: ApprovalActionKind = decision == "approved" ? .approve : .reject
    beginApprovalAction(queueItemID, kind: actionKind)
    defer { endApprovalAction(queueItemID, kind: actionKind) }
    do {
      try await waitForAgentRunMutationAvailability(run.id)
      defer { mutatingAgentRunIDs.remove(run.id) }
      let updated = try await performAgentRunApprovalDecision(
        runID: run.id,
        approvalID: approval.id,
        fingerprint: approval.fingerprint,
        decision: decision,
        requestedRole: approval.requestedRole,
        requestedFrom: approval.requestedFrom,
        note: note
      )
      if let index = agentRuns.firstIndex(where: { $0.id == updated.id }) {
        agentRuns[index] = updated
      } else {
        agentRuns.insert(updated, at: 0)
      }
      approvalItems.removeAll { $0.id == queueItemID }
      if selectedApprovalItemID == queueItemID {
        selectedApprovalItemID = nil
        approvalSelectionAnchor = nil
      }
      scheduleApprovalsRefresh()
      statusText = "\(approval.title): \(decision) · \(updated.pendingApprovalCount) pending"
      await continueOpenClawAfterApprovalBoundary(updated)
    } catch {
      var errors = approvalActionErrorsByItemID
      errors[queueItemID] = error.localizedDescription
      approvalActionErrorsByItemID = errors
      errorText = error.localizedDescription
      statusText = "Approval update failed"
    }
  }

  public func requestAgentRunChanges(
    _ run: AgentRunItem,
    approval: AgentRunApprovalItem,
    feedback: String
  ) async {
    guard let feedback = Self.normalizedApprovalRevisionFeedback(feedback) else {
      errorText = "Describe what the agent should change."
      statusText = "Revision feedback required"
      return
    }
    await decideAgentRunApproval(run, approval: approval, decision: "revised", note: feedback)
  }

  public func openClawExecApprovalDetails(for run: AgentRunItem) async throws -> OpenClawExecApprovalDetails? {
    guard let approvalID = run.openClawExecApprovalID else { return nil }
    let gateway = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
    return try await gateway.execApprovalDetails(id: approvalID)
  }

  private func approvedRunContinuation(
    for run: AgentRunItem
  ) async throws -> OpenClawApprovedRunContinuation {
    if let agentRunApprovalContinuationForTesting {
      return try await agentRunApprovalContinuationForTesting(run)
    }
    let gateway = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
    do {
      return try await gateway.resumeApprovedRun(
        runID: run.id,
        corpusID: activeCorpusIdentity?.id
      )
    } catch {
      guard Self.shouldUseLocalApprovalContinuationFallback(for: error) else { throw error }
      if run.workflowId != nil {
        let continuation = try await gateway.resumeWorkflowRun(
          runID: run.id,
          corpusID: activeCorpusIdentity?.id
        )
        return OpenClawApprovedRunContinuation(
          runID: continuation.runID,
          sessionKey: continuation.sessionKey,
          prompt: continuation.prompt,
          kind: "workflow"
        )
      }
      if run.isOpenClawExternalDraft {
        let continuation = try await gateway.resumeDraftRun(
          runID: run.id,
          corpusID: activeCorpusIdentity?.id
        )
        return OpenClawApprovedRunContinuation(
          runID: continuation.runID,
          sessionKey: continuation.sessionKey,
          prompt: continuation.prompt,
          kind: "external-draft"
        )
      }
      return OpenClawApprovedRunContinuation(
        runID: run.id,
        sessionKey: run.openClawSessionKey,
        prompt: Self.agentRunApprovalContinuationPrompt(run: run),
        kind: "run"
      )
    }
  }

  private func continueOpenClawAfterApproval(
    _ run: AgentRunItem,
    presentThread: Bool = false
  ) async throws -> Bool {
    let continuation = try await approvedRunContinuation(for: run)
    if continuation.alreadyResumed, continuation.continuationKey == nil { return false }
    if continuation.continuationKey != nil,
       openClawChatThreads.contains(where: { thread in
         openClawMessages(for: thread.id).contains(where: { message in
           message.role == .user
             && OpenClawContextPresentation(message.content).contexts.contains {
               $0.automaticPrompt == continuation.prompt
             }
         })
       }) {
      return false
    }
    let thread: OpenClawChatThread
    if let sessionKey = continuation.sessionKey,
       let existing = openClawChatThreads.first(where: { $0.sessionKey == sessionKey }) {
      if existing.isSettled { reopenOpenClawChatThread(existing.id) }
      thread = openClawChatThreads.first(where: { $0.id == existing.id }) ?? existing
    } else {
      let titlePrefix: String
      let continuationStatus: String
      switch continuation.kind {
      case "workflow":
        titlePrefix = "Workflow"
        continuationStatus = "Continuing approved workflow"
      case "external-draft":
        titlePrefix = "Approved draft"
        continuationStatus = "Sending approved draft"
      default:
        titlePrefix = "Approved run"
        continuationStatus = continuation.sessionKey == nil
          ? "Continuing approved run in a new OpenClaw session"
          : "Continuing approved run"
      }
      thread = createOpenClawChatThread(
        title: "\(titlePrefix): \(run.goal)",
        statusText: continuationStatus,
        sessionKey: continuation.sessionKey ?? Self.approvedRunContinuationSessionKey(
          runID: run.id,
          agentID: openClawAgentID
        )
      )
    }
    if presentThread {
      navigateToSurface(.openClaw)
      selectOpenClawChatThread(thread.id)
    }
    guard let pointer = openClawContextPointer(for: run, requiresExistingRecord: false) else {
      throw CocoaError(.fileReadCorruptFile, userInfo: [
        NSLocalizedDescriptionKey: "The approved run could not be attached to its continuation thread."
      ])
    }
    let actionText = automaticOpenClawActionText(
      pointer,
      prompt: continuation.prompt
    )
    let shouldDrain = enqueueOpenClawMessage(actionText, attachments: [], in: thread.id)
    if shouldDrain { await drainOpenClawSendQueue(for: thread.id) }
    return true
  }

  public func continueApprovedAgentRun(_ run: AgentRunItem) async {
    guard run.canContinueApprovedWork, !mutatingAgentRunIDs.contains(run.id) else { return }
    mutatingAgentRunIDs.insert(run.id)
    defer { mutatingAgentRunIDs.remove(run.id) }
    do {
      let continued = try await continueOpenClawAfterApproval(run, presentThread: true)
      statusText = continued
        ? "Continuing approved work for \(run.goal)"
        : "\(run.goal) is already continuing"
    } catch {
      errorText = error.localizedDescription
      do {
        let blocked = try await recordAgentRunApprovalContinuationFailure(run)
        statusText = "Approved work could not be continued; \(blocked.goal) is blocked"
      } catch {
        statusText = "Approved work could not be continued or durably blocked"
      }
    }
  }

  private func recordAgentRunApprovalContinuationFailure(
    _ run: AgentRunItem
  ) async throws -> AgentRunItem {
    guard let corpusRoot else {
      throw CocoaError(.fileNoSuchFile, userInfo: [NSLocalizedDescriptionKey: "No corpus is selected."])
    }
    let reason = Self.agentRunApprovalContinuationFailureReason
    let updated: AgentRunItem
    if let agentRunApprovalContinuationFailureForTesting {
      updated = try await agentRunApprovalContinuationFailureForTesting(run, reason)
    } else {
      updated = try await cli.runJSON([
        "run", "block", run.id,
        "--reason", reason,
        "--actor", "Org2Workspace",
        "--dir", corpusRoot.path,
        "--json"
      ])
    }
    if let index = agentRuns.firstIndex(where: { $0.id == updated.id }) {
      agentRuns[index] = updated
    } else {
      agentRuns.insert(updated, at: 0)
    }
    scheduleApprovalsRefresh()
    return updated
  }

  private func continueOpenClawWorkflowAfterRevision(
    _ run: AgentRunItem,
    approval: AgentRunApprovalItem
  ) async throws {
    let gateway = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
    let continuation = try await gateway.resumeWorkflowRevision(
      runID: run.id,
      approvalID: approval.id,
      corpusID: activeCorpusIdentity?.id
    )
    let thread: OpenClawChatThread
    if let existing = openClawChatThreads.first(where: { $0.sessionKey == continuation.sessionKey }) {
      if existing.isSettled { reopenOpenClawChatThread(existing.id) }
      thread = openClawChatThreads.first(where: { $0.id == existing.id }) ?? existing
    } else {
      thread = createOpenClawChatThread(
        title: "Workflow: \(run.goal)",
        statusText: "Continuing requested revision",
        sessionKey: continuation.sessionKey
      )
    }
    navigateToSurface(.openClaw)
    selectOpenClawChatThread(thread.id)
    guard let pointer = openClawContextPointer(for: run, requiresExistingRecord: false) else { return }
    let actionText = automaticOpenClawActionText(
      pointer,
      prompt: continuation.prompt
    )
    let shouldDrain = enqueueOpenClawMessage(actionText, attachments: [], in: thread.id)
    if shouldDrain { await drainOpenClawSendQueue(for: thread.id) }
  }

  private func continueOpenClawAfterApprovalBoundary(_ run: AgentRunItem) async {
    if run.status == "running",
       run.pendingApprovalCount == 0,
       run.hasOpenClawApprovalContinuation {
      do {
        let continued = try await continueOpenClawAfterApproval(run)
        statusText = continued
          ? "Review decisions recorded; continued \(run.goal)"
          : "Review decisions recorded; \(run.goal) is already continuing"
      } catch {
        errorText = error.localizedDescription
        do {
          let blocked = try await recordAgentRunApprovalContinuationFailure(run)
          statusText = "Review decisions recorded; \(blocked.goal) is blocked because continuation failed"
        } catch {
          statusText = "Review decisions recorded; continuation failed and the run could not be durably blocked"
        }
      }
      return
    }
    guard run.workflowId != nil else { return }
    guard let revision = run.resumableRevisionApproval else { return }
    do {
      try await continueOpenClawWorkflowAfterRevision(run, approval: revision)
      await refreshAgentRuns()
      statusText = "Changes requested; continuing \(run.goal)"
    } catch {
      errorText = error.localizedDescription
      statusText = "Changes recorded; OpenClaw continuation pending"
    }
  }

  public func saveAgentRunAsWorkflow(_ run: AgentRunItem) async {
    guard let corpusRoot, run.status == "completed", !mutatingAgentRunIDs.contains(run.id) else { return }
    mutatingAgentRunIDs.insert(run.id)
    defer { mutatingAgentRunIDs.remove(run.id) }
    do {
      _ = try await cli.run([
        "workflow", "save", run.id,
        "--id", "workflow-\(run.id)",
        "--dir", corpusRoot.path,
        "--json"
      ])
      await refreshAgentWorkflows()
      if let workflow = agentWorkflows.first(where: { $0.id == "workflow-\(run.id)" }) {
        selectAgentWorkflow(workflow)
      }
      statusText = "Created draft workflow from \(run.goal)"
    } catch {
      errorText = error.localizedDescription
      statusText = "Save as workflow failed"
    }
  }

  public func openAgentRunRecord(_ run: AgentRunItem) {
    guard let corpusRoot else { return }
    let relativePath = ".org2/runs/\(run.id).org2"
    let recordURL = corpusRoot.appendingPathComponent(relativePath)
    guard FileManager.default.fileExists(atPath: recordURL.path) else {
      errorText = "The run record could not be found at \(relativePath)."
      statusText = "Run record missing"
      return
    }
    let values = try? recordURL.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey])
    selectCorpusFile(CorpusFile(
      path: recordURL.path,
      relativePath: relativePath,
      modifiedAt: values?.contentModificationDate,
      byteCount: values?.fileSize.map(Int64.init)
    ), surface: .approvals)
  }

  public func askOpenClawAboutAgentRun(
    _ run: AgentRunItem,
    threadMode: OpenClawThreadMode = .newThread
  ) {
    guard let pointer = openClawContextPointer(for: run, requiresExistingRecord: true) else { return }
    addOpenClawContext(pointer, threadMode: threadMode)
  }

  @discardableResult
  public func respondToAgentRunClarification(_ run: AgentRunItem, response: String) async -> Bool {
    guard let corpusRoot, run.status == "blocked", !mutatingAgentRunIDs.contains(run.id) else { return false }
    guard let response = Self.normalizedAgentRunClarificationResponse(response) else {
      errorText = "Enter a response before resuming this run."
      statusText = "Clarification response required"
      return false
    }

    mutatingAgentRunIDs.insert(run.id)
    defer { mutatingAgentRunIDs.remove(run.id) }
    do {
      let gateway = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
      let continuation: OpenClawRunContinuation
      do {
        continuation = try await gateway.replyAndResumeRun(
          runID: run.id,
          response: response,
          corpusID: activeCorpusIdentity?.id
        )
      } catch {
        guard Self.shouldUseLocalClarificationResumeFallback(for: error) else { throw error }
        let commented: AgentRunItem = try await cli.runJSON([
          "run", "comment", run.id,
          "--author", "Workspace user",
          "--body", response,
          "--dir", corpusRoot.path,
          "--json"
        ])
        let resumed: AgentRunItem = try await cli.runJSON([
          "run", "resume", run.id,
          "--actor", "Org2Workspace",
          "--dir", corpusRoot.path,
          "--json"
        ])
        if let index = agentRuns.firstIndex(where: { $0.id == resumed.id }) {
          agentRuns[index] = resumed
        }
        continuation = OpenClawRunContinuation(
          runID: resumed.id,
          sessionKey: run.openClawSessionKey,
          prompt: Self.agentRunClarificationContinuationPrompt(
            run: commented,
            response: response
          )
        )
      }
      await refreshAgentRuns()

      let thread: OpenClawChatThread
      if let sessionKey = continuation.sessionKey,
         let existing = openClawChatThreads.first(where: { $0.sessionKey == sessionKey }) {
        if existing.isSettled { reopenOpenClawChatThread(existing.id) }
        thread = openClawChatThreads.first(where: { $0.id == existing.id }) ?? existing
      } else {
        thread = createOpenClawChatThread(
          title: "Resume: \(run.goal)",
          statusText: continuation.sessionKey == nil
            ? "Continuing in a new OpenClaw session"
            : "Continuing after clarification",
          sessionKey: continuation.sessionKey
        )
      }
      selectOpenClawChatThread(thread.id)
      guard let pointer = openClawContextPointer(for: run, requiresExistingRecord: false) else {
        statusText = "Run context could not be resolved"
        return false
      }
      let actionText = automaticOpenClawActionText(
        pointer,
        prompt: continuation.prompt,
        userText: response
      )
      let shouldDrain = enqueueOpenClawMessage(actionText, attachments: [], in: thread.id)
      if shouldDrain { await drainOpenClawSendQueue(for: thread.id) }
      statusText = continuation.sessionKey == nil
        ? "Response recorded; continuing \(run.goal) in a new OpenClaw session"
        : "Response recorded and sent; continuing \(run.goal)"
      return true
    } catch {
      errorText = error.localizedDescription
      statusText = "Clarification response failed"
      return false
    }
  }

  nonisolated static func normalizedAgentRunClarificationResponse(_ value: String) -> String? {
    let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
    return normalized.isEmpty ? nil : normalized
  }

  nonisolated static func shouldUseLocalClarificationResumeFallback(for error: Error) -> Bool {
    guard case let OpenClawGatewayError.gateway(code, message) = error else { return false }
    let normalizedCode = (code ?? "").uppercased()
    if normalizedCode.contains("METHOD")
        && (normalizedCode.contains("UNKNOWN")
          || normalizedCode.contains("NOT_FOUND")
          || normalizedCode.contains("UNSUPPORTED")) {
      return true
    }
    let normalizedMessage = message.lowercased()
    if normalizedMessage.contains("missing scope")
        && normalizedMessage.contains("operator.admin") {
      return true
    }
    return normalizedMessage.contains("org2.run.replyandresume")
      && (normalizedMessage.contains("unknown")
        || normalizedMessage.contains("not found")
        || normalizedMessage.contains("not registered")
        || normalizedMessage.contains("unsupported"))
  }

  nonisolated static func shouldUseLocalApprovalContinuationFallback(for error: Error) -> Bool {
    guard case let OpenClawGatewayError.gateway(code, message) = error else { return false }
    let normalizedCode = (code ?? "").uppercased()
    if normalizedCode.contains("METHOD")
        && (normalizedCode.contains("UNKNOWN")
          || normalizedCode.contains("NOT_FOUND")
          || normalizedCode.contains("UNSUPPORTED")) {
      return true
    }
    let normalizedMessage = message.lowercased()
    return normalizedMessage.contains("org2.run.resumeapproved")
      && (normalizedMessage.contains("unknown")
        || normalizedMessage.contains("not found")
        || normalizedMessage.contains("not registered")
        || normalizedMessage.contains("unsupported"))
  }

  nonisolated static func agentRunApprovalContinuationPrompt(run: AgentRunItem) -> String {
    [
      "ORG2_RUN_ID: \(run.id)",
      "ORG2_RUN_RESUME: approval-decided",
      "",
      "Continue the existing Org2 run “\(run.goal)” after every item in its approval boundary was decided.",
      "Re-read the durable run with the Org2 CLI and continue from the first incomplete step. Do not create a replacement run or request the same approval again.",
      "Perform only exact actions whose review material is approved. Skip every rejected or canceled action, and do not substitute a new recipient, payload, command, or attachment.",
      "For provider drafts, resolve the exact authority through `org2 run approval-resolve --decision-key artifact:PROVIDER:TOOL:DRAFT_ID --json` and verify provider state before any retry.",
      "Record external receipts and the final outcome on this durable run, or record the next specific blocker if the work cannot continue."
    ].joined(separator: "\n")
  }

  nonisolated static let agentRunApprovalContinuationFailureReason =
    "Approved actions are recorded, but OpenClaw did not accept the continuation. After restoring the OpenClaw connection, choose Resume and then Continue approved work; do not repeat the approval or create a replacement run."

  nonisolated static func approvedRunContinuationSessionKey(
    runID: String,
    agentID: String
  ) -> String {
    agentScopedOpenClawSessionKey("org2-run:\(runID)", agentID: agentID)
  }

  nonisolated static func agentRunClarificationContinuationPrompt(
    run: AgentRunItem,
    response: String
  ) -> String {
    [
      "ORG2_RUN_ID: \(run.id)",
      "ORG2_RUN_RESUME: clarification-answered",
      "",
      "Continue the existing Org2 run “\(run.goal)” after the user's clarification.",
      "Clarification: \(run.blockedReason ?? "Clarification requested")",
      "User response:",
      response.trimmingCharacters(in: .whitespacesAndNewlines),
      "",
      "Re-read the durable run before acting. The response is already recorded on that run and the run is now running; do not create a replacement run.",
      "If this lifecycle run coordinates a more specific child run carrying the same clarification, record the answer on that child and resume it rather than leaving the underlying work blocked.",
      "Continue from the blocked step, preserve existing context and review boundaries, and update this durable run with the outcome or the next actionable blocker."
    ].joined(separator: "\n")
  }

  public func openAgentRunArtifact(_ artifact: AgentRunArtifactItem) {
    let path = artifact.path.hasPrefix("/")
      ? artifact.path
      : corpusRoot?.appendingPathComponent(artifact.path).path ?? artifact.path
    let url = URL(fileURLWithPath: path).standardizedFileURL
    guard FileManager.default.fileExists(atPath: url.path) else {
      errorText = "The run output could not be found at \(artifact.path)."
      statusText = "Run output missing"
      return
    }
    if artifact.isPDF {
      NSWorkspace.shared.open(url)
      statusText = "Opened \(artifact.displayTitle)"
      return
    }
    let inAppExtensions = Set(["org", "org2", "md", "markdown", "txt"])
    guard inAppExtensions.contains(url.pathExtension.lowercased()) else {
      openFile(path: url.path, line: 1)
      statusText = "Opened \(artifact.displayTitle)"
      return
    }
    let values = try? url.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey])
    selectCorpusFile(CorpusFile(
      path: url.path,
      relativePath: corpusRoot.map { root in
        url.path.replacingOccurrences(of: root.standardizedFileURL.path + "/", with: "")
      } ?? artifact.path,
      modifiedAt: values?.contentModificationDate,
      byteCount: values?.fileSize.map(Int64.init)
    ), surface: .approvals)
  }

  public func openAgentRunContext(_ context: AgentRunContextItem) {
    guard let corpusRoot, let reference = context.fileReference else {
      errorText = "This run context is not a local file reference."
      statusText = "Run context unavailable"
      return
    }
    let url = (reference.hasPrefix("/")
      ? URL(fileURLWithPath: reference)
      : corpusRoot.appendingPathComponent(reference)).standardizedFileURL
    let rootPath = corpusRoot.standardizedFileURL.path
    guard url.path == rootPath || url.path.hasPrefix(rootPath + "/") else {
      errorText = "The run context is outside the active corpus."
      statusText = "Run context unavailable"
      return
    }
    guard FileManager.default.fileExists(atPath: url.path) else {
      errorText = "The run context could not be found at \(reference)."
      statusText = "Run context missing"
      return
    }
    let values = try? url.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey])
    selectCorpusFile(CorpusFile(
      path: url.path,
      relativePath: url.path.replacingOccurrences(of: rootPath + "/", with: ""),
      modifiedAt: values?.contentModificationDate,
      byteCount: values?.fileSize.map(Int64.init)
    ), surface: .approvals)
  }

  private func approvalCandidateSources(
    files: [CorpusFile],
    corpusRoot: URL,
    updatesStatus: Bool
  ) async -> [ApprovalCandidateSource] {
    if updatesStatus {
      statusText = searchIndexTask == nil
        ? "Scanning approval candidates..."
        : "Scanning approvals while search index updates..."
    }

    let scanOperation = approvalCandidateScanOperationForTesting
    return await Task.detached(priority: .utility) {
      scanOperation?()
      if let indexedCandidates = Self.approvalCandidateSourcesFromFreshIndex(
        files: files,
        corpusRoot: corpusRoot
      ) {
        return indexedCandidates
      }
      return Self.approvalCandidateSourcesByScanningFiles(files: files)
    }.value
  }

  nonisolated private static func approvalCandidateSourcesFromFreshIndex(
    files: [CorpusFile],
    corpusRoot: URL
  ) -> [ApprovalCandidateSource]? {
    guard let index = freshWorkspaceSearchIndex(files: files, corpusRoot: corpusRoot) else {
      return nil
    }
    let filesByPath = Dictionary(uniqueKeysWithValues: files.map { ($0.path, $0) })
    var candidates: [ApprovalCandidateSource] = []
    for indexedFile in index.files {
      guard let file = filesByPath[indexedFile.path],
            isApprovalIndexableFile(file)
      else {
        continue
      }
      candidates.append(contentsOf: approvalCandidateSources(
        file: file,
        sourceLines: indexedFile.lines
      ))
    }
    return candidates
  }

  nonisolated private static func approvalCandidateSourcesFromStoredIndex(corpusRoot: URL) -> [ApprovalCandidateSource]? {
    guard let index = storedWorkspaceSearchIndex(corpusRoot: corpusRoot) else {
      return nil
    }
    var candidates: [ApprovalCandidateSource] = []
    for indexedFile in index.files {
      let file = CorpusFile(
        path: indexedFile.path,
        relativePath: indexedFile.relativePath,
        modifiedAt: Date(timeIntervalSince1970: Double(indexedFile.modifiedMs) / 1000),
        byteCount: indexedFile.byteCount
      )
      guard isApprovalIndexableFile(file) else { continue }
      candidates.append(contentsOf: approvalCandidateSources(
        file: file,
        sourceLines: indexedFile.lines
      ))
    }
    return candidates
  }

  nonisolated private static func approvalCandidateSourcesByScanningFiles(files: [CorpusFile]) -> [ApprovalCandidateSource] {
    var candidates: [ApprovalCandidateSource] = []
    for file in files {
      guard isApprovalIndexableFile(file),
            let raw = try? String(contentsOfFile: file.path, encoding: .utf8)
      else {
        continue
      }
      let lines = normalizeLineEndings(raw)
        .split(separator: "\n", omittingEmptySubsequences: false)
        .map(String.init)
      candidates.append(contentsOf: approvalCandidateSources(file: file, sourceLines: lines))
    }
    return candidates
  }

  nonisolated private static func approvalCandidateSources(
    file: CorpusFile,
    sourceLines: [String]
  ) -> [ApprovalCandidateSource] {
    approvalCandidateSourceSlices(sourceLines).map { slice in
      ApprovalCandidateSource(
        file: file,
        sourceText: slice.sourceText,
        parseText: slice.sourceText,
        sourceLineOffset: slice.sourceLineOffset
      )
    }
  }

  nonisolated static func approvalCandidateSourceSlices(
    _ sourceLines: [String]
  ) -> [ApprovalCandidateSourceSlice] {
    var ranges: [Range<Int>] = []
    for index in sourceLines.indices {
      guard let level = approvalHeadingLevel(sourceLines[index]) else { continue }

      let directEnd = firstHeadingIndex(in: sourceLines, after: index) ?? sourceLines.count
      let directText = sourceLines[index..<directEnd].joined(separator: "\n")
      guard approvalCandidateTextMayContainItem(directText) else { continue }

      let subtreeEnd = firstHeadingIndex(in: sourceLines, after: index, maxLevel: level) ?? sourceLines.count
      ranges.append(index..<subtreeEnd)
    }
    guard !ranges.isEmpty else { return [] }

    return mergedApprovalCandidateRanges(ranges).map { range in
      ApprovalCandidateSourceSlice(
        sourceText: sourceLines[range].joined(separator: "\n"),
        sourceLineOffset: range.lowerBound
      )
    }
  }

  nonisolated private static func mergedApprovalCandidateRanges(_ ranges: [Range<Int>]) -> [Range<Int>] {
    let sorted = ranges.sorted { lhs, rhs in
      lhs.lowerBound == rhs.lowerBound
        ? lhs.upperBound < rhs.upperBound
        : lhs.lowerBound < rhs.lowerBound
    }
    var merged: [Range<Int>] = []
    for range in sorted {
      guard let last = merged.last else {
        merged.append(range)
        continue
      }
      if range.lowerBound <= last.upperBound {
        merged[merged.count - 1] = last.lowerBound..<max(last.upperBound, range.upperBound)
      } else {
        merged.append(range)
      }
    }
    return merged
  }

  nonisolated private static func firstHeadingIndex(
    in lines: [String],
    after index: Int,
    maxLevel: Int? = nil
  ) -> Int? {
    guard index + 1 < lines.count else { return nil }
    for candidateIndex in (index + 1)..<lines.count {
      guard let level = approvalHeadingLevel(lines[candidateIndex]) else { continue }
      if let maxLevel {
        if level <= maxLevel {
          return candidateIndex
        }
      } else {
        return candidateIndex
      }
    }
    return nil
  }

  nonisolated private static func approvalHeadingLevel(_ line: String) -> Int? {
    var count = 0
    for character in line {
      if character == "*" {
        count += 1
      } else {
        break
      }
    }
    guard count > 0,
          line.dropFirst(count).first?.isWhitespace == true
    else {
      return nil
    }
    return count
  }

  nonisolated private static func freshWorkspaceSearchIndex(files: [CorpusFile], corpusRoot: URL) -> WorkspaceSearchIndex? {
    let root = corpusRoot.standardizedFileURL
    let indexableFiles = files.filter { isApprovalIndexableFile($0) }
    let indexURL = searchIndexURL(corpusRoot: root)
    guard let data = try? Data(contentsOf: indexURL),
          let index = try? JSONDecoder().decode(WorkspaceSearchIndex.self, from: data),
          index.schema == "org2:search-index:v1",
          index.version == 1,
          URL(fileURLWithPath: index.rootDir).standardizedFileURL.path == root.path,
          index.recursive,
          !index.includeArchives,
          index.files.count == indexableFiles.count
    else {
      return nil
    }

    let expected = Dictionary(uniqueKeysWithValues: indexableFiles.map { ($0.path, $0) })
    for indexedFile in index.files {
      guard let file = expected[indexedFile.path],
            freshSearchIndexMetadataMatches(file: file, indexedFile: indexedFile)
      else {
        return nil
      }
    }
    return index
  }

  nonisolated private static func storedWorkspaceSearchIndex(corpusRoot: URL) -> WorkspaceSearchIndex? {
    let root = corpusRoot.standardizedFileURL
    let indexURL = searchIndexURL(corpusRoot: root)
    guard let data = try? Data(contentsOf: indexURL),
          let index = try? JSONDecoder().decode(WorkspaceSearchIndex.self, from: data),
          index.schema == "org2:search-index:v1",
          index.version == 1,
          URL(fileURLWithPath: index.rootDir).standardizedFileURL.path == root.path,
          index.recursive,
          !index.includeArchives
    else {
      return nil
    }
    return index
  }

  nonisolated private static func isApprovalIndexableFile(_ file: CorpusFile) -> Bool {
    guard !isDefaultIgnoredSyncArtifactPath(file.path) else { return false }
    let pathExtension = URL(fileURLWithPath: file.path).pathExtension.lowercased()
    return pathExtension == "org" || pathExtension == "org2"
  }

  nonisolated private static func freshSearchIndexMetadataMatches(
    file: CorpusFile,
    indexedFile: WorkspaceSearchIndexFile
  ) -> Bool {
    if let modifiedAt = file.modifiedAt,
       let byteCount = file.byteCount {
      return Int64(modifiedAt.timeIntervalSince1970 * 1000) == indexedFile.modifiedMs
        && byteCount == indexedFile.byteCount
    }

    guard let values = try? URL(fileURLWithPath: file.path).resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey]),
          let modifiedAt = values.contentModificationDate,
          let byteCount = values.fileSize
    else {
      return false
    }
    return Int64(modifiedAt.timeIntervalSince1970 * 1000) == indexedFile.modifiedMs
      && Int64(byteCount) == indexedFile.byteCount
  }

  nonisolated private static func searchIndexURL(corpusRoot: URL) -> URL {
    let configuredIndexHome = ProcessInfo.processInfo.environment["ORG2_INDEX_HOME"]?
      .trimmingCharacters(in: .whitespacesAndNewlines)
    let indexHome: URL
    if let configuredIndexHome, !configuredIndexHome.isEmpty {
      let expanded = expandHomePath(configuredIndexHome)
      indexHome = URL(fileURLWithPath: expanded).standardizedFileURL
    } else {
      indexHome = FileManager.default.homeDirectoryForCurrentUser
        .appendingPathComponent(".org2", isDirectory: true)
        .appendingPathComponent("index", isDirectory: true)
    }

    return indexHome
      .appendingPathComponent(corpusIndexDirectoryName(corpusRoot: corpusRoot), isDirectory: true)
      .appendingPathComponent("search-v1.json")
  }

  nonisolated private static func corpusIndexDirectoryName(corpusRoot: URL) -> String {
    let resolvedPath = corpusRoot.standardizedFileURL.path
    let base = corpusRoot.lastPathComponent
    let slug = base
      .lowercased()
      .replacingOccurrences(of: #"[^a-z0-9._-]+"#, with: "-", options: .regularExpression)
      .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
    let digest = SHA256.hash(data: Data(resolvedPath.utf8))
      .map { String(format: "%02x", $0) }
      .joined()
      .prefix(12)
    return "\((slug.isEmpty ? "corpus" : slug))-\(digest)"
  }

  nonisolated private static func expandHomePath(_ path: String) -> String {
    if path == "~" {
      return FileManager.default.homeDirectoryForCurrentUser.path
    }
    if path.hasPrefix("~/") {
      return FileManager.default.homeDirectoryForCurrentUser
        .appendingPathComponent(String(path.dropFirst(2)))
        .path
    }
    return path
  }

  nonisolated static func approvalCandidateTextMayContainItem(_ raw: String) -> Bool {
    let normalized = raw.lowercased()
    guard normalized.contains(":") else { return false }

    let hasHumanApprovalTitle = approvalTextHasHumanApprovalTitle(normalized)
    let hasPendingStatus = approvalStatusNeedles.contains { normalized.contains($0) }
    let hasSpecificReviewStatusKey = approvalSpecificReviewStatusKeys.contains {
      normalized.contains($0)
    }
    if hasSpecificReviewStatusKey && hasPendingStatus && hasHumanApprovalTitle {
      return true
    }

    if normalized.contains(":status:"),
       hasPendingStatus,
       hasHumanApprovalTitle {
      return true
    }

    let hasGateKey = approvalGateKeys.contains { normalized.contains($0) }
    if hasGateKey && containsApprovalSignal(normalized) {
      return true
    }

    let hasAccessPolicyKey = approvalAccessPolicyKeys.contains { normalized.contains($0) }
    return hasAccessPolicyKey && (hasPendingStatus || containsApprovalSignal(normalized))
  }

  nonisolated private static let approvalSpecificReviewStatusKeys = [
    ":org2_review_status:",
    ":review_status:",
    ":review:",
    ":followup_status:",
    ":reply_status:"
  ]

  nonisolated private static let approvalGateKeys = [
    ":waiting_on:",
    ":blocked_by:",
    ":org2_waiting_on:",
    ":next_action:",
    ":action_required:",
    ":org2_next_action:",
    ":handoff_summary:",
    ":org2_handoff_summary:"
  ]

  nonisolated private static let approvalAccessPolicyKeys = [
    ":access_policy:",
    ":review_policy:"
  ]

  nonisolated private static let approvalStatusNeedles = [
    "review-required",
    "requires-review",
    "approval-required",
    "needs-approval",
    "need-approval",
    "needs-review",
    "need-review",
    "pending-review",
    "pending-approval",
    "require-approval",
    "waiting-on-approval",
    "draft-needs-review",
    "draft-needs-approval",
    "reply-review",
    "needs-avi",
    "avi-approval",
    "needs-human",
    "human-review",
    "generated",
    "draft"
  ]

  nonisolated private static let humanApprovalTitleRegex = try? NSRegularExpression(
    pattern: #"(?m)^\*+\s+(?:(?:todo|in_progress|prog|wait|hold|paused)\s+)?(?:\[#[a-z0-9]\]\s+)?(?:approve|review|review/|review-send|review and approve|review/approve)\b"#
  )

  nonisolated private static func approvalTextHasHumanApprovalTitle(_ normalizedText: String) -> Bool {
    guard let humanApprovalTitleRegex else { return false }
    let range = NSRange(normalizedText.startIndex..<normalizedText.endIndex, in: normalizedText)
    return humanApprovalTitleRegex.firstMatch(in: normalizedText, range: range) != nil
  }

  public func clearApprovalFilter() {
    approvalFilter = ""
  }

  public func selectApprovalItem(_ item: ApprovalItem) {
    if selectedApprovalItemID != item.id {
      selectedApprovalItemID = item.id
    }
    approvalSelectionAnchor = ApprovalSelectionAnchor(
      item: item,
      visibleIndex: visibleApprovalItems.firstIndex(where: { $0.id == item.id })
    )
    if let runID = item.runId, let run = agentRuns.first(where: { $0.id == runID }) {
      selectAgentRun(run)
      if selectedApprovalItemID != item.id {
        selectedApprovalItemID = item.id
      }
      statusText = item.runDependencyText ?? item.sourceLabel
      return
    }
    if item.isRunApproval {
      statusText = item.runDependencyText ?? item.sourceLabel
      return
    }
    select(.agenda(item.agendaItem()), surface: .approvals)
    statusText = item.sourceLabel
  }

  public func handleApprovalItemClick(
    _ item: ApprovalItem,
    modifiers: NSEvent.ModifierFlags = []
  ) {
    selectedApprovalItemIDsForAIContext = Self.updatedAIContextSelection(
      selectedApprovalItemIDsForAIContext,
      activeID: selectedApprovalItemID,
      clickedID: item.id,
      visibleIDs: visibleApprovalItems.map(\.id),
      modifiers: modifiers
    )
    selectApprovalItem(item)
  }

  public func isApprovalItemSelectedForAIContext(_ item: ApprovalItem) -> Bool {
    selectedApprovalItemIDsForAIContext.isEmpty
      ? selectedApprovalItemID == item.id
      : selectedApprovalItemIDsForAIContext.contains(item.id)
  }

  public func reconcileApprovalAIContextSelection(visibleIDs: [ApprovalItem.ID]) {
    selectedApprovalItemIDsForAIContext.formIntersection(visibleIDs)
    bulkSelectedApprovalItemIDs.formIntersection(visibleIDs)
  }

  public var bulkApprovalSelectionCount: Int {
    let visibleIDs = Set(visibleApprovalItems.map(\.id))
    return bulkSelectedApprovalItemIDs.intersection(visibleIDs).count
  }

  public var hasBulkApprovalSelection: Bool {
    bulkApprovalSelectionCount > 0
  }

  public func isApprovalItemBulkSelected(_ item: ApprovalItem) -> Bool {
    bulkSelectedApprovalItemIDs.contains(item.id)
  }

  public func toggleApprovalItemBulkSelection(_ item: ApprovalItem) {
    var ids = bulkSelectedApprovalItemIDs
    if ids.contains(item.id) {
      ids.remove(item.id)
    } else {
      ids.insert(item.id)
    }
    bulkSelectedApprovalItemIDs = ids
    updateApprovalBulkSelectionStatusText()
  }

  public func selectAllVisibleApprovalItemsForBulkAction() {
    bulkSelectedApprovalItemIDs = Set(visibleApprovalItems.map(\.id))
    updateApprovalBulkSelectionStatusText()
  }

  public func extendApprovalBulkSelection(by delta: Int) {
    let items = visibleApprovalItems
    let result = Self.extendedKeyboardSelection(
      bulkSelectedApprovalItemIDs,
      activeID: selectedApprovalItemID,
      visibleIDs: items.map(\.id),
      delta: delta
    )
    guard let targetID = result.targetID,
          let target = items.first(where: { $0.id == targetID })
    else {
      statusText = "No visible approvals"
      return
    }
    bulkSelectedApprovalItemIDs = result.selection
    selectApprovalItem(target)
    updateApprovalBulkSelectionStatusText()
  }

  public func clearApprovalBulkSelection() {
    guard !bulkSelectedApprovalItemIDs.isEmpty else { return }
    bulkSelectedApprovalItemIDs = []
    statusText = "Approval selection cleared"
  }

  private func updateApprovalBulkSelectionStatusText() {
    let count = bulkApprovalSelectionCount
    if count == 0 {
      statusText = "No approvals selected"
    } else {
      statusText = count == 1 ? "1 approval selected" : "\(count) approvals selected"
    }
  }

  private func selectedApprovalItemsForBulkMutation() -> [ApprovalItem] {
    guard !bulkSelectedApprovalItemIDs.isEmpty else { return [] }
    return visibleApprovalItems.filter { bulkSelectedApprovalItemIDs.contains($0.id) }
  }

  public func approveSelectedApprovals() async {
    let items = selectedApprovalItemsForBulkMutation()
    guard !items.isEmpty else { return }
    await performBulkApprovalAction(items) { store, item in
      await store.approve(item)
    }
  }

  public func rejectSelectedApprovals(endStatus: TodoEditStatus, reason: String) async {
    let items = selectedApprovalItemsForBulkMutation()
    guard !items.isEmpty else { return }
    await performBulkApprovalAction(items) { store, item in
      await store.rejectApproval(item, endStatus: endStatus, reason: reason)
    }
  }

  public func completeSelectedApprovalsExternally(summary: String) async {
    let items = selectedApprovalItemsForBulkMutation()
    guard !items.isEmpty else { return }
    await performBulkApprovalAction(items) { store, item in
      await store.completeApprovalExternally(item, summary: summary)
    }
  }

  private func performBulkApprovalAction(
    _ items: [ApprovalItem],
    action: @escaping @MainActor @Sendable (WorkspaceStore, ApprovalItem) async -> Void
  ) async {
    let selectedIDs = Set(items.map(\.id))
    await withTaskGroup(of: Void.self) { group in
      for item in items {
        group.addTask { [weak self] in
          guard let self else { return }
          await action(self, item)
        }
      }
    }

    let failedIDs = selectedIDs.filter { approvalActionErrorsByItemID[$0] != nil }
    bulkSelectedApprovalItemIDs = Set(failedIDs)
    let completedCount = items.count - failedIDs.count
    if failedIDs.isEmpty {
      statusText = items.count == 1
        ? "Approval action completed"
        : "Approval actions completed for \(items.count) items"
    } else {
      statusText = "Approval actions completed: \(completedCount) succeeded, \(failedIDs.count) failed"
    }
  }

  public func showApprovalInQueue(run: AgentRunItem, approval: AgentRunApprovalItem) {
    runsAndReviewPage = .review
    approvalFilter = ""
    selectedApprovalItemID = "run:\(run.id):\(approval.id)"
    statusText = "Opened approval in Review"
  }

  public func approve(_ item: ApprovalItem) async {
    guard !isApprovalActionInProgress(item) else { return }
    let originalVisibleIndex = visibleApprovalItems.firstIndex(where: { $0.id == item.id })
    beginApprovalAction(item, kind: .approve)
    defer { endApprovalAction(item, kind: .approve) }

    do {
      if item.isRunApproval {
        let updated = try await decideRunApprovalItem(item, decision: "approved")
        removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
        scheduleApprovalsRefresh()
        await continueOpenClawAfterApprovalBoundary(updated)
        return
      }
      try await performStandaloneApprovalMutation(in: item.file) {
        try await approveAndAgentHandoff(HeadlineMutationTarget(
          file: item.file,
          line: item.line,
          title: Org2Display.cleanInline(item.title),
          agendaItemID: nil,
          idValue: item.idValue
        ))
      }
      removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
      scheduleApprovalsRefresh()
    } catch {
      recordApprovalActionFailure(item, error: error, status: "Approve handoff failed")
    }
  }

  public func promptAndRejectApproval(_ item: ApprovalItem) {
    guard !isApprovalActionInProgress(item) else { return }
    selectedApprovalItemID = item.id
    let rejection = item.isRunApproval
      ? Self.promptForRunApprovalRejection()
      : Self.promptForApprovalRejection()
    guard let rejection else { return }
    Task {
      await rejectApproval(
        item,
        endStatus: rejection.endStatus,
        reason: rejection.reason
      )
    }
  }

  public func rejectApproval(_ item: ApprovalItem, endStatus: TodoEditStatus, reason: String) async {
    guard !isApprovalActionInProgress(item) else { return }
    let originalVisibleIndex = visibleApprovalItems.firstIndex(where: { $0.id == item.id })
    beginApprovalAction(item, kind: .reject)
    defer { endApprovalAction(item, kind: .reject) }

    do {
      if item.isRunApproval {
        let updated = try await decideRunApprovalItem(item, decision: "rejected", note: reason)
        removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
        scheduleApprovalsRefresh()
        await continueOpenClawAfterApprovalBoundary(updated)
        return
      }
      try await performStandaloneApprovalMutation(in: item.file) {
        try await rejectApproval(
          HeadlineMutationTarget(
            file: item.file,
            line: item.line,
            title: Org2Display.cleanInline(item.title),
            agendaItemID: nil,
            idValue: item.idValue
          ),
          endStatus: endStatus,
          reason: reason
        )
      }
      removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
      scheduleApprovalsRefresh()
    } catch {
      recordApprovalActionFailure(item, error: error, status: "Reject approval failed")
    }
  }

  public func completeApprovalExternally(_ item: ApprovalItem, summary: String) async {
    guard !isApprovalActionInProgress(item) else { return }
    let normalizedSummary = summary.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !normalizedSummary.isEmpty else {
      errorText = "Describe where or how the work was completed."
      statusText = "External completion note required"
      return
    }
    let originalVisibleIndex = visibleApprovalItems.firstIndex(where: { $0.id == item.id })
    beginApprovalAction(item, kind: .externalCompletion)
    defer { endApprovalAction(item, kind: .externalCompletion) }

    do {
      if item.isRunApproval {
        let updated = try await decideRunApprovalItem(
          item,
          decision: "canceled",
          receipt: "Completed externally: \(normalizedSummary)"
        )
        removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
        scheduleApprovalsRefresh()
        statusText = "Recorded external completion for \(item.title) · \(updated.pendingApprovalCount) pending"
        await continueOpenClawAfterApprovalBoundary(updated)
        return
      }

      try await performStandaloneApprovalMutation(in: item.file) {
        try await completeStandaloneApprovalExternally(
          HeadlineMutationTarget(
            file: item.file,
            line: item.line,
            title: Org2Display.cleanInline(item.title),
            agendaItemID: nil,
            idValue: item.idValue
          ),
          summary: normalizedSummary
        )
      }
      removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
      scheduleApprovalsRefresh()
    } catch {
      recordApprovalActionFailure(item, error: error, status: "External completion failed")
    }
  }

  public func isApprovingApproval(_ item: ApprovalItem) -> Bool {
    approvingApprovalItemIDs.contains(item.id)
  }

  public func isRejectingApproval(_ item: ApprovalItem) -> Bool {
    rejectingApprovalItemIDs.contains(item.id)
  }

  public func isCompletingApprovalExternally(_ item: ApprovalItem) -> Bool {
    externallyCompletingApprovalItemIDs.contains(item.id)
  }

  public func isApprovalActionInProgress(_ item: ApprovalItem) -> Bool {
    isApprovalActionInProgress(item.id)
  }

  public func isAgentRunApprovalActionInProgress(runID: String, approvalID: String) -> Bool {
    isApprovalActionInProgress(Self.runApprovalQueueItemID(runID: runID, approvalID: approvalID))
  }

  nonisolated private static func runApprovalQueueItemID(
    runID: String,
    approvalID: String
  ) -> ApprovalItem.ID {
    ApprovalItem.ID("run:\(runID):\(approvalID)")
  }

  private func isApprovalActionInProgress(_ itemID: ApprovalItem.ID) -> Bool {
    approvingApprovalItemIDs.contains(itemID)
      || rejectingApprovalItemIDs.contains(itemID)
      || externallyCompletingApprovalItemIDs.contains(itemID)
  }

  public func approvalActionError(_ item: ApprovalItem) -> String? {
    approvalActionErrorsByItemID[item.id]
  }

  public func requestChanges(_ item: ApprovalItem, feedback: String) async {
    guard item.isRunApproval, !isApprovalActionInProgress(item) else { return }
    guard let feedback = Self.normalizedApprovalRevisionFeedback(feedback) else {
      errorText = "Describe what the agent should change."
      statusText = "Revision feedback required"
      return
    }
    let originalVisibleIndex = visibleApprovalItems.firstIndex(where: { $0.id == item.id })
    beginApprovalAction(item, kind: .reject)
    defer { endApprovalAction(item, kind: .reject) }
    do {
      let updated = try await decideRunApprovalItem(item, decision: "revised", note: feedback)
      removeApprovalItemOptimistically(item.id, originalVisibleIndex: originalVisibleIndex)
      scheduleApprovalsRefresh()
      await continueOpenClawAfterApprovalBoundary(updated)
    } catch {
      recordApprovalActionFailure(item, error: error, status: "Revision request failed")
    }
  }

  private func decideRunApprovalItem(
    _ item: ApprovalItem,
    decision: String,
    note: String? = nil,
    receipt: String? = nil
  ) async throws -> AgentRunItem {
    guard corpusRoot != nil, let runID = item.runId, let approvalID = item.approvalId else {
      throw CocoaError(.fileReadCorruptFile, userInfo: [NSLocalizedDescriptionKey: "This run approval is missing its run or approval identity."])
    }
    try await waitForAgentRunMutationAvailability(runID)
    defer { mutatingAgentRunIDs.remove(runID) }

    let updated = try await performAgentRunApprovalDecision(
      runID: runID,
      approvalID: approvalID,
      fingerprint: item.fingerprint,
      decision: decision,
      requestedRole: item.requestedRole,
      requestedFrom: item.requestedFrom,
      note: note,
      receipt: receipt
    )
    if let index = agentRuns.firstIndex(where: { $0.id == updated.id }) {
      agentRuns[index] = updated
    } else {
      agentRuns.insert(updated, at: 0)
    }
    statusText = "\(item.title): \(decision) · \(updated.pendingApprovalCount) pending"
    return updated
  }

  private func performAgentRunApprovalDecision(
    runID: String,
    approvalID: String,
    fingerprint: String?,
    decision: String,
    requestedRole: String?,
    requestedFrom: String?,
    note: String? = nil,
    receipt: String? = nil
  ) async throws -> AgentRunItem {
    guard let corpusRoot else {
      throw CocoaError(.fileNoSuchFile, userInfo: [NSLocalizedDescriptionKey: "No corpus is selected."])
    }
    let updated: AgentRunItem
    if let agentRunApprovalDecisionForTesting {
      updated = try await agentRunApprovalDecisionForTesting(
        runID,
        approvalID,
        decision,
        note
      )
    } else {
      var arguments = [
        "run", "approval-decide", runID, approvalID,
        "--decision", decision,
        "--actor", Self.agentRunApprovalDecisionActor(requestedFrom: requestedFrom),
        "--role", requestedRole ?? "owner",
        "--dir", corpusRoot.path,
        "--json"
      ]
      if let fingerprint = fingerprint?.trimmingCharacters(in: .whitespacesAndNewlines), !fingerprint.isEmpty {
        arguments.append(contentsOf: ["--fingerprint", fingerprint])
      }
      if let note = note?.trimmingCharacters(in: .whitespacesAndNewlines), !note.isEmpty {
        arguments.append(contentsOf: ["--note", note])
      }
      if let receipt = receipt?.trimmingCharacters(in: .whitespacesAndNewlines), !receipt.isEmpty {
        arguments.append(contentsOf: ["--receipt", receipt])
      }
      updated = try await cli.runJSON(arguments)
    }
    // A provider-backed decision can also supersede and close older run
    // projections. Reconcile those in the background so a large run archive
    // never blocks the approval row from disappearing. Repeated decisions are
    // coalesced into one scan, and the filesystem watcher remains a fallback.
    scheduleAgentRunsRefresh()
    return updated
  }

  nonisolated static func agentRunApprovalDecisionActor(requestedFrom: String?) -> String {
    let reviewer = requestedFrom?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    return reviewer.isEmpty ? "Org2Workspace" : reviewer
  }

  nonisolated static func normalizedApprovalRevisionFeedback(_ value: String) -> String? {
    let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
    return normalized.isEmpty ? nil : normalized
  }

  public func discussApprovalInOpenClaw(
    _ item: ApprovalItem,
    message: String? = nil,
    threadMode: OpenClawThreadMode = .newThread
  ) async {
    let userText = message?.trimmingCharacters(in: .whitespacesAndNewlines).nilIfBlank
      ?? "I need to discuss this approval item before deciding."
    let text = automaticOpenClawActionText(
      openClawContextPointer(for: item),
      prompt: item.discussionText,
      userText: userText
    )
    navigateToSurface(.openClaw)
    prepareOpenClawThread(
      mode: threadMode,
      title: "Discuss: \(Org2Display.cleanInline(item.title))",
      statusText: "New OpenClaw approval chat"
    )
    await sendOpenClawMessage(text: text)
  }

  public func copyApprovalDiscussionText(_ item: ApprovalItem) {
    NSPasteboard.general.clearContents()
    NSPasteboard.general.setString(item.discussionText, forType: .string)
    statusText = "Copied approval discussion text"
  }

  private func syncApprovalSelectionAfterRefresh() {
    guard !visibleApprovalItems.isEmpty else {
      selectedApprovalItemID = nil
      approvalSelectionAnchor = nil
      return
    }
    if let selectedApprovalItemID,
       let selectedItem = visibleApprovalItems.first(where: { $0.id == selectedApprovalItemID }) {
      approvalSelectionAnchor = ApprovalSelectionAnchor(
        item: selectedItem,
        visibleIndex: visibleApprovalItems.firstIndex(where: { $0.id == selectedItem.id })
      )
      return
    }
    if selectedSurface == .approvals {
      let anchoredItem = approvalSelectionAnchor.flatMap { approvalItem(matching: $0) }
      selectApprovalItem(anchoredItem ?? visibleApprovalItems[0])
    }
  }

  private func approvalItem(matching anchor: ApprovalSelectionAnchor) -> ApprovalItem? {
    if let idValue = anchor.idValue,
       let stableIDMatch = visibleApprovalItems.first(where: {
         $0.file == anchor.file
           && $0.idValue?.trimmingCharacters(in: .whitespacesAndNewlines) == idValue
       }) {
      return stableIDMatch
    }

    let titleMatches = visibleApprovalItems.enumerated().filter { _, item in
      item.file == anchor.file && item.title == anchor.title
    }
    if !titleMatches.isEmpty {
      let preferredIndex = anchor.visibleIndex ?? titleMatches[0].offset
      return titleMatches.min(by: { lhs, rhs in
        abs(lhs.offset - preferredIndex) < abs(rhs.offset - preferredIndex)
      })?.element
    }

    guard let visibleIndex = anchor.visibleIndex else { return nil }
    return visibleApprovalItems[min(max(visibleIndex, 0), visibleApprovalItems.count - 1)]
  }

  private func rebuildApprovalDisplayCache() {
    let terms = Self.filterTerms(from: approvalFilter)
    visibleApprovalItems = approvalItems.filter { item in
      guard !terms.isEmpty else { return true }
      let searchText = approvalFilterTextByItemID[item.id] ?? item.approvalFilterText
      return terms.allSatisfy { searchText.contains($0) }
    }
    if let selectedApprovalItemID,
       !visibleApprovalItems.contains(where: { $0.id == selectedApprovalItemID }) {
      self.selectedApprovalItemID = nil
    }
    pruneApprovalActionState()
  }

  private func rebuildApprovalSearchIndex() {
    var index: [ApprovalItem.ID: String] = [:]
    index.reserveCapacity(approvalItems.count)
    for item in approvalItems {
      index[item.id] = item.approvalFilterText
    }
    approvalFilterTextByItemID = index
  }

  private func beginApprovalAction(_ item: ApprovalItem, kind: ApprovalActionKind) {
    beginApprovalAction(item.id, kind: kind)
  }

  private func beginApprovalAction(_ itemID: ApprovalItem.ID, kind: ApprovalActionKind) {
    if approvalActionErrorsByItemID[itemID] != nil {
      var errors = approvalActionErrorsByItemID
      errors.removeValue(forKey: itemID)
      approvalActionErrorsByItemID = errors
    }
    switch kind {
    case .approve:
      var ids = approvingApprovalItemIDs
      ids.insert(itemID)
      approvingApprovalItemIDs = ids
    case .reject:
      var ids = rejectingApprovalItemIDs
      ids.insert(itemID)
      rejectingApprovalItemIDs = ids
    case .externalCompletion:
      var ids = externallyCompletingApprovalItemIDs
      ids.insert(itemID)
      externallyCompletingApprovalItemIDs = ids
    }
  }

  private func recordApprovalActionFailure(
    _ item: ApprovalItem,
    error: Error,
    status: String
  ) {
    var errors = approvalActionErrorsByItemID
    errors[item.id] = error.localizedDescription
    approvalActionErrorsByItemID = errors
    errorText = error.localizedDescription
    statusText = status
  }

  private func waitForAgentRunMutationAvailability(_ runID: AgentRunItem.ID) async throws {
    while mutatingAgentRunIDs.contains(runID) {
      try Task.checkCancellation()
      try await Task.sleep(nanoseconds: 15_000_000)
    }
    mutatingAgentRunIDs.insert(runID)
  }

  private func performStandaloneApprovalMutation<T>(
    in file: String,
    operation: () async throws -> T
  ) async throws -> T {
    let key = URL(fileURLWithPath: file).standardizedFileURL.path
    while mutatingStandaloneApprovalFiles.contains(key) {
      try Task.checkCancellation()
      try await Task.sleep(nanoseconds: 15_000_000)
    }
    mutatingStandaloneApprovalFiles.insert(key)
    defer { mutatingStandaloneApprovalFiles.remove(key) }
    return try await operation()
  }

  private func endApprovalAction(_ item: ApprovalItem, kind: ApprovalActionKind) {
    endApprovalAction(item.id, kind: kind)
  }

  private func endApprovalAction(_ itemID: ApprovalItem.ID, kind: ApprovalActionKind) {
    switch kind {
    case .approve:
      var ids = approvingApprovalItemIDs
      ids.remove(itemID)
      approvingApprovalItemIDs = ids
    case .reject:
      var ids = rejectingApprovalItemIDs
      ids.remove(itemID)
      rejectingApprovalItemIDs = ids
    case .externalCompletion:
      var ids = externallyCompletingApprovalItemIDs
      ids.remove(itemID)
      externallyCompletingApprovalItemIDs = ids
    }
  }

  private func pruneApprovalActionState() {
    let itemIDs = Set(approvalItems.map(\.id))
    let nextBulkSelectedIDs = bulkSelectedApprovalItemIDs.intersection(itemIDs)
    if nextBulkSelectedIDs != bulkSelectedApprovalItemIDs {
      bulkSelectedApprovalItemIDs = nextBulkSelectedIDs
    }
    let nextErrors = approvalActionErrorsByItemID.filter { itemIDs.contains($0.key) }
    if nextErrors != approvalActionErrorsByItemID {
      approvalActionErrorsByItemID = nextErrors
    }
  }

  private func preserveApprovalSelectionAfterMutation(mutatedID: ApprovalItem.ID, originalVisibleIndex: Int?) {
    guard selectedSurface == .approvals else { return }

    if let item = nextApprovalItem(afterMutating: mutatedID, originalVisibleIndex: originalVisibleIndex) {
      selectApprovalItem(item)
    } else {
      selectedApprovalItemID = nil
      approvalSelectionAnchor = nil
    }
  }

  private func removeApprovalItemOptimistically(_ id: ApprovalItem.ID, originalVisibleIndex: Int?) {
    bulkSelectedApprovalItemIDs.remove(id)
    approvalItems.removeAll { $0.id == id }
    preserveApprovalSelectionAfterMutation(mutatedID: id, originalVisibleIndex: originalVisibleIndex)
  }

  private func scheduleApprovalsRefresh(updatesStatus: Bool = false) {
    scheduledApprovalsRefreshTask?.cancel()
    scheduledApprovalsRefreshTask = Task { @MainActor [weak self] in
      try? await Task.sleep(nanoseconds: 250_000_000)
      guard !Task.isCancelled else { return }
      guard let self else { return }
      await self.refreshApprovals(updatesStatus: updatesStatus)
      if !Task.isCancelled {
        self.scheduledApprovalsRefreshTask = nil
      }
    }
  }

  private func scheduleAgentRunsRefresh() {
    scheduledAgentRunsRefreshTask?.cancel()
    scheduledAgentRunsRefreshTask = Task { @MainActor [weak self] in
      guard let self else { return }
      do {
        try await Task.sleep(nanoseconds: self.deferredAgentRunsRefreshDelayNanoseconds)
      } catch {
        return
      }
      guard !Task.isCancelled else { return }
      await self.refreshAgentRuns()
      if !Task.isCancelled {
        self.scheduledAgentRunsRefreshTask = nil
      }
    }
  }

  private func nextApprovalItem(afterMutating mutatedID: ApprovalItem.ID, originalVisibleIndex: Int?) -> ApprovalItem? {
    if let current = visibleApprovalItems.first(where: { $0.id == mutatedID }) {
      return current
    }

    guard !visibleApprovalItems.isEmpty else { return nil }
    let fallbackIndex = originalVisibleIndex ?? 0
    let boundedIndex = min(max(fallbackIndex, 0), visibleApprovalItems.count - 1)
    return visibleApprovalItems[boundedIndex]
  }

  nonisolated static func approvalItems(
    in document: Org2CanonicalDocument,
    file: String,
    sourceText: String,
    sourceLineOffset: Int = 0
  ) -> [ApprovalItem] {
    let lines = normalizeLineEndings(sourceText)
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    var items: [ApprovalItem] = []
    appendApprovalItems(
      from: document.children,
      file: file,
      sourceLines: lines,
      sourceLineOffset: sourceLineOffset,
      into: &items
    )
    return sortedApprovalItems(items)
  }

  nonisolated private static func appendApprovalItems(
    from nodes: [Org2CanonicalNode],
    file: String,
    sourceLines: [String],
    sourceLineOffset: Int,
    into items: inout [ApprovalItem]
  ) {
    for node in nodes {
      guard case .headline(let headline) = node else { continue }
      appendApprovalItem(
        from: headline,
        file: file,
        sourceLines: sourceLines,
        sourceLineOffset: sourceLineOffset,
        into: &items
      )
      appendApprovalItems(
        from: headline.children,
        file: file,
        sourceLines: sourceLines,
        sourceLineOffset: sourceLineOffset,
        into: &items
      )
    }
  }

  nonisolated private static func appendApprovalItem(
    from headline: Org2CanonicalHeadline,
    file: String,
    sourceLines: [String],
    sourceLineOffset: Int,
    into items: inout [ApprovalItem]
  ) {
    let todo = headline.todo?.uppercased()
    guard !isTerminalTodo(todo),
          let sourceRange = headline.sourceRange
    else {
      return
    }

    let properties = canonicalHeadlineProperties(headline)
    let title = approvalTitle(canonicalInlineText(headline.title))
    guard let status = approvalStatus(title: title, properties: properties) else { return }

    items.append(ApprovalItem(
      title: title,
      status: status,
      todo: todo,
      level: headline.level,
      file: file,
      line: sourceRange.startLine,
      idValue: properties["ID"],
      properties: properties,
      body: approvalBody(
        sourceLines: sourceLines,
        sourceLineOffset: sourceLineOffset,
        sourceRange: sourceRange,
        children: headline.children
      ),
      tags: headline.tags ?? []
    ))
  }

  nonisolated private static func canonicalHeadlineProperties(_ headline: Org2CanonicalHeadline) -> [String: String] {
    for child in headline.children {
      guard case .propertyDrawer(let drawer) = child else { continue }
      return Dictionary(uniqueKeysWithValues: drawer.properties.map { ($0.key.uppercased(), $0.value) })
    }
    return [:]
  }

  nonisolated private static func approvalBody(
    sourceLines: [String],
    sourceLineOffset: Int,
    sourceRange: Org2CanonicalSourceRange,
    children: [Org2CanonicalNode]
  ) -> String {
    let startLine = max(1, sourceRange.startLine + 1)
    let endLine = max(startLine, sourceRange.endLine)
    guard startLine <= endLine, !sourceLines.isEmpty else { return "" }

    let hiddenRanges = children.compactMap { child -> ClosedRange<Int>? in
      switch child {
      case .propertyDrawer(let drawer):
        guard let range = drawer.sourceRange else { return nil }
        return range.startLine...range.endLine
      case .planning(let planning):
        guard let range = planning.sourceRange else { return nil }
        return range.startLine...range.endLine
      default:
        return nil
      }
    }

    var bodyLines: [String] = []
    for lineNumber in startLine...endLine {
      let sourceIndex = lineNumber - sourceLineOffset - 1
      guard sourceLines.indices.contains(sourceIndex),
            !hiddenRanges.contains(where: { $0.contains(lineNumber) })
      else {
        continue
      }
      bodyLines.append(sourceLines[sourceIndex])
    }
    return bodyLines
      .joined(separator: "\n")
      .trimmingCharacters(in: .whitespacesAndNewlines)
  }

  nonisolated private static func approvalStatus(title: String, properties: [String: String]) -> String? {
    let status = firstPropertyText(
      in: properties,
      keys: [
        "ORG2_REVIEW_STATUS",
        "REVIEW_STATUS",
        "REVIEW",
        "STATUS",
        "FOLLOWUP_STATUS",
        "REPLY_STATUS"
      ]
    )
    if let status, isPendingApprovalStatus(status), titleNeedsHumanApproval(title) {
      return status
    }

    let waitingOn = firstPropertyText(in: properties, keys: ["WAITING_ON", "BLOCKED_BY", "ORG2_WAITING_ON"]) ?? ""
    if containsApprovalSignal(waitingOn) {
      return waitingOn.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "approval-required" : waitingOn
    }

    let nextAction = firstPropertyText(in: properties, keys: ["NEXT_ACTION", "ACTION_REQUIRED", "ORG2_NEXT_ACTION"]) ?? ""
    if containsApprovalSignal(nextAction) {
      return "approval-required"
    }

    let handoff = firstPropertyText(in: properties, keys: ["HANDOFF_SUMMARY", "ORG2_HANDOFF_SUMMARY"]) ?? ""
    if containsApprovalSignal(handoff) {
      return "approval-required"
    }

    let accessPolicy = firstPropertyText(in: properties, keys: ["ACCESS_POLICY", "REVIEW_POLICY"]) ?? ""
    if isPendingApprovalStatus(accessPolicy) || containsApprovalSignal(accessPolicy) {
      return accessPolicy.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "approval-required" : accessPolicy
    }

    return nil
  }

  nonisolated private static func firstPropertyText(in properties: [String: String], keys: [String]) -> String? {
    for key in keys {
      let value = properties[key]?.trimmingCharacters(in: .whitespacesAndNewlines)
      if value?.isEmpty == false {
        return value
      }
    }
    return nil
  }

  nonisolated private static func isPendingApprovalStatus(_ raw: String) -> Bool {
    let normalized = raw.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
    if [
      "review-required",
      "requires-review",
      "approval-required",
      "needs-approval",
      "needs-review",
      "pending-review",
      "pending-approval",
      "require-approval",
      "generated",
      "draft"
    ].contains(normalized) {
      return true
    }

    return normalized.contains("needs-review")
      || normalized.contains("need-review")
      || normalized.contains("needs-approval")
      || normalized.contains("need-approval")
      || normalized.contains("waiting-on-approval")
      || normalized.contains("pending-review")
      || normalized.contains("pending-approval")
      || normalized.contains("draft-needs-review")
      || normalized.contains("draft-needs-approval")
      || normalized.contains("reply-review")
      || normalized.contains("needs-avi")
      || normalized.contains("avi-approval")
      || normalized.contains("needs-human")
      || normalized.contains("human-review")
  }

  nonisolated private static func titleNeedsHumanApproval(_ title: String) -> Bool {
    let normalized = approvalTitle(title).lowercased()
    return normalized.hasPrefix("approve ")
      || normalized.hasPrefix("review ")
      || normalized.hasPrefix("review/")
      || normalized.hasPrefix("review-send ")
      || normalized.hasPrefix("review and approve ")
      || normalized.hasPrefix("review/approve ")
  }

  nonisolated private static func approvalTitle(_ raw: String) -> String {
    Org2Display.cleanInline(raw)
      .replacingOccurrences(
        of: #"^\s*\[#[A-Za-z0-9]\](?:\s+|$)"#,
        with: "",
        options: .regularExpression
      )
      .trimmingCharacters(in: .whitespacesAndNewlines)
  }

  nonisolated private static func containsApprovalSignal(_ raw: String) -> Bool {
    let normalized = raw.lowercased()
    return normalized.contains("approval")
      || normalized.contains("approve")
      || normalized.contains("review")
      || normalized.contains("avi")
  }

  nonisolated private static func isTerminalTodo(_ todo: String?) -> Bool {
    guard let todo else { return false }
    return todo == "DONE" || todo == "CANCELED" || todo == "CANCELLED"
  }

  nonisolated private static func canonicalInlineText(_ inlines: [Org2CanonicalInline]) -> String {
    inlines.map(canonicalInlineText).joined()
  }

  nonisolated private static func canonicalInlineText(_ inline: Org2CanonicalInline) -> String {
    switch inline {
    case .text(let text):
      return text.value
    case .timestamp(let timestamp):
      return timestamp.raw
    case .timestampRange(let range):
      return "\(range.start.raw)\(range.separatorRaw)\(range.end.raw)"
    case .emphasis(let emphasis):
      return "\(emphasis.marker)\(emphasis.content)\(emphasis.marker)"
    case .link(let link):
      return link.descriptionRaw ?? link.targetRaw
    case .progressCookie(let raw):
      return raw
    case .unsupported(let type):
      return type
    }
  }

  nonisolated private static func sortedApprovalItems(_ items: [ApprovalItem]) -> [ApprovalItem] {
    items.sorted { lhs, rhs in
      let statusOrder = lhs.status.localizedCaseInsensitiveCompare(rhs.status)
      if statusOrder != .orderedSame { return statusOrder == .orderedAscending }
      let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
      if titleOrder != .orderedSame { return titleOrder == .orderedAscending }
      if lhs.file != rhs.file { return lhs.file.localizedStandardCompare(rhs.file) == .orderedAscending }
      return lhs.line < rhs.line
    }
  }

  private func scheduleSearchIndexBuild(corpusRoot: URL) {
    searchIndexGeneration += 1
    let generation = searchIndexGeneration
    searchIndexTask?.cancel()
    isBuildingSearchIndex = true
    searchIndexStatusText = "Indexing search..."

    searchIndexTask = Task { [cli] in
      do {
        let payload: SearchIndexBuildPayload = try await cli.runJSON([
          "index",
          "--dir", corpusRoot.path,
          "--recursive",
          "--format", "json"
        ])
        guard !Task.isCancelled else { return }
        await MainActor.run {
          guard self.searchIndexGeneration == generation else { return }
          self.isBuildingSearchIndex = false
          let skipped = payload.skippedFiles > 0 ? ", \(payload.skippedFiles) skipped" : ""
          self.searchIndexStatusText = "\(payload.fileCount) files, \(payload.lineCount) lines indexed\(skipped)"
        }
      } catch {
        guard !Task.isCancelled else { return }
        await MainActor.run {
          guard self.searchIndexGeneration == generation else { return }
          self.isBuildingSearchIndex = false
          self.searchIndexStatusText = "Search index unavailable"
        }
      }
    }
  }

  public func runSearch() async {
    let dirtyGeneration = workspaceSurfaceDirtyGenerations[.search, default: 0]
    let query = searchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !query.isEmpty else {
      searchResults = []
      openClawChatSearchResults = []
      workspaceFileSearchResults = []
      workspacePageSearchResults = []
      workspaceAgentWorkSearchResults = []
      markWorkspaceSurfaceCleanIfUnchanged(.search, generation: dirtyGeneration)
      return
    }
    isSearching = true
    errorText = nil
    statusText = "Searching workspace..."
    defer { isSearching = false }

    let started = Date()
    let chatResults = Self.searchOpenClawChatThreads(openClawChatThreads, query: query, limit: 25)
    guard let corpusRoot else {
      searchResults = []
      openClawChatSearchResults = chatResults
      workspaceFileSearchResults = []
      workspacePageSearchResults = []
      workspaceAgentWorkSearchResults = []
      selectedSurface = .search
      let elapsed = Date().timeIntervalSince(started)
      statusText = chatResults.isEmpty
        ? "No corpus selected"
        : "\(chatResults.count) chat result\(chatResults.count == 1 ? "" : "s") in \(String(format: "%.1f", elapsed))s"
      markWorkspaceSurfaceCleanIfUnchanged(.search, generation: dirtyGeneration)
      return
    }

    let runs = agentRuns
    let approvals = approvalItems
    let workflows = agentWorkflows
    let goals = agentGoals
    let profiles = agentProfiles
    let agentWorkSearchTask = Task.detached(priority: .userInitiated) {
      Self.searchAgentWorkForWorkspace(
        runs: runs,
        approvals: approvals,
        workflows: workflows,
        goals: goals,
        profiles: profiles,
        query: query,
        limitPerCategory: 25
      )
    }

    do {
      let files = searchReadScope == .activeCorpus ? corpusFiles : []
      let pageNodes = searchReadScope == .activeCorpus ? orgRoamLinkResolver.nodes.filter(\.isPageNode) : []
      async let supplementalResults = Task.detached(priority: .userInitiated) {
        let resolvedPageNodes = pageNodes.isEmpty
          ? files.compactMap(Self.scanRoamFileNode)
          : pageNodes
        return (
          Self.searchCorpusFilesForWorkspace(files, query: query, limit: 25),
          Self.searchPageNodesForWorkspace(resolvedPageNodes, query: query, limit: 25)
        )
      }.value
      let federates = searchReadScope == .allCorpora && workspaceMountPaths().count > 1
      var arguments = federates
        ? ["workspace", "search", query] + workspaceMountArguments()
        : ["search", query, "--dir", corpusRoot.path]
      arguments += [
        "--recursive",
        "--limit", String(Self.workspaceSearchCandidateLimit),
        "--context", "1",
        "--index", federates ? "auto" : "current",
        "--sort", "relevance",
        "--format", "json"
      ]
      let payload: SearchPayload = try await cli.runJSON(arguments)
      let (fileResults, pageResults) = await supplementalResults
      let agentWorkResults = await agentWorkSearchTask.value
      searchResults = Self.prioritizedSearchResultsForDisplay(
        payload.results,
        query: query,
        limit: Self.workspaceSearchDisplayLimit
      )
      openClawChatSearchResults = chatResults
      workspaceFileSearchResults = fileResults
      workspacePageSearchResults = pageResults
      workspaceAgentWorkSearchResults = agentWorkResults
      selectedSurface = .search
      let elapsed = Date().timeIntervalSince(started)
      let totalCount = workspaceTextSearchResultCount
      let issueSuffix = payload.issues?.isEmpty == false ? ", \(payload.issues!.count) corpus issue\(payload.issues!.count == 1 ? "" : "s")" : ""
      statusText = "\(totalCount) search result\(totalCount == 1 ? "" : "s") in \(String(format: "%.1f", elapsed))s\(issueSuffix)"
      markWorkspaceSurfaceCleanIfUnchanged(.search, generation: dirtyGeneration)
    } catch {
      workspaceAgentWorkSearchResults = await agentWorkSearchTask.value
      errorText = error.localizedDescription
      statusText = "Search failed"
    }
  }

  public func refreshMeetings() async {
    guard let corpusRoot else {
      meetings = []
      return
    }

    let dirtyGeneration = workspaceSurfaceDirtyGenerations[.meetings, default: 0]
    isLoadingMeetings = true
    defer { isLoadingMeetings = false }

    do {
      let items = try await Task.detached(priority: .utility) {
        try Self.scanMeetingItems(corpusRoot: corpusRoot)
      }.value
      meetings = items
      if selectedSurface == .meetings {
        statusText = "\(items.count) meeting\(items.count == 1 ? "" : "s")"
      }
      reconcileMeetingProcessingState(with: items)
      syncMeetingSelectionAfterRefresh()
      recoverInterruptedMeetingTranscriptions(knownItems: items)
      markWorkspaceSurfaceCleanIfUnchanged(.meetings, generation: dirtyGeneration)
    } catch {
      errorText = error.localizedDescription
      statusText = "Meeting scan failed"
    }
  }

  public func promptAndStartMeetingRecording() {
    guard corpusRoot != nil else {
      statusText = "No corpus selected"
      return
    }
    guard !isRecordingMeeting else { return }

    let alert = NSAlert()
    alert.messageText = "Record Meeting"
    alert.informativeText = "Record local microphone audio into the selected Org2 corpus."
    alert.addButton(withTitle: "Start Recording")
    alert.addButton(withTitle: "Cancel")

    let field = NSTextField(frame: NSRect(x: 0, y: 0, width: 360, height: 24))
    field.placeholderString = "Meeting title"
    field.stringValue = meetingTitleDraft
    alert.accessoryView = field

    let response = alert.runModal()
    guard response == .alertFirstButtonReturn else { return }

    meetingTitleDraft = field.stringValue
    Task { await startMeetingRecording(title: field.stringValue) }
  }

  public func startMeetingRecording(title rawTitle: String) async {
    guard let corpusRoot else {
      statusText = "No corpus selected"
      return
    }
    guard !isRecordingMeeting else {
      meetingStatusText = "A meeting is already recording"
      return
    }

    do {
      let startedAt = Date()
      let paths = try MeetingArtifactWriter.preparePaths(
        corpusRoot: corpusRoot,
        title: rawTitle,
        recordedAt: startedAt
      )
      // The recorder creates its audio file before either capture stream has
      // fully started. Exclude that path immediately so a concurrent meeting
      // refresh cannot mistake the live file for an interrupted recording.
      meetingRecordingRecoveryExclusionPaths = paths
      try await meetingRecorder.startRecording(to: paths.audioURL)
      let systemAudioStartError: String?
      do {
        try await meetingSystemAudioRecorder.startRecording(to: paths.systemAudioURL)
        isCapturingSystemAudio = true
        meetingSystemAudioStatusText = "System audio recording"
        systemAudioStartError = nil
      } catch {
        isCapturingSystemAudio = false
        meetingSystemAudioStatusText = "System audio unavailable: \(error.localizedDescription)"
        systemAudioStartError = error.localizedDescription
      }
      activeMeetingRecording = PendingMeetingRecording(
        paths: paths,
        capturesSystemAudio: systemAudioStartError == nil,
        systemAudioStartError: systemAudioStartError
      )
      isRecordingMeeting = true
      isMeetingRecordingPaused = false
      startMeetingInputMetering()
      selectedSurface = .meetings
      meetingStatusText = "Recording \(paths.title)"
      statusText = meetingStatusText
    } catch {
      meetingRecordingRecoveryExclusionPaths = nil
      isCapturingSystemAudio = false
      isMeetingRecordingPaused = false
      meetingSystemAudioStatusText = "System audio not recording"
      stopMeetingInputMetering()
      errorText = error.localizedDescription
      meetingStatusText = "Recording failed: \(error.localizedDescription)"
      statusText = "Recording failed"
    }
  }

  public func stopMeetingRecording() async {
    guard let corpusRoot else {
      statusText = "No corpus selected"
      return
    }
    guard let recording = activeMeetingRecording else {
      meetingStatusText = "No active recording"
      return
    }

    do {
      let duration = try meetingRecorder.stopRecording()
      var systemAudioURL: URL?
      var systemAudioCaptureError = recording.systemAudioStartError
      if recording.capturesSystemAudio {
        do {
          if let systemDuration = try await meetingSystemAudioRecorder.stopRecording(), systemDuration > 0 {
            systemAudioURL = recording.paths.systemAudioURL
          } else {
            try? FileManager.default.removeItem(at: recording.paths.systemAudioURL)
            systemAudioCaptureError = "No system audio samples were captured."
          }
        } catch {
          try? FileManager.default.removeItem(at: recording.paths.systemAudioURL)
          systemAudioCaptureError = error.localizedDescription
        }
      }
      self.activeMeetingRecording = nil
      isRecordingMeeting = false
      isMeetingRecordingPaused = false
      isCapturingSystemAudio = false
      stopMeetingInputMetering()
      beginMeetingProcessing(paths: recording.paths, status: "Transcribing \(recording.paths.title) locally...")
      meetingRecordingRecoveryExclusionPaths = nil
      let progressID = startMeetingTranscriptionProgress(
        title: recording.paths.title,
        audioDuration: duration
      )
      Task { [weak self] in
        await self?.finishStoppedMeetingRecording(
          recording,
          corpusRoot: corpusRoot,
          duration: duration,
          systemAudioURL: systemAudioURL,
          systemAudioCaptureError: systemAudioCaptureError,
          progressID: progressID
        )
      }
    } catch {
      isRecordingMeeting = false
      isMeetingRecordingPaused = false
      if isCapturingSystemAudio {
        _ = try? await meetingSystemAudioRecorder.stopRecording()
      }
      isCapturingSystemAudio = false
      meetingSystemAudioStatusText = "System audio not recording"
      stopMeetingInputMetering()
      errorText = error.localizedDescription
      meetingStatusText = "Stop failed: \(error.localizedDescription)"
      statusText = "Recording stop failed"
    }
  }

  public func pauseMeetingRecording() async {
    guard isRecordingMeeting, !isMeetingRecordingPaused else { return }
    guard let activeMeetingRecording else {
      meetingStatusText = "No active recording"
      return
    }

    do {
      try meetingRecorder.pauseRecording()
      if activeMeetingRecording.capturesSystemAudio {
        try await meetingSystemAudioRecorder.pauseRecording()
      }
      isMeetingRecordingPaused = true
      stopMeetingInputMetering()
      meetingStatusText = "Paused \(activeMeetingRecording.paths.title)"
      statusText = meetingStatusText
    } catch {
      errorText = error.localizedDescription
      meetingStatusText = "Pause failed: \(error.localizedDescription)"
      statusText = "Recording pause failed"
    }
  }

  public func resumeMeetingRecording() async {
    guard isRecordingMeeting, isMeetingRecordingPaused else { return }
    guard let activeMeetingRecording else {
      meetingStatusText = "No active recording"
      return
    }

    do {
      try meetingRecorder.resumeRecording()
      if activeMeetingRecording.capturesSystemAudio {
        try await meetingSystemAudioRecorder.resumeRecording()
      }
      isMeetingRecordingPaused = false
      startMeetingInputMetering()
      meetingStatusText = "Recording \(activeMeetingRecording.paths.title)"
      statusText = meetingStatusText
    } catch {
      errorText = error.localizedDescription
      meetingStatusText = "Resume failed: \(error.localizedDescription)"
      statusText = "Recording resume failed"
    }
  }

  private func finishStoppedMeetingRecording(
    _ recording: PendingMeetingRecording,
    corpusRoot: URL,
    duration: TimeInterval,
    systemAudioURL: URL?,
    systemAudioCaptureError: String?,
    progressID: UUID
  ) async {
    defer {
      endMeetingProcessing(paths: recording.paths)
      stopMeetingTranscriptionProgress(id: progressID)
    }

    do {
      let transcript = await transcribeRecordedMeetingAudio(
        microphoneAudioURL: recording.paths.audioURL,
        systemAudioURL: systemAudioURL,
        systemAudioCaptureError: systemAudioCaptureError
      )
      let bundle = try MeetingArtifactWriter.writeArtifacts(
        paths: recording.paths,
        corpusRoot: corpusRoot,
        duration: duration,
        transcript: transcript,
        systemAudioURL: systemAudioURL
      )
      meetingTitleDraft = ""
      meetingSystemAudioStatusText = systemAudioURL == nil
        ? "System audio not captured"
        : "System audio saved"
      let completionText = transcript.status == .complete
        ? "Saved \(bundle.noteURL.lastPathComponent)"
        : "Saved \(bundle.noteURL.lastPathComponent); transcription \(transcript.status.label)"
      if !isRecordingMeeting {
        meetingStatusText = completionText
      }
      statusText = completionText
      await refreshAfterMeetingWrite(selecting: bundle.item)
    } catch {
      errorText = error.localizedDescription
      let failureText = "Meeting save failed: \(error.localizedDescription)"
      if !isRecordingMeeting {
        meetingStatusText = failureText
      }
      statusText = "Meeting save failed"
    }
  }

  private func recoverInterruptedMeetingTranscriptions(knownItems: [MeetingWorkspaceItem]) {
    guard let corpusRoot else { return }
    Task { [weak self] in
      guard let self else { return }
      let recoverable: [RecoverableMeetingRecording]
      do {
        recoverable = try await Task.detached(priority: .utility) {
          try Self.scanRecoverableMeetingRecordings(corpusRoot: corpusRoot)
        }.value
      } catch {
        await MainActor.run {
          self.errorText = error.localizedDescription
          self.statusText = "Meeting recovery scan failed"
        }
        return
      }

      await MainActor.run {
        self.startRecoveringInterruptedMeetings(recoverable, knownItems: knownItems, corpusRoot: corpusRoot)
      }
    }
  }

  private func startRecoveringInterruptedMeetings(
    _ recoverable: [RecoverableMeetingRecording],
    knownItems: [MeetingWorkspaceItem],
    corpusRoot: URL
  ) {
    guard !recoverable.isEmpty else { return }
    let knownAudioArtifacts = Set(knownItems.compactMap(\.audioArtifact))
    let activeRecordingPaths = meetingRecordingRecoveryExclusionPaths
      ?? activeMeetingRecording?.paths

    for recording in recoverable {
      guard Self.shouldRecoverMeetingRecording(
        recording.paths,
        activeRecordingPaths: activeRecordingPaths
      ) else {
        continue
      }
      let processingID = Self.meetingProcessingID(for: recording.paths)
      guard !activeMeetingProcessingIDs.contains(processingID) else { continue }
      let relativeAudio = MeetingArtifactWriter.relativePath(from: corpusRoot, to: recording.paths.audioURL)
      guard !knownAudioArtifacts.contains(relativeAudio) else { continue }

      beginMeetingProcessing(
        paths: recording.paths,
        status: "Resuming transcription for \(recording.paths.title)..."
      )
      let progressID = startMeetingTranscriptionProgress(
        title: recording.paths.title,
        audioDuration: recording.duration
      )
      Task { [weak self] in
        await self?.finishRecoveredMeetingRecording(
          recording,
          corpusRoot: corpusRoot,
          progressID: progressID
        )
      }
    }
  }

  private func finishRecoveredMeetingRecording(
    _ recording: RecoverableMeetingRecording,
    corpusRoot: URL,
    progressID: UUID
  ) async {
    defer {
      endMeetingProcessing(paths: recording.paths)
      stopMeetingTranscriptionProgress(id: progressID)
    }

    let transcript = await transcribeRecordedMeetingAudio(
      microphoneAudioURL: recording.paths.audioURL,
      systemAudioURL: recording.systemAudioURL,
      systemAudioCaptureError: recording.systemAudioCaptureError
    )

    do {
      let bundle = try MeetingArtifactWriter.writeArtifacts(
        paths: recording.paths,
        corpusRoot: corpusRoot,
        duration: recording.duration,
        transcript: transcript,
        systemAudioURL: recording.systemAudioURL,
        captureSources: recording.captureSources
      )
      let completionText = transcript.status == .complete
        ? "Recovered \(bundle.noteURL.lastPathComponent)"
        : "Recovered \(bundle.noteURL.lastPathComponent); transcription \(transcript.status.label)"
      if !isRecordingMeeting {
        meetingStatusText = completionText
      }
      statusText = completionText
      await refreshAfterMeetingWrite(selecting: bundle.item)
    } catch {
      errorText = error.localizedDescription
      let failureText = "Meeting recovery failed: \(error.localizedDescription)"
      if !isRecordingMeeting {
        meetingStatusText = failureText
      }
      statusText = "Meeting recovery failed"
    }
  }

  public func promptAndImportMeetingAudio() {
    guard corpusRoot != nil else {
      statusText = "No corpus selected"
      return
    }
    guard !isRecordingMeeting else { return }

    let panel = NSOpenPanel()
    panel.canChooseFiles = true
    panel.canChooseDirectories = false
    panel.allowsMultipleSelection = false
    panel.allowedContentTypes = [.audio, .movie]
    panel.prompt = "Import"
    panel.message = "Choose an audio or video file to transcribe into an Org2 meeting."

    if panel.runModal() == .OK, let url = panel.url {
      let title = meetingTitleDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        ? url.deletingPathExtension().lastPathComponent.replacingOccurrences(of: "-", with: " ")
        : meetingTitleDraft
      Task { await importMeetingAudio(url: url, title: title) }
    }
  }

  public func importMeetingAudio(url sourceURL: URL, title rawTitle: String) async {
    guard let corpusRoot else {
      statusText = "No corpus selected"
      return
    }
    guard !isRecordingMeeting else {
      meetingStatusText = "Stop the active recording before importing audio"
      return
    }

    var processingPaths: MeetingArtifactPaths?
    var progressID: UUID?
    defer {
      if let processingPaths {
        endMeetingProcessing(paths: processingPaths)
      }
      if let progressID {
        stopMeetingTranscriptionProgress(id: progressID)
      }
    }
    let recordedAt = Date()

    do {
      let ext = sourceURL.pathExtension.isEmpty ? "m4a" : sourceURL.pathExtension.lowercased()
      let paths = try MeetingArtifactWriter.preparePaths(
        corpusRoot: corpusRoot,
        title: rawTitle,
        recordedAt: recordedAt,
        audioExtension: ext
      )
      processingPaths = paths
      beginMeetingProcessing(paths: paths, status: "Importing \(paths.title)...")
      try FileManager.default.copyItem(at: sourceURL, to: paths.audioURL)
      meetingStatusText = "Transcribing \(paths.title) locally..."
      progressID = startMeetingTranscriptionProgress(title: paths.title, audioDuration: nil)
      let transcript = await transcribeAudioForMeeting(paths.audioURL)
      let bundle = try MeetingArtifactWriter.writeArtifacts(
        paths: paths,
        corpusRoot: corpusRoot,
        duration: nil,
        transcript: transcript,
        captureSources: "imported_audio"
      )
      meetingTitleDraft = ""
      meetingStatusText = transcript.status == .complete
        ? "Imported \(bundle.noteURL.lastPathComponent)"
        : "Imported \(bundle.noteURL.lastPathComponent); transcription \(transcript.status.label)"
      statusText = meetingStatusText
      await refreshAfterMeetingWrite(selecting: bundle.item)
    } catch {
      errorText = error.localizedDescription
      meetingStatusText = "Import failed: \(error.localizedDescription)"
      statusText = "Meeting import failed"
    }
  }

  public func selectMeeting(_ meeting: MeetingWorkspaceItem) {
    select(.meeting(meeting), surface: .meetings)
  }

  public func askOpenClawAboutSelectedMeeting(threadMode: OpenClawThreadMode = .newThread) {
    guard case .meeting(let meeting) = selectedLocation else {
      statusText = "Select a meeting first"
      return
    }
    prepareOpenClawThread(
      mode: threadMode,
      title: "Meeting: \(Org2Display.cleanInline(meeting.title))",
      statusText: "New OpenClaw meeting chat"
    )
    let pointer = openClawContextPointer(for: .meeting(meeting))
    publishOpenClawComposerDraft(automaticOpenClawActionText(
      pointer,
      prompt: "Use the selected meeting note and transcript artifact as context. Summarize the meeting, extract decisions, list action items, and cite the org2 file paths you used."
    ))
    navigateToSurface(.openClaw)
  }

  public func confirmAndDeleteMeeting(_ meeting: MeetingWorkspaceItem) {
    let alert = NSAlert()
    alert.alertStyle = .warning
    alert.messageText = "Delete Meeting?"
    alert.informativeText = "This deletes the meeting note and any linked audio/transcript artifacts from the corpus."
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }
    Task { await deleteMeeting(meeting) }
  }

  public func deleteMeeting(_ meeting: MeetingWorkspaceItem) async {
    guard let corpusRoot else {
      statusText = "No corpus selected"
      return
    }

    let urls = meetingArtifactURLs(for: meeting, corpusRoot: corpusRoot)
    do {
      for url in urls {
        if FileManager.default.fileExists(atPath: url.path) {
          try FileManager.default.removeItem(at: url)
        }
      }
      meetings.removeAll { $0.id == meeting.id }
      if selectedMeetingID == meeting.id {
        selectedMeetingID = nil
      }
      if selectedLocation?.file == meeting.file {
        selectedLocation = nil
        selectedEntrySource = nil
      }
      statusText = "Deleted \(Org2Display.cleanInline(meeting.title))"
      meetingStatusText = statusText
      await refreshMeetings()
      await refreshAgenda()
      Task { await refreshOpenClawThreads(showsLoading: false) }
    } catch {
      errorText = error.localizedDescription
      statusText = "Meeting delete failed"
      meetingStatusText = "Delete failed: \(error.localizedDescription)"
    }
  }

