  public func startNewAIThread(from location: WorkspaceLocation) {
    if case .agenda(let item) = location {
      startNewAIThreadFromAgendaSelection(including: item)
      return
    }
    startNewAIThread(with: [openClawContextPointer(for: location)])
  }

  public func startNewAIThreadFromAgendaSelection(including item: AgendaItem) {
    let items: [AgendaItem]
    if bulkSelectedAgendaItemIDs.contains(item.id) {
      items = visibleAgendaItems.filter { bulkSelectedAgendaItemIDs.contains($0.id) }
    } else {
      items = [item]
    }
    startNewAIThread(with: items.map { openClawContextPointer(for: WorkspaceLocation.agenda($0)) })
  }

  public func startNewAIThreadFromAgentRunSelection(including run: AgentRunItem) {
    let runs: [AgentRunItem]
    if selectedAgentRunIDsForAIContext.contains(run.id) {
      runs = agentRuns.filter { selectedAgentRunIDsForAIContext.contains($0.id) }
    } else {
      runs = [run]
    }
    startNewAIThread(with: runs.compactMap { openClawContextPointer(for: $0, requiresExistingRecord: false) })
  }

  public func startNewAIThreadFromApprovalSelection(including item: ApprovalItem) {
    let items: [ApprovalItem]
    if selectedApprovalItemIDsForAIContext.contains(item.id) {
      items = approvalItems.filter { selectedApprovalItemIDsForAIContext.contains($0.id) }
    } else {
      items = [item]
    }
    startNewAIThread(with: items.map(openClawContextPointer(for:)))
  }

  public func startNewAIThreadFromCorpusFileSelection(including file: CorpusFile) {
    let files: [CorpusFile]
    if selectedCorpusFileIDsForAIContext.contains(file.id) {
      files = corpusFiles.filter { selectedCorpusFileIDsForAIContext.contains($0.id) }
    } else {
      files = [file]
    }
    startNewAIThread(with: files.map(openClawContextPointer(for:)))
  }

  func openClawDraftByAddingCorpusFileContext(_ file: CorpusFile, to draft: String) -> String {
    let pointer = openClawContextPointer(for: file)
    guard !OpenClawContextPresentation(draft).contexts.contains(where: {
      $0.reference == pointer.reference
    }) else {
      return draft
    }
    return injectedOpenClawContext(pointer) + draft
  }

  public func askOpenClawAboutCurrentSelection(threadMode: OpenClawThreadMode = .newThread) {
    guard let pointer = openClawContextPointerForCurrentSelection() else {
      statusText = "Select a page or entry first"
      return
    }

    addOpenClawContext(pointer, threadMode: threadMode)
  }

  public func askOpenClawAboutBlock(_ block: OrgEditableBlock, threadMode: OpenClawThreadMode = .newThread) {
    if selectedRenderedBlockIndexes[block.id] != nil {
      selectedBlockID = block.id
    }

    guard let pointer = openClawContextPointer(for: OpenClawBlockContextPointer(source: selectedEntrySource, block: block)) else {
      askOpenClawAboutCurrentSelection(threadMode: threadMode)
      return
    }

    addOpenClawContext(pointer, threadMode: threadMode)
  }

  public func askOpenClawAboutSourceHeading(at line: Int) {
    guard let source = selectedEntrySource else {
      statusText = "No source loaded"
      return
    }
    if let block = Self.sourceAIContextBlock(at: line, in: selectedRenderedBlocks) {
      askOpenClawAboutBlock(block)
      return
    }

    Task { @MainActor [weak self] in
      let blocks = await Task.detached(priority: .userInitiated) {
        OrgEntryRenderer.parseEditable(source.text, baseLine: source.startLine)
      }.value
      guard let self, self.selectedEntrySource?.id == source.id else { return }
      guard let block = Self.sourceAIContextBlock(at: line, in: blocks) else {
        self.statusText = "Could not resolve that section"
        return
      }
      self.askOpenClawAboutBlock(block)
    }
  }

  func performRenderedEntryAction(_ action: OrgHTMLRenderedEntryAction, at line: Int) {
    guard let block = renderedHeadingBlock(at: line) else {
      statusText = "Could not resolve that entry"
      return
    }

    switch action {
    case .entryView:
      openRenderedEntryView(block)
    case .edit:
      beginEditingSource(for: block)
    case .askAI:
      askOpenClawAboutBlock(block)
    case .refile:
      presentRenderedEntryRefile(block)
    case .schedule(let target):
      guard let location = renderedHeadingLocation(for: block) else { return }
      Task { await applyPlanningShortcut(kind: .scheduled, target: target, to: location) }
    case .todo(let status):
      guard let location = renderedHeadingLocation(for: block) else { return }
      Task { await applyTodoShortcut(status, to: location) }
    case .deadline(let target):
      guard let location = renderedHeadingLocation(for: block) else { return }
      Task { await applyPlanningShortcut(kind: .deadline, target: target, to: location) }
    case .priority(let priority):
      guard let location = renderedHeadingLocation(for: block) else { return }
      Task { await applyPriorityShortcut(priority, to: location) }
    case .encrypt:
      Task { await runOrgCrypt(.encrypt, line: block.startLine) }
    case .decrypt:
      Task { await runOrgCrypt(.decrypt, line: block.startLine) }
    case .copy:
      copyRenderedEntry(block)
    case .cut:
      Task { await cutRenderedEntry(block) }
    case .copyReference:
      guard let source = selectedEntrySource else { return }
      copyFileReference(path: source.file, line: block.startLine)
    case .delete:
      confirmAndDeleteRenderedEntry(block)
    }
  }

  private func renderedHeadingBlock(at line: Int) -> OrgEditableBlock? {
    let blocks: [OrgEditableBlock]
    if !selectedRenderedBlocks.isEmpty {
      blocks = selectedRenderedBlocks
    } else if let source = selectedEntrySource {
      blocks = OrgEntryRenderer.parseEditable(source.text, baseLine: source.startLine)
    } else {
      return nil
    }
    return blocks.first { block in
      block.startLine == line && {
        if case .heading = block.rendered { return true }
        return false
      }()
    }
  }

  private func renderedHeadingLocation(for block: OrgEditableBlock) -> WorkspaceLocation? {
    guard let source = selectedEntrySource,
          source.isEditable,
          case .heading(let heading) = block.rendered
    else {
      statusText = "This entry is read-only"
      return nil
    }
    let title = Org2Display.cleanInline(heading.title).trimmingCharacters(in: .whitespacesAndNewlines)
    return .openClaw(OpenClawThread(
      title: title.isEmpty ? relativePath(source.file) : title,
      file: source.file,
      line: block.startLine,
      zone: "entry",
      modifiedAt: nil,
      idValue: nil
    ))
  }

  private func openRenderedEntryView(_ block: OrgEditableBlock) {
    guard let location = renderedHeadingLocation(for: block) else { return }
    activateDetailLocation(location, mode: .entry, surface: nil, recordsHistory: true)
    statusText = "Opened entry view"
  }

  private func copyRenderedEntry(_ block: OrgEditableBlock) {
    guard let source = selectedEntrySource else {
      statusText = "No source loaded"
      return
    }
    do {
      let text = try Self.renderedEntrySubtreeText(for: block, in: source)
      NSPasteboard.general.clearContents()
      NSPasteboard.general.setString(text, forType: .string)
      statusText = "Copied entry"
    } catch {
      errorText = error.localizedDescription
      statusText = "Copy failed"
    }
  }

  private func cutRenderedEntry(_ block: OrgEditableBlock) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "This entry is read-only"
      return
    }
    do {
      let text = try Self.renderedEntrySubtreeText(for: block, in: source)
      NSPasteboard.general.clearContents()
      NSPasteboard.general.setString(text, forType: .string)
      if await deleteBlock(block) {
        statusText = "Cut entry"
      }
    } catch {
      errorText = error.localizedDescription
      statusText = "Cut failed"
    }
  }

  private func confirmAndDeleteRenderedEntry(_ block: OrgEditableBlock) {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "This entry is read-only"
      return
    }
    let title: String
    if case .heading(let heading) = block.rendered {
      title = Org2Display.cleanInline(heading.title)
    } else {
      title = "this entry"
    }
    let alert = NSAlert()
    alert.alertStyle = .warning
    alert.messageText = "Delete \(title.isEmpty ? "this entry" : "“\(title)”")?"
    alert.informativeText = "This deletes the heading and its entire subtree. You can undo the change from the Edit menu."
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else {
      statusText = "Delete canceled"
      return
    }
    Task { await deleteBlock(block) }
  }

  private func presentRenderedEntryRefile(_ block: OrgEditableBlock) {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "This entry is read-only"
      return
    }
    let panel = NSOpenPanel()
    panel.title = "Move / Refile Entry"
    panel.message = "Choose the Org2 file where this entry should be appended."
    panel.prompt = "Refile"
    panel.canChooseDirectories = false
    panel.canChooseFiles = true
    panel.allowsMultipleSelection = false
    panel.directoryURL = corpusRoot
    panel.allowedContentTypes = [
      UTType(filenameExtension: "org2") ?? .plainText,
      UTType(filenameExtension: "org") ?? .plainText,
    ]
    guard panel.runModal() == .OK, let destination = panel.url else {
      statusText = "Refile canceled"
      return
    }
    guard destination.standardizedFileURL.path != URL(fileURLWithPath: source.file).standardizedFileURL.path else {
      statusText = "Choose a different file when refiling from the context menu"
      return
    }
    Task { await refileRenderedEntry(block, from: source, to: destination) }
  }

  private func refileRenderedEntry(
    _ block: OrgEditableBlock,
    from source: EntrySource,
    to destination: URL
  ) async {
    do {
      let payload: RefileMutationPayload = try await cli.runJSON([
        "refile",
        "--file", source.file,
        "--pos", "\(block.startLine)",
        "--to-file", destination.path,
        "--format", "json",
        "--apply",
      ])
      invalidateCanonicalDocumentCache(for: source.file)
      invalidateCanonicalDocumentCache(for: destination.path)
      if let selectedLocation, selectedEntrySource?.file == source.file {
        scheduleEntrySourceLoad(for: selectedLocation)
      }
      scheduleAgendaRefresh(preserveSelection: true)
      Task { await refreshCorpusFiles() }
      statusText = payload.changed
        ? "Refiled entry to \(relativePath(destination.path))"
        : "Entry was already in place"
    } catch {
      errorText = error.localizedDescription
      statusText = "Refile failed"
    }
  }

  nonisolated static func renderedEntrySubtreeText(
    for block: OrgEditableBlock,
    in source: EntrySource
  ) throws -> String {
    let range = try deletionRange(for: block, in: source)
    let lines = normalizeLineEndings(source.text)
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    let startIndex = range.startLine - source.startLine
    let endIndex = range.endLineExclusive - source.startLine
    guard startIndex >= 0,
          endIndex >= startIndex,
          endIndex <= lines.count
    else {
      throw WorkspaceEditError.invalidRange(file: source.file, line: block.startLine)
    }
    return lines[startIndex..<endIndex].joined(separator: "\n").trimmingCharacters(in: .newlines) + "\n"
  }

  nonisolated static func sourceAIContextBlock(
    at line: Int,
    in blocks: [OrgEditableBlock]
  ) -> OrgEditableBlock? {
    blocks.first { block in
      guard block.startLine == line else { return false }
      switch block.rendered {
      case .heading, .paragraph:
        return true
      default:
        return false
      }
    }
  }

  public func briefCurrentNode() async {
    guard let location = selectedLocation else {
      statusText = "Select a node first"
      return
    }
    guard let corpusRoot else {
      statusText = "Open a corpus first"
      return
    }

    let briefTitle = nodeBriefDisplayTitle(for: location)
    if let artifact = nodeBriefArtifact(for: location) {
      openNodeBriefArtifact(
        url: URL(fileURLWithPath: artifact.file).standardizedFileURL,
        relativePath: artifact.relativePath,
        title: briefTitle
      )
      return
    }

    isBuildingNodeBrief = true
    openClawStatusText = "Sending node brief request..."
    statusText = "Sending node brief request..."
    defer { isBuildingNodeBrief = false }

    do {
      let id = try await backlinkTargetID(for: location)
      if let artifact = nodeBriefArtifact(for: location, sourceID: id) {
        openNodeBriefArtifact(
          url: URL(fileURLWithPath: artifact.file).standardizedFileURL,
          relativePath: artifact.relativePath,
          title: briefTitle
        )
        return
      }
      let artifactRelativePath = Self.nodeBriefArtifactRelativePath(
        id: id,
        file: relativePath(location.file),
        line: location.lineForEditor
      )
      let artifactURL = corpusRoot.appendingPathComponent(artifactRelativePath).standardizedFileURL
      if Self.hasUsableNodeBriefArtifact(at: artifactURL) {
        openNodeBriefArtifact(url: artifactURL, relativePath: artifactRelativePath, title: briefTitle)
        return
      }

      let prompt = Self.nodeBriefPrompt(
        title: briefTitle,
        reference: "\(relativePath(location.file)):\(location.lineForEditor)",
        artifactRelativePath: artifactRelativePath,
        artifactLocalPath: artifactURL.path,
        artifactRuntimePath: mappedPathForOpenClaw(artifactURL.path),
        sourceID: id
      )
      pendingNodeBriefArtifactRelativePath = artifactRelativePath
      pendingNodeBriefTitle = briefTitle
      setOpenClawAssistantPanelPresented(true)
      prepareOpenClawThreadForNodeBrief(title: briefTitle)
      let runtimeTitle = selectedAIChatRuntime.title
      let briefContext: OpenClawWorkspaceContext?
      if let thread = selectedOpenClawChatThread {
        briefContext = currentOpenClawWorkspaceContext(
          threadContinuation: aiChatThreadContinuation(for: thread)
        )
      } else {
        briefContext = nil
      }
      await sendOpenClawMessage(
        automaticOpenClawActionText(
          openClawContextPointer(for: location),
          prompt: prompt
        ),
        attachments: [],
        workspaceContext: briefContext
      )
      if await openNodeBriefArtifactWhenAvailable(url: artifactURL, relativePath: artifactRelativePath, title: briefTitle) {
        return
      }
      if openClawStatusText == "\(runtimeTitle) replied" || openClawStatusText.hasPrefix("Edited ") {
        pendingNodeBriefArtifactRelativePath = nil
        pendingNodeBriefTitle = nil
        openClawStatusText = "\(runtimeTitle) replied without writing the node brief artifact"
        statusText = "Node brief artifact was not written"
      }
    } catch {
      errorText = error.localizedDescription
      openClawStatusText = "Node brief failed"
      statusText = "Node brief failed"
    }
  }

  private func openNodeBriefArtifactWhenAvailable(url: URL, relativePath: String, title: String) async -> Bool {
    let expectedPath = url.standardizedFileURL.path
    for delay in Self.nodeBriefArtifactRetryDelays {
      if delay > 0 {
        try? await Task.sleep(nanoseconds: delay)
      }
      if case .openClaw(let thread) = selectedLocation,
         URL(fileURLWithPath: thread.file).standardizedFileURL.path == expectedPath {
        return true
      }
      guard Self.hasUsableNodeBriefArtifact(at: url) else { continue }
      await refreshCorpusFiles()
      Task { await refreshOpenClawThreads(showsLoading: false) }
      openNodeBriefArtifact(url: url, relativePath: relativePath, title: title)
      return true
    }
    return false
  }

  private func rebuildMeetingDisplayCache() {
    let grouped = Dictionary(grouping: meetings) { item -> String in
      guard let recordedAt = item.recordedAt, recordedAt.count >= 10 else {
        return "Unknown date"
      }
      return String(recordedAt.prefix(10))
    }
    meetingDisplaySections = grouped.keys.sorted(by: >).map { key in
      let items = (grouped[key] ?? []).sorted {
        ($0.recordedAt ?? "") > ($1.recordedAt ?? "")
      }
      return MeetingSection(id: key, label: key, meetings: items)
    }
  }

  public var pendingMeetingProcessingItems: [MeetingProcessingItem] {
    let existingMeetingIDs = Set(meetings.map(Self.meetingProcessingID(for:)))
    return processingMeetings.filter { !existingMeetingIDs.contains($0.id) }
  }

  public func isMeetingProcessing(_ meeting: MeetingWorkspaceItem) -> Bool {
    activeMeetingProcessingIDs.contains(Self.meetingProcessingID(for: meeting))
  }

  public func select(_ location: WorkspaceLocation, surface: WorkspaceSurface? = nil) {
    let nextMode = resolvedEntrySourceMode(for: location, requestedMode: nil)
    let nextSurface = surface ?? selectedSurface
    if isCurrentNavigationDestination(
      location: location,
      surface: nextSurface,
      mode: nextMode
    ), !isWorkspaceDetailPaneClosed {
      applyDetailSelectionMetadata(for: location)
      return
    }

    if case .search = location {
      isPageSearchPresented = false
      pageSearchQuery = ""
      renderedSearchHighlightQuery = Self.normalizedRenderedSearchHighlightQuery(searchQuery)
      resetPageSearchMatches()
    } else {
      isPageSearchPresented = false
      pageSearchQuery = ""
      renderedSearchHighlightQuery = nil
      resetPageSearchMatches()
    }
    activateDetailLocation(location, mode: nil, surface: surface, recordsHistory: true)
  }

  public func selectSearchResult(_ result: SearchResult) {
    if activateCorpusIfNeeded(for: result.corpus, location: .search(result), surface: .search) {
      return
    }
    select(.search(result), surface: .search)
  }

  @discardableResult
  private func activateCorpusIfNeeded(
    for corpus: WorkspaceResultCorpus?,
    location: WorkspaceLocation,
    surface: WorkspaceSurface
  ) -> Bool {
    guard let corpus else { return false }
    let destination = URL(fileURLWithPath: corpus.root).standardizedFileURL
    guard destination.path != corpusRoot?.standardizedFileURL.path else { return false }
    guard !isSwitchingCorpus && !isRefreshingWorkspace else {
      statusText = "Wait for the current workspace refresh before opening another corpus."
      return true
    }
    guard !hasActiveEdit && !liveFileEditorHasUnsavedChanges else {
      errorText = "Save or cancel the current edit before opening another corpus."
      statusText = "Unsaved edit"
      return true
    }
    guard isDirectory(destination.path) else {
      errorText = "The mounted corpus is not available at \(destination.path)."
      statusText = "Corpus unavailable"
      return true
    }

    isSwitchingCorpus = true
    setCorpusRoot(destination)
    statusText = "Opening \(corpus.name)..."
    Task { @MainActor [weak self] in
      guard let self else { return }
      await self.refreshWorkspace()
      if case .search = location,
         !self.searchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        await self.runSearch()
      }
      self.isSwitchingCorpus = false
      self.select(location, surface: surface)
      self.statusText = "Opened \(corpus.name)"
    }
    return true
  }

  public func isResultInActiveCorpus(_ corpus: WorkspaceResultCorpus?) -> Bool {
    guard let corpus else { return true }
    return URL(fileURLWithPath: corpus.root).standardizedFileURL.path == corpusRoot?.standardizedFileURL.path
  }

  public func corpusQualifiedPath(_ file: String, corpus: WorkspaceResultCorpus?) -> String {
    guard let corpus else { return relativePath(file) }
    let relative = Self.relativePath(for: file, root: URL(fileURLWithPath: corpus.root))
    return "\(corpus.name) · \(relative)"
  }

