  @discardableResult
  public func focusPageSearch() -> Bool {
    guard selectedLocation != nil else { return false }
    isPageSearchPresented = true
    pageSearchQuery = renderedSearchHighlightQuery ?? ""
    schedulePageSearchRefresh(selectFirst: true, debounce: false)
    pageSearchFocusToken += 1
    return true
  }

  public var pageSearchOccurrenceSummary: String {
    guard let query = Self.normalizedRenderedSearchHighlightQuery(pageSearchQuery) else { return "" }
    guard query == renderedSearchHighlightQuery else { return "Searching…" }
    let total = max(pageSearchOccurrenceCount, pageSearchRenderedMatches.count)
    guard total > 0 else { return "0 matches" }
    if let pageSearchSelectedOccurrenceIndex {
      return "\(min(pageSearchSelectedOccurrenceIndex + 1, total)) of \(total)"
    }
    return "\(total) matches"
  }

  public var canNavigatePageSearchOccurrences: Bool {
    Self.normalizedRenderedSearchHighlightQuery(pageSearchQuery) == renderedSearchHighlightQuery
      && pageSearchRenderedMatches.count > 1
  }

  public func selectNextPageSearchOccurrence() {
    selectAdjacentPageSearchOccurrence(delta: 1)
  }

  public func selectPreviousPageSearchOccurrence() {
    selectAdjacentPageSearchOccurrence(delta: -1)
  }

  private func selectAdjacentPageSearchOccurrence(delta: Int) {
    guard Self.normalizedRenderedSearchHighlightQuery(pageSearchQuery) == renderedSearchHighlightQuery else {
      schedulePageSearchRefresh(selectFirst: true, debounce: false)
      return
    }
    guard !pageSearchRenderedMatches.isEmpty else { return }
    let current = pageSearchSelectedOccurrenceIndex ?? 0
    let count = pageSearchRenderedMatches.count
    let next = (current + delta + count) % count
    selectPageSearchOccurrence(at: next)
  }

  private func schedulePageSearchRefresh(selectFirst: Bool, debounce: Bool = true) {
    pageSearchRefreshGeneration += 1
    let generation = pageSearchRefreshGeneration
    pageSearchRefreshTask?.cancel()

    guard let query = Self.normalizedRenderedSearchHighlightQuery(pageSearchQuery) else {
      renderedSearchHighlightQuery = nil
      resetPageSearchMatches()
      pageSearchRefreshTask = nil
      return
    }

    let blocks = selectedRenderedBlocks
    let fallbackText = selectedEntrySource?.text ?? ""
    let liveText = isLiveFileEditorSelected ? editableEntryText : nil
    let filePath = isLiveFileEditorSelected ? nil : selectedEntrySource?.file
    pageSearchRefreshTask = Task { [blocks, fallbackText, filePath, generation, liveText, query] in
      if debounce {
        try? await Task.sleep(nanoseconds: 80_000_000)
      }
      guard !Task.isCancelled else { return }

      let result = await Task.detached(priority: .userInitiated) {
        let text: String
        if let liveText {
          text = liveText
        } else if let filePath,
                  let fileText = try? String(contentsOf: URL(fileURLWithPath: filePath), encoding: .utf8) {
          text = fileText
        } else {
          text = fallbackText
        }
        return PageSearchComputation(
          matches: Self.renderedPageSearchMatches(in: blocks, query: query),
          occurrenceCount: Self.countSearchOccurrences(in: text, query: query)
        )
      }.value
      guard !Task.isCancelled else { return }

      await MainActor.run { [weak self] in
        guard let self,
              self.pageSearchRefreshGeneration == generation,
              Self.normalizedRenderedSearchHighlightQuery(self.pageSearchQuery) == query,
              self.isPageSearchPresented
        else { return }
        self.renderedSearchHighlightQuery = query
        self.pageSearchRenderedMatches = result.matches
        self.pageSearchOccurrenceCount = result.occurrenceCount
        self.pageSearchRefreshTask = nil

        guard !result.matches.isEmpty else {
          self.pageSearchSelectedOccurrenceIndex = nil
          return
        }
        let nextIndex = selectFirst
          ? 0
          : min(self.pageSearchSelectedOccurrenceIndex ?? 0, result.matches.count - 1)
        self.selectPageSearchOccurrence(at: nextIndex)
      }
    }
  }

  private func resetPageSearchMatches() {
    pageSearchRefreshGeneration += 1
    pageSearchRefreshTask?.cancel()
    pageSearchRefreshTask = nil
    pageSearchRenderedMatches = []
    pageSearchOccurrenceCount = 0
    pageSearchSelectedOccurrenceIndex = nil
  }

  private func selectPageSearchOccurrence(at index: Int) {
    guard pageSearchRenderedMatches.indices.contains(index) else { return }
    let match = pageSearchRenderedMatches[index]
    pageSearchSelectedOccurrenceIndex = index
    selectedBlockID = match.blockID
    requestDetailScroll(toBlock: match.blockID)
  }

  public func navigateBack() {
    guard let snapshot = workspaceNavigationBackStack.popLast() else { return }
    if let runID = snapshot.agentRunDetailID,
       agentRuns.contains(where: { $0.id == runID }) {
      activateAgentRunDetail(runID, recordsHistory: false)
    } else if let location = snapshot.location {
      activateDetailLocation(
        location,
        mode: snapshot.selectedEntrySourceMode,
        surface: snapshot.selectedSurface,
        recordsHistory: false
      )
    } else {
      selectedSurface = snapshot.selectedSurface
      clearDetailForNavigation()
    }
    restoreWorkspaceSelection(from: snapshot)
    restoreWorkspacePaneLayout(from: snapshot)
  }

  private func activateDetailLocation(
    _ location: WorkspaceLocation,
    mode: EntrySourceMode?,
    surface: WorkspaceSurface?,
    recordsHistory: Bool
  ) {
    let nextMode = resolvedEntrySourceMode(for: location, requestedMode: mode)
    let nextSurface = surface ?? selectedSurface
    if recordsHistory,
       !isCurrentNavigationDestination(
         location: location,
         surface: nextSurface,
         mode: nextMode
       ),
       hasWorkspaceDetailContent || selectedSurface != nextSurface {
      recordCurrentNavigationDestination()
    }
    if presentedAgentRunID != nil { presentedAgentRunID = nil }
    if selectedSurface != nextSurface { selectedSurface = nextSurface }
    if isWorkspaceDetailPaneClosed { isWorkspaceDetailPaneClosed = false }
    if isWorkspaceDetailPaneExpanded { isWorkspaceDetailPaneExpanded = false }
    if canReuseActiveDetail(for: location, mode: nextMode) {
      applyDetailSelectionMetadata(for: location)
      selectedLocation = location
      scheduleSelectedDetailFreshnessCheck(for: location, mode: nextMode)
      return
    }

    persistLiveFileEditorDraftBeforeNavigation()
    cancelLiveFileEditorAutosave(resetStatus: false)
    switch location {
    case .search:
      break
    default:
      isPageSearchPresented = false
      pageSearchQuery = ""
      renderedSearchHighlightQuery = nil
      resetPageSearchMatches()
    }

    applyDetailSelectionMetadata(for: location)
    selectedLocation = location
    detailScrollRequest = nil
    cancelSourceEditorPreviewRender(clearStatus: true)
    cancelLinkedPDFPreview(clearStatus: true)
    isEditingEntry = false
    editableEntryText = ""
    sourceEditorSelection = NSRange(location: 0, length: 0)
    resetBlockState()
    selectedEntrySourceMode = nextMode
    selectedEntrySource = nil
    selectedEntryHTML = nil
    selectedEntryRenderError = nil
    entityActionItemsLoadGeneration += 1
    entityActionItems = nil
    isLoadingEntityActionItems = false
    selectedEntryHTMLRenderKey = nil
    selectedRenderedBlocks = []
    entryHTMLRenderTask?.cancel()
    entryHTMLRenderTask = nil
    entryHTMLRenderWatchdogTask?.cancel()
    entryHTMLRenderWatchdogTask = nil
    isRenderingEntrySource = false
    entryHTMLRenderGeneration += 1
    if Self.isPDFFile(location.file) {
      cancelBacklinksLoad(clearResults: true)
      scheduleLinkedPDFPreviewLoad(for: location)
    } else {
      scheduleBacklinksLoad(for: location)
      scheduleEntrySourceLoad(for: location)
    }
  }

  private func recordCurrentNavigationDestination() {
    let snapshot = currentWorkspaceNavigationSnapshot()
    guard workspaceNavigationBackStack.last != snapshot else { return }
    workspaceNavigationBackStack.append(snapshot)
    if workspaceNavigationBackStack.count > Self.detailNavigationHistoryLimit {
      workspaceNavigationBackStack.removeFirst(
        workspaceNavigationBackStack.count - Self.detailNavigationHistoryLimit
      )
    }
  }

  private func currentWorkspaceNavigationSnapshot() -> WorkspaceNavigationSnapshot {
    let locationAgendaItemID: String? = {
      guard case .agenda(let item) = selectedLocation else { return nil }
      return item.id
    }()
    let locationAssignedItemID: AssignedWorkItem.ID? = {
      guard case .assigned(let item) = selectedLocation else { return nil }
      return item.id
    }()
    let locationApprovalItemID: ApprovalItem.ID? = {
      guard selectedSurface == .approvals, let selectedLocation else { return nil }
      return approvalItems.first(where: {
        $0.file == selectedLocation.file && $0.line == selectedLocation.lineForEditor
      })?.id
    }()
    let locationCorpusFileID: String? = {
      guard selectedSurface == .files, let selectedLocation else { return nil }
      return corpusFiles.first(where: { $0.path == selectedLocation.file })?.id
    }()
    let locationMeetingID: String? = {
      guard case .meeting(let meeting) = selectedLocation else { return nil }
      return meeting.id
    }()

    return WorkspaceNavigationSnapshot(
      location: selectedLocation,
      agentRunDetailID: presentedAgentRunID,
      selectedSurface: selectedSurface,
      selectedEntrySourceMode: selectedEntrySourceMode,
      expandedWorkspaceSurface: expandedWorkspaceSurface,
      isWorkspaceSurfacePaneClosed: isWorkspaceSurfacePaneClosed,
      isWorkspaceDetailPaneClosed: isWorkspaceDetailPaneClosed,
      isWorkspaceDetailPaneExpanded: isWorkspaceDetailPaneExpanded,
      isOpenClawAssistantPresented: isOpenClawAssistantPresented,
      isNodeContextPanePresented: isNodeContextPanePresented,
      selectedAgendaItemID: locationAgendaItemID ?? selectedAgendaItemID,
      selectedAssignedWorkItemID: locationAssignedItemID ?? selectedAssignedWorkItemID,
      selectedApprovalItemID: locationApprovalItemID ?? selectedApprovalItemID,
      selectedCorpusFileID: locationCorpusFileID ?? selectedCorpusFileID,
      selectedMeetingID: locationMeetingID ?? selectedMeetingID,
      selectedOpenClawChatThreadID: selectedOpenClawChatThreadID
    )
  }

  private func isCurrentNavigationDestination(
    location: WorkspaceLocation?,
    surface: WorkspaceSurface,
    mode: EntrySourceMode
  ) -> Bool {
    guard selectedSurface == surface,
          presentedAgentRunID == nil,
          selectedEntrySourceMode == mode
    else {
      return false
    }
    switch (selectedLocation, location) {
    case (nil, nil):
      return true
    case (.some(let current), .some(let next)):
      return Self.selectionIdentity(for: current) == Self.selectionIdentity(for: next)
    default:
      return false
    }
  }

  private func navigateToSurface(_ surface: WorkspaceSurface, recordsHistory: Bool = true) {
    if recordsHistory, selectedSurface != surface {
      recordCurrentNavigationDestination()
    }
    if selectedSurface != surface {
      selectedSurface = surface
    }
  }

  private func restoreWorkspaceSelection(from snapshot: WorkspaceNavigationSnapshot) {
    selectedEntrySourceMode = snapshot.selectedEntrySourceMode
    selectedAgendaItemID = snapshot.selectedAgendaItemID
    agendaSelectionAnchor = selectedAgendaItemID.flatMap { selectedID in
      visibleAgendaItems.first(where: { $0.id == selectedID }).map(AgendaSelectionAnchor.init)
    }
    selectedAssignedWorkItemID = snapshot.selectedAssignedWorkItemID
    selectedApprovalItemID = snapshot.selectedApprovalItemID
    selectedCorpusFileID = snapshot.selectedCorpusFileID
    selectedMeetingID = snapshot.selectedMeetingID
    selectedAgentRunID = snapshot.agentRunDetailID ?? selectedAgentRunID
    if let threadID = snapshot.selectedOpenClawChatThreadID,
       openClawChatThreads.contains(where: { $0.id == threadID }) {
      selectOpenClawChatThread(threadID, persistsSelection: false)
    }
  }

  private func restoreWorkspacePaneLayout(from snapshot: WorkspaceNavigationSnapshot) {
    expandedWorkspaceSurface = snapshot.expandedWorkspaceSurface
    isWorkspaceSurfacePaneClosed = snapshot.isWorkspaceSurfacePaneClosed
    isWorkspaceDetailPaneClosed = snapshot.isWorkspaceDetailPaneClosed
    isWorkspaceDetailPaneExpanded = snapshot.isWorkspaceDetailPaneExpanded
    isOpenClawAssistantPresented = snapshot.isOpenClawAssistantPresented
    isNodeContextPanePresented = snapshot.isNodeContextPanePresented
    if snapshot.isNodeContextPanePresented, let selectedLocation {
      scheduleBacklinksLoad(for: selectedLocation)
    } else {
      cancelBacklinksLoad(clearResults: false)
    }
  }

  private func clearDetailForNavigation() {
    persistLiveFileEditorDraftBeforeNavigation()
    cancelLiveFileEditorAutosave(resetStatus: false)
    selectedLocation = nil
    presentedAgentRunID = nil
    cancelSourceEditorPreviewRender(clearStatus: true)
    cancelLinkedPDFPreview(clearStatus: true)
    selectedEntrySource = nil
    selectedEntryHTML = nil
    selectedEntryRenderError = nil
    selectedEntryHTMLRenderKey = nil
    selectedRenderedBlocks = []
    detailScrollRequest = nil
    entryHTMLRenderTask?.cancel()
    entryHTMLRenderTask = nil
    entryHTMLRenderWatchdogTask?.cancel()
    entryHTMLRenderWatchdogTask = nil
    isRenderingEntrySource = false
    entrySourceLoadWatchdogTask?.cancel()
    entrySourceLoadWatchdogTask = nil
    selectedDetailFreshnessTask?.cancel()
    selectedDetailFreshnessTask = nil
    activeEntrySourceLoadingGeneration = nil
    isLoadingEntrySource = false
    entrySourceLoadGeneration += 1
    cancelBacklinksLoad(clearResults: true)
    isEditingEntry = false
    editableEntryText = ""
    sourceEditorSelection = NSRange(location: 0, length: 0)
    resetBlockState()
    entryHTMLRenderGeneration += 1
  }

  private func resolvedEntrySourceMode(
    for location: WorkspaceLocation,
    requestedMode: EntrySourceMode?
  ) -> EntrySourceMode {
    if let requestedMode {
      return requestedMode
    }
    if case .meeting = location {
      return .page
    }
    return .entry
  }

  private func canReuseActiveDetail(for location: WorkspaceLocation, mode: EntrySourceMode) -> Bool {
    guard let selectedLocation,
          Self.selectionIdentity(for: selectedLocation) == Self.selectionIdentity(for: location),
          selectedEntrySourceMode == mode
    else {
      return false
    }
    if Self.isPDFFile(location.file) {
      return linkedPDFPreviewData != nil || isLoadingLinkedPDFPreview
    }
    return selectedEntrySource != nil || isRenderingEntrySource
  }

  private func scheduleSelectedDetailFreshnessCheck(
    for location: WorkspaceLocation,
    mode: EntrySourceMode
  ) {
    guard !Self.isPDFFile(location.file),
          editingBlockID == nil,
          !isEditingEntry,
          (!isLiveFileEditorSelected || !liveFileEditorHasUnsavedChanges)
    else { return }

    selectedDetailFreshnessTask?.cancel()
    selectedDetailFreshnessTask = Task { @MainActor [weak self] in
      guard let self else { return }
      let isCurrent = await self.cachedEntrySourceMatchesCurrentFileContents(
        for: location,
        mode: mode
      )
      guard !Task.isCancelled,
            self.selectedLocationMatches(location),
            self.selectedEntrySourceMode == mode
      else { return }
      self.selectedDetailFreshnessTask = nil
      guard !isCurrent else { return }
      self.invalidateCanonicalDocumentCache(for: location.file)
      await self.loadEntrySource(for: location)
    }
  }

  private func applyDetailSelectionMetadata(for location: WorkspaceLocation) {
    if case .agenda(let item) = location {
      if selectedAgendaItemID != item.id {
        selectedAgendaItemID = item.id
      }
      agendaSelectionAnchor = AgendaSelectionAnchor(item: item)
    }
    if case .assigned(let item) = location {
      if selectedAssignedWorkItemID != item.id {
        selectedAssignedWorkItemID = item.id
      }
    }
    if case .openClaw(let thread) = location {
      if selectedOpenClawThreadID != thread.id {
        selectedOpenClawThreadID = thread.id
      }
    }
    if case .meeting(let meeting) = location {
      if selectedMeetingID != meeting.id {
        selectedMeetingID = meeting.id
      }
    }
  }

  public func loadEntrySource(for location: WorkspaceLocation) async {
    if Self.isPDFFile(location.file) {
      linkedPDFLoadGeneration += 1
      await loadLinkedPDFPreview(for: location, generation: linkedPDFLoadGeneration)
      return
    }
    entrySourceLoadGeneration += 1
    let generation = entrySourceLoadGeneration
    await loadEntrySource(for: location, generation: generation, recoveryAttempt: 0)
  }

  private func scheduleEntrySourceLoad(for location: WorkspaceLocation) {
    entrySourceLoadGeneration += 1
    let generation = entrySourceLoadGeneration
    applyCachedEntrySourceIfAvailable(for: location, generation: generation)
    Task { await loadEntrySource(for: location, generation: generation, recoveryAttempt: 0) }
  }

  private func scheduleLinkedPDFPreviewLoad(for location: WorkspaceLocation) {
    linkedPDFLoadTask?.cancel()
    linkedPDFLoadGeneration += 1
    let generation = linkedPDFLoadGeneration
    linkedPDFLoadTask = Task { @MainActor [weak self] in
      await self?.loadLinkedPDFPreview(for: location, generation: generation)
    }
  }

  private func loadLinkedPDFPreview(
    for location: WorkspaceLocation,
    generation: Int
  ) async {
    guard generation == linkedPDFLoadGeneration,
          selectedLocationMatches(location),
          Self.isPDFFile(location.file)
    else { return }

    isLoadingLinkedPDFPreview = true
    linkedPDFPreviewError = nil
    defer {
      if generation == linkedPDFLoadGeneration {
        isLoadingLinkedPDFPreview = false
        linkedPDFLoadTask = nil
      }
    }

    do {
      let url = URL(fileURLWithPath: location.file).standardizedFileURL
      let loader = linkedPDFDataLoaderForTesting
      let data = try await Task.detached(priority: .userInitiated) {
        if let loader {
          return try await loader(url)
        }
        return try Data(contentsOf: url, options: .mappedIfSafe)
      }.value
      guard data.starts(with: Data("%PDF".utf8)) else {
        throw CocoaError(.fileReadCorruptFile)
      }
      guard generation == linkedPDFLoadGeneration,
            selectedLocationMatches(location)
      else { return }
      linkedPDFPreviewData = data
      linkedPDFPreviewError = nil
      errorText = nil
      statusText = "Opened \(relativePath(location.file))"
    } catch is CancellationError {
      return
    } catch {
      guard generation == linkedPDFLoadGeneration,
            selectedLocationMatches(location)
      else { return }
      linkedPDFPreviewData = nil
      linkedPDFPreviewError = "The linked PDF could not be loaded: \(error.localizedDescription)"
      errorText = linkedPDFPreviewError
      statusText = "PDF preview failed"
    }
  }

  public func retryLinkedPDFPreview() {
    guard let selectedLocation, Self.isPDFFile(selectedLocation.file) else { return }
    scheduleLinkedPDFPreviewLoad(for: selectedLocation)
  }

  public func cancelLinkedPDFPreview() {
    cancelLinkedPDFPreview(clearStatus: false)
    linkedPDFPreviewError = "PDF loading stopped. The file is unchanged; retry the preview when ready."
    statusText = "PDF loading stopped"
  }

  private func cancelLinkedPDFPreview(clearStatus: Bool) {
    linkedPDFLoadTask?.cancel()
    linkedPDFLoadTask = nil
    linkedPDFLoadGeneration += 1
    isLoadingLinkedPDFPreview = false
    if clearStatus {
      linkedPDFPreviewData = nil
      linkedPDFPreviewError = nil
    }
  }

  private func loadEntrySource(
    for location: WorkspaceLocation,
    generation: Int,
    recoveryAttempt: Int
  ) async {
    guard generation == entrySourceLoadGeneration else { return }
    activeEntrySourceLoadingGeneration = generation
    isLoadingEntrySource = true
    isRenderingEntrySource = false
    scheduleEntrySourceLoadWatchdog(
      for: location,
      generation: generation,
      recoveryAttempt: recoveryAttempt
    )
    defer {
      if activeEntrySourceLoadingGeneration == generation {
        entrySourceLoadWatchdogTask?.cancel()
        entrySourceLoadWatchdogTask = nil
        activeEntrySourceLoadingGeneration = nil
        isLoadingEntrySource = false
      }
    }

    do {
      let mode = selectedEntrySourceMode
      let testLoader = entrySourceLoaderForTesting
      let loaded = try await Task.detached(priority: .userInitiated) {
        let source: EntrySource
        if let testLoader {
          source = try await testLoader(location.file, location.lineForEditor, mode)
        } else {
          switch mode {
          case .entry:
            source = try Self.entrySource(file: location.file, line: location.lineForEditor)
          case .page:
            source = try Self.pageSource(file: location.file)
          }
        }
        return EntrySourceLoadResult(
          source: source,
          fileContentDigest: Self.fileContentDigest(
            for: URL(fileURLWithPath: source.file).standardizedFileURL
          )
        )
      }.value
      let source = loaded.source
      guard generation == entrySourceLoadGeneration,
            selectedLocationMatches(location)
      else {
        return
      }
      cacheEntrySource(
        source,
        for: location,
        mode: mode,
        modifiedAt: Self.modificationDate(
          for: URL(fileURLWithPath: source.file).standardizedFileURL
        ),
        fileContentDigest: loaded.fileContentDigest
      )
      guard !shouldDeferEntrySourceApplicationDuringActiveEdit(for: location) else {
        return
      }
      let previousSource = selectedEntrySource
      prepareEntryHTML(for: source)
      selectedEntrySource = source
      if location.idValue?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty != false,
         let id = Self.firstOrgID(in: source.text) {
        applyResolvedID(id, to: location)
      }
      updateEditableEntryTextFromLoadedSourceIfSafe(source, previousSource: previousSource)
      renderEntrySource(source, generation: generation)
    } catch {
      guard generation == entrySourceLoadGeneration,
            selectedLocationMatches(location)
      else {
        return
      }
      selectedEntrySource = nil
      selectedEntryHTML = nil
      selectedEntryRenderError = error.localizedDescription
      selectedEntryHTMLRenderKey = nil
      selectedRenderedBlocks = []
      selectedBlockID = nil
      isRenderingEntrySource = false
      errorText = error.localizedDescription
    }
  }

  private func scheduleEntrySourceLoadWatchdog(
    for location: WorkspaceLocation,
    generation: Int,
    recoveryAttempt: Int
  ) {
    entrySourceLoadWatchdogTask?.cancel()
    let timeout = entrySourceLoadTimeoutNanoseconds
    entrySourceLoadWatchdogTask = Task { @MainActor [weak self] in
      do {
        try await Task.sleep(nanoseconds: timeout)
      } catch {
        return
      }
      guard let self,
            generation == self.entrySourceLoadGeneration,
            self.isLoadingEntrySource,
            self.selectedEntrySource == nil,
            self.selectedLocationMatches(location)
      else {
        return
      }

      self.entrySourceLoadGeneration += 1
      let nextGeneration = self.entrySourceLoadGeneration
      self.activeEntrySourceLoadingGeneration = nil
      self.isLoadingEntrySource = false
      self.entrySourceLoadWatchdogTask = nil

      if recoveryAttempt == 0 {
        self.statusText = "Source load stalled; retrying"
        Task {
          await self.loadEntrySource(
            for: location,
            generation: nextGeneration,
            recoveryAttempt: 1
          )
        }
      } else {
        let message = "Source loading timed out. Reload the entry to try again."
        self.selectedEntryRenderError = message
        self.errorText = message
        self.statusText = "Source load failed"
      }
    }
  }

  private func applyCachedEntrySourceIfAvailable(for location: WorkspaceLocation, generation: Int) {
    let mode = selectedEntrySourceMode
    guard let source = cachedEntrySource(for: location, mode: mode) else { return }
    guard !shouldDeferEntrySourceApplicationDuringActiveEdit(for: location) else {
      return
    }
    let previousSource = selectedEntrySource
    prepareEntryHTML(for: source)
    selectedEntrySource = source
    updateEditableEntryTextFromLoadedSourceIfSafe(source, previousSource: previousSource)
    renderEntrySource(source, generation: generation)
  }

  private func shouldDeferEntrySourceApplicationDuringActiveEdit(for location: WorkspaceLocation) -> Bool {
    guard selectedLocationMatches(location), selectedEntrySource != nil else { return false }
    if editingBlockID != nil { return true }
    if isEditingEntry { return true }
    if isLiveFileEditorSelected && liveFileEditorHasUnsavedChanges {
      return true
    }
    return false
  }

  private func updateEditableEntryTextFromLoadedSourceIfSafe(_ source: EntrySource, previousSource: EntrySource?) {
    if isEditingEntry {
      let hadUnsavedChanges = Self.normalizeLineEndings(editableEntryText)
        != Self.normalizeLineEndings(previousSource?.text ?? "")
      if !hadUnsavedChanges {
        editableEntryText = source.text
      }
    } else if isLiveFileEditorSelected {
      let hadUnsavedChanges = Self.normalizeLineEndings(editableEntryText)
        != Self.normalizeLineEndings(previousSource?.text ?? "")
      guard !hadUnsavedChanges else { return }
      editableEntryText = source.text
    }
  }

  public func reloadSelectedEntrySource() async {
    isEditingEntry = false
    editableEntryText = ""
    detailScrollRequest = nil
    resetBlockState()
    guard let selectedLocation else { return }
    await loadEntrySource(for: selectedLocation)
  }

  public func cancelSelectedEntryLoading() {
    guard isLoadingEntrySource || isRenderingEntrySource else { return }
    entrySourceLoadGeneration += 1
    entryHTMLRenderGeneration += 1
    entrySourceLoadWatchdogTask?.cancel()
    entrySourceLoadWatchdogTask = nil
    entryHTMLRenderWatchdogTask?.cancel()
    entryHTMLRenderWatchdogTask = nil
    entryHTMLRenderTask?.cancel()
    entryHTMLRenderTask = nil
    activeEntrySourceLoadingGeneration = nil
    isLoadingEntrySource = false
    isRenderingEntrySource = false
    selectedEntryHTML = nil
    let message = "Loading stopped. The file is unchanged; retry the preview when ready."
    selectedEntryRenderError = message
    statusText = "Preview loading stopped"
  }

  private func updateSelectedFileDataNotebookState(for file: String?) {
    guard let file,
          let text = try? String(contentsOfFile: file, encoding: .utf8)
    else {
      selectedFileIsDataNotebook = false
      return
    }
    selectedFileIsDataNotebook = text.range(
      of: #"```sql[^\n]*\bresults\s*="#,
      options: [.regularExpression, .caseInsensitive]
    ) != nil
  }

  public var canRefreshSelectedDataNotebook: Bool {
    selectedFileIsDataNotebook
      && !hasActiveEdit
      && !liveFileEditorHasUnsavedChanges
      && !isLoadingEntrySource
      && !isRefreshingDataNotebook
  }

  nonisolated static func dataNotebookRefreshArguments(for file: String) -> [String] {
    [
      "query-data",
      "--file", file,
      "--all-results",
      "--apply",
      "--format", "json"
    ]
  }

  nonisolated static func dataNotebookLocationByRefreshingModificationDate(
    _ location: WorkspaceLocation?,
    file: String,
    modifiedAt: Date?
  ) -> WorkspaceLocation? {
    guard case .openClaw(let thread)? = location,
          URL(fileURLWithPath: thread.file).standardizedFileURL.path
            == URL(fileURLWithPath: file).standardizedFileURL.path
    else {
      return location
    }
    return .openClaw(OpenClawThread(
      title: thread.title,
      file: thread.file,
      line: thread.lineForEditor,
      zone: thread.zone,
      modifiedAt: modifiedAt,
      idValue: thread.idValue
    ))
  }

  private func refreshSelectedDataNotebookModificationDate(for file: String) {
    let modifiedAt = Self.modificationDate(for: URL(fileURLWithPath: file))
    let refreshedLocation = Self.dataNotebookLocationByRefreshingModificationDate(
      selectedLocation,
      file: file,
      modifiedAt: modifiedAt
    )
    guard refreshedLocation != selectedLocation else { return }
    selectedLocation = refreshedLocation
  }

  public func refreshSelectedDataNotebook() async {
    guard canRefreshSelectedDataNotebook,
          let file = selectedEntrySource?.file ?? selectedLocation?.file
    else {
      statusText = "Open a saved data notebook to refresh it"
      return
    }

    isRefreshingDataNotebook = true
    dataNotebookRefreshFailure = nil
    errorText = nil
    statusText = "Refreshing data…"
    defer { isRefreshingDataNotebook = false }

    do {
      let environment = dataSourceEnvironment()
      let result: DataQueryApplyPayload = try await cli.runJSON(
        Self.dataNotebookRefreshArguments(for: file),
        environment: environment
      )

      invalidateCanonicalDocumentCache(for: file)
      refreshSelectedDataNotebookModificationDate(for: file)
      if let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      await refreshCorpusFiles()
      dataNotebookRefreshFailure = nil
      statusText = result.changedResultCount == 0
        ? "Data is already current"
        : "Refreshed \(result.changedResultCount) of \(result.resultCount) data results"
    } catch {
      let message = error.localizedDescription
      let failure = Self.dataNotebookRefreshFailure(for: message)
      dataNotebookRefreshFailure = failure
      errorText = message
      statusText = failure.title
      if failure.needsCredentialUpdate {
        presentScarfMetabaseConfiguration()
      }
    }
  }

  public func presentScarfMetabaseConfiguration() {
    dataSourceConfigurationError = nil
    scarfMetabaseHasStoredAPIKey = DataSourceCredentialsKeychain.containsScarfMetabaseAPIKey()
    isDataSourceConfigurationPresented = true
  }

  public func dismissDataNotebookRefreshFailure() {
    dataNotebookRefreshFailure = nil
  }

  nonisolated static func dataNotebookRefreshFailure(for rawMessage: String) -> DataNotebookRefreshFailure {
    let message = rawMessage
      .replacingOccurrences(of: #"^Error:\s*"#, with: "", options: .regularExpression)
      .trimmingCharacters(in: .whitespacesAndNewlines)
    let normalized = message.lowercased()
    let authenticationFailure = normalized.contains("authentication failed")
      || normalized.contains("http 401")
      || normalized.contains("http 403")
      || normalized.contains("unauthorized")
      || normalized.contains("invalid api key")
    if authenticationFailure {
      return DataNotebookRefreshFailure(
        kind: .authentication,
        title: "Metabase authentication failed",
        message: "Metabase rejected the saved API key or it lacks permission. Enter a current API key, then retry the refresh."
      )
    }

    if normalized.contains("scarf_metabase_api_key") {
      return DataNotebookRefreshFailure(
        kind: .configuration,
        title: "Metabase credentials required",
        message: "Add the Metabase API key used by this notebook, then retry the refresh."
      )
    }

    let databaseConfigurationFailure = normalized.contains("scarf_metabase_database_id")
      || normalized.contains("requires a positive metabase databaseid")
    if databaseConfigurationFailure {
      return DataNotebookRefreshFailure(
        kind: .query,
        title: "Notebook data source is misconfigured",
        message: "The Metabase profile needs a positive numeric databaseId in org2.json. Database IDs are non-secret and should not be stored as app credentials."
      )
    }

    return DataNotebookRefreshFailure(
      kind: .query,
      title: "Data refresh failed",
      message: message.isEmpty ? "The data query failed without an error message." : message
    )
  }

  @discardableResult
  public func saveScarfMetabaseConfiguration(
    apiKey: String,
    clearAPIKey: Bool
  ) -> Bool {
    dataSourceConfigurationError = nil
    let normalizedAPIKey = apiKey.trimmingCharacters(in: .whitespacesAndNewlines)
    let requiresNewAPIKey = dataNotebookRefreshFailure?.kind == .authentication
      || (dataNotebookRefreshFailure?.kind == .configuration && !scarfMetabaseHasStoredAPIKey)
    if requiresNewAPIKey,
       (normalizedAPIKey.isEmpty || clearAPIKey) {
      let message = dataNotebookRefreshFailure?.kind == .authentication
        ? "Enter a new Metabase API key to replace the key that was rejected."
        : "Enter a Metabase API key."
      dataSourceConfigurationError = message
      errorText = message
      return false
    }

    do {
      if clearAPIKey {
        try DataSourceCredentialsKeychain.deleteScarfMetabaseAPIKey()
      } else {
        if !normalizedAPIKey.isEmpty {
          try DataSourceCredentialsKeychain.saveScarfMetabaseAPIKey(normalizedAPIKey)
        }
      }
      scarfMetabaseHasStoredAPIKey = DataSourceCredentialsKeychain.containsScarfMetabaseAPIKey()
      dataNotebookRefreshFailure = nil
      dataSourceConfigurationError = nil
      errorText = nil
      statusText = "Saved data refresh credentials"
      return true
    } catch {
      dataSourceConfigurationError = error.localizedDescription
      errorText = error.localizedDescription
      statusText = "Could not save data refresh credentials"
      return false
    }
  }

  private func dataSourceEnvironment() -> [String: String] {
    var environment: [String: String] = [:]
    if ProcessInfo.processInfo.environment["SCARF_METABASE_API_KEY"]?.isEmpty != false,
       let apiKey = DataSourceCredentialsKeychain.readScarfMetabaseAPIKey() {
      environment["SCARF_METABASE_API_KEY"] = apiKey
    }
    return environment
  }

  public func linkifyCurrentFile() async {
    guard let corpusRoot else {
      statusText = "No corpus selected"
      return
    }
    guard let file = selectedEntrySource?.file ?? selectedLocation?.file else {
      statusText = "Open a file first"
      return
    }

    do {
      let payload: RoamLinkifyPayload = try await cli.runJSON([
        "roam", "linkify",
        "--dir", corpusRoot.path,
        "--recursive",
        "--file", file,
        "--apply",
        "--format", "json"
      ])
      invalidateCanonicalDocumentCache(for: file)
      if let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      await refreshCorpusFiles()
      let relative = relativePath(file)
      statusText = payload.replacementCount > 0
        ? "Linkified \(relative): \(payload.replacementCount) link\(payload.replacementCount == 1 ? "" : "s")"
        : "No linkify changes in \(relative)"
      if payload.ambiguousSkipCount > 0 || payload.representedSuggestionCount > 0 {
        statusText += " (\(payload.ambiguousSkipCount) ambiguous, \(payload.representedSuggestionCount) suggestions)"
      }
    } catch {
      errorText = error.localizedDescription
      statusText = "Linkify failed"
    }
  }

  public func beginEditingSelectedEntry(initialSelection: NSRange? = nil) {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    editableEntryText = source.text
    sourceEditorLocalDraftText = source.text
    let restoredSelection = documentViewportSourceLine(for: source).map {
      NSRange(
        location: Self.sourceEditorUTF16Offset(forAbsoluteLine: $0, in: source),
        length: 0
      )
    }
    let initialEditorSelection = Self.clampedSourceEditorSelection(
      initialSelection ?? restoredSelection ?? NSRange(location: 0, length: 0),
      in: source.text
    )
    sourceEditorInteraction.reset(text: source.text, selection: initialEditorSelection)
    resetBlockState()
    sourceEditorDiagnostics = []
    sourceEditorPreviewHTML = selectedEntryHTML
    sourceEditorPreviewError = nil
    isSourceEditorPreviewPaused = false
    detailScrollRequest = nil
    isEditingEntry = true
  }

  public func requestSourceEditorCommand(_ command: OrgSourceEditorCommand) {
    guard isEditingEntry else {
      statusText = "Open source editing first"
      return
    }
    sourceEditorCommandGeneration += 1
    sourceEditorCommandRequest = OrgSourceEditorCommandRequest(
      id: sourceEditorCommandGeneration,
      command: command
    )
  }

  public func analyzeSourceEditorText(_ text: String) async -> OrgSourceEditorSemanticSnapshot? {
    do {
      return try await cli.analyzeEditorText(text)
    } catch {
      return nil
    }
  }

  public func scheduleSourceEditorPreview(immediate: Bool = false) {
    scheduleSourceEditorPreview(text: editableEntryText, immediate: immediate)
  }

  public func scheduleSourceEditorPreview(text: String, immediate: Bool = false) {
    guard isEditingEntry,
          sourceEditorPresentation == .split,
          !isSourceEditorPreviewPaused,
          let source = selectedEntrySource
    else {
      cancelSourceEditorPreviewRender(clearStatus: false)
      return
    }

    if documentPreviewKind == .slides {
      scheduleSlidePreview(text: text, source: source, immediate: immediate)
      return
    }

    cancelSlidePreviewRender(clearStatus: false)
    sourceEditorPreviewTask?.cancel()
    if isRenderingSourceEditorPreview {
      isRenderingSourceEditorPreview = false
    }
    sourceEditorPreviewGeneration += 1
    let generation = sourceEditorPreviewGeneration
    sourceEditorPreviewTask = Task { @MainActor [weak self] in
      guard let self else { return }
      if !immediate {
        do {
          try await Task.sleep(nanoseconds: Self.sourceEditorPreviewIdleDelayNanoseconds)
        } catch {
          return
        }
      }
      guard !Task.isCancelled,
            generation == self.sourceEditorPreviewGeneration,
            self.isEditingEntry,
            self.sourceEditorPresentation == .split,
            !self.isSourceEditorPreviewPaused,
            self.selectedEntrySource?.id == source.id,
            self.sourceEditorLocalDraftText == text || self.editableEntryText == text
      else { return }

      self.isRenderingSourceEditorPreview = true
      self.sourceEditorPreviewError = nil
      do {
        let html = try await self.cli.renderAppHTML(
          text,
          sourcePath: source.file,
          sourceLineOffset: max(0, source.startLine - 1),
          stylesheetPath: self.appHTMLStylesheetPath
        )
        guard !Task.isCancelled,
              generation == self.sourceEditorPreviewGeneration,
              self.isEditingEntry,
              self.sourceEditorPresentation == .split,
              !self.isSourceEditorPreviewPaused,
              self.selectedEntrySource?.id == source.id,
              self.sourceEditorLocalDraftText == text || self.editableEntryText == text
        else { return }
        self.sourceEditorPreviewHTML = Self.applyingPropertyDrawerDefault(
          to: html,
          expanded: self.propertyDrawersExpandedByDefault
        )
        self.sourceEditorPreviewError = nil
      } catch {
        guard generation == self.sourceEditorPreviewGeneration,
              self.isEditingEntry,
              self.sourceEditorPresentation == .split,
              !self.isSourceEditorPreviewPaused,
              self.selectedEntrySource?.id == source.id
        else { return }
        self.sourceEditorPreviewError = error.localizedDescription
      }
      if generation == self.sourceEditorPreviewGeneration {
        self.isRenderingSourceEditorPreview = false
      }
    }
  }

  public var canPreviewSlides: Bool {
    guard let source = selectedEntrySource else { return false }
    return Self.canPreviewSlides(source: source)
  }

  public func setDocumentPreviewPreference(_ preference: OrgDocumentPreviewPreference) {
    guard let source = selectedEntrySource else { return }
    let key = Self.documentViewportKey(for: source)
    documentPreviewPreference = preference
    switch preference {
    case .automatic:
      documentPreviewOverrides.removeValue(forKey: key)
    case .document, .slides:
      documentPreviewOverrides[key] = preference.rawValue
    }
    defaults.set(documentPreviewOverrides, forKey: documentPreviewOverridesKey)
      applyDocumentPreviewPreferenceForSelectedSource()

    if documentPreviewKind == .slides {
      let text = isEditingEntry ? (sourceEditorLocalDraftText ?? editableEntryText) : source.text
      scheduleSlidePreview(text: text, source: source, immediate: true)
    } else if isEditingEntry, sourceEditorPresentation == .split {
      scheduleSourceEditorPreview(immediate: true)
    }
  }

  public var inferredDocumentPreviewKind: OrgDocumentPreviewKind {
    guard let source = selectedEntrySource else { return .document }
    return inferredDocumentPreviewKinds[Self.documentViewportKey(for: source)] ?? .document
  }

  public var documentPreviewPreferenceLabel: String {
    if documentPreviewPreference == .automatic {
      return "Automatic (\(documentPreviewKind.title))"
    }
    return documentPreviewPreference.title
  }

  private func applyDocumentPreviewPreferenceForSelectedSource() {
    guard let source = selectedEntrySource else {
      documentPreviewPreference = .automatic
      if documentPreviewKind != .document {
        documentPreviewKind = .document
      }
      return
    }
    let key = Self.documentViewportKey(for: source)
    let preference = documentPreviewOverrides[key]
      .flatMap(OrgDocumentPreviewPreference.init(rawValue:)) ?? .automatic
    documentPreviewPreference = preference

    let preferredKind: OrgDocumentPreviewKind
    switch preference {
    case .automatic:
      preferredKind = inferredDocumentPreviewKinds[key] ?? .document
    case .document:
      preferredKind = .document
    case .slides:
      preferredKind = .slides
    }
    let effectiveKind: OrgDocumentPreviewKind = preferredKind == .slides && Self.canPreviewSlides(source: source)
      ? .slides
      : .document
    if documentPreviewKind != effectiveKind {
      documentPreviewKind = effectiveKind
    }
  }

  func updateInferredDocumentPreviewKind(from html: String?) {
    guard let source = selectedEntrySource,
          let kind = Self.documentPreviewKind(fromAppHTML: html)
    else { return }
    let key = Self.documentViewportKey(for: source)
    inferredDocumentPreviewKinds[key] = kind
    if documentPreviewPreference == .automatic {
      let previousKind = documentPreviewKind
      applyDocumentPreviewPreferenceForSelectedSource()
      if previousKind != documentPreviewKind, documentPreviewKind == .slides {
        let text = isEditingEntry ? (sourceEditorLocalDraftText ?? editableEntryText) : source.text
        scheduleSlidePreview(text: text, source: source, immediate: true)
      }
    }
  }

  nonisolated static func documentPreviewKind(fromAppHTML html: String?) -> OrgDocumentPreviewKind? {
    guard let html else { return nil }
    if html.contains("<meta name=\"org2-document-kind\" content=\"slides\"") {
      return .slides
    }
    if html.contains("<meta name=\"org2-document-kind\" content=\"document\"") {
      return .document
    }
    return nil
  }

  public func zoomSlidePreviewIn() {
    setSlidePreviewZoomScale(Self.nextSlidePreviewZoomScale(after: slidePreviewZoomScale))
  }

  public func zoomSlidePreviewOut() {
    setSlidePreviewZoomScale(Self.previousSlidePreviewZoomScale(before: slidePreviewZoomScale))
  }

  public func resetSlidePreviewZoom() {
    setSlidePreviewZoomScale(1)
  }

  public func setSlidePreviewPageCount(_ count: Int) {
    slidePreviewPageCount = max(0, count)
  }

  func requestSlidePreviewNavigation(_ target: OrgPDFPageNavigationTarget) {
    guard documentPreviewKind == .slides, slidePreviewPageCount > 0 else { return }
    slidePreviewNavigationGeneration += 1
    slidePreviewNavigationRequest = OrgPDFPageNavigationRequest(
      id: slidePreviewNavigationGeneration,
      target: target
    )
  }

  private func setSlidePreviewZoomScale(_ scale: CGFloat) {
    let normalized = min(max(0.25, scale), 4)
    guard abs(normalized - slidePreviewZoomScale) > 0.001 else { return }
    slidePreviewZoomScale = normalized
    if let source = selectedEntrySource {
      slidePreviewZoomScales[Self.documentViewportKey(for: source)] = normalized
    }
  }

  nonisolated private static let slidePreviewZoomSteps: [CGFloat] = [
    0.4, 0.5, 0.625, 0.75, 0.875, 1, 1.25, 1.5, 2, 3, 4,
  ]

  nonisolated static func nextSlidePreviewZoomScale(after scale: CGFloat) -> CGFloat {
    slidePreviewZoomSteps.first(where: { $0 > scale + 0.001 }) ?? slidePreviewZoomSteps.last!
  }

  nonisolated static func previousSlidePreviewZoomScale(before scale: CGFloat) -> CGFloat {
    slidePreviewZoomSteps.last(where: { $0 < scale - 0.001 }) ?? slidePreviewZoomSteps.first!
  }

  public func scheduleSlidePreview(
    text: String,
    source: EntrySource,
    immediate: Bool = false
  ) {
    guard documentPreviewKind == .slides,
          Self.canPreviewSlides(source: source)
    else {
      cancelSlidePreviewRender(clearStatus: false)
      return
    }

    slidePreviewTask?.cancel()
    isRenderingSlidePreview = false
    slidePreviewGeneration += 1
    let generation = slidePreviewGeneration
    if slidePreviewSourceID != source.id {
      slidePreviewSourceID = source.id
      slidePreviewPDF = nil
      slidePreviewError = nil
    }

    slidePreviewTask = Task { @MainActor [weak self] in
      guard let self else { return }
      if !immediate {
        do {
          try await Task.sleep(nanoseconds: Self.slidePreviewIdleDelayNanoseconds)
        } catch {
          return
        }
      }
      guard !Task.isCancelled,
            self.documentPreviewKind == .slides,
            self.selectedEntrySource?.id == source.id
      else { return }
      if self.isEditingEntry {
        guard self.sourceEditorLocalDraftText == text || self.editableEntryText == text else { return }
      } else {
        guard self.selectedEntrySource?.text == text else { return }
      }

      self.isRenderingSlidePreview = true
      self.slidePreviewError = nil
      do {
        let pdf: Data
        if let renderer = self.slidePreviewRendererForTesting {
          pdf = try await renderer(text, source.file, 1)
        } else {
          pdf = try await self.cli.renderPresentationPDF(
            text,
            sourcePath: source.file,
            sourceLineOffset: max(0, source.startLine - 1),
            passes: 1
          )
        }
        guard !Task.isCancelled,
              generation == self.slidePreviewGeneration,
              self.documentPreviewKind == .slides,
              self.selectedEntrySource?.id == source.id
        else { return }
        if self.isEditingEntry {
          guard self.sourceEditorLocalDraftText == text || self.editableEntryText == text else { return }
        } else {
          guard self.selectedEntrySource?.text == text else { return }
        }
        self.slidePreviewPDF = pdf
        self.slidePreviewError = nil
      } catch is CancellationError {
        return
      } catch {
        guard generation == self.slidePreviewGeneration,
              self.documentPreviewKind == .slides,
              self.selectedEntrySource?.id == source.id
        else { return }
        self.slidePreviewError = error.localizedDescription
      }
      if generation == self.slidePreviewGeneration {
        self.isRenderingSlidePreview = false
      }
    }
  }

  public func retrySlidePreview() {
    guard let source = selectedEntrySource else { return }
    let text = isEditingEntry ? (sourceEditorLocalDraftText ?? editableEntryText) : source.text
    scheduleSlidePreview(text: text, source: source, immediate: true)
  }

  public func setSourceEditorPreviewPaused(_ paused: Bool) {
    isSourceEditorPreviewPaused = paused
    if paused {
      cancelSourceEditorPreviewRender(clearStatus: false)
    } else {
      scheduleSourceEditorPreview(immediate: true)
    }
  }

  public func showSourceEditorBacklinks(at line: Int) {
    guard isEditingEntry, let source = selectedEntrySource else { return }
    nodeContextTab = .references
    isNodeContextPanePresented = true
    let absoluteLine = source.startLine + max(1, line) - 1
    statusText = "Loading references for line \(absoluteLine)"
    Task { await loadSourceEditorBacklinks(source: source, line: absoluteLine) }
  }

  private func loadSourceEditorBacklinks(source: EntrySource, line: Int) async {
    backlinksLoadTask?.cancel()
    backlinksLoadTask = nil
    backlinksLoadGeneration += 1
    let generation = backlinksLoadGeneration
    guard let corpusRoot else {
      backlinks = nil
      return
    }
    isLoadingBacklinks = true
    defer {
      if generation == backlinksLoadGeneration {
        isLoadingBacklinks = false
      }
    }

    do {
      let lookup: OrgIDLookupPayload = try await cli.runJSON([
        "id", "get",
        "--file", source.file,
        "--line", "\(line)",
        "--format", "json"
      ])
      let payload: BacklinksPayload = try await cli.runJSON([
        "backlinks",
        "--id", lookup.id,
        "--dir", corpusRoot.path,
        "--recursive",
        "--format", "json"
      ])
      guard generation == backlinksLoadGeneration,
            isEditingEntry,
            selectedEntrySource?.id == source.id
      else { return }
      backlinks = payload
      statusText = payload.backlinks.isEmpty
        ? "No references for this heading"
        : "Loaded \(payload.backlinks.count) reference\(payload.backlinks.count == 1 ? "" : "s")"
    } catch {
      guard generation == backlinksLoadGeneration,
            isEditingEntry,
            selectedEntrySource?.id == source.id
      else { return }
      backlinks = nil
      statusText = "This heading has no ID-backed references"
    }
  }

  private func cancelSourceEditorPreviewRender(clearStatus: Bool) {
    sourceEditorPreviewTask?.cancel()
    sourceEditorPreviewTask = nil
    sourceEditorPreviewGeneration += 1
    isRenderingSourceEditorPreview = false
    cancelSlidePreviewRender(clearStatus: clearStatus)
    if clearStatus {
      sourceEditorPreviewHTML = nil
      sourceEditorPreviewError = nil
    }
  }

  public func cancelSlidePreview() {
    cancelSlidePreviewRender(clearStatus: false)
  }

  private func cancelSlidePreviewRender(clearStatus: Bool) {
    slidePreviewTask?.cancel()
    slidePreviewTask = nil
    slidePreviewGeneration += 1
    isRenderingSlidePreview = false
    if clearStatus {
      slidePreviewPDF = nil
      slidePreviewError = nil
      slidePreviewSourceID = nil
    }
  }

  nonisolated private static func canPreviewSlides(source: EntrySource) -> Bool {
    let extensionName = URL(fileURLWithPath: source.file).pathExtension.lowercased()
    return ["org", "org2"].contains(extensionName)
      && source.startLine == 1
      && !source.isSubtree
  }

  public func beginEditingCurrentScope(atSourceLine sourceLine: Int? = nil) {
    if let sourceLine,
       let source = selectedEntrySource {
      recordDocumentViewportSourceLine(sourceLine, for: source)
      let sourceSelection = NSRange(
        location: Self.sourceEditorUTF16Offset(
          forAbsoluteLine: sourceLine,
          in: source
        ),
        length: 0
      )
      beginEditingSelectedEntry(initialSelection: sourceSelection)
      return
    }
    if let selectedBlock {
      beginEditingSource(for: selectedBlock)
      return
    }
    if let sourceLine = currentDocumentViewportSourceLine,
       let source = selectedEntrySource {
      recordDocumentViewportSourceLine(sourceLine, for: source)
      let sourceSelection = NSRange(
        location: Self.sourceEditorUTF16Offset(
          forAbsoluteLine: sourceLine,
          in: source
        ),
        length: 0
      )
      beginEditingSelectedEntry(initialSelection: sourceSelection)
      return
    }
    beginEditingSelectedEntry()
  }

  public func beginEditingVisibleBlock() {
    guard selectedEntrySource?.isEditable == true else {
      statusText = "No editable source loaded"
      return
    }

    if let selectedBlock {
      beginEditingSource(for: selectedBlock)
      return
    }

    guard let firstEditableBlock = selectableBlocks.first else {
      beginEditingSelectedEntry()
      return
    }
    beginEditingSource(for: firstEditableBlock)
  }

  public func cancelEditingSelectedEntry() {
    cancelSourceEditorPreviewRender(clearStatus: true)
    let selectedText = selectedEntrySource?.text ?? ""
    editableEntryText = selectedText
    sourceEditorLocalDraftText = nil
    sourceEditorInteraction.reset(
      text: selectedText,
      selection: NSRange(location: 0, length: 0)
    )
    sourceEditorDiagnostics = []
    sourceEditorCommandRequest = nil
    isEditingEntry = false
  }

  public func beginEditingSource(for block: OrgEditableBlock, selection: NSRange? = nil) {
    guard block.isEditable,
          let source = selectedEntrySource,
          source.isEditable
    else {
      statusText = "Block is read-only"
      return
    }
    let sourceSelection = Self.sourceEditorSelectionRange(
      for: block,
      in: source,
      selection: selection
    )
    recordDocumentViewportSourceLine(block.startLine, for: source)
    beginEditingSelectedEntry(initialSelection: sourceSelection)
  }

  nonisolated static func sourceEditorSelectionRange(
    for block: OrgEditableBlock,
    in source: EntrySource,
    selection: NSRange? = nil
  ) -> NSRange {
    let blockStartOffset = sourceEditorUTF16Offset(forAbsoluteLine: block.startLine, in: source)
    let sourceLength = source.text.utf16.count
    let blockLength = block.rawText.utf16.count
    let localSelection = selection ?? NSRange(location: 0, length: 0)
    let localLocation = min(max(0, localSelection.location), blockLength)
    let localLength = min(max(0, localSelection.length), max(0, blockLength - localLocation))
    let sourceLocation = min(sourceLength, blockStartOffset + localLocation)
    let sourceLengthRemaining = max(0, sourceLength - sourceLocation)
    return NSRange(
      location: sourceLocation,
      length: min(localLength, sourceLengthRemaining)
    )
  }

  nonisolated private static func clampedSourceEditorSelection(
    _ selection: NSRange,
    in text: String
  ) -> NSRange {
    let textLength = text.utf16.count
    let location = min(max(0, selection.location), textLength)
    return NSRange(
      location: location,
      length: min(max(0, selection.length), max(0, textLength - location))
    )
  }

  nonisolated private static func sourceEditorUTF16Offset(
    forAbsoluteLine line: Int,
    in source: EntrySource
  ) -> Int {
    let lineOffset = max(0, line - source.startLine)
    guard lineOffset > 0 else { return 0 }

    var currentLineOffset = 0
    var utf16Offset = 0
    var index = source.text.utf16.startIndex
    while index < source.text.utf16.endIndex {
      let codeUnit = source.text.utf16[index]
      utf16Offset += 1
      index = source.text.utf16.index(after: index)
      if codeUnit == 10 {
        currentLineOffset += 1
        if currentLineOffset >= lineOffset {
          return utf16Offset
        }
      }
    }
    return utf16Offset
  }

  public func beginEditingBlock(
    _ block: OrgEditableBlock,
    initialDraft: String? = nil,
    initialSelection: NSRange? = nil
  ) {
    guard block.isEditable, selectedEntrySource?.isEditable == true else {
      statusText = "Block is read-only"
      return
    }
    if initialDraft == nil,
       !isEditingEntry,
       selectedBlockID == block.id,
       editingBlockID == block.id {
      return
    }
    let draft = initialDraft ?? block.rawText
    isEditingEntry = false
    selectedBlockID = block.id
    editingBlockID = block.id
    editableBlockText = draft
    activeBlockDrafts[block.id] = draft
    activeBlockOriginals[block.id] = block
    if let initialSelection {
      activeBlockInitialSelections[block.id] = initialSelection
    } else {
      activeBlockInitialSelections.removeValue(forKey: block.id)
    }
    deferredStableAutosaves.removeValue(forKey: block.id)
    if draft != block.rawText {
      let updatedBlocks = Self.locallyUpdatingRenderedBlocks(
        selectedRenderedBlocks,
        replacing: block,
        with: draft
      )
      setSelectedRenderedBlocks(updatedBlocks, preservingMetadata: true)
      selectedBlockID = block.id
    }
  }

  public func updateEditingBlockDraft(_ block: OrgEditableBlock, draft: String) {
    guard editingBlockID == block.id else { return }
    activeBlockDrafts[block.id] = draft
  }

  public func initialSelectionForEditingBlock(_ block: OrgEditableBlock) -> NSRange? {
    guard editingBlockID == block.id else { return nil }
    return activeBlockInitialSelections[block.id]
  }

  public func cancelEditingBlock() {
    if let draft = transientDraftBlock, editingBlockID == draft.block.id {
      discardTransientDraft(status: "Draft discarded")
      return
    }
    if !applyDeferredStableAutosaveForActiveBlock() {
      restoreActiveBlockOriginal()
    }
    resetBlockEditing()
  }

  public var selectedBlock: OrgEditableBlock? {
    guard let selectedBlockID else { return nil }
    guard let index = selectedRenderedBlockIndexes[selectedBlockID],
          selectedRenderedBlocks.indices.contains(index),
          selectedRenderedBlocks[index].id == selectedBlockID
    else {
      return nil
    }
    return selectedRenderedBlocks[index]
  }

  public var hasSelectedBlock: Bool {
    selectedBlock != nil
  }

  public var canSaveActiveEdit: Bool {
    if isEditingEntry {
      return entryEditorHasUnsavedChanges && !isSavingEntry
    }
    if editingBlockID != nil {
      return !isSavingBlock
    }
    return false
  }

  public var canSaveCurrentFile: Bool {
    (isEditingEntry && !isSavingEntry)
      || canSaveActiveEdit
      || canSaveLiveFileEditor
      || (orgCryptEncryptOnSave && selectedFileForOrgCryptSave != nil)
  }

  public var canExportSlides: Bool {
    currentOrgSourceFile != nil && !isExportingSlides && !isSavingEntry && !isSavingBlock
  }

  public var canExportCurrentDocumentPDF: Bool {
    currentOrgSourceFile != nil
      && !isExportingCurrentDocumentPDF
      && !isSavingEntry
      && !isSavingBlock
  }

  public func exportCurrentDocumentPDF() async {
    guard let sourceFile = currentOrgSourceFile else {
      statusText = "Open an Org or Org2 file first"
      return
    }
    guard !isExportingCurrentDocumentPDF else { return }
    guard await savePendingEditsBeforeExport(blockedStatus: "Save the current edit before exporting the document") else {
      return
    }

    let panel = NSSavePanel()
    panel.canCreateDirectories = true
    panel.directoryURL = sourceFile.deletingLastPathComponent()
    panel.nameFieldStringValue = sourceFile.deletingPathExtension().lastPathComponent + ".pdf"
    panel.allowedContentTypes = [.pdf]
    panel.title = "Export Current Document as PDF"
    panel.prompt = "Export"

    guard panel.runModal() == .OK, let destination = panel.url else {
      statusText = "PDF export cancelled"
      return
    }

    isExportingCurrentDocumentPDF = true
    statusText = "Exporting document as PDF…"
    defer { isExportingCurrentDocumentPDF = false }

    do {
      try await exportCurrentDocumentPDF(sourceFile: sourceFile, destination: destination)
      finishSuccessfulDocumentPDFExport(destination: destination)
    } catch {
      errorText = error.localizedDescription
      statusText = "PDF export failed: \(error.localizedDescription)"
      exportNotice = Org2ExportNotice(
        title: "Couldn’t Export PDF",
        message: error.localizedDescription
      )
    }
  }

  func exportCurrentDocumentPDF(sourceFile: URL, destination: URL) async throws {
    let standardizedSource = sourceFile.standardizedFileURL
    let html = try await renderedCurrentDocumentHTML(sourceFile: standardizedSource)
    let baseURL = standardizedSource.deletingLastPathComponent()
    let pdf: Data
    if let documentPDFRendererForTesting {
      pdf = try await documentPDFRendererForTesting(html, baseURL)
    } else {
      pdf = try await Org2PDFExporter().data(for: html, baseURL: baseURL)
    }
    try Org2PDFExporter.validated(pdf).write(to: destination, options: .atomic)
  }

  func renderedCurrentDocumentHTML(sourceFile: URL) async throws -> String {
    let standardizedSource = sourceFile.standardizedFileURL
    let text = try await Task.detached(priority: .userInitiated) {
      try String(contentsOf: standardizedSource, encoding: .utf8)
    }.value
    return try await cli.renderAppHTML(
      text,
      sourcePath: standardizedSource.path,
      sourceLineOffset: 0,
      stylesheetPath: appHTMLStylesheetPath
    )
  }

  func finishSuccessfulDocumentPDFExport(destination: URL) {
    errorText = nil
    let didOpen = documentPDFExportFileOpenerForTesting?(destination)
      ?? NSWorkspace.shared.open(destination)
    if didOpen {
      statusText = "Exported and opened \(destination.lastPathComponent)"
      exportNotice = nil
      return
    }

    statusText = "Exported \(destination.lastPathComponent), but couldn’t open the PDF"
    exportNotice = Org2ExportNotice(
      title: "PDF Exported",
      message: "\(destination.path)\n\nThe PDF was saved, but macOS couldn’t open it automatically."
    )
  }

  public func exportSlides(format: Org2SlideExportFormat) async {
    guard let sourceFile = currentOrgSourceFile else {
      statusText = "Open an Org or Org2 file first"
      return
    }
    guard !isExportingSlides else { return }
    guard await savePendingEditsBeforeExport(blockedStatus: "Save the current edit before exporting slides") else {
      return
    }

    let panel = NSSavePanel()
    panel.canCreateDirectories = true
    panel.directoryURL = sourceFile.deletingLastPathComponent()
    panel.nameFieldStringValue = sourceFile.deletingPathExtension().lastPathComponent + ".\(format.fileExtension)"
    if format == .pdf {
      panel.allowedContentTypes = [.pdf]
    } else {
      panel.allowedContentTypes = [UTType(filenameExtension: "tex") ?? .plainText]
    }
    panel.title = "Export Slides as \(format.title)"
    panel.prompt = "Export"

    guard panel.runModal() == .OK, let destination = panel.url else {
      statusText = "Slide export cancelled"
      return
    }

    isExportingSlides = true
    statusText = "Exporting slides…"
    defer { isExportingSlides = false }

    do {
      try await cli.exportBeamer(file: sourceFile, destination: destination, format: format)
      finishSuccessfulSlideExport(format: format, destination: destination)
    } catch {
      errorText = error.localizedDescription
      statusText = "Slide export failed: \(error.localizedDescription)"
      exportNotice = Org2ExportNotice(
        title: "Couldn’t Export Slides",
        message: error.localizedDescription
      )
    }
  }

  func finishSuccessfulSlideExport(
    format: Org2SlideExportFormat,
    destination: URL
  ) {
    errorText = nil

    if format == .pdf {
      let didOpen = slideExportFileOpenerForTesting?(destination)
        ?? NSWorkspace.shared.open(destination)
      if didOpen {
        statusText = "Exported and opened \(destination.lastPathComponent)"
        exportNotice = nil
        return
      }

      statusText = "Exported slides to \(destination.lastPathComponent), but couldn’t open the PDF"
      exportNotice = Org2ExportNotice(
        title: "Slides Exported",
        message: "\(destination.path)\n\nThe PDF was saved, but macOS couldn’t open it automatically."
      )
      return
    }

    statusText = "Exported slides to \(destination.lastPathComponent)"
    exportNotice = Org2ExportNotice(
      title: "Slides Exported",
      message: destination.path
    )
  }

  private var currentOrgSourceFile: URL? {
    let path = selectedEntrySource?.file ?? selectedLocation?.file
    guard let path else { return nil }
    let sourceFile = URL(fileURLWithPath: path).standardizedFileURL
    guard ["org", "org2"].contains(sourceFile.pathExtension.lowercased()) else { return nil }
    return sourceFile
  }

  private func savePendingEditsBeforeExport(blockedStatus: String) async -> Bool {
    let hadPendingEdit = entryEditorHasUnsavedChanges
      || liveFileEditorHasUnsavedChanges
      || editingBlockID != nil
    guard hadPendingEdit else { return true }

    await saveActiveEdit()
    let stillPending = entryEditorHasUnsavedChanges
      || liveFileEditorHasUnsavedChanges
      || editingBlockID != nil
    if stillPending {
      statusText = blockedStatus
      return false
    }
    return true
  }

  public var hasActiveEdit: Bool {
    isEditingEntry || editingBlockID != nil
  }

  public var isLiveFileEditorSelected: Bool {
    selectedEntrySourceMode == .page
      && selectedLocation != nil
      && (selectedSurface == .files || selectedFileIsCSV)
  }

  public var selectedFileIsCSV: Bool {
    let file = selectedLocation?.file ?? selectedEntrySource?.file
    guard let file else { return false }
    return URL(fileURLWithPath: file).pathExtension.lowercased() == "csv"
  }

  public var selectedFileIsPDF: Bool {
    let file = selectedLocation?.file ?? selectedEntrySource?.file
    guard let file else { return false }
    return Self.isPDFFile(file)
  }

  nonisolated static func isPDFFile(_ path: String) -> Bool {
    URL(fileURLWithPath: path).pathExtension.lowercased() == "pdf"
  }

  public var isLiveFileEditorAvailable: Bool {
    isLiveFileEditorSelected && selectedEntrySource?.isEditable == true
  }

  public var canSaveLiveFileEditor: Bool {
    isLiveFileEditorAvailable && liveFileEditorHasUnsavedChanges && !isSavingEntry
  }

  public var liveFileEditorHasUnsavedChanges: Bool {
    guard let source = selectedEntrySource, isLiveFileEditorSelected else { return false }
    return Self.normalizeLineEndings(editableEntryText) != Self.normalizeLineEndings(source.text)
  }

  public var entryEditorHasUnsavedChanges: Bool {
    guard isEditingEntry, let source = selectedEntrySource else { return false }
    return Self.normalizeLineEndings(sourceEditorLocalDraftText ?? editableEntryText)
      != Self.normalizeLineEndings(source.text)
  }

  public func noteSourceEditorLocalTextChanged(_ text: String) {
    guard isEditingEntry else { return }
    sourceEditorLocalDraftText = text
  }

  public func cancelActiveEdit() {
    if editingBlockID != nil {
      cancelEditingBlock()
    } else {
      cancelEditingSelectedEntry()
    }
  }

  public func selectBlock(_ block: OrgEditableBlock) {
    guard selectedEntrySource?.isEditable == true else { return }
    guard selectedBlockID != block.id else { return }
    selectedBlockID = block.id
  }

  public func clearSelectedBlock() {
    selectedBlockID = nil
  }

  public func canSelectAdjacentBlock(_ direction: OrgBlockMoveDirection) -> Bool {
    guard let selectedBlock else { return false }
    let blocks = selectableBlocks
    guard let index = blocks.firstIndex(where: { $0.id == selectedBlock.id }) else { return false }
    switch direction {
    case .up:
      return index > 0
    case .down:
      return index < blocks.count - 1
    }
  }

  public func selectAdjacentBlock(_ direction: OrgBlockMoveDirection) {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return
    }
    let blocks = selectableBlocks
    guard let index = blocks.firstIndex(where: { $0.id == selectedBlock.id }) else {
      selectedBlockID = nil
      return
    }

    let nextIndex: Int
    switch direction {
    case .up:
      nextIndex = max(0, index - 1)
    case .down:
      nextIndex = min(blocks.count - 1, index + 1)
    }
    selectedBlockID = blocks[nextIndex].id
  }

  public func toggleRenderedBlockFold(_ block: OrgEditableBlock) {
    setRenderedBlock(block, folded: !foldedRenderedBlockIDs.contains(block.id))
  }

  @discardableResult
  public func collapseSelectedRenderedBlock() -> Bool {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return false
    }
    return setRenderedBlock(selectedBlock, folded: true)
  }

  @discardableResult
  public func expandSelectedRenderedBlock() -> Bool {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return false
    }
    return setRenderedBlock(selectedBlock, folded: false)
  }

  public func collapseAllRenderedBlocks() {
    let foldableIDs = Set(selectedRenderedBlocks.filter {
      OrgRenderedFoldTree.isFoldable($0, in: selectedRenderedBlocks)
    }.map(\.id))
    foldedRenderedBlockIDs = foldableIDs
    if let selectedBlockID,
       let ancestorID = OrgRenderedFoldTree.foldedAncestorID(
        hiding: selectedBlockID,
        foldedBlockIDs: foldableIDs,
        blocks: selectedRenderedBlocks
       ) {
      self.selectedBlockID = ancestorID
    }
    statusText = foldableIDs.isEmpty ? "Nothing to collapse" : "Collapsed rendered blocks"
  }

  public func expandAllRenderedBlocks() {
    foldedRenderedBlockIDs = []
    statusText = "Expanded rendered blocks"
  }

  @discardableResult
  private func setRenderedBlock(_ block: OrgEditableBlock, folded: Bool) -> Bool {
    guard OrgRenderedFoldTree.isFoldable(block, in: selectedRenderedBlocks) else {
      statusText = "Selected block has nothing to \(folded ? "collapse" : "expand")"
      return false
    }

    var nextFoldedIDs = foldedRenderedBlockIDs
    if folded {
      nextFoldedIDs.insert(block.id)
      if let selectedBlockID,
         let range = OrgRenderedFoldTree.childrenRange(for: block, in: selectedRenderedBlocks),
         let selectedIndex = selectedRenderedBlocks.firstIndex(where: { $0.id == selectedBlockID }),
         range.contains(selectedIndex) {
        self.selectedBlockID = block.id
      }
      statusText = "Collapsed block"
    } else {
      nextFoldedIDs.remove(block.id)
      statusText = "Expanded block"
    }
    foldedRenderedBlockIDs = nextFoldedIDs
    return true
  }

  public func beginEditingSelectedBlock() {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return
    }
    beginEditingSource(for: selectedBlock)
  }

  public func beginEditingSelectedBlock(appending text: String) -> Bool {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return false
    }
    beginEditingSource(
      for: selectedBlock,
      selection: NSRange(location: selectedBlock.rawText.utf16.count, length: 0)
    )
    insertTextInSourceEditor(text)
    return true
  }

  private func insertTextInSourceEditor(_ text: String) {
    guard isEditingEntry, !text.isEmpty else { return }
    let currentText = sourceEditorLocalDraftText ?? sourceEditorInteraction.text
    let range = Self.clampedSourceEditorSelection(sourceEditorSelection, in: currentText)
    let updatedText = (currentText as NSString).replacingCharacters(in: range, with: text)
    let updatedSelection = NSRange(location: range.location + text.utf16.count, length: 0)
    editableEntryText = updatedText
    sourceEditorLocalDraftText = updatedText
    sourceEditorInteraction.reset(text: updatedText, selection: updatedSelection)
  }

  public func duplicateSelectedBlock() async {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return
    }
    await duplicateBlock(selectedBlock)
  }

  public func deleteSelectedBlock() async {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return
    }
    await deleteBlock(selectedBlock)
  }

  public func moveSelectedBlock(_ direction: OrgBlockMoveDirection) async {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return
    }
    await moveBlock(selectedBlock, direction: direction)
  }

  public func insertBlockAfterSelected(_ kind: OrgInsertBlockKind, initialText: String? = nil) async {
    guard let selectedBlock else {
      statusText = "Select a block first"
      return
    }
    await insertBlock(after: selectedBlock, kind: kind, initialText: initialText)
  }

  public func beginAppendingSectionAtEnd() async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }

    if let lastBlock = selectedRenderedBlocks
      .filter({ block in
        block.isEditable
          && block.startLine >= source.startLine
          && block.endLineExclusive <= source.endLineExclusive
      })
      .max(by: { lhs, rhs in
        if lhs.endLineExclusive != rhs.endLineExclusive {
          return lhs.endLineExclusive < rhs.endLineExclusive
        }
        return lhs.startLine < rhs.startLine
      }) {
      await insertBlock(after: lastBlock, kind: .paragraph)
      return
    }

    let draft = appendDraftBlock(kind: .paragraph, in: source)
    transientDraftBlock = draft
    pendingBlockSelection = nil
    isEditingEntry = false
    activateTransientDraft(draft)
    statusText = "Started paragraph draft in \(relativePath(source.file))"
  }

  public func canMoveSelectedBlock(_ direction: OrgBlockMoveDirection) -> Bool {
    guard let selectedBlock else { return false }
    return canMoveBlock(selectedBlock, direction: direction)
  }

  public func saveActiveEdit() async {
    if isEditingEntry {
      await saveEditedEntry()
      return
    }

    if let draft = transientDraftBlock, editingBlockID == draft.block.id {
      await saveTransientDraftBlock(draft)
      return
    }

    guard let block = activeEditingBlock else {
      if isLiveFileEditorAvailable && liveFileEditorHasUnsavedChanges {
        await saveLiveFileEditor(explicit: true)
        return
      }
      await encryptSelectedFileAfterSave()
      return
    }
    await saveEditedBlock(block)
  }

  public func saveAndFinishActiveEdit() async {
    if isEditingEntry {
      if entryEditorHasUnsavedChanges {
        await saveEditedEntry()
      }
      guard isEditingEntry, !entryEditorHasUnsavedChanges else { return }
      cancelEditingSelectedEntry()
      return
    }

    await saveActiveEdit()
  }

  private var selectedFileForOrgCryptSave: String? {
    selectedEntrySource?.file ?? selectedLocation?.file
  }

  private func encryptSelectedFileAfterSave() async {
    guard orgCryptEncryptOnSave else {
      statusText = "No active edit to save"
      return
    }
    guard let file = selectedFileForOrgCryptSave else {
      statusText = "No file selected"
      return
    }

    do {
      let encryptedCount = try await encryptOrgCryptSubtreesAfterExplicitSave(file: file)
      invalidateCanonicalDocumentCache(for: file)
      if encryptedCount > 0 {
        statusText = "Encrypted \(encryptedCount) subtree\(encryptedCount == 1 ? "" : "s")"
        if let selectedLocation {
          await loadEntrySource(for: selectedLocation)
        }
        scheduleAgendaRefresh(preserveSelection: true)
      } else {
        statusText = "No plaintext :crypt: subtrees to encrypt"
      }
    } catch {
      recordOrgCryptEncryptionFailure(error, savedPrefix: nil)
    }
  }

  public func saveEditedEntry() async {
    guard let source = selectedEntrySource else {
      statusText = "No source loaded"
      return
    }
    guard source.isEditable else {
      statusText = "Selection is read-only"
      return
    }
    guard entryEditorHasUnsavedChanges else {
      statusText = "No source changes to save"
      return
    }

    isSavingEntry = true
    defer { isSavingEntry = false }

    let draft = sourceEditorLocalDraftText ?? editableEntryText
    let formatResult = await formattedEntryTextForSave(draft, source: source)
    let replacement = formatResult.text
    guard selectedEntrySource?.id == source.id,
          isEditingEntry,
          Self.normalizeLineEndings(sourceEditorLocalDraftText ?? editableEntryText)
            == Self.normalizeLineEndings(draft)
    else {
      return
    }
    let undoSnapshot = fileUndoSnapshot(for: source.file)
    do {
      try await Task.detached(priority: .userInitiated) {
        try Self.replaceEntrySource(source, with: replacement)
      }.value
    } catch {
      errorText = error.localizedDescription
      if case WorkspaceEditError.fileChanged = error {
        presentEditorSaveConflict(source: source, draft: replacement)
        statusText = "Save conflict: file changed on disk"
      } else {
        statusText = "Save failed"
      }
      return
    }

    let savedStatus: String
    do {
      let encryptedCount = try await encryptOrgCryptSubtreesAfterExplicitSave(file: source.file)
      savedStatus = encryptedCount > 0
        ? "Saved and encrypted \(encryptedCount) subtree\(encryptedCount == 1 ? "" : "s")"
        : "Saved \(relativePath(source.file)):\(source.displayRange)"
    } catch {
      recordOrgCryptEncryptionFailure(error, savedPrefix: "Saved, but")
      recordFileUndo(from: undoSnapshot)
      await finishSavedEntry(source: source, savedText: replacement, keepEditing: true)
      return
    }

    recordFileUndo(from: undoSnapshot)
    statusText = formatResult.warning.map { "\(savedStatus), but \($0)" } ?? savedStatus
    await finishSavedEntry(
      source: source,
      savedText: replacement,
      keepEditing: !savedStatus.contains("encrypted")
    )
  }

  private func formattedEntryTextForSave(
    _ text: String,
    source: EntrySource
  ) async -> (text: String, warning: String?) {
    guard formatOrgFilesOnSave,
          selectedEntrySourceMode == .page,
          source.startLine == 1,
          !source.isSubtree,
          Self.isOrgTextFile(URL(fileURLWithPath: source.file))
    else {
      return (text, nil)
    }

    do {
      return (try await cli.formatOrgText(text), nil)
    } catch {
      return (text, "formatting failed: \(error.localizedDescription)")
    }
  }

  private func presentEditorSaveConflict(source: EntrySource, draft: String) {
    editorSaveConflictSource = source
    editorSaveConflictDraft = draft
    editorSaveConflict = Org2EditorSaveConflict(
      file: source.file,
      canOverwrite: selectedEntrySourceMode == .page
        && source.startLine == 1
        && !source.isSubtree
    )
  }

  public func keepEditingAfterSaveConflict() {
    guard editorSaveConflictSource != nil else { return }
    clearEditorSaveConflict()
    statusText = "Kept unsaved editor changes"
  }

  public func reloadAfterSaveConflict() async {
    guard let conflict = editorSaveConflict else { return }
    let shouldResumeEditing = isEditingEntry
    clearEditorSaveConflict()
    errorText = nil
    cancelLiveFileEditorAutosave(resetStatus: true)
    cancelEditingSelectedEntry()
    guard let selectedLocation else {
      statusText = "Could not reload \(relativePath(conflict.file))"
      return
    }
    await loadEntrySource(for: selectedLocation)
    if shouldResumeEditing {
      beginEditingSelectedEntry()
    }
    statusText = "Reloaded \(relativePath(conflict.file)) from disk"
  }

  public func overwriteAfterSaveConflict() async {
    guard let conflict = editorSaveConflict,
          conflict.canOverwrite,
          let source = editorSaveConflictSource,
          let replacement = editorSaveConflictDraft,
          source.file == conflict.file,
          selectedEntrySource?.file == conflict.file
    else {
      statusText = "The conflicted file is no longer selected"
      clearEditorSaveConflict()
      return
    }

    isSavingEntry = true
    defer { isSavingEntry = false }

    let undoSnapshot = fileUndoSnapshot(for: source.file)
    let backupURL: URL
    do {
      backupURL = try await Task.detached(priority: .userInitiated) {
        try Self.overwriteConflictedPage(source, with: replacement)
      }.value
    } catch {
      errorText = error.localizedDescription
      statusText = "Conflict overwrite failed"
      return
    }

    clearEditorSaveConflict()
    errorText = nil
    recordFileUndo(from: undoSnapshot)
    await finishSavedEntry(source: source, savedText: replacement, keepEditing: true)
    statusText = "Saved \(relativePath(source.file)); recovery copy: \(relativePath(backupURL.path))"
  }

  private func clearEditorSaveConflict() {
    editorSaveConflict = nil
    editorSaveConflictSource = nil
    editorSaveConflictDraft = nil
  }

  public func noteLiveFileEditorTextChanged(_ text: String) {
    guard isLiveFileEditorSelected else { return }
    if editableEntryText != text {
      editableEntryText = text
    }
    liveFileEditorStatusText = liveFileEditorHasUnsavedChanges ? "Unsaved" : "Saved"
    scheduleLiveFileEditorAutosave()
  }

  public func revertLiveFileEditor() {
    cancelLiveFileEditorAutosave(resetStatus: true)
    editableEntryText = selectedEntrySource?.text ?? ""
    liveFileEditorStatusText = "Reverted"
  }

  public func saveLiveFileEditor(explicit: Bool) async {
    if explicit {
      cancelLiveFileEditorAutosave(resetStatus: false)
    }

    guard let source = selectedEntrySource, source.isEditable, isLiveFileEditorSelected else {
      if explicit {
        statusText = "No editable file loaded"
      }
      return
    }

    let replacement = editableEntryText
    let hasTextChanges = Self.normalizeLineEndings(replacement) != Self.normalizeLineEndings(source.text)
    guard hasTextChanges else {
      liveFileEditorStatusText = "Saved"
      if explicit {
        await encryptSelectedFileAfterSave()
      }
      return
    }

    let undoSnapshot = fileUndoSnapshot(for: source.file)
    if explicit {
      isSavingEntry = true
    } else {
      isLiveFileEditorAutosaving = true
    }
    defer {
      if explicit {
        isSavingEntry = false
      } else {
        isLiveFileEditorAutosaving = false
      }
    }

    do {
      if explicit {
        try await Task.detached(priority: .userInitiated) {
          try Self.replaceEntrySource(source, with: replacement)
        }.value
      } else {
        guard selectedEntrySource?.id == source.id,
              Self.normalizeLineEndings(editableEntryText) == Self.normalizeLineEndings(replacement)
        else {
          return
        }
        try Self.replaceEntrySource(source, with: replacement)
      }
    } catch {
      errorText = error.localizedDescription
      if case WorkspaceEditError.fileChanged = error {
        if explicit {
          presentEditorSaveConflict(source: source, draft: replacement)
        }
        liveFileEditorStatusText = "Conflict"
        statusText = "Save conflict: file changed on disk"
      } else {
        liveFileEditorStatusText = explicit ? "Save failed" : "Autosave failed"
      }
      if explicit {
        if !statusText.hasPrefix("Save conflict") {
          statusText = "Save failed"
        }
      }
      return
    }

    guard selectedEntrySource?.id == source.id else {
      recordFileUndo(from: undoSnapshot)
      return
    }
    if !explicit {
      guard Self.normalizeLineEndings(editableEntryText) == Self.normalizeLineEndings(replacement) else {
        return
      }
    }

    selectedEntrySource = Self.entrySource(source, replacingText: replacement)
    invalidateCanonicalDocumentCache(for: source.file)
    if let corpusRoot {
      upsertCorpusFile(corpusFile(for: URL(fileURLWithPath: source.file), corpusRoot: corpusRoot))
    }

    if explicit {
      let savedStatus: String
      do {
        let encryptedCount = try await encryptOrgCryptSubtreesAfterExplicitSave(file: source.file)
        savedStatus = encryptedCount > 0
          ? "Saved and encrypted \(encryptedCount) subtree\(encryptedCount == 1 ? "" : "s")"
          : "Saved \(relativePath(source.file))"
      } catch {
        recordOrgCryptEncryptionFailure(error, savedPrefix: "Saved, but")
        recordFileUndo(from: undoSnapshot)
        liveFileEditorStatusText = "Saved"
        scheduleAgendaRefresh(preserveSelection: true)
        return
      }

      recordFileUndo(from: undoSnapshot)
      statusText = savedStatus
      liveFileEditorStatusText = "Saved"
      if savedStatus.contains("encrypted"), let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      scheduleAgendaRefresh(preserveSelection: true)
    } else {
      recordFileUndo(from: undoSnapshot)
      liveFileEditorStatusText = "Autosaved"
      scheduleAgendaRefresh(preserveSelection: true)
    }
  }

  private func finishSavedEntry(
    source: EntrySource,
    savedText: String,
    keepEditing: Bool
  ) async {
    invalidateCanonicalDocumentCache(for: source.file)
    let savedSource = Self.entrySource(source, replacingText: savedText)
    selectedEntrySource = savedSource
    editableEntryText = savedSource.text
    sourceEditorLocalDraftText = keepEditing ? savedSource.text : nil
    sourceEditorInteraction.reset(
      text: savedSource.text,
      selection: Self.clampedSourceEditorSelection(sourceEditorSelection, in: savedSource.text)
    )
    isEditingEntry = keepEditing
    if !keepEditing, let selectedLocation {
      cancelSourceEditorPreviewRender(clearStatus: true)
      await loadEntrySource(for: selectedLocation)
    } else {
      renderEntrySource(savedSource, generation: entrySourceLoadGeneration)
    }
    scheduleAgendaRefresh(preserveSelection: true)
  }

  private func scheduleLiveFileEditorAutosave() {
    guard isLiveFileEditorAvailable else { return }
    guard liveFileEditorHasUnsavedChanges else {
      cancelLiveFileEditorAutosave(resetStatus: false)
      liveFileEditorStatusText = "Saved"
      return
    }

    liveFileEditorAutosaveTask?.cancel()
    liveFileEditorAutosaveGeneration += 1
    let generation = liveFileEditorAutosaveGeneration
    liveFileEditorAutosaveTask = Task { @MainActor [weak self] in
      do {
        try await Task.sleep(nanoseconds: Self.liveFileEditorAutosaveDelayNanoseconds)
      } catch {
        return
      }
      guard let self,
            !Task.isCancelled,
            self.liveFileEditorAutosaveGeneration == generation
      else {
        return
      }
      await self.saveLiveFileEditor(explicit: false)
    }
  }

  private func cancelLiveFileEditorAutosave(resetStatus: Bool) {
    liveFileEditorAutosaveTask?.cancel()
    liveFileEditorAutosaveTask = nil
    liveFileEditorAutosaveGeneration += 1
    if resetStatus {
      liveFileEditorStatusText = ""
    }
  }

  private func persistLiveFileEditorDraftBeforeNavigation() {
    guard isLiveFileEditorAvailable,
          liveFileEditorHasUnsavedChanges,
          let source = selectedEntrySource
    else {
      return
    }

    let replacement = editableEntryText
    Task { @MainActor [weak self, source, replacement] in
      guard let self else { return }
      do {
        let undoSnapshot = self.fileUndoSnapshot(for: source.file)
        try await Task.detached(priority: .utility) {
          try Self.replaceEntrySource(source, with: replacement)
        }.value
        self.recordFileUndo(from: undoSnapshot)
      } catch {
        self.errorText = error.localizedDescription
        self.liveFileEditorStatusText = "Autosave failed"
      }
    }
  }

  private func recordOrgCryptEncryptionFailure(_ error: Error, savedPrefix: String?) {
    let message = error.localizedDescription
    errorText = message
    orgCryptStatusText = message
    if case OrgCryptError.missingEncryptionConfiguration = error {
      statusText = [savedPrefix, "encryption needs configuration"].compactMap(\.self).joined(separator: " ")
      isOrgCryptConfigurationPresented = true
      return
    }
    statusText = [savedPrefix, "encryption failed"].compactMap(\.self).joined(separator: " ")
  }

  func requestSaveRenderedTableView(_ snapshot: OrgHTMLTableViewSnapshot) {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "This table is read-only"
      return
    }
    guard !isEditingEntry else {
      statusText = "Save or close source editing before saving a table view"
      return
    }
    let blocks = selectedRenderedBlocks.isEmpty
      ? OrgEntryRenderer.parseEditable(source.text, baseLine: source.startLine)
      : selectedRenderedBlocks
    guard let block = blocks.first(where: { candidate in
      guard candidate.startLine == snapshot.startLine,
            candidate.endLineExclusive - 1 == snapshot.endLine
      else { return false }
      if case .table = candidate.rendered { return true }
      return false
    }) else {
      statusText = "The table changed; refresh the file and try again"
      return
    }
    guard let replacement = OrgRenderedTableViewMutation.replacement(
      rawText: block.rawText,
      visibleBodyRowIndices: snapshot.visibleBodyRowIndices,
      expectedBodyRowCount: snapshot.totalBodyRowCount
    ) else {
      statusText = "Could not map this view back to the source table"
      return
    }
    guard Self.normalizeLineEndings(replacement) != Self.normalizeLineEndings(block.rawText) else {
      statusText = "The source table already matches this view"
      return
    }

    let hiddenRowCount = max(0, snapshot.totalBodyRowCount - snapshot.visibleBodyRowIndices.count)
    let alert = NSAlert()
    alert.alertStyle = hiddenRowCount > 0 ? .warning : .informational
    alert.messageText = "Save this table view to the source?"
    var details: [String] = []
    if snapshot.sortActive {
      details.append("The source rows will use the current sort order.")
    }
    if hiddenRowCount > 0 {
      details.append(
        "The source will keep the \(snapshot.visibleBodyRowIndices.count) visible row\(snapshot.visibleBodyRowIndices.count == 1 ? "" : "s") and remove \(hiddenRowCount) filtered row\(hiddenRowCount == 1 ? "" : "s")."
      )
    }
    details.append("The header is preserved, and the change can be undone from the Edit menu.")
    alert.informativeText = details.joined(separator: " ")
    alert.addButton(withTitle: "Save View")
    alert.addButton(withTitle: "Cancel")
    guard alert.runModal() == .alertFirstButtonReturn else { return }

    Task { @MainActor [weak self, source, block, replacement] in
      await self?.saveRenderedTableView(replacement, replacing: block, in: source)
    }
  }

  func requestRecalculateRenderedTableFormulas(at startLine: Int) {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "This table is read-only"
      return
    }
    guard !isEditingEntry else {
      statusText = "Save or close source editing before recalculating a table"
      return
    }
    guard !isSavingBlock else {
      statusText = "Another source update is still in progress"
      return
    }

    Task { @MainActor [weak self, source] in
      guard let self, self.selectedEntrySource?.id == source.id else { return }
      self.isSavingBlock = true
      defer { self.isSavingBlock = false }
      do {
        let undoSnapshot = self.fileUndoSnapshot(for: source.file)
        _ = try await self.cli.run([
          "table", "recalculate",
          "--file", source.file,
          "--line", String(startLine),
          "--apply", "--format", "json",
        ])
        self.recordFileUndo(from: undoSnapshot)
        self.invalidateCanonicalDocumentCache(for: source.file)
        let staleRenderKey = self.entryHTMLRenderKey(for: source)
        self.renderedHTMLCache.removeValue(forKey: staleRenderKey)
        self.renderedHTMLCacheOrder.removeAll { $0 == staleRenderKey }
        if let selectedLocation = self.selectedLocation {
          await self.loadEntrySource(for: selectedLocation)
        }
        self.statusText = "Recalculated table formulas at line \(startLine)"
        self.scheduleAgendaRefresh(preserveSelection: true)
      } catch {
        self.errorText = error.localizedDescription
        self.statusText = "Could not recalculate table formulas"
      }
    }
  }

  private func saveRenderedTableView(
    _ replacement: String,
    replacing block: OrgEditableBlock,
    in source: EntrySource
  ) async {
    guard selectedEntrySource?.id == source.id else {
      statusText = "The selected file changed before the table view could be saved"
      return
    }
    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let normalizedReplacement = Self.normalizeLineEndings(replacement)
      let updatedSource = try Self.replacingSourceBlock(block, in: source, with: normalizedReplacement)
      let undoSnapshot = fileUndoSnapshot(for: source.file)
      try await Task.detached(priority: .userInitiated) {
        try Self.replaceSourceRange(
          file: source.file,
          startLine: block.startLine,
          endLineExclusive: block.endLineExclusive,
          replacement: normalizedReplacement,
          expectedOriginal: block.rawText
        )
      }.value
      recordFileUndo(from: undoSnapshot)
      invalidateCanonicalDocumentCache(for: source.file)
      let staleRenderKey = entryHTMLRenderKey(for: source)
      renderedHTMLCache.removeValue(forKey: staleRenderKey)
      renderedHTMLCacheOrder.removeAll { $0 == staleRenderKey }

      if let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      } else if selectedEntrySource?.id == source.id {
        selectedEntrySource = updatedSource
        renderEntrySource(updatedSource, generation: entrySourceLoadGeneration)
      }
      statusText = "Saved table view to \(relativePath(source.file)):\(block.displayRange)"
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = "Could not save table view"
    }
  }

  public func saveEditedBlock(_ block: OrgEditableBlock) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard editingBlockID == block.id else {
      statusText = "Block edit is no longer active"
      return
    }

    if let draft = transientDraftBlock, draft.block.id == block.id {
      await saveTransientDraftBlock(draft)
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let replacement = Self.normalizeLineEndings(saveReplacementText(for: block))
      let sourceBlock = activeBlockOriginals[block.id] ?? block
      if finalizeDeferredStableAutosaveIfCurrent(
        block,
        source: source,
        sourceBlock: sourceBlock,
        replacement: replacement
      ) {
        return
      }

      let undoSnapshot = fileUndoSnapshot(for: source.file)
      let updatedSource = try Self.replacingSourceBlock(
        sourceBlock,
        in: source,
        with: replacement
      )
      let currentRenderedBlocks = selectedRenderedBlocks
      try await Task.detached(priority: .userInitiated) {
        try Self.replaceSourceRange(
          file: source.file,
          startLine: sourceBlock.startLine,
          endLineExclusive: sourceBlock.endLineExclusive,
          replacement: replacement,
          expectedOriginal: sourceBlock.rawText
        )
      }.value
      let encryptedCount = try await encryptOrgCryptSubtreesAfterExplicitSave(file: source.file)

      if encryptedCount > 0 {
        recordFileUndo(from: undoSnapshot)
        guard selectedEntrySource?.id == source.id else { return }
        deferredStableAutosaves.removeValue(forKey: block.id)
        invalidateCanonicalDocumentCache(for: source.file)
        resetBlockEditing()
        statusText = "Saved and encrypted \(encryptedCount) subtree\(encryptedCount == 1 ? "" : "s")"
        if let selectedLocation {
          await loadEntrySource(for: selectedLocation)
        }
        scheduleAgendaRefresh(preserveSelection: true)
        return
      }

      let updatedBlocks = await Task.detached(priority: .userInitiated) {
        Self.locallyUpdatingRenderedBlocks(
          currentRenderedBlocks,
          replacing: block,
          with: replacement
        )
      }.value

      guard selectedEntrySource?.id == source.id else {
        recordFileUndo(from: undoSnapshot)
        return
      }

      recordFileUndo(from: undoSnapshot)
      deferredStableAutosaves.removeValue(forKey: block.id)
      invalidateCanonicalDocumentCache(for: source.file)
      selectedEntrySource = updatedSource
      let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: updatedSource)
      selectedRenderedBlocks = updatedVisibleBlocks
      selectedBlockID = blockForSelectionLine(
        sourceBlock.startLine,
        mode: .containingOrNearest,
        in: updatedVisibleBlocks
      )?.id
      statusText = "Saved block \(relativePath(source.file)):\(sourceBlock.displayRange)"
      resetBlockEditing()
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = "Block save failed"
    }
  }

  private func finalizeDeferredStableAutosaveIfCurrent(
    _ block: OrgEditableBlock,
    source: EntrySource,
    sourceBlock: OrgEditableBlock,
    replacement: String
  ) -> Bool {
    guard let deferred = deferredStableAutosaves[block.id],
          Self.normalizeLineEndings(deferred.block.rawText) == replacement,
          let fileText = try? Self.sourceText(
            file: source.file,
            startLine: deferred.block.startLine,
            endLineExclusive: deferred.block.endLineExclusive
          ),
          Self.normalizeLineEndings(fileText) == replacement
    else {
      return false
    }

    deferredStableAutosaves.removeValue(forKey: block.id)
    if selectedEntrySource?.id == source.id {
      selectedEntrySource = deferred.source
    }
    let updatedBlocks = Self.replacingBlock(
      selectedBlock,
      with: deferred.block,
      in: selectedRenderedBlocks
    )
    setSelectedRenderedBlocks(updatedBlocks, preservingMetadata: true)
    selectedBlockID = deferred.block.id
    invalidateCanonicalDocumentCache(for: source.file)
    statusText = "Saved block \(relativePath(source.file)):\(sourceBlock.displayRange)"
    resetBlockEditing()
    return true
  }

  public func autosaveEditedBlock(_ block: OrgEditableBlock, replacement: String) async {
    guard let source = selectedEntrySource, source.isEditable else { return }
    guard editingBlockID == block.id else { return }
    guard transientDraftBlock?.block.id != block.id else { return }

    let normalizedReplacement = Self.normalizeLineEndings(replacement)
    guard normalizedReplacement != block.rawText else { return }
    guard isCurrentAutosaveDraft(block, in: source, replacement: normalizedReplacement) else {
      return
    }

    let updatedSource: EntrySource
    do {
      updatedSource = try Self.replacingSourceBlock(
        block,
        in: source,
        with: normalizedReplacement
      )
    } catch {
      errorText = error.localizedDescription
      statusText = "Autosave failed"
      return
    }

    do {
      let undoSnapshot = fileUndoSnapshot(for: source.file)
      let file = source.file
      let startLine = block.startLine
      let endLineExclusive = block.endLineExclusive
      try Self.replaceSourceRange(
        file: file,
        startLine: startLine,
        endLineExclusive: endLineExclusive,
        replacement: normalizedReplacement,
        expectedOriginal: block.rawText
      )

      recordFileUndo(from: undoSnapshot)
      guard isCurrentAutosaveDraft(block, in: source, replacement: normalizedReplacement) else {
        return
      }

      let currentRenderedBlocks = selectedRenderedBlocks
      let updatedBlocks = await Task.detached(priority: .utility) {
        Self.locallyUpdatingRenderedBlocks(
          currentRenderedBlocks,
          replacing: block,
          with: normalizedReplacement
        )
      }.value
      guard isCurrentAutosaveDraft(block, in: source, replacement: normalizedReplacement) else {
        return
      }

      let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: updatedSource)
      let parsedUpdatedBlock = blockForSelectionLine(
        block.startLine,
        mode: .containingOrNearest,
        in: updatedVisibleBlocks
      )
      let updatedBlock = parsedUpdatedBlock?.preservingID(block.id)
      let renderedBlocks = Self.replacingBlock(
        parsedUpdatedBlock,
        with: updatedBlock,
        in: updatedVisibleBlocks
      )
      if shouldPreserveRenderedBlockMetadata(
        original: block,
        updated: updatedBlock,
        renderedBlocks: renderedBlocks
      ), let updatedBlock {
        invalidateCanonicalDocumentCache(for: source.file)
        deferredStableAutosaves[block.id] = DeferredStableAutosave(
          source: updatedSource,
          block: updatedBlock
        )
        activeBlockDrafts[updatedBlock.id] = normalizedReplacement
        pendingAgendaRefreshAfterBlockEditing = true
        return
      }

      invalidateCanonicalDocumentCache(for: source.file)
      selectedEntrySource = updatedSource
      setSelectedRenderedBlocks(
        renderedBlocks,
        preservingMetadata: shouldPreserveRenderedBlockMetadata(
          original: block,
          updated: updatedBlock,
          renderedBlocks: renderedBlocks
        )
      )
      if selectedBlockID != updatedBlock?.id {
        selectedBlockID = updatedBlock?.id
      }
      if editingBlockID != updatedBlock?.id {
        editingBlockID = updatedBlock?.id
      }
      if editableBlockText != normalizedReplacement {
        editableBlockText = normalizedReplacement
      }
      if let updatedBlock {
        activeBlockDrafts[updatedBlock.id] = normalizedReplacement
      }
      pendingAgendaRefreshAfterBlockEditing = true
    } catch {
      errorText = error.localizedDescription
      statusText = "Autosave failed"
    }
  }

  private func setSelectedRenderedBlocks(
    _ blocks: [OrgEditableBlock],
    preservingMetadata: Bool
  ) {
    if preservingMetadata {
      preservesSelectedRenderedBlocksMetadataForNextAssignment = true
    }
    selectedRenderedBlocks = blocks
    foldedRenderedBlockIDs = OrgRenderedFoldTree.prunedFoldedIDs(foldedRenderedBlockIDs, blocks: blocks)
  }

  private func shouldPreserveRenderedBlockMetadata(
    original: OrgEditableBlock,
    updated: OrgEditableBlock?,
    renderedBlocks: [OrgEditableBlock]
  ) -> Bool {
    guard let updated else { return false }
    return updated.id == original.id
      && updated.startLine == original.startLine
      && updated.endLineExclusive == original.endLineExclusive
      && renderedBlocks.count == selectedRenderedBlocks.count
      && selectedRenderedBlockIndexes[updated.id] != nil
  }

  private func isCurrentAutosaveDraft(
    _ block: OrgEditableBlock,
    in source: EntrySource,
    replacement: String
  ) -> Bool {
    selectedEntrySource?.id == source.id
      && editingBlockID == block.id
      && Self.normalizeLineEndings(activeBlockDrafts[block.id] ?? "") == replacement
  }

  private func saveReplacementText(for block: OrgEditableBlock) -> String {
    editingDraftText(for: block)
  }

  private func editingDraftText(for block: OrgEditableBlock) -> String {
    if let draft = activeBlockDrafts[block.id],
       draft != block.rawText {
      return draft
    }
    if editableBlockText != block.rawText {
      return editableBlockText
    }
    return activeBlockDrafts[block.id] ?? editableBlockText
  }

  public func splitEditingBlock(_ block: OrgEditableBlock, atUTF16Offset offset: Int, draftText: String? = nil) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard editingBlockID == block.id else {
      statusText = "Block edit is no longer active"
      return
    }
    let activeTransientDraft = transientDraftBlock?.block.id == block.id ? transientDraftBlock : nil
    let sourceBlock = activeTransientDraft == nil ? activeBlockOriginals[block.id] ?? block : block
    guard block.isEditable,
          sourceBlock.startLine >= source.startLine,
          sourceBlock.endLineExclusive <= source.endLineExclusive || activeTransientDraft != nil
    else {
      statusText = "Block cannot be split"
      return
    }
    let draft = draftText ?? editingDraftText(for: block)
    guard let plan = Self.splitBlockPlan(for: block, draft: draft, utf16Offset: offset) else {
      statusText = "Block cannot be split"
      return
    }
    if let activeTransientDraft {
      await splitTransientDraftBlock(activeTransientDraft, originalBlock: block, plan: plan)
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let undoSnapshot = fileUndoSnapshot(for: source.file)
      if let replacement = plan.replacement {
        try await Task.detached(priority: .userInitiated) {
          try Self.replaceSourceRange(
            file: source.file,
            startLine: sourceBlock.startLine,
            endLineExclusive: sourceBlock.endLineExclusive,
            replacement: replacement,
            expectedOriginal: sourceBlock.rawText
          )
        }.value
        recordFileUndo(from: undoSnapshot)
        invalidateCanonicalDocumentCache(for: source.file)
      }
      isEditingEntry = false

      let draftToActivate: TransientDraftBlock?
      if let draftSpec = plan.draft {
        let draft = transientDraftBlock(
          from: draftSpec,
          sourceFile: source.file,
          originalBlock: sourceBlock
        )
        transientDraftBlock = draft
        draftToActivate = draft
        statusText = "Started draft in \(relativePath(source.file))"
      } else if let newBlockLineOffset = plan.newBlockLineOffset {
        draftToActivate = nil
        transientDraftBlock = nil
        resetBlockEditing()
        pendingBlockSelection = PendingBlockSelection(
          file: source.file,
          line: sourceBlock.startLine + newBlockLineOffset,
          mode: .containingOrNearest,
          beginEditing: true
        )
        statusText = "Split block in \(relativePath(source.file))"
      } else {
        draftToActivate = nil
      }

      if plan.replacement != nil, let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      if let draftToActivate {
        activateTransientDraft(draftToActivate)
      }
      if plan.replacement != nil {
        scheduleAgendaRefresh(preserveSelection: true)
      }
    } catch {
      errorText = error.localizedDescription
      statusText = "Split failed"
    }
  }

  private func splitTransientDraftBlock(
    _ activeDraft: TransientDraftBlock,
    originalBlock block: OrgEditableBlock,
    plan: SplitBlockPlan
  ) async {
    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let undoSnapshot = fileUndoSnapshot(for: activeDraft.file)
      if let replacementBody = plan.replacement {
        let replacement = "\(activeDraft.replacementPrefix)\(replacementBody)\(activeDraft.replacementSuffix)"
        try await Task.detached(priority: .userInitiated) {
          try Self.replaceSourceRange(
            file: activeDraft.file,
            startLine: activeDraft.insertionLine,
            endLineExclusive: activeDraft.replacementEndLineExclusive,
            replacement: replacement
          )
        }.value
        recordFileUndo(from: undoSnapshot)
        invalidateCanonicalDocumentCache(for: activeDraft.file)
      }

      selectedRenderedBlocks.removeAll { $0.id == activeDraft.block.id }
      activeBlockDrafts.removeValue(forKey: activeDraft.block.id)
      activeBlockOriginals.removeValue(forKey: activeDraft.block.id)
      isEditingEntry = false
      let bodyLineOffset = Self.lineBreakCount(in: activeDraft.replacementPrefix)

      let draftToActivate: TransientDraftBlock?
      if let draftSpec = plan.draft {
        let draftBaseBlock = bodyLineOffset == 0
          ? block
          : Self.shiftedBlock(block, by: bodyLineOffset)
        let nextDraft = transientDraftBlock(
          from: draftSpec,
          sourceFile: activeDraft.file,
          originalBlock: draftBaseBlock
        )
        transientDraftBlock = nextDraft
        draftToActivate = nextDraft
        statusText = "Started draft in \(relativePath(activeDraft.file))"
      } else if let newBlockLineOffset = plan.newBlockLineOffset {
        draftToActivate = nil
        transientDraftBlock = nil
        resetBlockEditing()
        pendingBlockSelection = PendingBlockSelection(
          file: activeDraft.file,
          line: block.startLine + bodyLineOffset + newBlockLineOffset,
          mode: .containingOrNearest,
          beginEditing: true
        )
        statusText = "Split block in \(relativePath(activeDraft.file))"
      } else {
        draftToActivate = nil
        transientDraftBlock = nil
        resetBlockEditing()
      }

      if plan.replacement != nil, let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      if let draftToActivate {
        activateTransientDraft(draftToActivate)
      }
      if plan.replacement != nil {
        scheduleAgendaRefresh(preserveSelection: true)
      }
    } catch {
      errorText = error.localizedDescription
      statusText = "Split failed"
    }
  }

  public func deleteBackwardFromStartOfEditingBlock(_ block: OrgEditableBlock, draftText: String? = nil) async {
    let draft = Self.normalizeLineEndings(draftText ?? editingDraftText(for: block))
    if draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      if transientDraftBlock?.block.id == block.id {
        let fallbackSelection = previousMergeTarget(before: block)
        discardTransientDraft(status: "Draft discarded")
        selectedBlockID = fallbackSelection?.id
        return
      }
      await deleteBlock(block)
      return
    }

    await mergeEditingBlockBackward(block, draftText: draft)
  }

  private func mergeEditingBlockBackward(_ block: OrgEditableBlock, draftText: String) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard editingBlockID == block.id else {
      statusText = "Block edit is no longer active"
      return
    }
    guard block.isEditable,
          block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
            || transientDraftBlock?.block.id == block.id
    else {
      statusText = "Block cannot be merged"
      return
    }
    guard let previous = previousMergeTarget(before: block) else {
      statusText = "No previous text block"
      return
    }
    guard let replacement = Self.mergedTextBlockRawText(
      previous: previous,
      current: block,
      currentDraft: draftText
    ) else {
      statusText = "Blocks cannot be merged"
      return
    }

    let isTransientMerge = transientDraftBlock?.block.id == block.id
    let replacementStartLine = previous.startLine
    let replacementEndLineExclusive = isTransientMerge ? previous.endLineExclusive : block.endLineExclusive

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let undoSnapshot = fileUndoSnapshot(for: source.file)
      let expectedOriginal = try Self.sourceText(
        in: source,
        startLine: replacementStartLine,
        endLineExclusive: replacementEndLineExclusive
      )
      let updatedSource = try Self.replacingSourceRange(
        in: source,
        startLine: replacementStartLine,
        endLineExclusive: replacementEndLineExclusive,
        replacement: replacement
      )
      try await Task.detached(priority: .userInitiated) {
        try Self.replaceSourceRange(
          file: source.file,
          startLine: replacementStartLine,
          endLineExclusive: replacementEndLineExclusive,
          replacement: replacement,
          expectedOriginal: expectedOriginal
        )
      }.value

      let updatedBlocks = await Task.detached(priority: .userInitiated) {
        OrgEntryRenderer.parseEditable(updatedSource.text, baseLine: updatedSource.startLine)
      }.value

      guard selectedEntrySource?.id == source.id else {
        recordFileUndo(from: undoSnapshot)
        return
      }

      recordFileUndo(from: undoSnapshot)
      invalidateCanonicalDocumentCache(for: source.file)
      transientDraftBlock = nil
      resetBlockEditing()
      isEditingEntry = false
      selectedEntrySource = updatedSource
      let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: updatedSource)
      setSelectedRenderedBlocks(updatedVisibleBlocks, preservingMetadata: false)
      if let mergedBlock = blockForSelectionLine(
        previous.startLine,
        mode: .containingOrNearest,
        in: updatedVisibleBlocks
      ) {
        selectedBlockID = mergedBlock.id
        editingBlockID = mergedBlock.id
        editableBlockText = mergedBlock.rawText
        activeBlockDrafts[mergedBlock.id] = mergedBlock.rawText
        activeBlockOriginals[mergedBlock.id] = mergedBlock
      }
      statusText = "Merged block in \(relativePath(source.file))"
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = "Merge failed"
    }
  }

  public func convertEditingBlock(_ block: OrgEditableBlock, to kind: OrgInsertBlockKind, draftText: String? = nil) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard editingBlockID == block.id else {
      statusText = "Block edit is no longer active"
      return
    }
    guard block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block is outside the selected source"
      return
    }

    let draftText = draftText ?? editingDraftText(for: block)
    let draft = conversionDraftBlock(for: kind, replacing: block, in: source, draft: draftText)
    transientDraftBlock = draft
    pendingBlockSelection = nil
    isEditingEntry = false
    activateTransientDraft(draft)
    statusText = "Converted block to \(kind.title.lowercased()) draft"
  }

  public func insertBlock(after block: OrgEditableBlock, kind: OrgInsertBlockKind, initialText: String? = nil) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block is outside the selected source"
      return
    }

    let draft = insertionDraftBlock(for: kind, after: block, in: source, initialText: initialText)
    transientDraftBlock = draft
    pendingBlockSelection = nil
    isEditingEntry = false
    activateTransientDraft(draft)
    statusText = "Started \(kind.title.lowercased()) draft in \(relativePath(source.file))"
  }

  public func toggleListItemCheckbox(_ block: OrgEditableBlock) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block is outside the selected source"
      return
    }
    guard case .listItem(_, _, let checkbox, _) = block.rendered,
          let checkbox,
          let replacement = Self.toggledListItemCheckboxRawText(block.rawText, current: checkbox)
    else {
      statusText = "List item has no checkbox"
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      try await replaceBlockSourceAndFinish(
        source: source,
        block: block,
        replacement: replacement,
        status: checkbox == .checked ? "Marked incomplete" : "Marked complete",
        selectLine: block.startLine
      )
    } catch {
      errorText = error.localizedDescription
      statusText = "Checkbox update failed"
    }
  }

  public func toggleHeadingTodo(_ block: OrgEditableBlock) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block is outside the selected source"
      return
    }
    guard case .heading(let heading) = block.rendered,
          let currentStatus = heading.todo,
          let nextStatus = Self.nextHeadingTodoStatus(after: currentStatus),
          let replacement = Self.toggledHeadingTodoRawText(
            block.rawText,
            current: currentStatus,
            next: nextStatus
          )
    else {
      statusText = "Heading has no TODO keyword"
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      try await replaceBlockSourceAndFinish(
        source: source,
        block: block,
        replacement: replacement,
        status: "\(nextStatus) -> heading",
        selectLine: block.startLine
      )
    } catch {
      errorText = error.localizedDescription
      statusText = "TODO update failed"
    }
  }

  public nonisolated static func nextHeadingTodoStatus(after current: String) -> String? {
    let normalized = current.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
    guard !normalized.isEmpty else { return nil }
    if doneHeadingTodoKeywords.contains(normalized) {
      return "TODO"
    }
    if activeHeadingTodoKeywords.contains(normalized) {
      return "DONE"
    }
    return nil
  }

  public func setHeadingPriority(_ block: OrgEditableBlock, priority: String?) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block is outside the selected source"
      return
    }
    guard case .heading = block.rendered,
          let replacement = Self.headingRawTextSettingPriority(block.rawText, priority: priority)
    else {
      statusText = "Heading priority update failed"
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      try await replaceBlockSourceAndFinish(
        source: source,
        block: block,
        replacement: replacement,
        status: priority.map { "[#\($0)] -> heading" } ?? "Priority cleared",
        selectLine: block.startLine
      )
    } catch {
      errorText = error.localizedDescription
      statusText = "Priority update failed"
    }
  }

