    createOpenClawChatThread(
      title: "Shared AI Room",
      statusText: "Shared room ready · @mention an agent to request a response",
      runtime: .openClaw,
      isSharedRoom: true,
      roomAudience: .thread,
      defersPersistence: true
    )
