  private func rebuildExternalThreadDisplayCache() {
    let query = externalThreadSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    guard !query.isEmpty else {
      filteredExternalThreads = externalThreads
      return
    }
    filteredExternalThreads = externalThreads.filter { thread in
      [thread.title, thread.preview, thread.workspacePath, thread.source]
        .compactMap { $0?.lowercased() }
        .contains { $0.contains(query) }
    }
  }

  public func openExternalThreads() {
    makeSurfacePrimary(.externalThreads)
  }

  public func refreshExternalThreads() async {
    let requestID = UUID()
    let searchQuery = externalThreadSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    externalThreadRefreshRequestID = requestID
    isRefreshingExternalThreads = true
    externalThreadError = nil
    defer {
      if externalThreadRefreshRequestID == requestID {
        externalThreadRefreshRequestID = nil
        isRefreshingExternalThreads = false
      }
    }
    do {
      let summaries = try await externalThreadSummaries(searchQuery: searchQuery)
      guard externalThreadRefreshRequestID == requestID,
            externalThreadSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines) == searchQuery
      else { return }
      externalThreads = summaries
      if let selectedExternalThreadID,
         !externalThreads.contains(where: { $0.id == selectedExternalThreadID }) {
        self.selectedExternalThreadID = nil
        selectedExternalThreadDetail = nil
      }
    } catch is CancellationError {
      return
    } catch {
      guard externalThreadRefreshRequestID == requestID else { return }
      externalThreadError = error.localizedDescription
    }
  }

  public func updateExternalThreadSearchQuery(_ searchQuery: String) async {
    externalThreadSearchQuery = searchQuery
    await refreshExternalThreads()
  }

  public func externalThreadSummaries(
    searchQuery: String = ""
  ) async throws -> [ExternalThreadSummary] {
    let localCodexThreadIDs = Set(openClawChatThreads.compactMap { thread in
      thread.runtime == .codex || thread.isSharedRoom ? thread.runtimeThreadID : nil
    })
    let normalizedSearchQuery = searchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    let summaries: [ExternalThreadSummary]
    if normalizedSearchQuery.isEmpty {
      summaries = try await externalCodexClient().listExternalThreads(limit: 100)
    } else {
      summaries = try await externalCodexClient().searchExternalThreads(
        normalizedSearchQuery,
        limit: 100
      )
    }
    let filteredSummaries = summaries.filter {
      !localCodexThreadIDs.contains($0.externalID)
    }
    let summariesByID = Dictionary(uniqueKeysWithValues: filteredSummaries.map { ($0.id, $0) })
    externalThreadDetailCache = externalThreadDetailCache.filter { id, detail in
      summariesByID[id]?.updatedAt == detail.thread.updatedAt
    }
    externalThreadDetailCacheOrder.removeAll { externalThreadDetailCache[$0] == nil }
    return filteredSummaries
  }

  public func selectExternalThread(_ id: String) async {
    guard let summary = externalThreads.first(where: { $0.id == id }) else { return }
    selectedExternalThreadID = id
    selectedExternalThreadDetail = nil
    await loadExternalThread(harness: summary.harness, externalID: summary.externalID)
  }

  public func loadExternalThread(
    harness: ExternalThreadHarness,
    externalID: String
  ) async {
    let requestID = UUID()
    externalThreadLoadRequestID = requestID
    isLoadingExternalThread = true
    externalThreadError = nil
    defer {
      if externalThreadLoadRequestID == requestID {
        externalThreadLoadRequestID = nil
        isLoadingExternalThread = false
      }
    }
    do {
      let detail = try await externalThreadDetail(harness: harness, externalID: externalID)
      guard externalThreadLoadRequestID == requestID,
            selectedExternalThreadID == detail.thread.id
      else { return }
      selectedExternalThreadDetail = detail
    } catch {
      if externalThreadLoadRequestID == requestID {
        externalThreadError = error.localizedDescription
      }
    }
  }

  public func reportExternalThreadActionError(_ error: Error) {
    externalThreadError = error.localizedDescription
    statusText = "External thread action failed"
  }

  public func externalThreadDetail(
    harness: ExternalThreadHarness,
    externalID: String
  ) async throws -> ExternalThreadDetail {
    let cacheID = "\(harness.rawValue):\(externalID)"
    if let cached = externalThreadDetailCache[cacheID] {
      touchExternalThreadDetailCache(cacheID)
      return cached
    }
    let detail: ExternalThreadDetail
    switch harness {
    case .codex:
      detail = try await externalCodexClient().readExternalThread(externalID)
    }
    externalThreadDetailCache[cacheID] = detail
    touchExternalThreadDetailCache(cacheID)
    while externalThreadDetailCacheOrder.count > Self.externalThreadDetailCacheLimit {
      externalThreadDetailCache.removeValue(forKey: externalThreadDetailCacheOrder.removeFirst())
    }
    return detail
  }

  private func touchExternalThreadDetailCache(_ id: String) {
    externalThreadDetailCacheOrder.removeAll { $0 == id }
    externalThreadDetailCacheOrder.append(id)
  }

  @discardableResult
  public func saveExternalThreadToOrg2(
    _ detail: ExternalThreadDetail,
    opensDocument: Bool = true
  ) async throws -> URL {
    guard let corpusRoot else {
      throw CodexAppServerError.invalidResponse("Open an Org2 corpus before importing a thread")
    }
    let relativePath = Self.externalThreadSnapshotRelativePath(detail.thread)
    let destination = corpusRoot.appendingPathComponent(relativePath).standardizedFileURL
    let content = Self.externalThreadSnapshotText(detail)
    try await Task.detached(priority: .userInitiated) {
      try FileManager.default.createDirectory(
        at: destination.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
      try content.write(to: destination, atomically: true, encoding: .utf8)
    }.value
    invalidateCanonicalDocumentCache(for: destination.path)
    if opensDocument {
      openFile(path: destination.path, line: 1)
      statusText = "Saved external thread to \(relativePath)"
    }
    Task { @MainActor [weak self] in
      await self?.refreshCorpusFiles()
    }
    return destination
  }

  @discardableResult
  public func continueExternalThreadInOrg2(
    _ detail: ExternalThreadDetail,
    selectsThread: Bool = true
  ) async throws -> UUID {
    let snapshotURL = try await saveExternalThreadToOrg2(detail, opensDocument: false)
    let relativePath = relativePath(snapshotURL.path)
    let title = Self.normalizedOpenClawThreadTitle("Continue: \(detail.thread.title)")
    let thread = createOpenClawChatThread(
      title: title,
      statusText: "External thread ready to continue",
      runtime: .codex,
      selectsThread: selectsThread
    )
    let reference = "\(mappedPathForOpenClaw(snapshotURL.path)):1"
    let draft = OpenClawContextPresentation.automaticContext(
      kind: "external \(detail.thread.harness.title) thread",
      title: detail.thread.title,
      reference: reference,
      prompt: "Continue the conversation using the imported read-only transcript as context."
    )
    cacheOpenClawDraft(draft, for: thread.id)
    if selectsThread {
      publishOpenClawComposerDraft(draft)
      makeSurfacePrimary(.openClaw)
      openClawStatusText = "Imported \(relativePath) as read-only context"
      statusText = "Started a new Org2 thread from \(detail.thread.harness.title)"
    }
    return thread.id
  }

  nonisolated static func externalThreadSnapshotRelativePath(
    _ thread: ExternalThreadSummary
  ) -> String {
    let base = thread.title.lowercased().unicodeScalars.map { scalar -> Character in
      CharacterSet.alphanumerics.contains(scalar) ? Character(String(scalar)) : "-"
    }
    let slug = String(base)
      .split(separator: "-", omittingEmptySubsequences: true)
      .prefix(10)
      .joined(separator: "-")
    let identifier = thread.externalID.prefix(12)
    return "views/external-threads/\(slug.isEmpty ? "thread" : slug)-\(identifier).org2"
  }

  nonisolated static func externalThreadSnapshotText(_ detail: ExternalThreadDetail) -> String {
    let formatter = ISO8601DateFormatter()
    let thread = detail.thread
    var lines = [
      "* External thread: \(thread.title)",
      ":PROPERTIES:",
      ":ID: external-thread-\(thread.harness.rawValue)-\(thread.externalID)",
      ":KIND: external-thread",
      ":EXTERNAL_HARNESS: \(thread.harness.rawValue)",
      ":EXTERNAL_THREAD_ID: \(thread.externalID)",
      ":EXTERNAL_UPDATED_AT: \(formatter.string(from: thread.updatedAt))",
      ":IMPORTED_AT: \(formatter.string(from: Date()))",
      ":END:",
      "",
      "This is a read-only snapshot imported from \(thread.harness.title). The external task remains the source of truth.",
      ""
    ]
    if let workspacePath = thread.workspacePath {
      lines.append("Workspace: =\(workspacePath)=")
      lines.append("")
    }
    lines.append("** Conversation")
    for message in detail.messages {
      lines.append("")
      lines.append("*** \(message.role == .user ? "You" : thread.harness.title)")
      lines.append(":PROPERTIES:")
      lines.append(":MESSAGE_ID: \(message.id)")
      lines.append(":CREATED_AT: \(formatter.string(from: message.createdAt))")
      lines.append(":END:")
      lines.append(contentsOf: message.content.split(separator: "\n", omittingEmptySubsequences: false).map {
        ": \($0)"
      })
    }
    return lines.joined(separator: "\n") + "\n"
  }

  public func stopOpenClawRun() async {
    guard let threadID = selectedOpenClawChatThreadID else { return }
    _ = await stopAIChatRemoteRun(threadID: threadID)
  }

  @discardableResult
  public func stopAIChatRemoteRun(threadID: UUID) async -> Bool {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      return false
    }
    let activeDestinationID = activeSharedRoomDestinationByThreadID[threadID]
      ?? thread.destinationID
    if aiChatDestination(id: activeDestinationID)?.adapter.isDirectProvider == true {
      guard isAIChatThreadRunning(threadID) else {
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = "No active \(aiChatDestinationTitle(activeDestinationID)) request to stop"
        }
        return false
      }
      markOpenClawRunStopped(
        in: threadID,
        statusText: "\(aiChatDestinationTitle(activeDestinationID)) stopped"
      )
      aiChatDrainTasksByThreadID[threadID]?.task.cancel()
      return true
    }
    let activeRuntime = thread.isSharedRoom
      ? (activeSharedRoomDestinationByThreadID[threadID].map(aiChatDestinationRuntime)
          ?? (codexActiveTurnsByThreadID[threadID] == nil ? .openClaw : .codex))
      : thread.runtime
    if activeRuntime == .codex {
      let destinationName = aiChatDestinationTitle(activeDestinationID)
      guard let active = codexActiveTurnsByThreadID[threadID],
            let codexClient = try? codexClient(forDestinationID: activeDestinationID)
      else {
        guard isAIChatThreadRunning(threadID) else {
          if selectedOpenClawChatThreadID == threadID {
            openClawStatusText = "No active \(destinationName) request to stop"
          }
          return false
        }
        // Codex may still be connecting, authenticating, or creating its
        // runtime thread. Those phases do not have a turn ID yet, but they
        // are still user-cancellable work. Cancel the local drain task; the
        // app-server request cancellation handler releases the pending RPC.
        markOpenClawRunStopped(
          in: threadID,
          statusText: "\(destinationName) stopped"
        )
        aiChatDrainTasksByThreadID[threadID]?.task.cancel()
        return true
      }
      do {
        if thread.isSharedRoom {
          markOpenClawRunStopped(in: threadID)
        }
        try await codexClient.interrupt(
          threadID: active.runtimeThreadID,
          turnID: active.turnID
        )
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = thread.isSharedRoom ? "Shared room stopped" : "Stopping Codex…"
        }
        return true
      } catch {
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = "Could not stop Codex: \(error.localizedDescription)"
        }
        return false
      }
    }
    if activeRuntime == .claude {
      guard isAIChatThreadRunning(threadID) else {
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = "No active Claude Code request to stop"
        }
        return false
      }
      markOpenClawRunStopped(
        in: threadID,
        statusText: thread.isSharedRoom ? "Shared room stopped" : "Claude Code stopped"
      )
      await claudeCodeClient?.interrupt(openOrgThreadID: threadID)
      aiChatDrainTasksByThreadID[threadID]?.task.cancel()
      return true
    }
    guard let gateway = openClawGatewayClientsByThreadID[threadID] else {
      // A recovered run spends time between Gateway connections while its
      // pending turn remains durable. That is still an active run from the
      // user's perspective, and clearing the pending turn is what prevents
      // the recovery loop from immediately resurrecting it.
      guard isAIChatThreadRunning(threadID) else {
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = "No active OpenClaw run to stop"
        }
        return false
      }
      markOpenClawRunStopped(in: threadID)
      return true
    }
    // Make the stop durable before waiting on the Gateway. In particular, a
    // recovered turn keeps a persisted pending-turn record; leaving it in
    // place lets the recovery loop interpret the socket close as a transient
    // disconnect and resurrect the run a few seconds later.
    markOpenClawRunStopped(in: threadID)
    do {
      try await gateway.abort()
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = thread.isSharedRoom ? "Shared room stopped" : "OpenClaw stopped"
      }
      return true
    } catch {
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "Stopped locally; Gateway abort failed: \(error.localizedDescription)"
      }
      return false
    }
  }

  @discardableResult
  public func sendAIChatRemoteMessage(
    _ rawText: String,
    attachments: [OpenClawChatAttachment] = [],
    threadID: UUID,
    delivery: AIChatMessageDeliveryPreference = .automatic
  ) -> Bool {
    sendAIChatRemoteMessageDestination(
      rawText,
      attachments: attachments,
      threadID: threadID,
      delivery: delivery
    ) != nil
  }

  @discardableResult
  public func sendAIChatRemoteMessageDestination(
    _ rawText: String,
    attachments: [OpenClawChatAttachment] = [],
    threadID: UUID,
    delivery: AIChatMessageDeliveryPreference = .automatic
  ) -> UUID? {
    let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !text.isEmpty || !attachments.isEmpty,
          let thread = openClawChatThreads.first(where: { $0.id == threadID }),
          !thread.isSettled
    else {
      return nil
    }
    let destinationThreadID = aiChatDestinationThreadID(
      for: text,
      sourceThreadID: threadID,
      selectsFork: false
    )
    guard submitAIChatMessage(
      text,
      attachments: attachments,
      in: destinationThreadID,
      workspaceContext: threadScopedOpenClawWorkspaceContext(
        for: openClawChatThreads.first(where: { $0.id == destinationThreadID }) ?? thread
      ),
      delivery: delivery
    ) else {
      return nil
    }
    return destinationThreadID
  }

  func drainAIChatInbox() {
    guard let corpusRoot else { return }
    let directory = Self.aiChatInboxDirectory(corpusRoot: corpusRoot)
    guard let files = try? FileManager.default.contentsOfDirectory(
      at: directory,
      includingPropertiesForKeys: nil,
      options: [.skipsHiddenFiles]
    ) else { return }

    for file in files
      .filter({ $0.pathExtension.lowercased() == "json" })
      .sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
      do {
        let values = try file.resourceValues(forKeys: [.fileSizeKey, .isSymbolicLinkKey])
        guard values.isSymbolicLink != true, (values.fileSize ?? 0) <= 512_000 else {
          throw CocoaError(
            .fileReadTooLarge,
            userInfo: [NSLocalizedDescriptionKey: "AI chat inbox envelope is too large or is a symbolic link."]
          )
        }
        let envelope = try JSONDecoder().decode(
          AIChatInboxMessage.self,
          from: Data(contentsOf: file)
        )
        guard envelope.schema == "org2:ai-chat-inbox-message:v1" else {
          throw CocoaError(
            .fileReadCorruptFile,
            userInfo: [NSLocalizedDescriptionKey: "Unsupported AI chat inbox schema in \(file.lastPathComponent)."]
          )
        }
        let content = envelope.content.trimmingCharacters(in: .whitespacesAndNewlines)
        let authorLabel = envelope.authorLabel.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !content.isEmpty, content.count <= 200_000,
              !authorLabel.isEmpty, authorLabel.count <= 200,
              (envelope.authorAgentRef?.count ?? 0) <= 1_000,
              (envelope.source?.count ?? 0) <= 2_000
        else {
          throw CocoaError(
            .validationMissingMandatoryProperty,
            userInfo: [NSLocalizedDescriptionKey: "AI chat inbox message fields are missing or exceed their limits."]
          )
        }
        guard let thread = openClawChatThreads.first(where: { $0.id == envelope.threadID }) else {
          throw CocoaError(
            .fileNoSuchFile,
            userInfo: [NSLocalizedDescriptionKey: "AI chat thread \(envelope.threadID) no longer exists."]
          )
        }

        if thread.messages.contains(where: { $0.id == envelope.id }) {
          if persistOpenClawTranscript() {
            try FileManager.default.removeItem(at: file)
          }
          continue
        }
        if thread.isSettled {
          reopenOpenClawChatThread(thread.id)
        }
        let createdAt = Self.aiChatInboxDate(envelope.createdAt) ?? Date()
        let message = OpenClawChatMessage(
          id: envelope.id,
          role: .assistant,
          content: content,
          createdAt: createdAt,
          authorRuntime: thread.runtime,
          authorLabel: authorLabel,
          authorAgentRef: envelope.authorAgentRef,
          source: envelope.source
        )
        let current = openClawChatThreads.first(where: { $0.id == envelope.threadID }) ?? thread
        let messages = (current.messages + [message]).sorted {
          if $0.createdAt != $1.createdAt { return $0.createdAt < $1.createdAt }
          return $0.id.uuidString < $1.id.uuidString
        }
        updateOpenClawChatThread(
          current.id,
          messages: messages,
          notifiesForNewAssistantMessages: true,
          shouldPersist: false
        )
        guard persistOpenClawTranscript() else { continue }
        try FileManager.default.removeItem(at: file)
        openClawStatusText = "Background message from \(authorLabel)"
      } catch {
        errorText = "AI chat background delivery failed: \(error.localizedDescription)"
      }
    }
  }

  public func updateAIChatRemoteThreadState(
    threadID: UUID,
    isPinned: Bool?,
    isSettled: Bool?
  ) -> Bool {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      return false
    }
    if let isPinned, thread.isPinned != isPinned {
      toggleOpenClawChatThreadPin(threadID)
    }
    if let isSettled {
      let current = openClawChatThreads.first(where: { $0.id == threadID }) ?? thread
      if isSettled, !current.isSettled {
        settleOpenClawChatThread(threadID)
      } else if !isSettled, current.isSettled {
        reopenOpenClawChatThread(threadID)
      }
    }
    return true
  }

  public func mobileRemoteWorkspaceSnapshot(refreshesCanonicalState: Bool = true) async -> MobileRemoteWorkspaceSnapshot {
    if refreshesCanonicalState {
      await refreshAgenda(updatesStatus: false)
      await refreshApprovals(updatesStatus: false)
      await refreshAgentWorkflows(updatesStatus: false)
    }
    return currentMobileRemoteWorkspaceSnapshot()
  }

  public func setMobileRemoteAgendaStatus(itemID: String, status rawStatus: String) async throws -> MobileRemoteWorkspaceSnapshot {
    guard let status = TodoEditStatus(rawValue: rawStatus) else {
      throw CocoaError(
        .validationMissingMandatoryProperty,
        userInfo: [NSLocalizedDescriptionKey: "Choose TODO, in progress, done, or canceled."]
      )
    }
    await refreshAgenda(updatesStatus: false)
    guard let item = currentAgendaItems().first(where: { $0.id == itemID }) else {
      return currentMobileRemoteWorkspaceSnapshot()
    }
    let target = HeadlineMutationTarget(item: item)
    let newStatus = try await setTodoStatus(status, for: target)
    optimisticallyUpdateAgendaItem(id: item.id, todo: newStatus)
    invalidateCanonicalDocumentCache(for: item.file)
    await refreshAgenda(updatesStatus: false)
    return currentMobileRemoteWorkspaceSnapshot()
  }

  public func decideMobileRemoteApproval(
    itemID: String,
    decision: String,
    note rawNote: String?,
    endStatus rawEndStatus: String?
  ) async throws -> MobileRemoteWorkspaceSnapshot {
    await refreshApprovals(updatesStatus: false)
    guard let item = approvalItems.first(where: { $0.id == itemID }) else {
      return currentMobileRemoteWorkspaceSnapshot()
    }
    guard !isApprovalActionInProgress(item) else {
      throw CocoaError(
        .fileWriteUnknown,
        userInfo: [NSLocalizedDescriptionKey: "This approval is already being updated."]
      )
    }

    let normalizedDecision = decision.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    let note = rawNote?.trimmingCharacters(in: .whitespacesAndNewlines)
    let actionKind: ApprovalActionKind = normalizedDecision == "approved" ? .approve : .reject
    beginApprovalAction(item, kind: actionKind)
    defer { endApprovalAction(item, kind: actionKind) }

    var continuationRun: AgentRunItem?
    switch normalizedDecision {
    case "approved":
      if item.isRunApproval {
        continuationRun = try await decideRunApprovalItem(item, decision: "approved")
      } else {
        try await approveAndAgentHandoff(HeadlineMutationTarget(
          file: item.file,
          line: item.line,
          title: Org2Display.cleanInline(item.title),
          idValue: item.idValue
        ))
      }
    case "rejected":
      guard let note, !note.isEmpty else {
        throw CocoaError(
          .validationMissingMandatoryProperty,
          userInfo: [NSLocalizedDescriptionKey: "Enter a reason before rejecting this approval."]
        )
      }
      if item.isRunApproval {
        continuationRun = try await decideRunApprovalItem(item, decision: "rejected", note: note)
      } else {
        let endStatus = rawEndStatus.flatMap(TodoEditStatus.init(rawValue:)) ?? .canceled
        try await rejectApproval(
          HeadlineMutationTarget(
            file: item.file,
            line: item.line,
            title: Org2Display.cleanInline(item.title),
            idValue: item.idValue
          ),
          endStatus: endStatus,
          reason: note
        )
      }
    case "revised":
      guard item.isRunApproval else {
        throw CocoaError(
          .featureUnsupported,
          userInfo: [NSLocalizedDescriptionKey: "Revision requests are available for run-backed approvals."]
        )
      }
      guard let note, !note.isEmpty else {
        throw CocoaError(
          .validationMissingMandatoryProperty,
          userInfo: [NSLocalizedDescriptionKey: "Describe what the agent should change."]
        )
      }
      continuationRun = try await decideRunApprovalItem(item, decision: "revised", note: note)
    default:
      throw CocoaError(
        .validationMissingMandatoryProperty,
        userInfo: [NSLocalizedDescriptionKey: "Choose approve, reject, or request changes."]
      )
    }

    await refreshApprovals(updatesStatus: false)
    if !item.isRunApproval {
      await refreshAgenda(preserveSelection: true, updatesStatus: false)
    }
    if let continuationRun {
      await continueOpenClawAfterApprovalBoundary(continuationRun)
    }
    return currentMobileRemoteWorkspaceSnapshot()
  }

  public func setMobileRemoteWorkflowState(
    workflowID: String,
    state: String
  ) async throws -> MobileRemoteWorkspaceSnapshot {
    await refreshAgentWorkflows(updatesStatus: false)
    guard let workflow = agentWorkflows.first(where: { $0.id == workflowID }) else {
      return currentMobileRemoteWorkspaceSnapshot()
    }
    guard ["active", "paused", "draft"].contains(state) else {
      throw CocoaError(
        .validationMissingMandatoryProperty,
        userInfo: [NSLocalizedDescriptionKey: "Choose active, paused, or draft."]
      )
    }
    guard let corpusRoot, !mutatingAgentWorkflowIDs.contains(workflow.id) else {
      throw CocoaError(
        .fileWriteUnknown,
        userInfo: [NSLocalizedDescriptionKey: "This workflow is already being updated."]
      )
    }
    mutatingAgentWorkflowIDs.insert(workflow.id)
    defer { mutatingAgentWorkflowIDs.remove(workflow.id) }
    let action = state == "active" ? "activate" : state == "paused" ? "pause" : "draft"
    _ = try await cli.run(["workflow", action, workflow.id, "--dir", corpusRoot.path, "--json"])
    await refreshAgentWorkflows(updatesStatus: false)
    try? await syncAgentWorkflowsWithOpenClaw()
    return currentMobileRemoteWorkspaceSnapshot()
  }

  public func runMobileRemoteWorkflow(
    workflowID: String,
    inputs: [String: String]
  ) async throws -> UUID {
    await refreshAgentWorkflows(updatesStatus: false)
    guard let workflow = agentWorkflows.first(where: { $0.id == workflowID }) else {
      throw CocoaError(
        .fileNoSuchFile,
        userInfo: [NSLocalizedDescriptionKey: "That workflow is no longer available."]
      )
    }
    let missingInputs = workflow.inputs.filter { input in
      input.required && (inputs[input.id] ?? input.default ?? "")
        .trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }
    guard missingInputs.isEmpty else {
      throw CocoaError(
        .validationMissingMandatoryProperty,
        userInfo: [NSLocalizedDescriptionKey: "Fill in: \(missingInputs.map(\.id).joined(separator: ", "))."]
      )
    }

    let gateway = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
    let prepared = try await gateway.prepareWorkflowRun(
      workflowID: workflow.id,
      inputs: inputs,
      corpusID: activeCorpusIdentity?.id
    )
    let threadID = createAIChatRemoteThread(runtime: .openClaw)
    guard sendAIChatRemoteMessage(prepared.prompt, threadID: threadID) else {
      throw CocoaError(
        .fileWriteUnknown,
        userInfo: [NSLocalizedDescriptionKey: "The workflow thread could not be started."]
      )
    }
    return threadID
  }

  private func currentMobileRemoteWorkspaceSnapshot() -> MobileRemoteWorkspaceSnapshot {
    let agendaItems = (agenda?.overdue ?? []).flatMap { day in
      day.items.map { mobileRemoteAgendaItem($0, date: day.date) }
    } + (agenda?.days ?? []).flatMap { day in
      day.items.map { mobileRemoteAgendaItem($0, date: day.date) }
    }
    return MobileRemoteWorkspaceSnapshot(
      agenda: agendaItems,
      approvals: approvalItems.map { item in
        MobileRemoteApprovalItem(
          id: item.id,
          title: item.title,
          status: item.status,
          todo: item.todo,
          level: item.level,
          file: item.file,
          line: item.line,
          sourceID: item.idValue,
          properties: item.properties,
          body: item.body,
          tags: item.tags,
          kind: item.kind,
          runID: item.runId,
          approvalID: item.approvalId,
          fingerprint: item.fingerprint,
          action: item.action,
          riskClass: item.riskClass,
          requestedRole: item.requestedRole,
          requestedFrom: item.requestedFrom,
          requestedAt: item.requestedAt,
          runGoal: item.runGoal,
          runStatus: item.runStatus,
          runDecisionEffect: item.runDecisionEffect
        )
      },
      workflows: agentWorkflows.map { workflow in
        MobileRemoteWorkflowItem(
          id: workflow.id,
          title: workflow.title,
          description: workflow.description,
          state: workflow.state,
          riskClass: workflow.riskClass,
          scheduleSummary: workflow.scheduleSummary,
          file: workflow.file,
          agentRef: workflow.agentRef,
          goalRef: workflow.goalRef,
          inputs: workflow.inputs.map {
            MobileRemoteWorkflowInput(
              id: $0.id,
              description: $0.description,
              required: $0.required,
              defaultValue: $0.default
            )
          }
        )
      }
    )
  }

  private func currentAgendaItems() -> [AgendaItem] {
    (agenda?.overdue ?? []).flatMap(\.items) + (agenda?.days ?? []).flatMap(\.items)
  }

  private func mobileRemoteAgendaItem(_ item: AgendaItem, date: String) -> MobileRemoteAgendaItem {
    MobileRemoteAgendaItem(
      id: item.id,
      title: item.headline,
      todo: item.todo ?? "TODO",
      file: item.file,
      line: item.lineForEditor,
      date: date,
      kind: item.kind,
      tags: item.tags,
      body: item.body ?? "",
      priority: item.priority,
      time: item.time,
      effort: item.effort
    )
  }

  public func mobileRemoteFilePreview(
    path rawPath: String,
    line requestedLine: Int?
  ) throws -> MobileRemoteFilePreview {
    let target = try mobileRemotePreviewTarget(for: rawPath)
    guard ["org2", "org", "md", "csv"].contains(target.url.pathExtension.lowercased()) else {
      throw MobileRemoteFilePreviewError.unsupportedFile
    }
    let document = try openClawLocalEditDocument(
      at: target.relativePath,
      corpusRoot: target.root,
      enforcesSnapshotSizeLimit: false
    )
    guard document.origin != .missing else {
      throw MobileRemoteFilePreviewError.unavailable
    }

    var lines = document.text
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    if lines.isEmpty { lines = [""] }
    let highlightedLine = requestedLine.flatMap { line in
      (1...lines.count).contains(line) ? line : nil
    }
    return MobileRemoteFilePreview(
      title: target.url.lastPathComponent,
      relativePath: target.relativePath,
      startLine: 1,
      highlightedLine: highlightedLine,
      content: document.text
    )
  }

  private func mobileRemotePreviewTarget(
    for rawPath: String
  ) throws -> (root: URL, url: URL, relativePath: String) {
    var path = rawPath.trimmingCharacters(in: .whitespacesAndNewlines)
    if path.hasPrefix("~/") {
      path = FileManager.default.homeDirectoryForCurrentUser
        .appendingPathComponent(String(path.dropFirst(2)))
        .path
    }
    guard !path.isEmpty else {
      throw MobileRemoteFilePreviewError.invalidPath
    }

    let roots = workspaceMountPaths()
      .map { URL(fileURLWithPath: $0).resolvingSymlinksInPath().standardizedFileURL }
    let candidates: [(root: URL, url: URL)]
    if path.hasPrefix("/") {
      let url = URL(fileURLWithPath: path).resolvingSymlinksInPath().standardizedFileURL
      candidates = roots.map { ($0, url) }
    } else {
      let relative = path.hasPrefix("./") ? String(path.dropFirst(2)) : path
      candidates = roots.flatMap { root -> [(root: URL, url: URL)] in
        var relativePaths = [relative]
        let corpusPrefix = root.lastPathComponent + "/"
        if relative.hasPrefix(corpusPrefix) {
          relativePaths.append(String(relative.dropFirst(corpusPrefix.count)))
        }
        return relativePaths.map {
          (root, root.appendingPathComponent($0).resolvingSymlinksInPath().standardizedFileURL)
        }
      }
    }

    for candidate in candidates {
      let rootPath = candidate.root.path
      let candidatePath = candidate.url.path
      guard candidatePath.hasPrefix(rootPath + "/"),
            FileManager.default.fileExists(atPath: candidatePath)
      else { continue }
      return (
        candidate.root,
        candidate.url,
        Self.relativePath(for: candidatePath, root: candidate.root)
      )
    }
    throw MobileRemoteFilePreviewError.invalidPath
  }

  public func aiChatRemoteModelOptions(for threadID: UUID) async throws -> [AIChatModelOption] {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      throw AIChatRemoteConfigurationError.threadNotFound
    }
    return try await modelsForAIChatDestination(thread.destinationID)
  }

  public func aiChatRemoteConfiguration(
    for threadID: UUID
  ) async throws -> AIChatRemoteConfiguration {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      throw AIChatRemoteConfigurationError.threadNotFound
    }
    let adapter = aiChatDestination(id: thread.destinationID)?.adapter
      ?? {
        switch thread.runtime {
        case .codex: .codexLocal
        case .claude: .claudeLocal
        case .openClaw: .openClaw
        }
      }()
    switch adapter {
    case .codexLocal, .codexRemote, .codexManagedRemote:
      let models = try await codexClient(forDestinationID: thread.destinationID).listModels()
      let selected = thread.model.flatMap { model in
        models.first(where: { $0.id == model })
      } ?? models.first(where: \.isDefault)
      return AIChatRemoteConfiguration(
        models: models,
        effectiveModel: selected?.id,
        reasoningEffort: thread.reasoningEffort,
        reasoningOptions: selected?.reasoningOptions ?? [],
        defaultReasoningEffort: selected?.defaultReasoningEffort
      )
    case .claudeLocal:
      let models = try await modelsForAIChatDestination(thread.destinationID)
      return AIChatRemoteConfiguration(
        models: models,
        effectiveModel: thread.model,
        reasoningEffort: nil,
        reasoningOptions: [],
        defaultReasoningEffort: nil
      )
    case .openClaw:
      let settings = openClawSettings(
        forDestinationID: thread.destinationID,
        allowKeychainRead: true
      )
      let client = OpenClawGatewayClient(settings: settings)
      let models = try await client.listModels()
      let configuration = try await client.sessionConfiguration(sessionKey: thread.sessionKey)
      return AIChatRemoteConfiguration(
        models: models,
        effectiveModel: configuration?.model ?? thread.model,
        reasoningEffort: thread.reasoningEffort,
        reasoningOptions: configuration?.reasoningOptions ?? [],
        defaultReasoningEffort: configuration?.defaultReasoningEffort
      )
    case .openAI, .anthropic, .openRouter, .ollama:
      let models = try await modelsForAIChatDestination(thread.destinationID)
      return AIChatRemoteConfiguration(
        models: models,
        effectiveModel: thread.model ?? aiChatDestination(id: thread.destinationID)?.model,
        reasoningEffort: nil,
        reasoningOptions: [],
        defaultReasoningEffort: nil
      )
    }
  }

  public func setAIChatRemoteModel(
    _ model: String?,
    threadID: UUID
  ) async throws -> [AIChatModelOption] {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      throw AIChatRemoteConfigurationError.threadNotFound
    }
    guard !isAIChatThreadRunning(threadID) else {
      throw AIChatRemoteConfigurationError.turnInProgress
    }

    let options = try await aiChatRemoteModelOptions(for: threadID)
    if let model, !options.contains(where: { $0.id == model }) {
      throw AIChatRemoteConfigurationError.unknownModel(model)
    }

    if aiChatDestination(id: thread.destinationID)?.adapter == .openClaw {
      let settings = openClawSettings(
        forDestinationID: thread.destinationID,
        allowKeychainRead: true
      )
      let configuredAgentID = aiChatDestination(id: thread.destinationID)?.agentID ?? ""
      _ = try await OpenClawGatewayClient(settings: settings).patchSessionConfiguration(
        sessionKey: thread.sessionKey,
        agentID: OpenClawChatClient.openClawAgentHeaderValue(
          for: configuredAgentID.isEmpty ? openClawAgentID : configuredAgentID
        ),
        model: model,
        reasoningEffort: nil
      )
    }

    guard let index = openClawChatThreads.firstIndex(where: { $0.id == threadID }) else {
      throw AIChatRemoteConfigurationError.threadNotFound
    }
    openClawChatThreads[index] = openClawChatThreads[index].replacingOpenClawChatMetadata(
      model: .some(model),
      reasoningEffort: .some(nil)
    )
    persistLastAIChatConfiguration(
      destinationID: openClawChatThreads[index].destinationID,
      model: model,
      reasoningEffort: nil
    )
    if selectedOpenClawChatThreadID == threadID {
      aiChatModelOptions = options
      aiChatReasoningOptions = []
      aiChatEffectiveModel = model ?? options.first(where: \.isDefault)?.id
      aiChatDefaultReasoningEffort = nil
    }
    persistOpenClawTranscript()
    return options
  }

  public func setAIChatRemoteReasoningEffort(
    _ reasoningEffort: String?,
    threadID: UUID
  ) async throws {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      throw AIChatRemoteConfigurationError.threadNotFound
    }
    guard !isAIChatThreadRunning(threadID) else {
      throw AIChatRemoteConfigurationError.turnInProgress
    }

    let configuration = try await aiChatRemoteConfiguration(for: threadID)
    if let reasoningEffort,
       !configuration.reasoningOptions.contains(where: { $0.id == reasoningEffort }) {
      throw AIChatRemoteConfigurationError.unknownReasoningEffort(reasoningEffort)
    }
    if aiChatDestination(id: thread.destinationID)?.adapter == .openClaw {
      let settings = openClawSettings(
        forDestinationID: thread.destinationID,
        allowKeychainRead: true
      )
      let configuredAgentID = aiChatDestination(id: thread.destinationID)?.agentID ?? ""
      _ = try await OpenClawGatewayClient(settings: settings).patchSessionConfiguration(
        sessionKey: thread.sessionKey,
        agentID: OpenClawChatClient.openClawAgentHeaderValue(
          for: configuredAgentID.isEmpty ? openClawAgentID : configuredAgentID
        ),
        model: thread.model,
        reasoningEffort: reasoningEffort
      )
    }

    guard let index = openClawChatThreads.firstIndex(where: { $0.id == threadID }) else {
      throw AIChatRemoteConfigurationError.threadNotFound
    }
    openClawChatThreads[index] = openClawChatThreads[index].replacingOpenClawChatMetadata(
      reasoningEffort: .some(reasoningEffort)
    )
    persistLastAIChatConfiguration(
      destinationID: openClawChatThreads[index].destinationID,
      model: openClawChatThreads[index].model,
      reasoningEffort: reasoningEffort
    )
    if selectedOpenClawChatThreadID == threadID {
      aiChatModelOptions = configuration.models
      aiChatReasoningOptions = configuration.reasoningOptions
      aiChatEffectiveModel = configuration.effectiveModel
      aiChatDefaultReasoningEffort = configuration.defaultReasoningEffort
    }
    persistOpenClawTranscript()
  }

  public func sendComposedOpenClawMessage(
    text rawText: String,
    delivery: AIChatMessageDeliveryPreference = .automatic
  ) {
    let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
    let attachments = openClawPendingAttachments
    guard !text.isEmpty || !attachments.isEmpty else { return }
    ensureOpenClawChatThread()
    guard let threadID = selectedOpenClawChatThreadID else { return }
    clearOpenClawDraftForSelectedThread()
    openClawPendingAttachments = []
    submitAIChatMessage(
      text,
      attachments: attachments,
      in: threadID,
      delivery: delivery
    )
  }

  public func submitOpenClawComposerInput(text rawText: String) {
    let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !text.isEmpty || !openClawPendingAttachments.isEmpty else { return }

    switch OpenClawSlashCommands.parse(
      text,
      gatewayCommands: activeAIChatGatewayCommands,
      corpusSkills: corpusAgentSkillCommands
    ) {
    case .message(let message):
      sendComposedOpenClawMessage(text: message)
    case .unknown(let name):
      guard !name.isEmpty else {
        clearOpenClawDraftForSelectedThread()
        appendLocalOpenClawCommand(
          text,
          result: "Type / followed by a command, or use /help to see all commands."
        )
        return
      }
      guard openClawPendingAttachments.isEmpty else {
        appendLocalOpenClawCommand(
          text,
          result: "Slash commands must be sent without attachments. Remove the attachment and try again."
        )
        return
      }
      ensureOpenClawChatThread()
      guard let threadID = selectedOpenClawChatThreadID else { return }
      clearOpenClawDraftForSelectedThread()
      openClawStatusText = "Sending /\(name) to \(selectedAIChatRuntime.title)…"
      Task { @MainActor [weak self] in
        guard let self,
              self.enqueueOpenClawMessage(
                text,
                attachments: [],
                in: threadID,
                audience: self.selectedAIChatIsSharedRoom ? .openClaw : nil
              )
        else { return }
        await self.drainOpenClawSendQueue(for: threadID)
      }
    case .command(let command, let arguments):
      guard openClawPendingAttachments.isEmpty else {
        appendLocalOpenClawCommand(
          text,
          result: "Slash commands cannot include attachments yet. Remove the attachment and try again."
        )
        return
      }
      ensureOpenClawChatThread()
      guard let threadID = selectedOpenClawChatThreadID else { return }
      clearOpenClawDraftForSelectedThread()
      openClawStatusText = "Running /\(command.name)…"
      Task { @MainActor [weak self] in
        await self?.executeOpenClawSlashCommand(command, arguments: arguments, rawText: text, threadID: threadID)
      }
    }
  }

  private func executeOpenClawSlashCommand(
    _ command: OpenClawSlashCommand,
    arguments: String,
    rawText: String,
    threadID: UUID
  ) async {
    if command.origin == .openClaw || command.isAgentAssisted {
      let isSharedRoom = openClawChatThreads.first(where: { $0.id == threadID })?.isSharedRoom == true
      guard enqueueOpenClawMessage(
        rawText,
        attachments: [],
        in: threadID,
        audience: isSharedRoom ? .openClaw : nil
      ) else { return }
      await drainOpenClawSendQueue(for: threadID)
      return
    }

    do {
      let result: String
      switch command.name {
      case "help":
        result = OpenClawSlashCommands.helpText(
          gatewayCommands: activeAIChatGatewayCommands,
          corpusSkills: corpusAgentSkillCommands
        )
      case "search":
        result = await executeOpenClawSearch(arguments)
      case "open":
        result = executeOpenClawOpen(arguments)
      case "today":
        openDailyNote(.today)
        result = statusText
      case "agenda":
        makeSurfacePrimary(.agenda)
        await refreshAgenda(preserveSelection: true, updatesStatus: false)
        if let agenda {
          result = "Opened Agenda — \(agenda.totalItemCount) item\(agenda.totalItemCount == 1 ? "" : "s"), \(agenda.todayItemCount) today."
        } else {
          result = "Opened Agenda."
        }
      case "related":
        result = await executeOpenClawRelated()
      case "spellcheck":
        result = await executeOpenClawSpellcheck()
      case "lint":
        result = try await executeOpenClawLint()
      case "export":
        result = try await executeOpenClawExport(arguments)
      case "publish":
        result = try await executeOpenClawPublish(arguments)
      default:
        result = "Command /\(command.name) is not implemented yet."
      }
      appendLocalOpenClawCommand(rawText, result: result, in: threadID)
    } catch {
      appendLocalOpenClawCommand(
        rawText,
        result: "Could not run /\(command.name): \(error.localizedDescription)",
        in: threadID
      )
    }
  }

  private func appendLocalOpenClawCommand(_ command: String, result: String, in threadID: UUID? = nil) {
    ensureOpenClawChatThread()
    guard let threadID = threadID ?? selectedOpenClawChatThreadID else { return }
    var messages = openClawMessages(for: threadID)
    messages.append(OpenClawChatMessage(role: .user, content: command))
    messages.append(OpenClawChatMessage(role: .system, content: result))
    replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
    openClawStatusText = "Ran \(command.split(whereSeparator: { $0.isWhitespace }).first ?? "command")"
  }

  private func executeOpenClawSearch(_ query: String) async -> String {
    guard !query.isEmpty else { return "Usage: /search QUERY" }
    searchQuery = query
    await runSearch()
    makeSurfacePrimary(.search)
    guard !searchResults.isEmpty else { return "No corpus results for “\(query)”." }
    let rows = searchResults.prefix(8).map { result in
      "• \(relativePath(result.file)):\(result.lineForEditor) — \(result.snippet.replacingOccurrences(of: "\n", with: " "))"
    }
    let suffix = searchResults.count > rows.count ? "\n\n\(searchResults.count - rows.count) more results are open in Search." : ""
    return "Found \(searchResults.count) corpus result\(searchResults.count == 1 ? "" : "s"):\n\n\(rows.joined(separator: "\n"))\(suffix)"
  }

  private func executeOpenClawOpen(_ query: String) -> String {
    guard !query.isEmpty else { return "Usage: /open PATH" }
    let normalized = query.lowercased()
    let exact = corpusFiles.filter {
      $0.relativePath.lowercased() == normalized || $0.name.lowercased() == normalized
    }
    let matches = exact.isEmpty
      ? corpusFiles.filter { $0.relativePath.lowercased().contains(normalized) }
      : exact
    guard let match = matches.first else { return "No corpus file matches “\(query)”." }
    guard matches.count == 1 else {
      return "More than one file matches “\(query)”: \(matches.prefix(8).map(\.relativePath).joined(separator: ", "))"
    }
    selectCorpusFile(match)
    return "Opened \(match.relativePath)."
  }

  private func executeOpenClawRelated() async -> String {
    guard let location = selectedLocation else { return "Open a document first, then run /related." }
    await loadBacklinks(for: location)
    guard let backlinks, !backlinks.backlinks.isEmpty else { return "No backlinks found for the current document." }
    let rows = backlinks.backlinks.prefix(12).map {
      "• \(relativePath($0.file)):\($0.lineForEditor) — \($0.srcTitle)"
    }
    return "\(backlinks.backlinks.count) backlink\(backlinks.backlinks.count == 1 ? "" : "s"):\n\n\(rows.joined(separator: "\n"))"
  }

  private func executeOpenClawSpellcheck() async -> String {
    guard let source = selectedEntrySource else { return "Open a document first, then run /spellcheck." }
    guard let snapshot = await analyzeSourceEditorText(source.text) else { return "The document could not be analyzed for spell checking." }
    let issues = OpenClawSpellchecker.issues(
      in: source.text,
      snapshot: snapshot,
      lineOffset: max(0, source.startLine - 1)
    )
    guard !issues.isEmpty else { return "No spelling issues found in prose regions." }
    let rows = issues.map { issue -> String in
      let suggestions = issue.suggestions.isEmpty ? "" : " → \(issue.suggestions.joined(separator: ", "))"
      return "• line \(issue.line): \(issue.word)\(suggestions)"
    }
    let suffix = issues.count == 50 ? "\n\nStopped after 50 issues." : ""
    return "Found \(issues.count) possible spelling issue\(issues.count == 1 ? "" : "s"):\n\n\(rows.joined(separator: "\n"))\(suffix)"
  }

  private func executeOpenClawLint() async throws -> String {
    guard let corpusRoot else { return "Open a corpus first, then run /lint." }
    let data = try await cli.run(["lint", "--dir", corpusRoot.path, "--recursive", "--format", "text"])
    let output = String(decoding: data, as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)
    return output.isEmpty ? "Lint passed with no findings." : String(output.prefix(12_000))
  }

  private func executeOpenClawExport(_ arguments: String) async throws -> String {
    guard let sourceFile = currentOrgSourceFile else { return "Open a document first. Usage: /export pdf|html" }
    let format = arguments.lowercased()
    guard format == "pdf" || format == "html" else { return "Usage: /export pdf|html" }
    guard await savePendingEditsBeforeExport(blockedStatus: "Save the current edit before exporting the document") else {
      return "Save the current edit before exporting the document."
    }
    let panel = NSSavePanel()
    panel.allowedContentTypes = format == "pdf" ? [.pdf] : [.html]
    panel.nameFieldStringValue = sourceFile.deletingPathExtension().lastPathComponent + ".\(format)"
    guard panel.runModal() == .OK, let destination = panel.url else { return "Export cancelled." }
    if format == "html" {
      let html = try await renderedCurrentDocumentHTML(sourceFile: sourceFile)
      try Data(html.utf8).write(to: destination, options: .atomic)
    } else {
      try await exportCurrentDocumentPDF(sourceFile: sourceFile, destination: destination)
    }
    return "Exported \(destination.lastPathComponent)."
  }

  private func executeOpenClawPublish(_ arguments: String) async throws -> String {
    guard let corpusRoot else { return "Open a corpus first, then run /publish." }
    let config = corpusRoot.appendingPathComponent("org2.json")
    guard FileManager.default.fileExists(atPath: config.path) else {
      return "Publishing requires org2.json in the corpus root."
    }
    var parts = arguments.split(whereSeparator: { $0.isWhitespace }).map(String.init)
    let preview = parts.first?.lowercased() == "preview"
    if preview { parts.removeFirst() }
    var cliArguments = ["publish"]
    if let project = parts.first { cliArguments.append(project) }
    cliArguments.append(contentsOf: ["--config", config.path])
    if preview { cliArguments.append("--preview") }
    let data = try await cli.run(cliArguments)
    let output = String(decoding: data, as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)
    return output.isEmpty ? (preview ? "Publish preview passed." : "Publish completed.") : String(output.prefix(12_000))
  }

  private func sendOpenClawMessage(
    _ text: String,
    attachments: [OpenClawChatAttachment],
    workspaceContext: OpenClawWorkspaceContext? = nil
  ) async {
    ensureOpenClawChatThread()
    guard let sourceThreadID = selectedOpenClawChatThreadID else { return }
    let threadID = aiChatDestinationThreadID(
      for: text,
      sourceThreadID: sourceThreadID,
      selectsFork: true
    )
    let deliveryKind: OpenClawChatMessage.DeliveryKind = isAIChatThreadRunning(threadID)
      ? .followUp
      : .turn
    guard enqueueOpenClawMessage(
      text,
      attachments: attachments,
      in: threadID,
      workspaceContext: workspaceContext,
      deliveryKind: deliveryKind
    ) else { return }
    await drainOpenClawSendQueue(for: threadID)
  }

  @discardableResult
  private func submitAIChatMessage(
    _ text: String,
    attachments: [OpenClawChatAttachment],
    in threadID: UUID,
    workspaceContext: OpenClawWorkspaceContext? = nil,
    audience: AIChatAudience? = nil,
    delivery: AIChatMessageDeliveryPreference = .automatic
  ) -> Bool {
    let destinationThreadID = aiChatDestinationThreadID(
      for: text,
      sourceThreadID: threadID,
      selectsFork: selectedOpenClawChatThreadID == threadID
    )
    if destinationThreadID != threadID {
      return submitAIChatMessage(
        text,
        attachments: attachments,
        in: destinationThreadID,
        workspaceContext: workspaceContext,
        audience: audience,
        delivery: delivery
      )
    }
    let shouldTrySteering = delivery == .steer
      && isAIChatThreadRunning(threadID)
      && canSteerAIChatThread(threadID)
    if shouldTrySteering {
      let userMessage = OpenClawChatMessage(
        role: .user,
        content: text,
        attachments: attachments,
        deliveryStatus: .sending,
        deliveryKind: .steer,
        audience: audience
      )
      var messages = openClawMessages(for: threadID)
      messages.append(userMessage)
      replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
      if selectedOpenClawChatThreadID == threadID {
        let destinationTitle = openClawChatThreads.first(where: { $0.id == threadID })
          .map { aiChatDestinationTitle($0.destinationID) }
          ?? "agent"
        openClawStatusText = "Steering \(destinationTitle)…"
      }
      Task { @MainActor [weak self] in
        await self?.deliverAIChatSteer(
          userMessage,
          in: threadID
        )
      }
      return true
    }

    let kind: OpenClawChatMessage.DeliveryKind = isAIChatThreadRunning(threadID)
      ? .followUp
      : .turn
    let shouldDrain = enqueueOpenClawMessage(
      text,
      attachments: attachments,
      in: threadID,
      workspaceContext: workspaceContext,
      deliveryKind: kind,
      audience: audience
    )
    if shouldDrain {
      Task { @MainActor [weak self] in
        await self?.drainOpenClawSendQueue(for: threadID)
      }
    }
    return true
  }

  private func canSteerAIChatThread(_ threadID: UUID) -> Bool {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      return false
    }
    guard !thread.isSharedRoom else { return false }
    guard aiChatDestination(id: thread.destinationID)?.adapter.isDirectProvider != true else {
      return false
    }
    if aiChatSteerHandlerForTesting != nil { return true }
    switch thread.runtime {
    case .codex:
      let hasClient = thread.destinationID == AIChatDestinationConfiguration.localCodexID
        ? codexAppServerClient != nil
        : codexAppServerClientsByDestinationID[thread.destinationID] != nil
      return codexActiveTurnsByThreadID[threadID] != nil && hasClient
    case .openClaw:
      return openClawGatewayClientsByThreadID[threadID] != nil
        && openClawActiveRunIDByThreadID[threadID] != nil
    case .claude:
      return false
    }
  }

  private func deliverAIChatSteer(
    _ message: OpenClawChatMessage,
    in threadID: UUID
  ) async {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else { return }
    do {
      if let aiChatSteerHandlerForTesting {
        try await aiChatSteerHandlerForTesting(
          thread.runtime,
          threadID,
          message.content,
          message.attachments
        )
      } else {
        switch thread.runtime {
        case .codex:
          guard let active = codexActiveTurnsByThreadID[threadID] else {
            throw CodexAppServerError.server(
              code: nil,
              message: "There is no active turn to steer."
            )
          }
          let codexClient = try codexClient(forDestinationID: thread.destinationID)
          try await codexClient.steer(
            threadID: active.runtimeThreadID,
            expectedTurnID: active.turnID,
            message: message.content,
            attachments: message.attachments
          )
        case .openClaw:
          guard let gateway = openClawGatewayClientsByThreadID[threadID] else {
            throw OpenClawGatewayError.protocolFailure("there is no live OpenClaw run to steer")
          }
          try await gateway.steer(
            message: Self.expandingOpenClawAgentCommand(message).content,
            attachments: message.attachments,
            idempotencyKey: message.id.uuidString.lowercased()
          )
        case .claude:
          throw ClaudeCodeError.invalidResponse(
            "steering is not available for Claude Code; queue a follow-up instead"
          )
        }
      }
      replaceOpenClawDeliveryStatus(for: message.id, in: threadID, with: .sent)
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "Guidance sent to \(aiChatDestinationTitle(thread.destinationID))"
      }
    } catch {
      if shouldQueueAIChatSteerAsFollowUp(after: error, runtime: thread.runtime) {
        enqueueExistingAIChatMessageAsFollowUp(message.id, in: threadID)
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = "The run finished; queued as a follow-up"
        }
        if !drainingOpenClawThreadIDs.contains(threadID) {
          await drainOpenClawSendQueue(for: threadID)
        }
        return
      }
      replaceOpenClawSendFailure(
        for: message.id,
        in: threadID,
        with: "Could not steer \(aiChatDestinationTitle(thread.destinationID)): \(error.localizedDescription)"
      )
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "Could not steer \(aiChatDestinationTitle(thread.destinationID))"
      }
    }
  }

  private func shouldQueueAIChatSteerAsFollowUp(
    after error: Error,
    runtime: AIChatRuntime
  ) -> Bool {
    switch runtime {
    case .codex:
      guard let error = error as? CodexAppServerError else { return false }
      switch error {
      case .server(_, let message):
        return message.localizedCaseInsensitiveContains("active turn")
          || message.localizedCaseInsensitiveContains("in progress")
      case .invalidResponse(let message):
        return message.localizedCaseInsensitiveContains("turn/steer")
      case .executableNotFound, .launchFailed, .disconnected, .notAuthenticated,
           .requestTimedOut, .turnFailed, .turnInterrupted:
        return false
      }
    case .openClaw:
      guard let error = error as? OpenClawGatewayError else { return false }
      let message: String
      switch error {
      case .protocolFailure(let detail), .gateway(_, let detail):
        message = detail
      case .invalidEndpoint, .connection, .sessionConfigurationRejected,
           .emptyResponse, .aborted, .acceptedRunRecovery:
        return false
      }
      return message.localizedCaseInsensitiveContains("active run")
        || message.localizedCaseInsensitiveContains("live run")
        || message.localizedCaseInsensitiveContains("in progress")
    case .claude:
      return false
    }
  }

  private func enqueueExistingAIChatMessageAsFollowUp(_ messageID: UUID, in threadID: UUID) {
    var messages = openClawMessages(for: threadID)
    guard let index = messages.firstIndex(where: { $0.id == messageID }) else { return }
    let message = messages[index]
    messages[index] = OpenClawChatMessage(
      id: message.id,
      role: message.role,
      content: message.content,
      attachments: message.attachments,
      createdAt: message.createdAt,
      changeSummary: message.changeSummary,
      responseTrace: message.responseTrace,
      deliveryStatus: .sending,
      deliveryKind: .followUp,
      audience: message.audience,
      targetRuntime: message.targetRuntime,
      audienceDestinationIDs: message.audienceDestinationIDs,
      targetDestinationID: message.targetDestinationID,
      isRoomDispatchCopy: message.isRoomDispatchCopy,
      roomRoundID: message.roomRoundID
    )
    replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
    enqueueOpenClawUserMessage(messageID, in: threadID)
  }

  private func enqueueOpenClawMessage(
    _ text: String,
    attachments: [OpenClawChatAttachment],
    in threadID: UUID,
    workspaceContext: OpenClawWorkspaceContext? = nil,
    deliveryKind: OpenClawChatMessage.DeliveryKind = .turn,
    audience: AIChatAudience? = nil
  ) -> Bool {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else { return false }
    stoppedOpenClawThreadIDs.remove(threadID)
    let destinationRouting = thread.isSharedRoom
      ? AIChatDestinationRouting(
          text,
          destinations: enabledAIChatDestinations,
          allDestinationIDs: thread.roomDestinationIDs
        )
      : nil
    let effectiveText = destinationRouting?.normalizedText ?? text
    var targetDestinationIDs = thread.isSharedRoom
      ? (destinationRouting?.destinationIDs ?? [])
      : [thread.destinationID]
    if targetDestinationIDs.isEmpty, let audience {
      targetDestinationIDs = audience.runtimes.map(AIChatDestinationConfiguration.defaultID(for:))
    }
    let targetRuntimes = targetDestinationIDs.map(aiChatDestinationRuntime)
    let effectiveAudience: AIChatAudience = {
      if targetRuntimes.isEmpty { return .thread }
      if targetDestinationIDs.count > 1 { return .everyone }
      return AIChatAudience(runtime: targetRuntimes[0])
    }()
    if thread.isSharedRoom,
       let index = openClawChatThreads.firstIndex(where: { $0.id == threadID }) {
      let participants = (thread.roomDestinationIDs + targetDestinationIDs).reduce(into: [String]()) {
        if !$0.contains($1) { $0.append($1) }
      }
      if participants != thread.roomDestinationIDs {
        openClawChatThreads[index] = thread.replacingOpenClawChatMetadata(
          roomDestinationIDs: participants
        )
      }
    }
    let createdAt = Date()
    var messages = openClawMessages(for: threadID)

    if targetRuntimes.isEmpty {
      messages.append(OpenClawChatMessage(
        role: .user,
        content: effectiveText,
        attachments: attachments,
        createdAt: createdAt,
        audience: .thread
      ))
      replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
      if selectedOpenClawChatThreadID == threadID,
         !drainingOpenClawThreadIDs.contains(threadID) {
        openClawStatusText = "Posted to shared context"
      }
      return false
    }

    if aiChatSendOriginsByThreadID[threadID] == nil {
      aiChatSendOriginsByThreadID[threadID] = AIChatSendOrigin(
        corpusRoot: corpusRoot?.standardizedFileURL,
        transcriptURL: openClawTranscriptURL.standardizedFileURL,
        workspaceContext: workspaceContext ?? threadScopedOpenClawWorkspaceContext(for: thread)
      )
    }
    let roomRoundID = thread.isSharedRoom ? UUID() : nil
    let userMessages = targetDestinationIDs.enumerated().map { index, destinationID in
      let runtime = aiChatDestinationRuntime(destinationID)
      return OpenClawChatMessage(
        id: index == 0 ? (roomRoundID ?? UUID()) : UUID(),
        role: .user,
        content: effectiveText,
        attachments: attachments,
        createdAt: createdAt,
        deliveryStatus: .sending,
        deliveryKind: deliveryKind,
        audience: thread.isSharedRoom ? effectiveAudience : nil,
        targetRuntime: runtime,
        audienceDestinationIDs: thread.isSharedRoom ? targetDestinationIDs : [],
        targetDestinationID: destinationID,
        isRoomDispatchCopy: index > 0,
        roomRoundID: roomRoundID
      )
    }
    messages.append(contentsOf: userMessages)
    replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
    for userMessage in userMessages {
      enqueueOpenClawUserMessage(userMessage.id, in: threadID)
    }
    if drainingOpenClawThreadIDs.contains(threadID) {
      openClawStatusText = openClawQueuedStatusText()
      return false
    }
    if thread.isSharedRoom {
      let names = targetDestinationIDs.map(aiChatDestinationTitle).joined(separator: " + ")
      openClawStatusText = "Sending to \(names)…"
    }
    return true
  }

  private func drainOpenClawSendQueue(for threadID: UUID) async {
    if let activeTask = aiChatDrainTasksByThreadID[threadID] {
      await activeTask.task.value
      return
    }
    let token = UUID()
    let task = Task { @MainActor [weak self] in
      guard let self else { return }
      await self.performOpenClawSendQueueDrain(for: threadID)
    }
    aiChatDrainTasksByThreadID[threadID] = (token, task)
    await task.value
    if aiChatDrainTasksByThreadID[threadID]?.token == token {
      aiChatDrainTasksByThreadID.removeValue(forKey: threadID)
    }
  }

  private func performOpenClawSendQueueDrain(for threadID: UUID) async {
    guard !drainingOpenClawThreadIDs.contains(threadID) else { return }
    let sendOrigin: AIChatSendOrigin
    if let existingOrigin = aiChatSendOriginsByThreadID[threadID] {
      sendOrigin = existingOrigin
    } else {
      guard let thread = openClawChatThread(
        threadID,
        transcriptURL: openClawTranscriptURL.standardizedFileURL
      ) else { return }
      let currentOrigin = AIChatSendOrigin(
        corpusRoot: corpusRoot?.standardizedFileURL,
        transcriptURL: openClawTranscriptURL.standardizedFileURL,
        workspaceContext: threadScopedOpenClawWorkspaceContext(for: thread)
      )
      aiChatSendOriginsByThreadID[threadID] = currentOrigin
      sendOrigin = currentOrigin
    }
    prepareOpenClawRunPresentation(for: threadID)
    drainingOpenClawThreadIDs.insert(threadID)
    openClawRequestStartedAtByThreadID[threadID] = Date()
    syncSelectedOpenClawSendState()
    defer {
      drainingOpenClawThreadIDs.remove(threadID)
      activeSharedRoomRuntimeByThreadID.removeValue(forKey: threadID)
      activeSharedRoomDestinationByThreadID.removeValue(forKey: threadID)
      activeOpenClawUserMessageIDByThreadID.removeValue(forKey: threadID)
      openClawRequestStartedAtByThreadID.removeValue(forKey: threadID)
      if openClawPendingUserMessageIDs(for: threadID).isEmpty {
        aiChatSendOriginsByThreadID.removeValue(forKey: threadID)
      }
      syncSelectedOpenClawSendState()
    }

    while let userMessageID = openClawPendingUserMessageIDs(for: threadID).first {
      guard let requestMessages = openClawMessagesThrough(
        userMessageID,
        in: threadID,
        transcriptURL: sendOrigin.transcriptURL
      ) else {
        removeFirstPendingOpenClawUserMessage(in: threadID)
        continue
      }
      guard let chatThread = openClawChatThread(
        threadID,
        transcriptURL: sendOrigin.transcriptURL
      ) else {
        removeAllPendingOpenClawUserMessages(in: threadID)
        return
      }
      guard let userMessage = requestMessages.last(where: { $0.id == userMessageID }) else {
        removeFirstPendingOpenClawUserMessage(in: threadID)
        continue
      }
      let dispatchDestinationID = chatThread.isSharedRoom
        ? (userMessage.targetDestinationID
            ?? userMessage.targetRuntime.map(AIChatDestinationConfiguration.defaultID(for:))
            ?? chatThread.destinationID)
        : chatThread.destinationID
      guard let dispatchDestination = aiChatDestination(id: dispatchDestinationID) else {
        replaceOpenClawDeliveryStatus(for: userMessageID, in: threadID, with: .failed)
        insertSharedRoomFailure(
          "Destination is no longer configured.",
          destinationID: dispatchDestinationID,
          runtime: userMessage.targetRuntime ?? chatThread.runtime,
          after: userMessageID,
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL
        )
        removeFirstPendingOpenClawUserMessage(in: threadID)
        continue
      }
      let dispatchRuntime = dispatchDestination.runtime
      if chatThread.isSharedRoom {
        activeSharedRoomRuntimeByThreadID[threadID] = dispatchRuntime
        activeSharedRoomDestinationByThreadID[threadID] = dispatchDestinationID
      }
      if isActiveAIChatSendOrigin(sendOrigin) {
        openClawStatusText = "\(dispatchDestination.name) is working…"
      }

      var localEditTurnID: String?
      let usesLocalEditBroker = dispatchDestination.adapter == .codexLocal
        || dispatchDestination.adapter == .codexRemote
        || dispatchDestination.adapter == .codexManagedRemote
        || (
          dispatchDestination.adapter == .openClaw
            &&
          openClawLocalEditsEnabled
            && openClawLocalEditNodeState == .connected
        )
      if usesLocalEditBroker, let corpusRoot = sendOrigin.corpusRoot {
        let turnID = UUID().uuidString.lowercased()
        localEditTurnID = turnID
        openClawLocalEditCorpusRootsByTurnID[turnID] = corpusRoot.standardizedFileURL
        aiChatReadCorpusRootsByTurnID[turnID] = Set(
          sendOrigin.workspaceContext.authorizedCorpora.map {
            URL(fileURLWithPath: $0.localRoot).standardizedFileURL.path
          }
        ).union([corpusRoot.standardizedFileURL.path])
        await localEditBroker().beginTurn(turnID)
      }
      activeOpenClawUserMessageIDByThreadID[threadID] = userMessageID
      do {
        clearOpenClawSendFailure(
          for: userMessageID,
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL
        )
        let changeObservation: CorpusChangeObservation?
        if localEditTurnID == nil {
          changeObservation = await beginCorpusChangeObservation(
            corpusRoot: sendOrigin.corpusRoot
          )
        } else {
          changeObservation = nil
        }
        let reply: String
        switch dispatchDestination.adapter {
        case .openClaw:
          let sessionKey = Self.agentScopedOpenClawSessionKey(
            chatThread.sessionKey,
            agentID: dispatchDestination.agentID.isEmpty
              ? openClawAgentID
              : dispatchDestination.agentID
          )
          reply = try await sendOpenClawRequest(
            messages: requestMessages,
            sessionKey: sessionKey,
            threadID: threadID,
            destinationID: dispatchDestinationID,
            localEditTurnID: localEditTurnID,
            sendOrigin: sendOrigin
          )
        case .codexLocal, .codexRemote, .codexManagedRemote:
          guard let localEditTurnID else {
            throw CodexAppServerError.invalidResponse(
              "choose an Org2 corpus before sending a Codex message"
            )
          }
          reply = try await sendCodexRequest(
            messages: requestMessages,
            threadID: threadID,
            destinationID: dispatchDestinationID,
            localEditTurnID: localEditTurnID,
            sendOrigin: sendOrigin
          )
        case .claudeLocal:
          reply = try await sendClaudeCodeRequest(
            messages: requestMessages,
            threadID: threadID,
            destinationID: dispatchDestinationID,
            sendOrigin: sendOrigin
          )
        case .openAI, .anthropic, .openRouter, .ollama:
          reply = try await sendDirectProviderRequest(
            messages: requestMessages,
            threadID: threadID,
            destination: dispatchDestination,
            sendOrigin: sendOrigin
          )
        }
        guard openClawPendingUserMessageIDs(for: threadID).contains(userMessageID) else {
          // Stop/dequeue may race the final frame. Once the local request was
          // canceled, a late reply must not put the thread back into a live
          // presentation or append an answer to the stopped turn.
          clearOpenClawCompletedRunPresentation(for: threadID)
          return
        }
        codexActiveTurnsByThreadID.removeValue(forKey: threadID)
        let assistantMessageID = insertOpenClawReply(
          reply,
          after: userMessageID,
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL,
          changeSummary: nil,
          authorRuntime: chatThread.isSharedRoom ? dispatchRuntime : nil,
          authorDestinationID: chatThread.isSharedRoom ? dispatchDestinationID : nil
        )
        activeOpenClawUserMessageIDByThreadID.removeValue(forKey: threadID)
        clearOpenClawCompletedRunPresentation(for: threadID)
        removeFirstPendingOpenClawUserMessage(in: threadID)
        if isActiveAIChatSendOrigin(sendOrigin) {
          openClawStatusText = openClawPendingUserMessageIDs(for: threadID).isEmpty
            ? "\(dispatchDestination.name) replied"
            : openClawQueuedStatusText()
        }

        let exactLocalChangeSummary: OpenClawCorpusChangeSummary?
        if let localEditTurnID {
          exactLocalChangeSummary = await localEditBroker().consumeChangeSummary(for: localEditTurnID)
          await localEditBroker().endTurn(localEditTurnID)
          openClawLocalEditCorpusRootsByTurnID.removeValue(forKey: localEditTurnID)
          aiChatReadCorpusRootsByTurnID.removeValue(forKey: localEditTurnID)
        } else {
          exactLocalChangeSummary = nil
        }
        let changeSummary: OpenClawCorpusChangeSummary?
        if localEditTurnID != nil {
          changeSummary = exactLocalChangeSummary
        } else if let changeObservation {
          changeSummary = await openClawChangeSummary(
            since: changeObservation,
            referencedIn: reply,
            corpusRoot: sendOrigin.corpusRoot
          )
        } else {
          changeSummary = nil
        }
        if let changeSummary {
          replaceOpenClawChangeSummary(
            changeSummary,
            for: assistantMessageID,
            in: threadID,
            transcriptURL: sendOrigin.transcriptURL
          )
          if isActiveAIChatSendOrigin(sendOrigin) {
            await refreshAfterOpenClawChanges(changeSummary)
          } else if let corpusRoot = sendOrigin.corpusRoot {
            invalidateCachedCorpusWorkspace(
              at: corpusRoot.path,
              surfaces: Set(WorkspaceSurface.allCases.filter { $0 != .home })
            )
          }
        } else if isActiveAIChatSendOrigin(sendOrigin) {
          await refreshSelectedDetailFromDisk()
        }
        let hasFinishedQueue = openClawPendingUserMessageIDs(for: threadID).isEmpty
        let configurationFallbackNotice = hasFinishedQueue
          ? aiChatConfigurationFallbackNoticesByThreadID.removeValue(forKey: threadID)
          : nil
        if isActiveAIChatSendOrigin(sendOrigin), hasFinishedQueue {
          if let configurationFallbackNotice {
            openClawStatusText = configurationFallbackNotice
          } else if dispatchRuntime == .openClaw,
             openClawGatewayStateByThreadID[threadID] == .fallbackHTTP {
            openClawStatusText = "OpenClaw replied via HTTP compatibility"
          } else {
            openClawStatusText = changeSummary.map {
              ($0.totalInsertions == 0 && $0.totalDeletions == 0)
                ? $0.title
                : "\($0.title): +\($0.totalInsertions) -\($0.totalDeletions)"
            } ?? "\(dispatchDestination.name) replied"
          }
        } else if isActiveAIChatSendOrigin(sendOrigin) {
          openClawStatusText = openClawQueuedStatusText()
        }
      } catch {
        activeOpenClawUserMessageIDByThreadID.removeValue(forKey: threadID)
        codexActiveTurnsByThreadID.removeValue(forKey: threadID)
        if let localEditTurnID {
          await localEditBroker().endTurn(localEditTurnID)
          openClawLocalEditCorpusRootsByTurnID.removeValue(forKey: localEditTurnID)
          aiChatReadCorpusRootsByTurnID.removeValue(forKey: localEditTurnID)
        }
        if stoppedOpenClawThreadIDs.contains(threadID)
          || error is CancellationError
          || Self.openClawRunWasStopped(after: error) {
          markOpenClawRunStopped(
            in: threadID,
            transcriptURL: sendOrigin.transcriptURL,
            statusText: "\(dispatchDestination.name) stopped"
          )
          return
        }
        let failureText = Self.openClawSendFailureText(from: error)
        if isActiveAIChatSendOrigin(sendOrigin) {
          openClawStatusText = failureText
        }
        if openClawChatThread(
          threadID,
          transcriptURL: sendOrigin.transcriptURL
        )?.pendingTurn != nil {
          openClawGatewayStateByThreadID[threadID] = .reconnecting
          openClawGatewayDetailByThreadID[threadID] =
            "This turn is saved and will reconnect without sending it twice."
          scheduleOpenClawPendingTurnRecovery(for: threadID)
          return
        }
        if chatThread.isSharedRoom {
          replaceOpenClawDeliveryStatus(for: userMessageID, in: threadID, with: .sent)
          insertSharedRoomFailure(
            failureText,
            destinationID: dispatchDestinationID,
            runtime: dispatchRuntime,
            after: userMessageID,
            in: threadID,
            transcriptURL: sendOrigin.transcriptURL
          )
          removeFirstPendingOpenClawUserMessage(in: threadID)
          clearOpenClawCompletedRunPresentation(for: threadID)
          openClawStatusText = openClawPendingUserMessageIDs(for: threadID).isEmpty
            ? "\(dispatchDestination.name) could not respond"
            : openClawQueuedStatusText()
          continue
        }
        markPendingOpenClawMessagesFailed(
          failureText,
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL
        )
        removeAllPendingOpenClawUserMessages(in: threadID)
        return
      }
    }
  }

  func recoverPendingOpenClawTurns() async {
    let tasks = pendingOpenClawRecoveryThreadIDs().map { threadID in
      Task { @MainActor [weak self] in
        await self?.recoverPendingOpenClawTurn(in: threadID)
      }
    }
    for task in tasks {
      await task.value
    }
  }

  private func pendingOpenClawRecoveryThreadIDs() -> [UUID] {
    openClawChatThreads.compactMap { thread -> UUID? in
      guard let pendingTurn = thread.pendingTurn else { return nil }
      let destinationID = pendingTurn.destinationID ?? thread.destinationID
      return aiChatDestination(id: destinationID)?.adapter == .openClaw ? thread.id : nil
    }
  }

  private func hasPendingOpenClawRecovery(in threadID: UUID) -> Bool {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }),
          let pendingTurn = thread.pendingTurn
    else {
      return false
    }
    let destinationID = pendingTurn.destinationID ?? thread.destinationID
    return aiChatDestination(id: destinationID)?.adapter == .openClaw
  }

  private func startPendingOpenClawTurnRecovery() {
    for threadID in pendingOpenClawRecoveryThreadIDs() {
      scheduleOpenClawPendingTurnRecovery(for: threadID, initialDelaySeconds: 0)
    }
  }

  private func recoverPendingOpenClawTurn(in threadID: UUID) async {
    guard !drainingOpenClawThreadIDs.contains(threadID) else { return }
    let sendOrigin: AIChatSendOrigin
    if let existingOrigin = aiChatSendOriginsByThreadID[threadID] {
      sendOrigin = existingOrigin
    } else {
      guard let thread = openClawChatThread(
        threadID,
        transcriptURL: openClawTranscriptURL.standardizedFileURL
      ) else { return }
      let currentOrigin = AIChatSendOrigin(
        corpusRoot: corpusRoot?.standardizedFileURL,
        transcriptURL: openClawTranscriptURL.standardizedFileURL,
        workspaceContext: threadScopedOpenClawWorkspaceContext(for: thread)
      )
      aiChatSendOriginsByThreadID[threadID] = currentOrigin
      sendOrigin = currentOrigin
    }
    guard let thread = openClawChatThread(
      threadID,
      transcriptURL: sendOrigin.transcriptURL
    ),
          let pendingTurn = thread.pendingTurn
    else {
      aiChatSendOriginsByThreadID.removeValue(forKey: threadID)
      return
    }
    guard let pendingUserMessage = thread.messages.first(where: {
      $0.id == pendingTurn.userMessageID && $0.role == .user
    }) else {
      clearOpenClawPendingTurn(
        pendingTurn.runID,
        in: threadID,
        transcriptURL: sendOrigin.transcriptURL,
        shouldPersist: true
      )
      aiChatSendOriginsByThreadID.removeValue(forKey: threadID)
      return
    }

    prepareOpenClawRunPresentation(for: threadID)
    drainingOpenClawThreadIDs.insert(threadID)
    activeOpenClawUserMessageIDByThreadID[threadID] = pendingUserMessage.id
    openClawRequestStartedAtByThreadID[threadID] = pendingTurn.startedAt
    openClawActiveRunIDByThreadID[threadID] = pendingTurn.runID
    syncSelectedOpenClawSendState()
    if isActiveAIChatSendOrigin(sendOrigin) {
      openClawStatusText = "Reconnecting to \(aiChatDestinationTitle(pendingTurn.destinationID ?? thread.destinationID))"
    }

    let pendingDestinationID = pendingTurn.destinationID ?? thread.destinationID
    var completed = false
    do {
      let reply: String
      if let openClawRecoveryHandler {
        reply = try await openClawRecoveryHandler(pendingTurn, thread.sessionKey)
      } else {
        let gateway = OpenClawGatewayClient(
          settings: openClawSettings(
            forDestinationID: pendingDestinationID,
            allowKeychainRead: true
          )
        )
        openClawGatewayClientsByThreadID[threadID] = gateway
        reply = try await gateway.reconnectAcceptedRun(
          runID: pendingTurn.runID,
          sessionKey: thread.sessionKey,
          agentID: pendingTurn.agentID,
          requestStartedAt: pendingTurn.startedAt
        ) { [weak self] event in
          await self?.handleOpenClawGatewayEvent(
            event,
            threadID: threadID,
            destinationID: pendingDestinationID
          )
        }
      }
      let stillPending = openClawChatThread(
        threadID,
        transcriptURL: sendOrigin.transcriptURL
      )?.pendingTurn?.runID == pendingTurn.runID
      if stillPending {
        _ = insertOpenClawReply(
          reply,
          after: pendingTurn.userMessageID,
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL,
          changeSummary: nil,
          authorRuntime: thread.isSharedRoom ? .openClaw : nil,
          authorDestinationID: thread.isSharedRoom ? pendingDestinationID : nil
        )
        removeFirstPendingOpenClawUserMessage(in: threadID)
        clearOpenClawCompletedRunPresentation(for: threadID)
        if isActiveAIChatSendOrigin(sendOrigin) {
          openClawStatusText = openClawPendingUserMessageIDs(for: threadID).isEmpty
            ? "OpenClaw reconnected and replied"
            : openClawQueuedStatusText()
        }
        completed = true
        if isActiveAIChatSendOrigin(sendOrigin) {
          await refreshSelectedDetailFromDisk()
        }
      }
    } catch {
      let pendingTurnStillExists = openClawChatThread(
        threadID,
        transcriptURL: sendOrigin.transcriptURL
      )?.pendingTurn?.runID == pendingTurn.runID
      if Self.openClawRunWasStopped(after: error) || !pendingTurnStillExists {
        markOpenClawRunStopped(
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL
        )
      } else {
        openClawGatewayStateByThreadID[threadID] = .reconnecting
        openClawLastEventAtByThreadID[threadID] = Date()
        openClawGatewayDetailByThreadID[threadID] =
          "This turn is saved and will reconnect without sending it twice."
        if isActiveAIChatSendOrigin(sendOrigin) {
          openClawStatusText = "OpenClaw will reconnect to this saved turn"
        }
        scheduleOpenClawPendingTurnRecovery(for: threadID)
      }
    }

    openClawGatewayClientsByThreadID.removeValue(forKey: threadID)
    activeOpenClawUserMessageIDByThreadID.removeValue(forKey: threadID)
    drainingOpenClawThreadIDs.remove(threadID)
    openClawRequestStartedAtByThreadID.removeValue(forKey: threadID)
    syncSelectedOpenClawSendState()
    if completed, !openClawPendingUserMessageIDs(for: threadID).isEmpty {
      await drainOpenClawSendQueue(for: threadID)
    } else if completed {
      aiChatSendOriginsByThreadID.removeValue(forKey: threadID)
    }
  }

  private func scheduleOpenClawPendingTurnRecovery(
    for threadID: UUID,
    initialDelaySeconds: UInt64 = 5
  ) {
    guard openClawRecoveryTasksByThreadID[threadID] == nil,
          hasPendingOpenClawRecovery(in: threadID)
    else { return }

    let token = UUID()
    openClawRecoveryTaskTokensByThreadID[threadID] = token
    openClawRecoveryTasksByThreadID[threadID] = Task { @MainActor [weak self] in
      var delaySeconds = initialDelaySeconds
      while !Task.isCancelled {
        if delaySeconds > 0 {
          do {
            try await Task.sleep(nanoseconds: delaySeconds * 1_000_000_000)
          } catch {
            break
          }
        }
        guard let self, self.hasPendingOpenClawRecovery(in: threadID) else { break }
        await self.recoverPendingOpenClawTurn(in: threadID)
        guard !Task.isCancelled,
              self.hasPendingOpenClawRecovery(in: threadID)
        else { break }
        delaySeconds = delaySeconds == 0 ? 5 : min(delaySeconds * 2, 60)
      }
      guard let self,
            self.openClawRecoveryTaskTokensByThreadID[threadID] == token
      else { return }
      self.openClawRecoveryTasksByThreadID.removeValue(forKey: threadID)
      self.openClawRecoveryTaskTokensByThreadID.removeValue(forKey: threadID)
    }
  }

  private func cancelOpenClawPendingTurnRecovery(for threadID: UUID) {
    openClawRecoveryTasksByThreadID.removeValue(forKey: threadID)?.cancel()
    openClawRecoveryTaskTokensByThreadID.removeValue(forKey: threadID)
  }

  private func cancelAllOpenClawPendingTurnRecovery() {
    for task in openClawRecoveryTasksByThreadID.values {
      task.cancel()
    }
    openClawRecoveryTasksByThreadID.removeAll()
    openClawRecoveryTaskTokensByThreadID.removeAll()
  }

