      codexAccountState = .unavailable(error.localizedDescription)
      openClawStatusText = error.localizedDescription
    }
  }

  private func sendDirectProviderRequest(
    messages: [OpenClawChatMessage],
    threadID: UUID,
    destination: AIChatDestinationConfiguration,
    sendOrigin: AIChatSendOrigin
  ) async throws -> String {
    guard destination.adapter.isDirectProvider,
          let thread = openClawChatThread(
            threadID,
            transcriptURL: sendOrigin.transcriptURL
          ),
          let userMessage = messages.last(where: { $0.role == .user })
    else {
      throw AIProviderChatError.invalidResponse
    }
    let requestMessages = thread.isSharedRoom
      ? Self.sharedRoomRequestMessages(
          messages,
          targetDestinationName: destination.name,
          targetDestinationID: destination.id,
          destinationNamesByID: Dictionary(
            uniqueKeysWithValues: enabledAIChatDestinations.map { ($0.id, $0.name) }
          ),
          through: userMessage.id
        )
      : messages
    let model = thread.model(forDestinationID: destination.id)
      ?? destination.model
      ?? ""
    let token = AIChatDestinationCredentials.readToken(
      destinationID: destination.id,
      allowUserInteraction: true
    )
    let settings = try AIProviderChatSettings(
      adapter: destination.adapter,
      endpoint: destination.endpoint,
      apiKey: token
    )

    openClawGatewayStateByThreadID[threadID] = .connecting
    openClawGatewayDetailByThreadID[threadID] = destination.name
    if selectedOpenClawChatThreadID == threadID {
      openClawStatusText = "Connecting to \(destination.name)"
    }
    try Task.checkCancellation()
    openClawGatewayStateByThreadID[threadID] = .connected
    if selectedOpenClawChatThreadID == threadID {
      openClawStatusText = "\(destination.name) is working"
    }
    let reply = try await AIProviderChatClient(settings: settings).send(
      messages: requestMessages,
      model: model,
      workspaceContext: sendOrigin.workspaceContext,
      destinationName: destination.name
    )
    try Task.checkCancellation()
    return reply
  }

  private func sendClaudeCodeRequest(
    messages: [OpenClawChatMessage],
    threadID: UUID,
    destinationID: String,
    sendOrigin: AIChatSendOrigin
  ) async throws -> String {
    guard let corpusRoot = sendOrigin.corpusRoot else {
      throw ClaudeCodeError.invalidResponse("choose an Org2 corpus before using Claude Code")
    }
    guard let destination = aiChatDestination(id: destinationID),
          destination.adapter == .claudeLocal,
          let thread = openClawChatThread(threadID, transcriptURL: sendOrigin.transcriptURL),
          let userMessage = messages.last(where: { $0.role == .user }),
          thread.runtime == .claude
            || (thread.isSharedRoom && userMessage.targetDestinationID == destinationID)
    else {
      throw ClaudeCodeError.invalidResponse("the selected thread is not routed to Claude Code")
    }
    let requestMessages = thread.isSharedRoom
      ? Self.sharedRoomRequestMessages(
          messages,
          targetDestinationName: destination.name,
          targetDestinationID: destinationID,
          destinationNamesByID: Dictionary(
            uniqueKeysWithValues: enabledAIChatDestinations.map { ($0.id, $0.name) }
          ),
          through: userMessage.id
        )
      : messages
    let requestUserMessage = requestMessages.last(where: { $0.id == userMessage.id }) ?? userMessage

    openClawGatewayStateByThreadID[threadID] = .connecting
    openClawGatewayDetailByThreadID[threadID] = destination.name
    if selectedOpenClawChatThreadID == threadID {
      openClawStatusText = "Connecting to \(destination.name)"
    }

    let result: ClaudeCodeTurnResult
    if let claudeSendHandlerForTesting {
      result = try await claudeSendHandlerForTesting(
        requestMessages,
        threadID,
        sendOrigin.workspaceContext
      )
    } else {
      result = try await localClaudeCodeClient().runTurn(
        openOrgThreadID: threadID,
        existingSessionID: thread.runtimeThreadID(forDestinationID: destinationID),
        message: Self.expandingOpenClawAgentCommand(requestUserMessage).content,
        systemPrompt: sendOrigin.workspaceContext.localAgentSystemPrompt(
          runtime: "claude",
          runtimeTitle: "Claude Code"
        ),
        attachments: requestUserMessage.attachments,
        cwd: corpusRoot,
        model: thread.model(forDestinationID: destinationID),
        sandboxAccess: codexSandboxAccess
      )
    }

    if result.sessionID != thread.runtimeThreadID(forDestinationID: destinationID) {
      var runtimeThreadIDs = thread.runtimeThreadIDsByDestination
      runtimeThreadIDs[destinationID] = result.sessionID
      replaceOpenClawChatThread(
        thread.replacingOpenClawChatMetadata(
          runtimeThreadID: destinationID == thread.destinationID ? .some(result.sessionID) : nil,
          runtimeThreadIDsByDestination: runtimeThreadIDs
        ),
        transcriptURL: sendOrigin.transcriptURL
      )
    }
    openClawGatewayStateByThreadID[threadID] = .connected
    openClawGatewayDetailByThreadID[threadID] = destination.name
    let reply = result.reply.trimmingCharacters(in: .whitespacesAndNewlines)
    return reply.isEmpty
      ? "Claude Code completed the turn without a text response."
      : reply
  }

  private func sendCodexRequest(
    messages: [OpenClawChatMessage],
    threadID: UUID,
    destinationID: String,
    localEditTurnID: String,
    sendOrigin: AIChatSendOrigin
  ) async throws -> String {
    guard let corpusRoot = sendOrigin.corpusRoot else {
      throw CodexAppServerError.invalidResponse("choose an Org2 corpus before using Codex")
    }
    guard let userMessage = messages.last(where: { $0.role == .user }) else {
      throw CodexAppServerError.invalidResponse("no user message was available")
    }

    guard let destination = aiChatDestination(id: destinationID),
          destination.runtime == .codex,
          let thread = openClawChatThread(
      threadID,
      transcriptURL: sendOrigin.transcriptURL
    ),
          thread.runtime == .codex
            || (thread.isSharedRoom && userMessage.targetDestinationID == destinationID)
    else {
      throw CodexAppServerError.invalidResponse("the selected thread is not routed to Codex")
    }
    let requestMessages = thread.isSharedRoom
      ? Self.sharedRoomRequestMessages(
          messages,
          targetDestinationName: destination.name,
          targetDestinationID: destinationID,
          destinationNamesByID: Dictionary(
            uniqueKeysWithValues: enabledAIChatDestinations.map { ($0.id, $0.name) }
          ),
          through: userMessage.id
        )
      : messages
    let requestUserMessage = requestMessages.last(where: { $0.id == userMessage.id }) ?? userMessage

    if let codexSendHandlerForTesting {
      return try await codexSendHandlerForTesting(
        requestMessages,
        threadID,
        sendOrigin.workspaceContext
      )
    }

    let client = try codexClient(forDestinationID: destinationID)
    let account = try await client.accountState()
    if destinationID == AIChatDestinationConfiguration.localCodexID {
      codexAccountState = account
    }
    guard case .chatGPT = account else {
      if case .apiKey = account {
        throw CodexAppServerError.invalidResponse(
          "Codex is using an API key. Sign in with ChatGPT in Configure to use subscription access."
        )
      }
      throw CodexAppServerError.notAuthenticated
    }

    openClawGatewayStateByThreadID[threadID] = .connecting
    openClawGatewayDetailByThreadID[threadID] = destination.name
    if selectedOpenClawChatThreadID == threadID {
      openClawStatusText = "Connecting to \(destination.name)"
    }

    let existingRuntimeThreadID = thread.runtimeThreadID(forDestinationID: destinationID)
    let selectedModel = thread.model(forDestinationID: destinationID)
    let selectedReasoningEffort = thread.isSharedRoom ? nil : thread.reasoningEffort
    let destinationRoot: URL
    if (destination.adapter == .codexRemote
        || destination.adapter == .codexManagedRemote),
       !destination.workspaceRoot.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      destinationRoot = URL(fileURLWithPath: NSString(string: destination.workspaceRoot)
        .expandingTildeInPath)
    } else {
      destinationRoot = corpusRoot
    }
    let threadResolution = try await client.ensureThreadRecoveringStaleSession(
      existingThreadID: existingRuntimeThreadID,
      cwd: destinationRoot,
      model: selectedModel,
      sandboxAccess: codexSandboxAccess
    )
    let runtimeThreadID = threadResolution.threadID
    codexLocalThreadIDsByRuntimeThreadID["\(destinationID)\u{0}\(runtimeThreadID)"] = threadID
    if runtimeThreadID != existingRuntimeThreadID {
      var runtimeThreadIDs = thread.runtimeThreadIDsByDestination
      runtimeThreadIDs[destinationID] = runtimeThreadID
      replaceOpenClawChatThread(
        thread.replacingOpenClawChatMetadata(
          runtimeThreadID: destinationID == thread.destinationID ? .some(runtimeThreadID) : nil,
          runtimeThreadIDsByDestination: runtimeThreadIDs
        ),
        transcriptURL: sendOrigin.transcriptURL
      )
    }
    openClawGatewayStateByThreadID[threadID] = .connected
    openClawGatewayDetailByThreadID[threadID] = destination.name
    if selectedOpenClawChatThreadID == threadID {
      openClawStatusText = "\(destination.name) is working"
    }

    var workspacePrompt = sendOrigin.workspaceContext.codexSystemPrompt()
    if threadResolution.replacedStaleThread {
      workspacePrompt += """


      OpenOrg could not safely reopen the previous Codex task, so it created a replacement task for this same chat. Continue from the conversation context below. Do not repeat already completed work unless the latest user message asks you to.

      \(Self.codexRecoveryConversationContext(
        requestMessages,
        excludingMessageID: requestUserMessage.id
      ))
      """
    }
    if destination.adapter == .codexRemote
        || destination.adapter == .codexManagedRemote {
      workspacePrompt += """


      Remote execution note: this Codex destination runs with `\(destinationRoot.path)` as its filesystem working directory. Paths in the Org2 context may describe the Mac hosting Org2; use the remote working directory for direct filesystem operations. The `org2_workspace_*` tools still operate on the active corpus through Org2 on that Mac.
      """
    }

    let result = try await client.runTurn(
      threadID: runtimeThreadID,
      turnID: localEditTurnID,
      message: Self.expandingOpenClawAgentCommand(requestUserMessage).content,
      workspaceContext: workspacePrompt,
      attachments: requestUserMessage.attachments,
      cwd: destinationRoot,
      clientUserMessageID: requestUserMessage.id,
      model: selectedModel,
      reasoningEffort: selectedReasoningEffort,
      sandboxAccess: codexSandboxAccess
    )
    let reply = result.reply.trimmingCharacters(in: .whitespacesAndNewlines)
    return reply.isEmpty
      ? "Codex completed the turn without a text response."
      : reply
  }

  nonisolated private static func codexRecoveryConversationContext(
    _ messages: [OpenClawChatMessage],
    excludingMessageID: UUID
  ) -> String {
    let transcript = messages.compactMap { message -> String? in
      guard message.id != excludingMessageID,
            !message.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
            message.role == .user || message.role == .assistant
      else { return nil }
      let speaker = message.role == .user ? "User" : "Assistant"
      return "\(speaker): \(message.content)"
    }.joined(separator: "\n\n")
    guard !transcript.isEmpty else { return "No earlier chat messages were available." }
    let limit = 32_000
    guard transcript.count > limit else { return transcript }
    return "[Earlier messages omitted]\n\n" + String(transcript.suffix(limit))
  }

  private func localCodexClient() -> CodexAppServerClient {
    if let codexAppServerClient {
      return codexAppServerClient
    }
    let client = CodexAppServerClient(
      eventHandler: { [weak self] event in
        await self?.handleCodexAppServerEvent(event)
      },
      dynamicToolHandler: { [weak self] call in
        guard let self else {
          return CodexDynamicToolResult(success: false, text: "OpenOrg was closed.")
        }
        return await self.handleCodexDynamicToolCall(call)
      }
    )
    codexAppServerClient = client
    return client
  }

  private func localClaudeCodeClient() -> ClaudeCodeClient {
    if let claudeCodeClient { return claudeCodeClient }
    let client = ClaudeCodeClient { [weak self] threadID, event in
      await self?.handleClaudeCodeEvent(event, threadID: threadID)
    }
    claudeCodeClient = client
    return client
  }

  private func invalidateCodexClient(forDestinationID destinationID: String) {
    guard let client = codexAppServerClientsByDestinationID.removeValue(
      forKey: destinationID
    ) else { return }
    Task { await client.shutdown() }
  }

  public func shutdownAIChatTransports() async {
    let clients = [codexAppServerClient, externalCodexAppServerClient]
      .compactMap { $0 } + Array(codexAppServerClientsByDestinationID.values)
    codexAppServerClient = nil
    externalCodexAppServerClient = nil
    codexAppServerClientsByDestinationID.removeAll()
    codexActiveTurnsByThreadID.removeAll()
    let claudeClient = claudeCodeClient
    claudeCodeClient = nil
    var stoppedClients = Set<ObjectIdentifier>()
    for client in clients where stoppedClients.insert(ObjectIdentifier(client)).inserted {
      await client.shutdown()
    }
    await claudeClient?.shutdown()
  }

  private func codexClient(forDestinationID destinationID: String) throws -> CodexAppServerClient {
    if destinationID == AIChatDestinationConfiguration.localCodexID {
      return localCodexClient()
    }
    if let existing = codexAppServerClientsByDestinationID[destinationID] {
      return existing
    }
    guard let destination = aiChatDestination(id: destinationID),
          destination.runtime == .codex
    else {
      throw CodexAppServerError.invalidResponse("the configured AI destination is not a Codex target")
    }
    let transport: CodexAppServerTransport
    switch destination.adapter {
    case .codexLocal:
      transport = .local
    case .codexRemote:
      guard let endpoint = URL(string: destination.endpoint),
            endpoint.scheme?.lowercased() == "ws" || endpoint.scheme?.lowercased() == "wss"
      else {
        throw CodexAppServerError.invalidResponse(
          "\(destination.title) needs a ws:// or wss:// Codex App Server endpoint"
        )
      }
      transport = .remote(
        endpoint: endpoint,
        bearerToken: AIChatDestinationCredentials.readToken(
          destinationID: destinationID,
          allowUserInteraction: true
        )
      )
    case .codexManagedRemote:
      guard !destination.endpoint.isEmpty else {
        throw CodexAppServerError.invalidResponse(
          "\(destination.title) needs a Codex SSH host or ~/.ssh/config alias"
        )
      }
      transport = .managedRemote(sshHost: destination.endpoint)
    case .claudeLocal, .openClaw, .openAI, .anthropic, .openRouter, .ollama:
      throw CodexAppServerError.invalidResponse("the configured AI destination is not a Codex target")
    }
    let client = CodexAppServerClient(
      transport: transport,
      eventHandler: { [weak self] event in
        await self?.handleCodexAppServerEvent(event, destinationID: destinationID)
      },
      dynamicToolHandler: { [weak self] call in
        guard let self else {
          return CodexDynamicToolResult(success: false, text: "OpenOrg was closed.")
        }
        return await self.handleCodexDynamicToolCall(call)
      }
    )
    codexAppServerClientsByDestinationID[destinationID] = client
    return client
  }

  private func modelsForAIChatDestination(
    _ destinationID: String
  ) async throws -> [AIChatModelOption] {
    guard let destination = aiChatDestination(id: destinationID) else {
      throw CodexAppServerError.invalidResponse("AI destination \(destinationID) is not configured")
    }
    switch destination.adapter {
    case .codexLocal, .codexRemote, .codexManagedRemote:
      return try await codexClient(forDestinationID: destinationID).listModels()
    case .claudeLocal:
      return [
        AIChatModelOption(id: "sonnet", label: "Sonnet"),
        AIChatModelOption(id: "opus", label: "Opus"),
        AIChatModelOption(id: "haiku", label: "Haiku")
      ]
    case .openClaw:
      return try await OpenClawGatewayClient(
        settings: openClawSettings(forDestinationID: destinationID, allowKeychainRead: true)
      ).listModels()
    case .openAI, .anthropic, .openRouter, .ollama:
      guard let model = destination.model else { return [] }
      return [AIChatModelOption(id: model, label: model, isDefault: true)]
    }
  }

  private func externalCodexClient() -> CodexAppServerClient {
    if let externalCodexAppServerClient {
      return externalCodexAppServerClient
    }
    // Keep read-only history browsing independent from an active Org2 Codex
    // turn. Some app-server versions serialize thread reads behind live turns.
    let client = CodexAppServerClient(
      eventHandler: { _ in },
      dynamicToolHandler: { _ in
        CodexDynamicToolResult(
          success: false,
          text: "External thread browsing is read-only."
        )
      }
    )
    externalCodexAppServerClient = client
    return client
  }

  private func handleCodexDynamicToolCall(
    _ call: CodexDynamicToolCall
  ) async -> CodexDynamicToolResult {
    if call.tool == "org2_thread_post" {
      return await handleCodexThreadPostTool(call.arguments)
    }
    let command: String
    switch call.tool {
    case "org2_workspace_read":
      command = OpenClawLocalEditBroker.readCommand
    case "org2_workspace_patch_preview":
      command = OpenClawLocalEditBroker.previewCommand
    case "org2_workspace_patch_apply":
      command = OpenClawLocalEditBroker.applyCommand
    default:
      return CodexDynamicToolResult(
        success: false,
        text: #"{"error":{"code":"UNSUPPORTED_COMMAND","message":"Unsupported Org2 workspace tool."}}"#
      )
    }

    let paramsJSON: String?
    if let data = try? JSONEncoder().encode(call.arguments) {
      paramsJSON = String(data: data, encoding: .utf8)
    } else {
      paramsJSON = nil
    }
    let result = await localEditBroker().handle(command: command, paramsJSON: paramsJSON)
    if result.ok {
      return CodexDynamicToolResult(
        success: true,
        text: result.payloadJSON ?? #"{"ok":true}"#
      )
    }
    let errorObject: JSONValue = .object([
      "error": .object([
        "code": .string(result.errorCode ?? "LOCAL_EDIT_FAILED"),
        "message": .string(result.errorMessage ?? "Local Org2 edit failed.")
      ])
    ])
    let errorText = (try? JSONEncoder().encode(errorObject))
      .flatMap { String(data: $0, encoding: .utf8) }
      ?? #"{"error":{"code":"LOCAL_EDIT_FAILED","message":"Local Org2 edit failed."}}"#
    return CodexDynamicToolResult(success: false, text: errorText)
  }

  func handleCodexThreadPostTool(_ arguments: JSONValue) async -> CodexDynamicToolResult {
    guard let corpusRoot else {
      return CodexDynamicToolResult(success: false, text: "No active Org2 corpus is selected.")
    }
    let values = arguments.objectValue ?? [:]
    let threadID = values["threadId"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    let message = values["message"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    let author = values["author"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    guard !threadID.isEmpty, !message.isEmpty, !author.isEmpty else {
      return CodexDynamicToolResult(
        success: false,
        text: "threadId, message, and author are required for org2_thread_post."
      )
    }

    var cliArguments = [
      "thread", "post", threadID,
      "--message", message,
      "--author", author,
      "--dir", corpusRoot.standardizedFileURL.path,
      "--apply",
      "--json",
    ]
    for (name, flag) in [
      ("agentRef", "--agent-ref"),
      ("source", "--source"),
      ("idempotencyKey", "--idempotency-key"),
    ] {
      let value = values[name]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
      if !value.isEmpty { cliArguments.append(contentsOf: [flag, value]) }
    }

    do {
      let output = try await cli.run(cliArguments)
      drainAIChatInbox()
      return CodexDynamicToolResult(success: true, text: String(decoding: output, as: UTF8.self))
    } catch {
      return CodexDynamicToolResult(success: false, text: error.localizedDescription)
    }
  }

  private func handleClaudeCodeEvent(
    _ event: ClaudeCodeEvent,
    threadID: UUID
  ) async {
    guard openClawChatThreads.contains(where: { $0.id == threadID }) else { return }
    openClawLastEventAtByThreadID[threadID] = Date()
    switch event {
    case .sessionStarted(let sessionID):
      openClawGatewayStateByThreadID[threadID] = .connected
      openClawActiveRunIDByThreadID[threadID] = sessionID
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "Claude Code is working"
      }
    case .textDelta(let delta):
      openClawLiveState.noteEvent(for: threadID, coalesced: true)
      openClawLiveState.appendStreamingDelta(delta, for: threadID)
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "Claude Code is replying"
      }
    case .activity(let id, let title, let status):
      let activity = OpenClawRunActivity(
        id: id,
        runID: openClawActiveRunIDByThreadID[threadID] ?? "claude-code",
        kind: .tool,
        title: title,
        detail: nil,
        status: status
      )
      var activities = openClawRunActivitiesByThreadID[threadID] ?? []
      if let index = activities.firstIndex(where: { $0.id == id }) {
        activities[index] = activity
      } else {
        activities.append(activity)
      }
      openClawRunActivitiesByThreadID[threadID] = Array(activities.suffix(80))
    case .warning(let message):
      openClawGatewayDetailByThreadID[threadID] = message
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = message
      }
    }
  }

  private func handleCodexAppServerEvent(
    _ event: CodexAppServerEvent,
    destinationID: String = AIChatDestinationConfiguration.localCodexID
  ) async {
    let destinationName = aiChatDestination(id: destinationID)?.name ?? "Codex"
    switch event {
    case .connectionChanged(let isConnected, let detail):
      if !isConnected {
        for threadID in openClawSendingThreadIDs where
          openClawChatThreads.first(where: { $0.id == threadID }).map({
            $0.destinationID == destinationID
              || ($0.isSharedRoom && $0.roomDestinationIDs.contains(destinationID))
          }) == true {
          openClawGatewayStateByThreadID[threadID] = .disconnected
          openClawGatewayDetailByThreadID[threadID] = detail
          openClawLastEventAtByThreadID[threadID] = Date()
        }
      }
    case .accountUpdated(let authMode, let plan):
      guard destinationID == AIChatDestinationConfiguration.localCodexID else { return }
      if authMode == "chatgpt" {
        let currentEmail: String?
        if case .chatGPT(let email, _) = codexAccountState {
          currentEmail = email
        } else {
          currentEmail = nil
        }
        codexAccountState = .chatGPT(email: currentEmail, plan: plan)
      } else if authMode == "apikey" {
        codexAccountState = .apiKey
      } else if let authMode {
        codexAccountState = .other(authMode)
      } else {
        codexAccountState = .signedOut
      }
    case .loginCompleted(_, let success, let error):
      guard destinationID == AIChatDestinationConfiguration.localCodexID else { return }
      isCodexSigningIn = false
      if success {
        await refreshCodexAccount()
        openClawStatusText = "Signed in to Codex with ChatGPT"
      } else {
        codexAccountState = .unavailable(error ?? "ChatGPT sign-in failed")
        openClawStatusText = error ?? "ChatGPT sign-in failed"
      }
    case .turnStarted(let runtimeThreadID, let turnID):
      guard let threadID = localChatThreadID(
        forRuntimeThreadID: runtimeThreadID,
        destinationID: destinationID
      ) else { return }
      if stoppedOpenClawThreadIDs.contains(threadID) {
        // Stop can race a successful turn/start response. The local request
        // has already been cleared, so immediately interrupt the late remote
        // turn instead of allowing invisible work to continue.
        if let client = try? codexClient(forDestinationID: destinationID) {
          try? await client.interrupt(threadID: runtimeThreadID, turnID: turnID)
        }
        return
      }
      openClawLastEventAtByThreadID[threadID] = Date()
      codexActiveTurnsByThreadID[threadID] = (runtimeThreadID, turnID)
      openClawGatewayStateByThreadID[threadID] = .connected
      openClawActiveRunIDByThreadID[threadID] = turnID
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "\(destinationName) is working"
      }
    case .agentMessageDelta(let runtimeThreadID, _, let itemID, let delta):
      guard let threadID = localChatThreadID(
        forRuntimeThreadID: runtimeThreadID,
        destinationID: destinationID
      ) else { return }
      openClawLiveState.noteEvent(for: threadID, coalesced: true)
      let streamingReply = CodexStreamingText.appending(
        delta,
        itemID: itemID,
        after: codexStreamingItemIDByThreadID[threadID],
        to: openClawLiveState.streamingReply(for: threadID)
      )
      openClawLiveState.replaceStreamingReply(streamingReply, for: threadID, coalesced: true)
      codexStreamingItemIDByThreadID[threadID] = itemID
      if selectedOpenClawChatThreadID == threadID {
        let nextStatus = "\(destinationName) is replying"
        if openClawStatusText != nextStatus {
          openClawStatusText = nextStatus
        }
      }
    case .reasoningDelta(let runtimeThreadID, _, let delta):
      guard let threadID = localChatThreadID(
        forRuntimeThreadID: runtimeThreadID,
        destinationID: destinationID
      ) else { return }
      openClawLiveState.noteEvent(for: threadID, coalesced: true)
      openClawLiveState.appendReasoningDelta(delta, for: threadID)
    case .activity(
      let runtimeThreadID,
      let turnID,
      let itemID,
      let title,
      let detail,
      let status
    ):
      guard let threadID = localChatThreadID(
        forRuntimeThreadID: runtimeThreadID,
        destinationID: destinationID
      ) else { return }
      openClawLastEventAtByThreadID[threadID] = Date()
      let activity = OpenClawRunActivity(
        id: itemID,
        runID: turnID,
        kind: .tool,
        title: title,
        detail: detail,
        status: status
      )
      var activities = openClawRunActivitiesByThreadID[threadID] ?? []
      if let index = activities.firstIndex(where: { $0.id == itemID }) {
        activities[index] = activity
      } else {
        activities.append(activity)
      }
      openClawRunActivitiesByThreadID[threadID] = Array(activities.suffix(80))
    case .warning(let runtimeThreadID, let message):
      if let runtimeThreadID,
         let threadID = localChatThreadID(
           forRuntimeThreadID: runtimeThreadID,
           destinationID: destinationID
         ) {
        openClawLastEventAtByThreadID[threadID] = Date()
        openClawGatewayDetailByThreadID[threadID] = message
        if selectedOpenClawChatThreadID == threadID {
          openClawStatusText = message
        }
      }
    }
  }

  private func localChatThreadID(
    forRuntimeThreadID runtimeThreadID: String,
    destinationID: String = AIChatDestinationConfiguration.localCodexID
  ) -> UUID? {
    codexLocalThreadIDsByRuntimeThreadID["\(destinationID)\u{0}\(runtimeThreadID)"]
      ?? openClawChatThreads.first {
      ($0.runtime == .codex || $0.isSharedRoom)
        && $0.runtimeThreadID(forDestinationID: destinationID) == runtimeThreadID
    }?.id
  }

  private func sendOpenClawRequest(
    messages: [OpenClawChatMessage],
    sessionKey: String,
    threadID: UUID,
    destinationID: String,
    localEditTurnID: String?,
    sendOrigin: AIChatSendOrigin
  ) async throws -> String {
    guard let destination = aiChatDestination(id: destinationID),
          destination.runtime == .openClaw
    else {
      throw OpenClawGatewayError.protocolFailure("the configured destination is not an OpenClaw target")
    }
    let configuredAgentID = destination.agentID.trimmingCharacters(in: .whitespacesAndNewlines)
    let agentID = OpenClawChatClient.openClawAgentHeaderValue(
      for: configuredAgentID.isEmpty ? openClawAgentID : configuredAgentID
    )
    let threadConfiguration = openClawChatThread(
      threadID,
      transcriptURL: sendOrigin.transcriptURL
    )
    let workspaceContext = workspaceContext(
      sendOrigin.workspaceContext,
      localEditTurnID: localEditTurnID
    )
    let expandedMessages = messages.map(Self.expandingOpenClawAgentCommand)
    guard let originalUserMessage = expandedMessages.last(where: { $0.role == .user }) else {
      throw OpenClawGatewayError.protocolFailure("no user message was available")
    }
    let requestMessages = threadConfiguration?.isSharedRoom == true
      ? Self.sharedRoomRequestMessages(
          expandedMessages,
          targetDestinationName: destination.name,
          targetDestinationID: destinationID,
          destinationNamesByID: Dictionary(
            uniqueKeysWithValues: enabledAIChatDestinations.map { ($0.id, $0.name) }
          ),
          through: originalUserMessage.id
        )
      : expandedMessages
    let latestUserMessage = requestMessages.last(where: { $0.id == originalUserMessage.id })
      ?? originalUserMessage
    let isGatewayCommand = OpenClawSlashCommands.isGatewayCommand(
      latestUserMessage.content,
      gatewayCommands: openClawGatewayCommands,
      corpusSkills: corpusAgentSkillCommands
    )
    let selectedModel = threadConfiguration?.model(forDestinationID: destinationID)
    let selectedReasoningEffort = threadConfiguration?.isSharedRoom == true
      ? nil
      : threadConfiguration?.reasoningEffort
    if let openClawSendHandler {
      return try await openClawSendHandler(requestMessages, agentID, sessionKey, workspaceContext)
    }
    let settings = openClawSettings(
      forDestinationID: destinationID,
      allowKeychainRead: true
    )
    let gateway = OpenClawGatewayClient(settings: settings)
    openClawGatewayClientsByThreadID[threadID] = gateway
    prepareOpenClawRunPresentation(for: threadID)
    defer { openClawGatewayClientsByThreadID.removeValue(forKey: threadID) }

    let gatewayMessage = Self.openClawGatewayMessage(
      userMessage: latestUserMessage.content,
      workspaceContext: workspaceContext,
      isGatewayCommand: isGatewayCommand,
      runtimeAgentID: agentID
    )
    let pendingTurn = OpenClawPendingTurn(
      userMessageID: latestUserMessage.id,
      runID: UUID().uuidString.lowercased(),
      agentID: agentID,
      destinationID: destinationID,
      gatewayMessage: gatewayMessage
    )
    replaceOpenClawPendingTurn(
      pendingTurn,
      in: threadID,
      transcriptURL: sendOrigin.transcriptURL,
      shouldPersist: true
    )
    openClawActiveRunIDByThreadID[threadID] = pendingTurn.runID

    do {
      return try await gateway.send(
        message: gatewayMessage,
        attachments: latestUserMessage.attachments,
        agentID: agentID,
        sessionKey: sessionKey,
        model: selectedModel,
        reasoningEffort: selectedReasoningEffort,
        idempotencyKey: pendingTurn.runID,
        requestStartedAt: pendingTurn.startedAt
      ) { [weak self] event in
        await self?.handleOpenClawGatewayEvent(
          event,
          threadID: threadID,
          destinationID: destinationID
        )
      }
    } catch let error as OpenClawGatewayError where Self.shouldRetryAIChatWithDefaults(
      after: error,
      model: selectedModel,
      reasoningEffort: selectedReasoningEffort
    ) {
      let notice = clearRejectedAIChatConfiguration(
        for: threadID,
        destinationID: destinationID,
        transcriptURL: sendOrigin.transcriptURL,
        model: selectedModel,
        reasoningEffort: selectedReasoningEffort
      )
      aiChatConfigurationFallbackNoticesByThreadID[threadID] = notice
      openClawGatewayDetailByThreadID[threadID] = notice
      if isActiveAIChatSendOrigin(sendOrigin) {
        openClawStatusText = "Saved AI settings unavailable; retrying with defaults"
      }
      do {
        return try await gateway.send(
          message: gatewayMessage,
          attachments: latestUserMessage.attachments,
          agentID: agentID,
          sessionKey: sessionKey,
          model: nil,
          reasoningEffort: nil,
          idempotencyKey: pendingTurn.runID,
          requestStartedAt: pendingTurn.startedAt
        ) { [weak self] event in
          await self?.handleOpenClawGatewayEvent(
            event,
            threadID: threadID,
            destinationID: destinationID
          )
        }
      } catch {
        aiChatConfigurationFallbackNoticesByThreadID.removeValue(forKey: threadID)
        if !Self.openClawRunMayStillBeWorking(after: error) {
          clearOpenClawPendingTurn(
            pendingTurn.runID,
            in: threadID,
            transcriptURL: sendOrigin.transcriptURL,
            shouldPersist: true
          )
        }
        throw error
      }
    } catch let error as OpenClawGatewayError where error.permitsHTTPFallback {
      clearOpenClawPendingTurn(
        pendingTurn.runID,
        in: threadID,
        transcriptURL: sendOrigin.transcriptURL,
        shouldPersist: true
      )
      if selectedModel != nil || selectedReasoningEffort != nil {
        openClawGatewayStateByThreadID[threadID] = .disconnected
        openClawGatewayDetailByThreadID[threadID] = error.localizedDescription
        throw OpenClawGatewayError.gateway(
          code: "LIVE_GATEWAY_REQUIRED",
          message: "Model and reasoning overrides require the live OpenClaw Gateway. \(error.localizedDescription)"
        )
      }
      if isGatewayCommand {
        openClawGatewayStateByThreadID[threadID] = .disconnected
        openClawGatewayDetailByThreadID[threadID] = error.localizedDescription
        throw OpenClawGatewayError.gateway(
          code: "LIVE_GATEWAY_REQUIRED",
          message: "OpenClaw slash commands require the live Gateway. \(error.localizedDescription)"
        )
      }
      if latestUserMessage.attachments.contains(where: { !$0.mimeType.hasPrefix("image/") }) {
        openClawGatewayStateByThreadID[threadID] = .disconnected
        openClawGatewayDetailByThreadID[threadID] = error.localizedDescription
        throw OpenClawGatewayError.gateway(
          code: "LIVE_GATEWAY_REQUIRED",
          message: "File attachments require the live OpenClaw Gateway. \(error.localizedDescription)"
        )
      }
      openClawGatewayStateByThreadID[threadID] = .fallbackHTTP
      openClawGatewayDetailByThreadID[threadID] = error.localizedDescription
      openClawStreamingReplyByThreadID.removeValue(forKey: threadID)
      openClawReasoningByThreadID.removeValue(forKey: threadID)
      openClawRunActivitiesByThreadID[threadID] = []
      if isActiveAIChatSendOrigin(sendOrigin) {
        openClawStatusText = "Using HTTP compatibility for this turn"
      }
      let client = OpenClawChatClient(settings: settings)
      return try await client.send(
        messages: requestMessages,
        agentID: agentID,
        sessionKey: sessionKey,
        workspaceContext: sendOrigin.workspaceContext
      )
    } catch {
      if !Self.openClawRunMayStillBeWorking(after: error) {
        clearOpenClawPendingTurn(
          pendingTurn.runID,
          in: threadID,
          transcriptURL: sendOrigin.transcriptURL,
          shouldPersist: true
        )
      }
      throw error
    }
  }

  nonisolated private static func openClawRunMayStillBeWorking(after error: Error) -> Bool {
    guard let gatewayError = error as? OpenClawGatewayError else { return false }
    if case .acceptedRunRecovery = gatewayError { return true }
    return false
  }

  nonisolated private static func openClawRunWasStopped(after error: Error) -> Bool {
    guard let gatewayError = error as? OpenClawGatewayError else { return false }
    if case .aborted = gatewayError { return true }
    return false
  }

  nonisolated static func shouldRetryAIChatWithDefaults(
    after error: Error,
    model: String?,
    reasoningEffort: String?
  ) -> Bool {
    guard model != nil || reasoningEffort != nil,
          let gatewayError = error as? OpenClawGatewayError,
          case .sessionConfigurationRejected = gatewayError
    else {
      return false
    }
    return true
  }

  private func clearRejectedAIChatConfiguration(
    for threadID: UUID,
    destinationID: String,
    transcriptURL: URL,
    model: String?,
    reasoningEffort: String?
  ) -> String {
    if let thread = openClawChatThread(threadID, transcriptURL: transcriptURL) {
      let replacement: OpenClawChatThread
      if thread.isSharedRoom {
        var modelsByDestination = thread.roomModelsByDestination
        modelsByDestination.removeValue(forKey: destinationID)
        replacement = thread.replacingOpenClawChatMetadata(
          roomModels: thread.roomModels.replacingModel(nil, for: .openClaw),
          roomModelsByDestination: modelsByDestination
        )
      } else {
        replacement = thread.replacingOpenClawChatMetadata(
          model: .some(nil),
          reasoningEffort: .some(nil)
        )
      }
      replaceOpenClawChatThread(
        replacement,
        transcriptURL: transcriptURL
      )
      if !thread.isSharedRoom {
        persistLastAIChatConfiguration(
          destinationID: thread.destinationID,
          model: nil,
          reasoningEffort: nil
        )
      }
    }
    if selectedOpenClawChatThreadID == threadID {
      aiChatReasoningOptions = []
      aiChatEffectiveModel = nil
      aiChatDefaultReasoningEffort = nil
    }

    let rejectedChoice: String
    switch (model, reasoningEffort) {
    case let (model?, reasoningEffort?):
      rejectedChoice = "model \(model) and reasoning level \(reasoningEffort)"
    case let (model?, nil):
      rejectedChoice = "model \(model)"
    case let (nil, reasoningEffort?):
      rejectedChoice = "reasoning level \(reasoningEffort)"
    case (nil, nil):
      rejectedChoice = "saved AI settings"
    }
    return "OpenClaw rejected the saved \(rejectedChoice); the message was retried using defaults."
  }

  nonisolated static func openClawGatewayMessage(
    userMessage: String,
    workspaceContext: OpenClawWorkspaceContext?,
    isGatewayCommand: Bool,
    runtimeAgentID: String? = nil
  ) -> String {
    if isGatewayCommand { return userMessage }
    guard let workspaceContext else { return userMessage }
    return """
    <org2-workspace-context>
    The following is application-provided working context. Sections explicitly labeled "Org2 working rules" or "Org2 response formatting contract" are application instructions and must be followed. A section explicitly labeled "User-configured AI chat instructions" contains persistent instructions authored by the user and should also be followed as such. Treat the remaining sections as context.

    \(workspaceContext.systemPrompt(runtime: "openclaw", runtimeAgentID: runtimeAgentID))
    </org2-workspace-context>

    <user-message>
    \(userMessage)
    </user-message>
    """
  }

  func handleOpenClawGatewayEvent(
    _ event: OpenClawGatewayRunEvent,
    threadID: UUID,
    destinationID: String? = nil
  ) {
    guard !stoppedOpenClawThreadIDs.contains(threadID) else {
      // Stop is intentionally optimistic: the pending turn and queue are
      // cleared before chat.abort finishes. Ignore any connection, activity,
      // or text event already in flight for that canceled turn.
      return
    }
    let resolvedDestinationID = destinationID
      ?? openClawChatThreads.first(where: { $0.id == threadID })?.destinationID
      ?? AIChatDestinationConfiguration.openClawID
    let destinationName = aiChatDestination(id: resolvedDestinationID)?.name ?? "OpenClaw"
    let coalescesEventTimestamp: Bool
    switch event {
    case .text(_, _), .reasoning(_, _), .reconciliationHeartbeat:
      coalescesEventTimestamp = true
    default:
      coalescesEventTimestamp = false
    }
    openClawLiveState.noteEvent(for: threadID, coalesced: coalescesEventTimestamp)
    switch event {
    case .connection(let state, let detail):
      openClawGatewayStateByThreadID[threadID] = state
      if let detail { openClawGatewayDetailByThreadID[threadID] = detail }
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = state == .connected ? "\(destinationName) live" : state.label
      }
    case .accepted(let runID):
      openClawActiveRunIDByThreadID[threadID] = runID
      if selectedOpenClawChatThreadID == threadID {
        openClawStatusText = "\(destinationName) is working"
      }
    case .reconciliationHeartbeat:
      break
    case .text(let text, let replace):
      if replace {
        openClawStreamingReplyByThreadID[threadID] = text
      } else {
        openClawLiveState.appendStreamingDelta(text, for: threadID)
      }
      if selectedOpenClawChatThreadID == threadID {
        let nextStatus = "\(destinationName) is replying"
        if openClawStatusText != nextStatus {
          openClawStatusText = nextStatus
        }
      }
    case .reasoning(let text, let replace):
      if replace {
        openClawReasoningByThreadID[threadID] = text
      } else {
        openClawLiveState.appendReasoningDelta(text, for: threadID)
      }
    case .activity(let activity):
      var activities = openClawRunActivitiesByThreadID[threadID] ?? []
      if let index = activities.firstIndex(where: { $0.id == activity.id }) {
        activities[index] = OpenClawActivityFeed.merging(activities[index], with: activity)
      } else {
        activities.append(activity)
      }
      openClawRunActivitiesByThreadID[threadID] = Array(activities.suffix(80))
      if selectedOpenClawChatThreadID == threadID, activity.status == .running {
        openClawStatusText = activity.title
      }
    }
  }

  private func prepareOpenClawRunPresentation(for threadID: UUID) {
    openClawGatewayStateByThreadID[threadID] = .connecting
    openClawGatewayDetailByThreadID.removeValue(forKey: threadID)
    clearOpenClawCompletedRunPresentation(for: threadID)
    openClawLastEventAtByThreadID[threadID] = Date()
  }

  private func clearOpenClawCompletedRunPresentation(for threadID: UUID) {
    openClawActiveRunIDByThreadID.removeValue(forKey: threadID)
    openClawLastEventAtByThreadID.removeValue(forKey: threadID)
    openClawStreamingReplyByThreadID.removeValue(forKey: threadID)
    codexStreamingItemIDByThreadID.removeValue(forKey: threadID)
    openClawReasoningByThreadID.removeValue(forKey: threadID)
    openClawRunActivitiesByThreadID[threadID] = []
  }

  private nonisolated static func expandingOpenClawAgentCommand(_ message: OpenClawChatMessage) -> OpenClawChatMessage {
    guard message.role == .user,
          case .command(let command, _) = OpenClawSlashCommands.parse(message.content),
          command.isAgentAssisted
    else { return message }
    let instruction: String
    switch command.name {
    case "brief":
      instruction = "Create a concise, cited brief of the currently selected Org2 document. Explain its purpose, main ideas, decisions, open tasks, and important links. Cite source file and line ranges."
    default:
      instruction = "Summarize the currently selected Org2 document concisely. Preserve decisions, TODOs, dates, and important links, and cite source file and line ranges."
    }
    return OpenClawChatMessage(
      id: message.id,
      role: message.role,
      content: "\(message.content)\n\n\(instruction)",
      attachments: message.attachments,
      createdAt: message.createdAt,
      changeSummary: message.changeSummary,
      responseTrace: message.responseTrace,
      sendFailure: message.sendFailure,
      deliveryStatus: message.deliveryStatus,
      deliveryKind: message.deliveryKind,
      authorRuntime: message.authorRuntime,
      authorLabel: message.authorLabel,
      authorAgentRef: message.authorAgentRef,
      source: message.source,
      audience: message.audience,
      targetRuntime: message.targetRuntime,
      authorDestinationID: message.authorDestinationID,
      audienceDestinationIDs: message.audienceDestinationIDs,
      targetDestinationID: message.targetDestinationID,
      isRoomDispatchCopy: message.isRoomDispatchCopy,
      roomRoundID: message.roomRoundID
    )
  }

  nonisolated static func sharedRoomRequestMessages(
    _ messages: [OpenClawChatMessage],
    target: AIChatRuntime,
    through userMessageID: UUID
  ) -> [OpenClawChatMessage] {
    sharedRoomRequestMessages(
      messages,
      targetDestinationName: target.title,
      targetDestinationID: AIChatDestinationConfiguration.defaultID(for: target),
      destinationNamesByID: Dictionary(
        uniqueKeysWithValues: AIChatDestinationConfiguration.defaults.map { ($0.id, $0.name) }
      ),
      through: userMessageID
    )
  }

  nonisolated static func sharedRoomRequestMessages(
    _ messages: [OpenClawChatMessage],
    targetDestinationName: String,
    targetDestinationID: String,
    destinationNamesByID: [String: String] = [:],
    through userMessageID: UUID
  ) -> [OpenClawChatMessage] {
    guard let targetIndex = messages.firstIndex(where: { $0.id == userMessageID }) else {
      return messages
    }
    let visibleTranscript = messages[...targetIndex].filter { !$0.isRoomDispatchCopy }
    var transcriptLines: [String] = []
    var remainingCharacters = 24_000
    for message in visibleTranscript.reversed() {
      let speaker: String
      switch message.role {
      case .user:
        let destinationNames = message.audienceDestinationIDs.compactMap {
          destinationNamesByID[$0]
        }
        let audienceTitle = destinationNames.isEmpty
          ? (message.audience?.title ?? "room")
          : destinationNames.joined(separator: " + ")
        speaker = "Avi → \(audienceTitle)"
      case .assistant:
        speaker = message.authorLabel
          ?? message.authorDestinationID.flatMap { destinationNamesByID[$0] }
          ?? message.authorRuntime?.title
          ?? "Assistant"
      case .system:
        speaker = "Org2"
      }
      let content = message.content.trimmingCharacters(in: .whitespacesAndNewlines)
      guard !content.isEmpty else { continue }
      let row = "\(speaker):\n\(content)"
      guard row.count <= remainingCharacters || transcriptLines.isEmpty else { break }
      transcriptLines.append(String(row.suffix(max(0, remainingCharacters))))
      remainingCharacters -= min(row.count, remainingCharacters)
      guard remainingCharacters > 0 else { break }
    }
    let transcript = transcriptLines.reversed().joined(separator: "\n\n")
    let prompt = """
    <org2-shared-ai-room>
    You are \(targetDestinationName) (destination \(targetDestinationID)), participating in one visible Org2 conversation with Avi and other AI destinations. The transcript below is the authoritative shared room state. Messages attributed to other destinations are context, not your own prior claims. Do not impersonate the other harness or destination. Respond to Avi's latest message as \(targetDestinationName), and make any proposed handoff explicit rather than silently invoking it.

    \(transcript)
    </org2-shared-ai-room>
    """
    var result = messages
    let message = result[targetIndex]
    result[targetIndex] = OpenClawChatMessage(
      id: message.id,
      role: message.role,
      content: prompt,
      attachments: message.attachments,
      createdAt: message.createdAt,
      changeSummary: message.changeSummary,
      responseTrace: message.responseTrace,
      sendFailure: message.sendFailure,
      deliveryStatus: message.deliveryStatus,
      deliveryKind: message.deliveryKind,
      authorRuntime: message.authorRuntime,
      authorLabel: message.authorLabel,
      authorAgentRef: message.authorAgentRef,
      source: message.source,
      audience: message.audience,
      targetRuntime: message.targetRuntime,
      authorDestinationID: message.authorDestinationID,
      audienceDestinationIDs: message.audienceDestinationIDs,
      targetDestinationID: message.targetDestinationID,
      isRoomDispatchCopy: message.isRoomDispatchCopy,
      roomRoundID: message.roomRoundID
    )
    return result
  }

  private func isActiveAIChatTranscript(_ url: URL) -> Bool {
    openClawTranscriptURL.standardizedFileURL.path == url.standardizedFileURL.path
  }

  private func isActiveAIChatSendOrigin(_ origin: AIChatSendOrigin) -> Bool {
    isActiveAIChatTranscript(origin.transcriptURL)
      && corpusRoot?.standardizedFileURL.path == origin.corpusRoot?.standardizedFileURL.path
  }

  private func openClawChatThread(
    _ threadID: UUID,
    transcriptURL: URL
  ) -> OpenClawChatThread? {
    if isActiveAIChatTranscript(transcriptURL) {
      return openClawChatThreads.first(where: { $0.id == threadID })
    }
    return Self.loadOpenClawTranscript(
      from: transcriptURL,
      marksInterruptedSends: false
    ).threads.first(where: { $0.id == threadID })
  }

  private func replaceOpenClawChatThread(
    _ thread: OpenClawChatThread,
    transcriptURL: URL,
    shouldPersist: Bool = true
  ) {
    if isActiveAIChatTranscript(transcriptURL) {
      guard let index = openClawChatThreads.firstIndex(where: { $0.id == thread.id }) else { return }
      openClawChatThreads[index] = thread
      if selectedOpenClawChatThreadID == thread.id {
        replaceOpenClawMessages(thread.messages, shouldPersist: false)
      }
      sortOpenClawChatThreadsForDisplay()
      if shouldPersist {
        persistOpenClawTranscript()
      }
      return
    }

    guard shouldPersist else { return }
    let transcript = Self.loadOpenClawTranscript(
      from: transcriptURL,
      marksInterruptedSends: false
    )
    guard let index = transcript.threads.firstIndex(where: { $0.id == thread.id }) else { return }
    var threads = transcript.threads
    threads[index] = thread
    do {
      try Self.saveOpenClawTranscript(
        OpenClawTranscriptState(
          threads: Self.sortedOpenClawChatThreadsForDisplay(threads),
          selectedThreadID: transcript.selectedThreadID,
          settlementSettings: transcript.settlementSettings
        ),
        to: transcriptURL
      )
    } catch {
      errorText = "AI chat transcript save failed: \(error.localizedDescription)"
    }
  }

  private func openClawMessagesThrough(
    _ messageID: UUID,
    in threadID: UUID,
    transcriptURL: URL? = nil
  ) -> [OpenClawChatMessage]? {
    let messages = transcriptURL.map {
      openClawMessages(for: threadID, transcriptURL: $0)
    } ?? openClawMessages(for: threadID)
    guard let index = messages.firstIndex(where: { $0.id == messageID }) else {
      return nil
    }
    return Array(messages[...index])
  }

  private func insertOpenClawReply(
    _ reply: String,
    after userMessageID: UUID,
    in threadID: UUID,
    transcriptURL: URL? = nil,
    changeSummary: OpenClawCorpusChangeSummary?,
    authorRuntime: AIChatRuntime? = nil,
    authorDestinationID: String? = nil
  ) -> UUID {
    let targetTranscriptURL = transcriptURL ?? openClawTranscriptURL
    var messages = openClawMessages(for: threadID, transcriptURL: targetTranscriptURL)
    let roomRoundID = messages.first(where: { $0.id == userMessageID })?.roomRoundID
    let trace = OpenClawResponseTrace(
      reasoning: openClawReasoningByThreadID[threadID] ?? "",
      activities: openClawRunActivitiesByThreadID[threadID] ?? []
    )
    let assistantMessage = OpenClawChatMessage(
      role: .assistant,
      content: reply,
      changeSummary: changeSummary,
      responseTrace: trace.isEmpty ? nil : trace,
      authorRuntime: authorRuntime,
      authorDestinationID: authorDestinationID,
      roomRoundID: roomRoundID
    )
    guard let index = messages.firstIndex(where: { $0.id == userMessageID }) else {
      messages.append(assistantMessage)
      updateOpenClawChatThread(
        threadID,
        messages: messages,
        notifiesForNewAssistantMessages: true,
        transcriptURL: targetTranscriptURL,
        shouldPersist: true,
        pendingTurnUpdate: .replace(nil)
      )
      return assistantMessage.id
    }
    messages[index] = messages[index].replacingDeliveryStatus(.sent, sendFailure: nil)
    var insertionIndex = messages.index(after: index)
    while insertionIndex < messages.endIndex,
          messages[insertionIndex].role == .user,
          messages[insertionIndex].deliveryKind == .steer {
      insertionIndex = messages.index(after: insertionIndex)
    }
    messages.insert(assistantMessage, at: insertionIndex)
    updateOpenClawChatThread(
      threadID,
      messages: messages,
      notifiesForNewAssistantMessages: true,
      transcriptURL: targetTranscriptURL,
      shouldPersist: true,
      pendingTurnUpdate: .replace(nil)
    )
    return assistantMessage.id
  }

  private func insertSharedRoomFailure(
    _ failure: String,
    destinationID: String,
    runtime: AIChatRuntime,
    after userMessageID: UUID,
    in threadID: UUID,
    transcriptURL: URL
  ) {
    var messages = openClawMessages(for: threadID, transcriptURL: transcriptURL)
    let roomRoundID = messages.first(where: { $0.id == userMessageID })?.roomRoundID
    let failureMessage = OpenClawChatMessage(
      role: .system,
      content: "\(aiChatDestinationTitle(destinationID)) could not respond: \(failure)",
      authorRuntime: runtime,
      authorDestinationID: destinationID,
      roomRoundID: roomRoundID
    )
    guard let index = messages.firstIndex(where: { $0.id == userMessageID }) else {
      messages.append(failureMessage)
      updateOpenClawChatThread(
        threadID,
        messages: messages,
        transcriptURL: transcriptURL,
        shouldPersist: true
      )
      return
    }
    messages.insert(failureMessage, at: messages.index(after: index))
    updateOpenClawChatThread(
      threadID,
      messages: messages,
      transcriptURL: transcriptURL,
      shouldPersist: true
    )
  }

  private func replaceOpenClawChangeSummary(
    _ changeSummary: OpenClawCorpusChangeSummary,
    for messageID: UUID,
    in threadID: UUID,
    transcriptURL: URL? = nil
  ) {
    let targetTranscriptURL = transcriptURL ?? openClawTranscriptURL
    var messages = openClawMessages(for: threadID, transcriptURL: targetTranscriptURL)
    guard let index = messages.firstIndex(where: { $0.id == messageID }) else { return }
    messages[index] = messages[index].replacingChangeSummary(changeSummary)
    updateOpenClawChatThread(
      threadID,
      messages: messages,
      transcriptURL: targetTranscriptURL,
      shouldPersist: true
    )
  }

  public func retryOpenClawMessage(_ messageID: UUID) async {
    guard let threadID = openClawThreadID(containing: messageID),
          let message = openClawMessages(for: threadID).first(where: { $0.id == messageID }),
          message.role == .user,
          message.sendFailure != nil
    else {
      return
    }
    guard !openClawPendingUserMessageIDs(for: threadID).contains(messageID) else { return }
    // A user-initiated retry is a new attempt. Stop guards intentionally ignore
    // late events from the canceled attempt, but must not suppress the retry's
    // gateway events or turn its errors back into another stopped result.
    stoppedOpenClawThreadIDs.remove(threadID)
    clearOpenClawSendFailure(for: messageID, in: threadID)
    replaceOpenClawDeliveryStatus(for: messageID, in: threadID, with: .sending)
    if message.deliveryKind == .steer,
       isAIChatThreadRunning(threadID),
       canSteerAIChatThread(threadID),
       let retryMessage = openClawMessages(for: threadID).first(where: { $0.id == messageID }) {
      await deliverAIChatSteer(retryMessage, in: threadID)
      return
    }
    enqueueOpenClawUserMessage(messageID, in: threadID)
    if drainingOpenClawThreadIDs.contains(threadID) {
      openClawStatusText = openClawQueuedStatusText()
      return
    }
    await drainOpenClawSendQueue(for: threadID)
  }

  public func isAIChatMessageQueued(_ messageID: UUID) -> Bool {
    let threadID: UUID?
    if let selectedOpenClawChatThreadID,
       openClawPendingUserMessageIDs(for: selectedOpenClawChatThreadID).contains(messageID) {
      threadID = selectedOpenClawChatThreadID
    } else {
      threadID = openClawPendingUserMessageIDsByThreadID.first(where: {
        $0.value.contains(messageID)
      })?.key
    }
    guard let threadID else { return false }
    return !isActiveAIChatMessage(messageID, in: threadID)
  }

  public func canSteerQueuedAIChatMessage(_ messageID: UUID) -> Bool {
    guard let threadID = openClawThreadID(containing: messageID),
          isAIChatMessageQueued(messageID),
          isAIChatThreadRunning(threadID)
    else { return false }
    return canSteerAIChatThread(threadID)
  }

  public func steerQueuedAIChatMessage(_ messageID: UUID) async {
    guard let threadID = openClawThreadID(containing: messageID),
          canSteerQueuedAIChatMessage(messageID),
          var pendingIDs = openClawPendingUserMessageIDsByThreadID[threadID],
          let pendingIndex = pendingIDs.firstIndex(of: messageID)
    else { return }

    var messages = openClawMessages(for: threadID)
    guard let messageIndex = messages.firstIndex(where: { $0.id == messageID }) else {
      return
    }
    let message = messages[messageIndex]
    pendingIDs.remove(at: pendingIndex)
    if pendingIDs.isEmpty {
      openClawPendingUserMessageIDsByThreadID.removeValue(forKey: threadID)
    } else {
      openClawPendingUserMessageIDsByThreadID[threadID] = pendingIDs
    }
    messages[messageIndex] = OpenClawChatMessage(
      id: message.id,
      role: message.role,
      content: message.content,
      attachments: message.attachments,
      createdAt: message.createdAt,
      changeSummary: message.changeSummary,
      responseTrace: message.responseTrace,
      deliveryStatus: .sending,
      deliveryKind: .steer,
      audience: message.audience,
      targetRuntime: message.targetRuntime,
      audienceDestinationIDs: message.audienceDestinationIDs,
      targetDestinationID: message.targetDestinationID,
      isRoomDispatchCopy: message.isRoomDispatchCopy,
      roomRoundID: message.roomRoundID
    )
    replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
    syncSelectedOpenClawSendState()
    if selectedOpenClawChatThreadID == threadID {
      let destinationID = openClawChatThreads.first(where: { $0.id == threadID })?.destinationID
        ?? AIChatDestinationConfiguration.openClawID
      openClawStatusText = "Steering \(aiChatDestinationTitle(destinationID))…"
    }
    await deliverAIChatSteer(messages[messageIndex], in: threadID)
  }

  public func deleteQueuedAIChatMessage(_ messageID: UUID) {
    guard dequeueAIChatMessage(messageID) != nil else { return }
    openClawStatusText = "Removed queued message"
  }

  public func editQueuedAIChatMessage(_ messageID: UUID) {
    guard let threadID = openClawThreadID(containing: messageID),
          selectedOpenClawChatThreadID == threadID,
          let message = dequeueAIChatMessage(messageID)
    else { return }

    let existingDraft = openClawDraft(for: threadID)
    let restoredDraft = Self.openClawDraftByAppendingDictation(
      existing: message.content,
      dictatedText: existingDraft
    )
    cacheOpenClawDraft(restoredDraft, for: threadID)
    openClawDraft = restoredDraft
    for attachment in message.attachments where !openClawPendingAttachments.contains(where: {
      $0.id == attachment.id
    }) {
      openClawPendingAttachments.append(attachment)
    }
    openClawStatusText = "Queued message moved back to the composer"
  }

  @discardableResult
  private func dequeueAIChatMessage(_ messageID: UUID) -> OpenClawChatMessage? {
    guard let threadID = openClawThreadID(containing: messageID),
          !isActiveAIChatMessage(messageID, in: threadID),
          var pendingIDs = openClawPendingUserMessageIDsByThreadID[threadID],
          let pendingIndex = pendingIDs.firstIndex(of: messageID)
    else { return nil }

    var messages = openClawMessages(for: threadID)
    guard let messageIndex = messages.firstIndex(where: { $0.id == messageID }) else {
      return nil
    }
    let message = messages.remove(at: messageIndex)
    pendingIDs.remove(at: pendingIndex)
    if pendingIDs.isEmpty {
      openClawPendingUserMessageIDsByThreadID.removeValue(forKey: threadID)
    } else {
      openClawPendingUserMessageIDsByThreadID[threadID] = pendingIDs
    }
    replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
    syncSelectedOpenClawSendState()
    return message
  }

  private func isActiveAIChatMessage(_ messageID: UUID, in threadID: UUID) -> Bool {
    if activeOpenClawUserMessageIDByThreadID[threadID] == messageID {
      return true
    }
    return openClawChatThreads.first(where: { $0.id == threadID })?
      .pendingTurn?.userMessageID == messageID
  }

  private func clearOpenClawSendFailure(
    for messageID: UUID,
    in threadID: UUID,
    transcriptURL: URL? = nil
  ) {
    replaceOpenClawSendFailure(
      for: messageID,
      in: threadID,
      transcriptURL: transcriptURL,
      with: nil
    )
  }

  private func markPendingOpenClawMessagesFailed(
    _ failureText: String,
    in threadID: UUID,
    transcriptURL: URL? = nil
  ) {
    for messageID in openClawPendingUserMessageIDs(for: threadID) {
      replaceOpenClawSendFailure(
        for: messageID,
        in: threadID,
        transcriptURL: transcriptURL,
        with: failureText
      )
    }
  }

  private func markOpenClawRunStopped(
    in threadID: UUID,
    transcriptURL: URL? = nil,
    statusText: String = "OpenClaw stopped"
  ) {
    cancelOpenClawPendingTurnRecovery(for: threadID)
    let targetTranscriptURL = transcriptURL ?? openClawTranscriptURL
    stoppedOpenClawThreadIDs.insert(threadID)
    let pendingTurn = openClawChatThread(
      threadID,
      transcriptURL: targetTranscriptURL
    )?.pendingTurn
    var stoppedMessageIDs = Set(openClawPendingUserMessageIDs(for: threadID))
    if let activeMessageID = activeOpenClawUserMessageIDByThreadID[threadID] {
      stoppedMessageIDs.insert(activeMessageID)
    }
    if let pendingUserMessageID = pendingTurn?.userMessageID {
      stoppedMessageIDs.insert(pendingUserMessageID)
    }

    var messages = openClawMessages(for: threadID, transcriptURL: targetTranscriptURL)
    var changedMessages = false
    let stoppedSendFailureText = aiChatStoppedSendFailureText(for: threadID)
    for index in messages.indices where stoppedMessageIDs.contains(messages[index].id) {
      let message = messages[index]
      guard message.role == .user,
            message.deliveryStatus == .sending
              || message.sendFailure != stoppedSendFailureText
      else {
        continue
      }
      messages[index] = message.replacingDeliveryStatus(
        .interrupted,
        sendFailure: stoppedSendFailureText
      )
      changedMessages = true
    }
    if changedMessages {
      updateOpenClawChatThread(
        threadID,
        messages: messages,
        transcriptURL: targetTranscriptURL,
        shouldPersist: true
      )
    }
    if let pendingTurn {
      clearOpenClawPendingTurn(
        pendingTurn.runID,
        in: threadID,
        transcriptURL: targetTranscriptURL,
        shouldPersist: true
      )
    }

    removeAllPendingOpenClawUserMessages(in: threadID)
    activeOpenClawUserMessageIDByThreadID.removeValue(forKey: threadID)
    openClawRequestStartedAtByThreadID.removeValue(forKey: threadID)
    clearOpenClawCompletedRunPresentation(for: threadID)
    openClawGatewayStateByThreadID[threadID] = .disconnected
    openClawGatewayDetailByThreadID[threadID] =
      "Stopped by you. This turn will not reconnect."
    if selectedOpenClawChatThreadID == threadID,
       isActiveAIChatTranscript(targetTranscriptURL) {
      openClawStatusText = statusText
    }
    syncSelectedOpenClawSendState()
  }

  private func aiChatStoppedSendFailureText(for threadID: UUID) -> String {
    guard let thread = openClawChatThreads.first(where: { $0.id == threadID }) else {
      return "The AI request was stopped by you. Retry to start this request again."
    }
    let destinationID = activeSharedRoomDestinationByThreadID[threadID]
      ?? thread.destinationID
    return "\(aiChatDestinationTitle(destinationID)) was stopped by you. Retry to start this request again."
  }

  private func replaceOpenClawSendFailure(
    for messageID: UUID,
    in threadID: UUID,
    transcriptURL: URL? = nil,
    with failureText: String?
  ) {
    let targetTranscriptURL = transcriptURL ?? openClawTranscriptURL
    var messages = openClawMessages(for: threadID, transcriptURL: targetTranscriptURL)
    guard let index = messages.firstIndex(where: { $0.id == messageID }) else { return }
    let message = messages[index]
    let nextStatus: OpenClawChatMessage.DeliveryStatus
    if failureText == nil, message.deliveryStatus == .sending {
      nextStatus = .sending
    } else {
      nextStatus = failureText == nil ? .sent : .failed
    }
    guard message.sendFailure != failureText || message.deliveryStatus != nextStatus else { return }
    messages[index] = message.replacingSendFailure(failureText)
    updateOpenClawChatThread(
      threadID,
      messages: messages,
      transcriptURL: targetTranscriptURL,
      shouldPersist: true
    )
  }

  private func replaceOpenClawDeliveryStatus(
    for messageID: UUID,
    in threadID: UUID,
    with deliveryStatus: OpenClawChatMessage.DeliveryStatus
  ) {
    var messages = openClawMessages(for: threadID)
    guard let index = messages.firstIndex(where: { $0.id == messageID }) else { return }
    let message = messages[index]
    guard message.deliveryStatus != deliveryStatus || message.sendFailure != nil else { return }
    messages[index] = message.replacingDeliveryStatus(deliveryStatus)
    replaceOpenClawMessages(messages, for: threadID, shouldPersist: true)
  }

  private func openClawMessages(for threadID: UUID) -> [OpenClawChatMessage] {
    if selectedOpenClawChatThreadID == threadID {
      return openClawMessages
    }
    return openClawChatThreads.first(where: { $0.id == threadID })?.messages ?? []
  }

  private func openClawMessages(
    for threadID: UUID,
    transcriptURL: URL
  ) -> [OpenClawChatMessage] {
    if isActiveAIChatTranscript(transcriptURL) {
      return openClawMessages(for: threadID)
    }
    return openClawChatThread(threadID, transcriptURL: transcriptURL)?.messages ?? []
  }

  private func replaceOpenClawMessages(
    _ messages: [OpenClawChatMessage],
    for threadID: UUID,
    shouldPersist: Bool,
    notifiesForNewAssistantMessages: Bool = false
  ) {
    if selectedOpenClawChatThreadID == threadID {
      replaceOpenClawMessages(messages, shouldPersist: false)
    }
    updateOpenClawChatThread(
      threadID,
      messages: messages,
      notifiesForNewAssistantMessages: notifiesForNewAssistantMessages
    )
    if shouldPersist {
      persistOpenClawTranscript()
    }
  }

  private func replaceOpenClawPendingTurn(
    _ pendingTurn: OpenClawPendingTurn?,
    in threadID: UUID,
    transcriptURL: URL? = nil,
    shouldPersist: Bool
  ) {
    let targetTranscriptURL = transcriptURL ?? openClawTranscriptURL
    guard let thread = openClawChatThread(
      threadID,
      transcriptURL: targetTranscriptURL
    ) else { return }
    updateOpenClawChatThread(
      threadID,
      messages: thread.messages,
      transcriptURL: targetTranscriptURL,
      shouldPersist: shouldPersist,
      pendingTurnUpdate: .replace(pendingTurn)
    )
  }

  private func clearOpenClawPendingTurn(
    _ runID: String,
    in threadID: UUID,
    transcriptURL: URL? = nil,
    shouldPersist: Bool
  ) {
    let targetTranscriptURL = transcriptURL ?? openClawTranscriptURL
    guard let pendingTurn = openClawChatThread(
      threadID,
      transcriptURL: targetTranscriptURL
    )?.pendingTurn,
          pendingTurn.runID == runID
    else {
      return
    }
    replaceOpenClawPendingTurn(
      nil,
      in: threadID,
      transcriptURL: targetTranscriptURL,
      shouldPersist: shouldPersist
    )
  }

  private func openClawSessionKey(for threadID: UUID) -> String? {
    guard let index = openClawChatThreads.firstIndex(where: { $0.id == threadID }) else { return nil }
    let thread = openClawChatThreads[index]
    guard thread.runtime == .openClaw else { return thread.sessionKey }
    let sessionKey = Self.agentScopedOpenClawSessionKey(thread.sessionKey, agentID: openClawAgentID)
    if sessionKey != thread.sessionKey {
      openClawChatThreads[index] = thread.replacingOpenClawChatMetadata(sessionKey: sessionKey)
      if selectedOpenClawChatThreadID == threadID {
        openClawSessionKey = sessionKey
      }
      persistOpenClawTranscript()
    }
    return sessionKey
  }

  private func openClawThreadID(containing messageID: UUID) -> UUID? {
    if let selectedOpenClawChatThreadID,
       openClawMessages.contains(where: { $0.id == messageID }) {
      return selectedOpenClawChatThreadID
    }
    return openClawChatThreads.first { thread in
      thread.messages.contains(where: { $0.id == messageID })
    }?.id
  }

  private func openClawPendingUserMessageIDs(for threadID: UUID) -> [UUID] {
    openClawPendingUserMessageIDsByThreadID[threadID] ?? []
  }

  private func enqueueOpenClawUserMessage(_ messageID: UUID, in threadID: UUID) {
    openClawPendingUserMessageIDsByThreadID[threadID, default: []].append(messageID)
    syncSelectedOpenClawSendState()
  }

  private func removeFirstPendingOpenClawUserMessage(in threadID: UUID) {
    guard var pending = openClawPendingUserMessageIDsByThreadID[threadID], !pending.isEmpty else {
      syncSelectedOpenClawSendState()
      return
    }
    pending.removeFirst()
    if pending.isEmpty {
      openClawPendingUserMessageIDsByThreadID.removeValue(forKey: threadID)
    } else {
      openClawPendingUserMessageIDsByThreadID[threadID] = pending
    }
    syncSelectedOpenClawSendState()
  }

  private func removeAllPendingOpenClawUserMessages(in threadID: UUID) {
    openClawPendingUserMessageIDsByThreadID.removeValue(forKey: threadID)
    syncSelectedOpenClawSendState()
  }

  private func removeAllPendingOpenClawUserMessages() {
    openClawPendingUserMessageIDsByThreadID.removeAll()
    syncSelectedOpenClawSendState()
  }

  private func syncSelectedOpenClawSendState() {
    openClawSendingThreadIDs = Set(drainingOpenClawThreadIDs.filter {
      !openClawPendingUserMessageIDs(for: $0).isEmpty
    })
    guard let selectedOpenClawChatThreadID else {
      isSendingOpenClawMessage = false
      openClawQueuedMessageCount = 0
      openClawRequestStartedAt = nil
      return
    }
    isSendingOpenClawMessage = openClawSendingThreadIDs.contains(selectedOpenClawChatThreadID)
    openClawQueuedMessageCount = openClawPendingUserMessageIDs(for: selectedOpenClawChatThreadID).count
    openClawRequestStartedAt = openClawRequestStartedAtByThreadID[selectedOpenClawChatThreadID]
  }

  nonisolated private static func openClawSendFailureText(from error: Error) -> String {
    let message = error.localizedDescription.trimmingCharacters(in: .whitespacesAndNewlines)
    return message.isEmpty ? "AI chat message failed to send." : message
  }

  private func beginCorpusChangeObservation(
    corpusRoot requestedCorpusRoot: URL? = nil
  ) async -> CorpusChangeObservation {
    let serial = corpusFileEventSerial
    guard let corpusRoot = requestedCorpusRoot ?? corpusRoot else {
      return CorpusChangeObservation(
        eventSerial: serial,
        snapshot: OpenClawCorpusSnapshot(rootPath: "", files: [:])
      )
    }
    let root = corpusRoot.standardizedFileURL
    let files = corpusFiles
    let snapshot = await Task.detached(priority: .utility) {
      if let index = Self.freshWorkspaceSearchIndex(files: files, corpusRoot: root) {
        return OpenClawCorpusSnapshot(
          rootPath: root.path,
          files: Dictionary(uniqueKeysWithValues: index.files.map {
            ($0.relativePath, OpenClawSnapshotFile(text: $0.lines.joined(separator: "\n")))
          })
        )
      }
      return (try? Self.openClawCorpusSnapshot(corpusRoot: root))
        ?? OpenClawCorpusSnapshot(rootPath: root.path, files: [:])
    }.value
    return CorpusChangeObservation(eventSerial: serial, snapshot: snapshot)
  }

  private func openClawChangeSummary(
    since observation: CorpusChangeObservation,
    referencedIn reply: String,
    corpusRoot requestedCorpusRoot: URL? = nil
  ) async -> OpenClawCorpusChangeSummary? {
    guard let corpusRoot = requestedCorpusRoot ?? corpusRoot else { return nil }
    let root = corpusRoot.standardizedFileURL
    let referencedPaths = openClawReferencedChangeRelativePaths(
      in: reply,
      corpusRoot: root
    )
    if self.corpusRoot?.standardizedFileURL.path != root.path {
      let afterSnapshot = await Task.detached(priority: .utility) {
        try? Self.openClawCorpusSnapshot(corpusRoot: root)
      }.value
      guard let afterSnapshot else { return nil }
      return Self.openClawChangeSummary(
        before: observation.snapshot,
        after: afterSnapshot
      ).map {
        attributedOpenClawChangeSummary($0, referencedPaths: referencedPaths)
      }
    }
    for delay in Self.openClawChangeSnapshotRetryDelays {
      // FSEvents can deliver several writes from one agent turn in adjacent
      // batches. Give the first batch one coalescing window so the summary and
      // incremental refresh see the whole edit set, not whichever path arrived
      // first.
      try? await Task.sleep(nanoseconds: delay > 0 ? delay : 150_000_000)
      var changedPaths = Set(recentCorpusFileEvents.lazy
        .filter { $0.serial > observation.eventSerial }
        .map(\.path))
      for relativePath in referencedPaths {
        let path = root.appendingPathComponent(relativePath).standardizedFileURL.path
        if (observation.snapshot.files[relativePath] != nil) != FileManager.default.fileExists(atPath: path) {
          changedPaths.insert(path)
        }
      }
      guard !changedPaths.isEmpty else { continue }
      let relativeChangedPaths = Set(changedPaths.compactMap { path -> String? in
        let prefix = root.path + "/"
        return path.hasPrefix(prefix) ? String(path.dropFirst(prefix.count)) : nil
      })
      let afterSnapshot = await Task.detached(priority: .utility) {
        try? Self.openClawCorpusSnapshot(corpusRoot: root, relativePaths: relativeChangedPaths)
      }.value
      guard let afterSnapshot else { continue }
      let beforeSnapshot = observation.snapshot.filtered(to: relativeChangedPaths)
      if let summary = Self.openClawChangeSummary(before: beforeSnapshot, after: afterSnapshot) {
        return attributedOpenClawChangeSummary(summary, referencedPaths: referencedPaths)
      }
    }
    return nil
  }

  private func recordCorpusFileEvents(_ paths: [String]) {
    guard let corpusRoot else { return }
    let rootPrefix = corpusRoot.standardizedFileURL.path + "/"
    for rawPath in paths {
      let path = URL(fileURLWithPath: rawPath).standardizedFileURL.path
      guard path.hasPrefix(rootPrefix) else { continue }
      corpusFileEventSerial += 1
      recentCorpusFileEvents.append((corpusFileEventSerial, path))
    }
    if recentCorpusFileEvents.count > 4_096 {
      recentCorpusFileEvents.removeFirst(recentCorpusFileEvents.count - 2_048)
    }
  }

  nonisolated static func classifyCorpusFileEvents(
    _ paths: [String],
    corpusRoot: URL
  ) -> CorpusFileEventClassification {
    let root = corpusRoot.standardizedFileURL.path
    let rootPrefix = root + "/"
    let contentExtensions = Set(["org", "org2", "md", "csv"])
    var contentPaths: [String] = []
    var seenContentPaths = Set<String>()
    var hasAgentRunStateChanges = false
    var hasConfigurationChanges = false
    var hasAIChatInboxChanges = false

    for rawPath in paths {
      let path = URL(fileURLWithPath: rawPath).standardizedFileURL.path
      guard path.hasPrefix(rootPrefix) else { continue }
      let relativePath = String(path.dropFirst(rootPrefix.count))
      if relativePath == "org2.json" || relativePath == ".org2/app.css" {
        hasConfigurationChanges = true
        continue
      }
      if relativePath.hasPrefix(".org2/runs/"),
         URL(fileURLWithPath: path).pathExtension.lowercased() == "org2" {
        hasAgentRunStateChanges = true
        continue
      }
      if relativePath.hasPrefix(".org2/ai-chat-inbox/") {
        hasAIChatInboxChanges = true
        continue
      }
      guard contentExtensions.contains(URL(fileURLWithPath: path).pathExtension.lowercased()),
            !isDefaultIgnoredSyncArtifactPath(path),
            seenContentPaths.insert(path).inserted
      else {
        continue
      }
      contentPaths.append(path)
    }

    return CorpusFileEventClassification(
      contentPaths: contentPaths,
      hasAgentRunStateChanges: hasAgentRunStateChanges,
      hasConfigurationChanges: hasConfigurationChanges,
      hasAIChatInboxChanges: hasAIChatInboxChanges
    )
  }

  private func attributedOpenClawChangeSummary(
    _ summary: OpenClawCorpusChangeSummary,
    referencedIn reply: String
  ) -> OpenClawCorpusChangeSummary {
    attributedOpenClawChangeSummary(
      summary,
      referencedPaths: openClawReferencedChangeRelativePaths(in: reply)
    )
  }

  private func attributedOpenClawChangeSummary(
    _ summary: OpenClawCorpusChangeSummary,
    referencedPaths: Set<String>
  ) -> OpenClawCorpusChangeSummary {
    guard !referencedPaths.isEmpty else { return summary }
    let filteredFiles = summary.files.filter { referencedPaths.contains($0.relativePath) }
    return filteredFiles.isEmpty ? summary : OpenClawCorpusChangeSummary(files: filteredFiles)
  }

  private func openClawReferencedChangeRelativePaths(
    in reply: String,
    corpusRoot requestedCorpusRoot: URL? = nil
  ) -> Set<String> {
    guard let corpusRoot = requestedCorpusRoot ?? corpusRoot else { return [] }
    let rootPath = Self.trimTrailingSlashes(corpusRoot.standardizedFileURL.path)
    var paths = Set<String>()

    for reference in OpenClawFileReference.extract(from: reply, limit: 24) {
      if let relativePath = openClawRelativePathForReference(reference.path, corpusRootPath: rootPath) {
        paths.insert(relativePath)
      }
    }

    return paths
  }

  private func openClawRelativePathForReference(_ rawPath: String, corpusRootPath rootPath: String) -> String? {
    let path = rawPath.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !path.isEmpty else { return nil }

    var candidates: [String] = []
    if let localPath = localPathForOpenClawReference(path) {
      candidates.append(localPath)
    }

    if let remoteRoot = effectiveOpenClawRemoteCorpusPath().map(Self.trimTrailingSlashes) {
      let normalizedPath = Self.trimTrailingSlashes(path)
      if normalizedPath == remoteRoot {
        candidates.append(rootPath)
      } else if normalizedPath.hasPrefix(remoteRoot + "/") {
        candidates.append(rootPath + "/" + String(normalizedPath.dropFirst(remoteRoot.count + 1)))
      }
    }

    if path.hasPrefix("~/") {
      candidates.append(NSHomeDirectory() + "/" + String(path.dropFirst(2)))
    } else if NSString(string: path).isAbsolutePath {
      candidates.append(path)
    } else {
      candidates.append(rootPath + "/" + path)
    }

    for candidate in candidates {
      let normalized = Self.trimTrailingSlashes(URL(fileURLWithPath: candidate).standardizedFileURL.path)
      if normalized == rootPath {
        return ""
      }
      if normalized.hasPrefix(rootPath + "/") {
        return String(normalized.dropFirst(rootPath.count + 1))
      }
    }
    return nil
  }

  private func refreshAfterOpenClawChanges(_ summary: OpenClawCorpusChangeSummary) async {
    guard let corpusRoot else { return }
    let root = corpusRoot.standardizedFileURL
    let changedFiles = summary.files.map { root.appendingPathComponent($0.relativePath).standardizedFileURL.path }
    let generatedBriefTitle = pendingNodeBriefTitle
    let generatedBriefRelativePath = pendingNodeBriefArtifactRelativePath.flatMap { pending in
      summary.files.contains(where: { $0.relativePath == pending }) ? pending : nil
    }
    for file in changedFiles {
      invalidateCanonicalDocumentCache(for: file)
    }

    if let selectedEntrySource,
       changedFiles.contains(URL(fileURLWithPath: selectedEntrySource.file).standardizedFileURL.path),
       let selectedLocation {
      await loadEntrySource(for: selectedLocation)
    }

    scheduleIncrementalCorpusRefresh(changedFiles)

    if let generatedBriefRelativePath {
      let artifactURL = root.appendingPathComponent(generatedBriefRelativePath).standardizedFileURL
      openNodeBriefArtifact(
        url: artifactURL,
        relativePath: generatedBriefRelativePath,
        title: generatedBriefTitle ?? artifactURL.deletingPathExtension().lastPathComponent
      )
    }
  }

  public func setWorkspaceRealtimeRefreshActive(_ isActive: Bool) {
    guard isWorkspaceRealtimeRefreshActive != isActive else { return }
    isWorkspaceRealtimeRefreshActive = isActive
    if isActive {
      workspaceActivationRefreshTask?.cancel()
      workspaceActivationRefreshTask = Task { @MainActor [weak self] in
        try? await Task.sleep(nanoseconds: Self.applicationActivationRefreshDelayNanoseconds)
        guard !Task.isCancelled,
              let self,
              self.isWorkspaceRealtimeRefreshActive
        else { return }
        self.workspaceDidBecomeActive()
        self.workspaceActivationRefreshTask = nil
      }
    } else {
      workspaceActivationRefreshTask?.cancel()
      workspaceActivationRefreshTask = nil
      sourceAutoSyncActivationTask?.cancel()
      sourceAutoSyncActivationTask = nil
      mountedCorpusEventRefreshTask?.cancel()
      mountedCorpusEventRefreshTask = nil
      workspaceSurfaceRefreshTasks.values.forEach { $0.cancel() }
      workspaceSurfaceRefreshTasks = [:]
    }
  }

  public func workspaceDidBecomeActive() {
    guard isWorkspaceRealtimeRefreshActive else { return }
    rebuildCorpusFileWatchers()
    scheduleAgendaClockInvalidation()

    if needsFullCorpusRefreshAfterEvents {
      scheduleFullCorpusFileRefreshAfterEvents()
      return
    }
    if !pendingCorpusChangedPaths.isEmpty {
      scheduleIncrementalCorpusRefresh([])
      return
    }

    if let selectedLocation,
       let knownFile = corpusFiles.first(where: {
         $0.path == URL(fileURLWithPath: selectedLocation.file).standardizedFileURL.path
       }),
       knownFile.modifiedAt != Self.modificationDate(
         for: URL(fileURLWithPath: selectedLocation.file).standardizedFileURL
       ) {
      scheduleIncrementalCorpusRefresh([selectedLocation.file])
      return
    }

    // The filesystem event may have arrived while the app was inactive, and
    // sync software may preserve the original modification time. Verify the
    // visible file by content whenever the workspace becomes active.
    if let selectedLocation {
      scheduleSelectedDetailFreshnessCheck(
        for: selectedLocation,
        mode: selectedEntrySourceMode
      )
    }

    // Activation itself is not a data change. File events, the selected-file
    // freshness check above, source sync, and run-review polling invalidate the
    // relevant surfaces. Unconditionally invalidating the visible surface here
    // made every Cmd-Tab launch a potentially corpus-wide refresh.
  }

  public func isWorkspaceSurfaceDirty(_ surface: WorkspaceSurface) -> Bool {
    dirtyWorkspaceSurfaces.contains(surface)
  }

  private func markWorkspaceSurfacesDirty(
    _ surfaces: Set<WorkspaceSurface>,
    refreshVisible: Bool
  ) {
    let invalidatedSurfaces = surfaces.filter { $0 != .home }
    dirtyWorkspaceSurfaces.formUnion(invalidatedSurfaces)
    for surface in invalidatedSurfaces {
      workspaceSurfaceDirtyGenerations[surface, default: 0] &+= 1
    }
    guard refreshVisible,
          isWorkspaceRealtimeRefreshActive,
          dirtyWorkspaceSurfaces.contains(selectedSurface)
    else {
      return
    }
    scheduleRefreshForActivatedSurface(selectedSurface)
  }

  private func markWorkspaceSurfaceCleanIfUnchanged(
    _ surface: WorkspaceSurface,
    generation: UInt64
  ) {
    guard workspaceSurfaceDirtyGenerations[surface, default: 0] == generation else { return }
    dirtyWorkspaceSurfaces.remove(surface)
  }

  private func scheduleRefreshForActivatedSurface(
    _ surface: WorkspaceSurface,
    delayNanoseconds: UInt64 = 0
  ) {
    guard isWorkspaceRealtimeRefreshActive,
          dirtyWorkspaceSurfaces.contains(surface),
          workspaceSurfaceRefreshTasks[surface] == nil
    else {
      return
    }

    workspaceSurfaceRefreshTasks[surface] = Task { @MainActor [weak self] in
      if delayNanoseconds > 0 {
        try? await Task.sleep(nanoseconds: delayNanoseconds)
      } else {
        await Task.yield()
      }
      guard !Task.isCancelled, let self else { return }
      await self.refreshWorkspaceSurfaceIfDirty(surface)
      self.workspaceSurfaceRefreshTasks[surface] = nil
      if self.isWorkspaceRealtimeRefreshActive,
         self.selectedSurface == surface,
         self.dirtyWorkspaceSurfaces.contains(surface) {
        self.scheduleRefreshForActivatedSurface(surface, delayNanoseconds: 150_000_000)
      }
    }
  }

  private func refreshWorkspaceSurfaceIfDirty(_ surface: WorkspaceSurface) async {
    guard dirtyWorkspaceSurfaces.contains(surface),
          !workspaceSurfaceIsRefreshing(surface)
    else {
      return
    }
    let dirtyGeneration = workspaceSurfaceDirtyGenerations[surface, default: 0]

    switch surface {
    case .home:
      break
    case .agenda:
      if agendaMode == .assigned {
        await refreshAssignedWork(showsLoading: false)
      } else {
        await refreshAgenda(preserveSelection: true, updatesStatus: false)
      }
    case .approvals:
      await refreshSelectedRunReviewPage()
    case .files:
      await refreshCorpusFiles()
    case .search:
      if !searchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        if dirtyWorkspaceSurfaces.contains(.approvals) {
          await refreshAgentRuns()
        }
        await runSearch()
      }
    case .meetings:
      await refreshMeetings()
    case .sources:
      await refreshSourceConnections()
    case .openClaw:
      await refreshOpenClawThreads(showsLoading: false)
    case .externalThreads:
      await refreshExternalThreads()
    }
    markWorkspaceSurfaceCleanIfUnchanged(surface, generation: dirtyGeneration)
  }

  private func workspaceSurfaceIsRefreshing(_ surface: WorkspaceSurface) -> Bool {
    switch surface {
    case .home:
      false
    case .agenda:
      agendaMode == .assigned ? isRefreshingAssignedWork : isRefreshingAgenda
    case .approvals:
      switch runsAndReviewPage {
      case .runs: isRefreshingAgentRuns
      case .review: isRefreshingApprovals
      case .goals: isRefreshingAgentGoals
      case .agents: isRefreshingAgentProfiles
      case .workflows: isRefreshingAgentWorkflows
      }
    case .files:
      isScanningCorpusFiles
    case .search:
      isSearching
    case .meetings:
      isLoadingMeetings
    case .sources:
      isLoadingSources
    case .openClaw:
      isRefreshingOpenClawThreads
    case .externalThreads:
      isRefreshingExternalThreads
    }
  }

  private func scheduleAgendaClockInvalidation(now: Date = Date()) {
    agendaClockRefreshTask?.cancel()
    guard corpusRoot != nil else { return }
    let next = Self.nextAgendaClockInvalidationDate(after: now)
    let delay = max(0.1, next.timeIntervalSince(now))
    agendaClockRefreshTask = Task { @MainActor [weak self] in
      try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
      guard !Task.isCancelled, let self else { return }
      self.markWorkspaceSurfacesDirty([.agenda], refreshVisible: true)
      self.scheduleAgendaClockInvalidation()
    }
  }

  nonisolated static func nextAgendaClockInvalidationDate(
    after date: Date,
    calendar: Calendar = .current
  ) -> Date {
    let start = calendar.startOfDay(for: date)
    return calendar.date(byAdding: .day, value: 1, to: start)
      ?? date.addingTimeInterval(86_400)
  }

  private func scheduleIncrementalCorpusRefresh(_ changedPaths: [String]) {
    pendingCorpusChangedPaths.formUnion(changedPaths.map {
      URL(fileURLWithPath: $0).standardizedFileURL.path
    })
    scheduleCorpusEventRefreshTask()
  }

  private func scheduleRunReviewRefreshAfterEvents() {
    runReviewFileEventGeneration += 1
    guard runReviewFileEventRefreshTask == nil else { return }
    guard isWorkspaceRealtimeRefreshActive else { return }

    runReviewFileEventRefreshTask = Task { @MainActor [weak self] in
      while let self, !Task.isCancelled {
        let generation = self.runReviewFileEventGeneration
        do {
          try await Task.sleep(nanoseconds: 1_000_000_000)
        } catch {
          return
        }
        guard !Task.isCancelled else { return }
        guard generation == self.runReviewFileEventGeneration else { continue }
        guard self.isWorkspaceRealtimeRefreshActive,
              self.selectedSurface == .approvals || self.selectedSurface == .search else {
          self.runReviewFileEventRefreshTask = nil
          return
        }

        await self.refreshWorkspaceSurfaceIfDirty(self.selectedSurface)
        if generation == self.runReviewFileEventGeneration {
          self.runReviewFileEventRefreshTask = nil
          return
        }
      }
    }
  }

  private func scheduleFullCorpusFileRefreshAfterEvents() {
    needsFullCorpusRefreshAfterEvents = true
    scheduleCorpusEventRefreshTask()
  }

  private func scheduleCorpusEventRefreshTask() {
    guard isWorkspaceRealtimeRefreshActive,
          activeSourceSyncEventBatchCount == 0,
          postOpenClawWorkspaceRefreshTask == nil
    else {
      return
    }
    corpusEventRefreshGeneration += 1
    let generation = corpusEventRefreshGeneration
    postOpenClawWorkspaceRefreshTask = Task { @MainActor [weak self] in
      try? await Task.sleep(nanoseconds: 120_000_000)
      guard let self else { return }

      while !Task.isCancelled,
            self.isWorkspaceRealtimeRefreshActive,
            self.activeSourceSyncEventBatchCount == 0 {
        if self.needsFullCorpusRefreshAfterEvents {
          self.needsFullCorpusRefreshAfterEvents = false
          self.pendingCorpusChangedPaths = []
          await self.performFullCorpusFileRefreshAfterEvents()
        } else {
          let paths = Array(self.pendingCorpusChangedPaths)
          self.pendingCorpusChangedPaths = []
          await self.applyIncrementalCorpusChanges(paths)
          if Task.isCancelled {
            self.pendingCorpusChangedPaths.formUnion(paths)
            break
          }
        }

        guard self.needsFullCorpusRefreshAfterEvents ||
                !self.pendingCorpusChangedPaths.isEmpty
        else {
          break
        }
        try? await Task.sleep(nanoseconds: 120_000_000)
      }

      guard generation == self.corpusEventRefreshGeneration else { return }
      self.postOpenClawWorkspaceRefreshTask = nil
      if self.isWorkspaceRealtimeRefreshActive,
         self.needsFullCorpusRefreshAfterEvents ||
          !self.pendingCorpusChangedPaths.isEmpty {
        self.scheduleCorpusEventRefreshTask()
      }
    }
  }

  private func performFullCorpusFileRefreshAfterEvents() async {
    markWorkspaceSurfacesDirty(
      [.agenda, .approvals, .files, .search, .meetings, .sources, .openClaw],
      refreshVisible: false
    )
    let filesDirtyGeneration = workspaceSurfaceDirtyGenerations[.files, default: 0]
    await refreshCorpusFiles()
    await searchIndexTask?.value
    guard !Task.isCancelled else { return }
    markWorkspaceSurfaceCleanIfUnchanged(.files, generation: filesDirtyGeneration)
    await refreshSelectedDetailFromDisk()
    guard !Task.isCancelled else { return }
    await refreshWorkspaceSurfaceIfDirty(selectedSurface)
  }

  private func applyIncrementalCorpusChanges(_ changedPaths: [String]) async {
    guard let corpusRoot, !changedPaths.isEmpty else { return }
    let root = corpusRoot.standardizedFileURL
    let rootPrefix = root.path + "/"
    let paths = Array(Set(changedPaths.map {
      URL(fileURLWithPath: $0).standardizedFileURL.path
    }.filter { $0.hasPrefix(rootPrefix) }))
    guard !paths.isEmpty else { return }

    let refreshedFiles = await Task.detached(priority: .utility) {
      paths.compactMap { Self.corpusFile(atPath: $0, corpusRoot: root) }
    }.value
    let changedSet = Set(paths)
    var filesByPath = Dictionary(uniqueKeysWithValues: corpusFiles.map { ($0.path, $0) })
    for path in changedSet { filesByPath.removeValue(forKey: path) }
    for file in refreshedFiles { filesByPath[file.path] = file }
    corpusFiles = filesByPath.values.sorted {
      $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending
    }
    reconcilePinnedFiles(for: root)

    await updateSearchIndex(changedPaths: paths, corpusRoot: root)
    await updateOrgRoamLinkResolver(changedPaths: changedSet, refreshedFiles: refreshedFiles)

    if let selectedLocation,
       changedSet.contains(URL(fileURLWithPath: selectedLocation.file).standardizedFileURL.path),
       editingBlockID == nil,
       !isEditingEntry,
       (!isLiveFileEditorSelected || !liveFileEditorHasUnsavedChanges) {
      // A user-initiated mutation may already have loaded and cached this exact
      // file version before its filesystem event arrives. Compare contents,
      // rather than modification time, so atomic sync replacements and tools
      // that preserve timestamps cannot leave the visible document stale.
      let cacheMatchesDisk = await cachedEntrySourceMatchesCurrentFileContents(
        for: selectedLocation,
        mode: selectedEntrySourceMode
      )
      if !cacheMatchesDisk {
        invalidateCanonicalDocumentCache(for: selectedLocation.file)
        await loadEntrySource(for: selectedLocation)
      }
    }

    guard !Task.isCancelled else { return }
    markWorkspaceSurfacesDirty(
      Self.invalidatedWorkspaceSurfaces(for: paths, corpusRoot: root),
      refreshVisible: false
    )
    await refreshWorkspaceSurfaceIfDirty(selectedSurface)
  }

  private func updateSearchIndex(changedPaths: [String], corpusRoot: URL) async {
    searchIndexGeneration += 1
    let generation = searchIndexGeneration
    searchIndexTask?.cancel()
    searchIndexTask = Task { [cli] in
      do {
        let payload: SearchIndexBuildPayload = try await cli.runJSON([
          "index", "--dir", corpusRoot.path, "--recursive",
          "--files"
        ] + changedPaths + ["--incremental", "--format", "json"])
        guard !Task.isCancelled else { return }
        await MainActor.run {
          guard self.searchIndexGeneration == generation else { return }
          self.searchIndexTask = nil
          self.isBuildingSearchIndex = false
          self.searchIndexStatusText = "\(payload.fileCount) files indexed"
        }
      } catch {
        guard !Task.isCancelled else { return }
        await MainActor.run {
          guard self.searchIndexGeneration == generation else { return }
          self.searchIndexTask = nil
          self.isBuildingSearchIndex = false
          self.searchIndexStatusText = "Search index update deferred"
        }
      }
    }
    await searchIndexTask?.value
  }

  private func updateOrgRoamLinkResolver(
    changedPaths: Set<String>,
    refreshedFiles: [CorpusFile]
  ) async {
    orgRoamLinkResolverGeneration += 1
    let generation = orgRoamLinkResolverGeneration
    let unchangedNodes = orgRoamLinkResolver.nodes.filter { !changedPaths.contains($0.file) }
    let changedNodes = await Task.detached(priority: .utility) {
      refreshedFiles.flatMap(Self.scanRoamNodes)
    }.value
    guard generation == orgRoamLinkResolverGeneration else { return }
    orgRoamLinkResolver = OrgRoamLinkResolver(
      nodes: unchangedNodes + changedNodes,
      linkAbbreviations: orgRoamLinkResolver.linkAbbreviations
    )
  }

  private func openClawQueuedStatusText() -> String {
    let destinationID = selectedOpenClawChatThreadID.flatMap { threadID in
      activeSharedRoomDestinationByThreadID[threadID]
        ?? openClawPendingUserMessageIDs(for: threadID).first.flatMap { messageID in
          openClawMessages(for: threadID).first(where: { $0.id == messageID })?.targetDestinationID
        }
        ?? openClawChatThreads.first(where: { $0.id == threadID })?.destinationID
    } ?? AIChatDestinationConfiguration.openClawID
    let title = aiChatDestinationTitle(destinationID)
    if openClawQueuedMessageCount > 1 {
      return "Sending to \(title)... \(openClawQueuedMessageCount - 1) queued"
    }
    return "Sending to \(title)..."
  }

  public func resetOpenClawChat() {
    ensureOpenClawChatThread()
    let threadID = selectedOpenClawChatThreadID
    openClawMessages = []
    clearOpenClawDraftForSelectedThread()
    openClawPendingAttachments = []
    if let threadID {
      cancelOpenClawPendingTurnRecovery(for: threadID)
      if let index = openClawChatThreads.firstIndex(where: { $0.id == threadID }),
         openClawChatThreads[index].runtime == .codex
           || openClawChatThreads[index].runtime == .claude
           || openClawChatThreads[index].isSharedRoom {
        openClawChatThreads[index] = openClawChatThreads[index]
          .replacingOpenClawChatMetadata(
            runtimeThreadID: .some(nil),
            runtimeThreadIDsByDestination: [:]
          )
        codexActiveTurnsByThreadID.removeValue(forKey: threadID)
        activeSharedRoomRuntimeByThreadID.removeValue(forKey: threadID)
        activeSharedRoomDestinationByThreadID.removeValue(forKey: threadID)
        persistOpenClawTranscript()
      }
      if let runID = openClawChatThreads.first(where: { $0.id == threadID })?.pendingTurn?.runID {
        clearOpenClawPendingTurn(runID, in: threadID, shouldPersist: true)
      }
      removeAllPendingOpenClawUserMessages(in: threadID)
      drainingOpenClawThreadIDs.remove(threadID)
      activeOpenClawUserMessageIDByThreadID.removeValue(forKey: threadID)
      openClawRequestStartedAtByThreadID.removeValue(forKey: threadID)
    }
    syncSelectedOpenClawSendState()
    openClawChatScrollPosition = nil
    openClawAssistantChatScrollPosition = nil
    switch selectedAIChatRuntime {
    case .codex:
      openClawStatusText = "Ready for a Codex message"
    case .claude:
      openClawStatusText = "Ready for a Claude Code message"
    case .openClaw:
      openClawStatusText = Self.openClawStatusText(settings: currentOpenClawSettings())
    }
  }

  public var selectedOpenClawChatThread: OpenClawChatThread? {
    guard let selectedOpenClawChatThreadID else { return nil }
    return openClawChatThreads.first(where: { $0.id == selectedOpenClawChatThreadID })
  }

  public var settledOpenClawChatThreads: [OpenClawChatThread] {
    archivedOpenClawChatThreads
  }

  public var sidebarOpenClawChatThreads: [OpenClawChatThread] {
    guard let promotedThread = sidebarPromotedOpenClawChatThread else {
      return visibleOpenClawChatThreads
    }
    return [promotedThread] + visibleOpenClawChatThreads.filter { $0.id != promotedThread.id }
  }

  public var sidebarSettledOpenClawChatThreads: [OpenClawChatThread] {
    guard let promotedThread = sidebarPromotedOpenClawChatThread,
          promotedThread.isSettled
    else {
      return settledOpenClawChatThreads
    }
    return settledOpenClawChatThreads.filter { $0.id != promotedThread.id }
  }

  private var sidebarPromotedOpenClawChatThread: OpenClawChatThread? {
    guard let sidebarPromotedOpenClawChatThreadID,
          selectedOpenClawChatThreadID == sidebarPromotedOpenClawChatThreadID
    else {
      return nil
    }
    return openClawChatThreads.first { $0.id == sidebarPromotedOpenClawChatThreadID }
  }

  private func rebuildOpenClawThreadDisplayCache() {
    visibleOpenClawChatThreads = Self.sortedOpenClawChatThreadsForDisplay(
      openClawChatThreads.filter { !$0.isSettled }
    )
    archivedOpenClawChatThreads = Self.sortedOpenClawChatThreadsForDisplay(
      openClawChatThreads.filter(\.isSettled)
    )
    openClawUnreadMessageCount = openClawChatThreads.reduce(0) { $0 + $1.unreadMessageCount }
  }

  public var canUndoOpenClawChatThreadArchive: Bool {
    guard let lastArchivedOpenClawChatThreadID else { return false }
    return openClawChatThreads.contains {
      $0.id == lastArchivedOpenClawChatThreadID && $0.isSettled
    }
  }

  public var canOpenCanonicalOpenClawResourceThread: Bool {
    currentOpenClawResourceReference() != nil
  }

  public var hasCanonicalOpenClawResourceThread: Bool {
    guard let resource = currentOpenClawResourceReference() else { return false }
    return openClawChatThreads.contains { $0.resource?.key == resource.key }
  }

  public func openCanonicalOpenClawResourceThread() {
    guard let resource = currentOpenClawResourceReference() else {
      statusText = "Add an ID to this heading before creating its resource thread"
      return
    }
    let pointer = openClawContextPointerForCurrentSelection()

    if let thread = openClawChatThreads.first(where: { $0.resource?.key == resource.key }) {
      if thread.isSettled {
        reopenOpenClawChatThread(thread.id)
      }
      navigateToSurface(.openClaw)
      selectOpenClawChatThread(thread.id)
      openClawStatusText = "Opened resource thread for \(resource.title)"
      statusText = "Opened resource thread"
      return
    }

    let thread = createOpenClawChatThread(
      title: "Resource: \(resource.title)",
      statusText: "New OpenClaw resource thread",
      resource: resource
    )
    if let pointer {
      addOpenClawContext(pointer, threadMode: .currentThread)
    }
    navigateToSurface(.openClaw)
    selectOpenClawChatThread(thread.id)
    openClawStatusText = "Created resource thread for \(resource.title)"
    statusText = "Created resource thread"
  }

  @discardableResult
  public func createOpenClawChatThread(runtime: AIChatRuntime = .openClaw) -> UUID {
    createOpenClawChatThread(
      title: "New Chat",
      statusText: "New \(runtime.title) chat",
      runtime: runtime,
      defersPersistence: true
    ).id
  }

  @discardableResult
  public func createAIChatThread(destinationID: String) -> UUID {
    let destination = aiChatDestination(id: destinationID)
      ?? AIChatDestinationConfiguration.defaults.first(where: { $0.id == destinationID })
      ?? AIChatDestinationConfiguration.defaults[0]
    return createOpenClawChatThread(
      title: "New Chat",
