    let assignee = resolvedAgentHandoffAssignee()
    try await setTodoAssignee(assignee, for: target)
    try upsertHeadlineProperties(
      file: target.file,
      line: target.line,
      properties: [
        "STATUS": "ready",
        "ASSIGNED_AT": timestamp
      ]
    )
  }

