  public var selectedNodeEntityType: Org2EntityType? {
    selectedEntrySource.flatMap(Self.entityType)
  }

  public var selectedNodeHasExplicitEntityType: Bool {
    selectedEntrySource.map(Self.hasExplicitEntityType) == true
  }

  public var canSetSelectedNodeEntityType: Bool {
    guard let source = selectedEntrySource,
          source.isEditable,
          Self.isEntityTypeTarget(source)
    else {
      return false
    }
    return !isSavingEntry
      && !isSavingBlock
      && !isEditingEntry
      && editingBlockID == nil
      && !liveFileEditorHasUnsavedChanges
  }

  nonisolated static func entityType(for source: EntrySource) -> Org2EntityType? {
    if let explicit = explicitEntityType(for: source) {
      return explicit
    }

    let metadata = entityMetadataText(for: source)
    if let legacyKind = firstRegularExpressionCapture(
      in: metadata,
      pattern: #"(?im)^\s*(?:#\+(?:ORG2_KIND|KIND)|:KIND):\s*(person)\s*$"#
    ).flatMap(Org2EntityType.init) {
      return legacyKind
    }
    if hasLegacyPersonTag(in: metadata) {
      return Org2EntityType("person")
    }

    guard !source.isSubtree, source.startLine == 1 else { return nil }
    let components = URL(fileURLWithPath: source.file).pathComponents.map { $0.lowercased() }
    if components.contains(where: { ["people", "persons", "contacts"].contains($0) }) {
      return Org2EntityType("person")
    }
    if components.contains(where: { ["company", "companies", "accounts", "organizations", "orgs"].contains($0) }) {
      return Org2EntityType("company")
    }
    if components.contains(where: { ["project", "projects"].contains($0) }) {
      return Org2EntityType("project")
    }
    return nil
  }

  nonisolated static func showsEntityActionItems(for source: EntrySource) -> Bool {
    guard !source.isSubtree else { return false }
    return entityType(for: source)?.supportsActionItems == true
  }

  public func loadEntityActionItems(for source: EntrySource) async {
    entityActionItemsLoadGeneration += 1
    let generation = entityActionItemsLoadGeneration

    guard Self.showsEntityActionItems(for: source),
          let corpusRoot
    else {
      entityActionItems = nil
      isLoadingEntityActionItems = false
      return
    }

    let fallbackTitle = URL(fileURLWithPath: source.file)
      .deletingPathExtension()
      .lastPathComponent
      .replacingOccurrences(of: "-", with: " ")
    let object: String
    if let id = Self.firstOrgID(in: source.text) {
      object = "id:\(id)"
    } else {
      object = Self.openClawTitle(from: source.text, fallback: fallbackTitle).title
    }
    guard !object.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
      entityActionItems = nil
      isLoadingEntityActionItems = false
      return
    }

    entityActionItems = nil
    isLoadingEntityActionItems = true
    defer {
      if generation == entityActionItemsLoadGeneration {
        isLoadingEntityActionItems = false
      }
    }

    do {
      let payload: NodeActionItemsPayload
      if let loader = nodeActionItemsLoaderForTesting {
        payload = try await loader(object, corpusRoot)
      } else {
        payload = try await cli.runJSON([
          "query", "actions",
          "--object", object,
          "--dir", corpusRoot.path,
          "--recursive",
          "--recent-days", "30",
          "--open-limit", "5",
          "--completed-limit", "2",
          "--format", "json",
        ])
      }
      guard generation == entityActionItemsLoadGeneration,
            selectedEntrySource?.id == source.id
      else { return }
      entityActionItems = payload
    } catch is CancellationError {
      return
    } catch {
      guard generation == entityActionItemsLoadGeneration,
            selectedEntrySource?.id == source.id
      else { return }
      entityActionItems = nil
    }
  }

  public func selectEntityActionItem(_ item: NodeActionItem) {
    guard let corpusRoot else { return }
    let root = corpusRoot.resolvingSymlinksInPath().standardizedFileURL
    let candidate = (item.file.hasPrefix("/")
      ? URL(fileURLWithPath: item.file)
      : root.appendingPathComponent(item.file))
      .resolvingSymlinksInPath()
      .standardizedFileURL
    guard candidate.path.hasPrefix(root.path + "/") else {
      statusText = "Action item is outside the active corpus"
      return
    }
    let backlink = BacklinkItem(
      srcId: item.id,
      srcTitle: item.title,
      file: candidate.path,
      line: max(0, item.line - 1),
      context: item.snippet ?? item.title
    )
    select(.backlink(backlink), surface: selectedSurface)
  }

  public func setSelectedNodeEntityType(_ entityType: Org2EntityType?) async {
    guard let source = selectedEntrySource,
          source.isEditable,
          Self.isEntityTypeTarget(source),
          canSetSelectedNodeEntityType
    else {
      statusText = "No editable node loaded"
      return
    }
    guard let replacement = Self.sourceTextSettingEntityType(source, entityType: entityType) else {
      statusText = "Node type update failed"
      return
    }
    guard Self.normalizeLineEndings(replacement) != Self.normalizeLineEndings(source.text) else {
      statusText = entityType.map { "Type is already \($0.title)" } ?? "Node has no explicit type"
      return
    }

    let undoSnapshot = fileUndoSnapshot(for: source.file)
    isSavingEntry = true
    defer { isSavingEntry = false }
    do {
      try await Task.detached(priority: .userInitiated) {
        try Self.replaceEntrySource(source, with: replacement)
      }.value
      guard selectedEntrySource?.id == source.id else {
        recordFileUndo(from: undoSnapshot)
        return
      }
      recordFileUndo(from: undoSnapshot)
      await finishSavedEntry(source: source, savedText: replacement, keepEditing: false)
      statusText = entityType.map { "Type -> \($0.title)" } ?? "Explicit node type removed"
    } catch {
      errorText = error.localizedDescription
      statusText = "Node type update failed"
    }
  }

  public func promptAndSetSelectedNodeEntityType() {
    guard canSetSelectedNodeEntityType else {
      statusText = "No editable node loaded"
      return
    }

    let alert = NSAlert()
    alert.messageText = "Set Node Type"
    alert.informativeText = "Use a short type such as person, company, project, decision, or topic."
    alert.addButton(withTitle: "Set")
    alert.addButton(withTitle: "Cancel")
    let field = NSTextField(frame: NSRect(x: 0, y: 0, width: 320, height: 24))
    field.placeholderString = "entity type"
    field.stringValue = selectedNodeEntityType?.rawValue ?? ""
    alert.accessoryView = field
    alert.window.initialFirstResponder = field

    guard alert.runModal() == .alertFirstButtonReturn else { return }
    guard let entityType = Org2EntityType(field.stringValue) else {
      statusText = "Node type must contain a letter or number"
      return
    }
    Task { await setSelectedNodeEntityType(entityType) }
  }

  nonisolated static func sourceTextSettingEntityType(
    _ source: EntrySource,
    entityType: Org2EntityType?
  ) -> String? {
    guard isEntityTypeTarget(source) else { return nil }
    var lines = normalizeLineEndings(source.text)
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    guard !lines.isEmpty else { return nil }

    if source.isSubtree {
      lines[0] = removingEntityTypeTags(from: lines[0])
      removeDirectEntityTypeProperties(from: &lines)
      if let entityType {
        upsertDirectEntityTypeProperty(entityType.rawValue, in: &lines)
      }
    } else {
      removeFileEntityTypeMetadata(from: &lines)
      if let entityType {
        upsertFileEntityTypeProperty(entityType.rawValue, in: &lines)
      }
    }
    return lines.joined(separator: "\n")
  }

  nonisolated private static func isEntityTypeTarget(_ source: EntrySource) -> Bool {
    if source.isSubtree {
      return source.text.split(separator: "\n", maxSplits: 1, omittingEmptySubsequences: false)
        .first.map { $0.range(of: #"^\*+\s+"#, options: .regularExpression) != nil } == true
    }
    return source.startLine == 1
  }

  nonisolated private static func explicitEntityType(for source: EntrySource) -> Org2EntityType? {
    let metadata = entityMetadataText(for: source)
    if let propertyType = firstRegularExpressionCapture(
      in: metadata,
      pattern: #"(?im)^\s*(?:#\+(?:ORG2_ENTITY_TYPE|ENTITY_TYPE)|:(?:ORG2_ENTITY_TYPE|ENTITY_TYPE)):\s*(.+?)\s*$"#
    ).flatMap(Org2EntityType.init) {
      return propertyType
    }
    return entityTagTokens(in: metadata).compactMap(Org2EntityType.init).first
  }

  nonisolated private static func hasExplicitEntityType(_ source: EntrySource) -> Bool {
    explicitEntityType(for: source) != nil
  }

  nonisolated private static func entityMetadataText(for source: EntrySource) -> String {
    let lines = normalizeLineEndings(source.text)
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    guard source.isSubtree else {
      return lines.prefix { !isHeadingLine($0) }.joined(separator: "\n")
    }
    guard !lines.isEmpty else { return "" }
    var end = 1
    while end < lines.count,
          lines[end].trimmingCharacters(in: .whitespaces).range(
            of: #"^(?:SCHEDULED|DEADLINE|CLOSED):"#,
            options: [.regularExpression, .caseInsensitive]
          ) != nil {
      end += 1
    }
    if end < lines.count,
       lines[end].trimmingCharacters(in: .whitespaces).uppercased() == ":PROPERTIES:" {
      end += 1
      while end < lines.count {
        let isEnd = lines[end].trimmingCharacters(in: .whitespaces).uppercased() == ":END:"
        end += 1
        if isEnd { break }
      }
    }
    return lines[..<end].joined(separator: "\n")
  }

  nonisolated private static func entityTagTokens(in metadata: String) -> [String] {
    metadata
      .split(separator: "\n", omittingEmptySubsequences: false)
      .filter { line in
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        return trimmed.hasPrefix("*")
          || trimmed.lowercased().hasPrefix("#+filetags:")
          || trimmed.lowercased().hasPrefix("#+roam_tags:")
      }
      .flatMap { line in
        line.split(separator: ":").compactMap { rawToken -> String? in
          let token = rawToken.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
          if token.hasPrefix("type_") { return String(token.dropFirst("type_".count)) }
          if token.hasPrefix("type-") { return String(token.dropFirst("type-".count)) }
          return nil
        }
      }
  }

  nonisolated private static func hasLegacyPersonTag(in metadata: String) -> Bool {
    metadata
      .split(separator: "\n", omittingEmptySubsequences: false)
      .filter { line in
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        return trimmed.hasPrefix("*")
          || trimmed.lowercased().hasPrefix("#+filetags:")
          || trimmed.lowercased().hasPrefix("#+roam_tags:")
      }
      .contains { line in
        line.split(separator: ":").contains { rawToken in
          rawToken.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == "person"
        }
      }
  }

  nonisolated private static func firstRegularExpressionCapture(
    in text: String,
    pattern: String
  ) -> String? {
    guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
    let source = text as NSString
    guard let match = regex.firstMatch(
      in: text,
      range: NSRange(location: 0, length: source.length)
    ), match.numberOfRanges > 1, match.range(at: 1).location != NSNotFound else {
      return nil
    }
    return source.substring(with: match.range(at: 1))
      .trimmingCharacters(in: .whitespacesAndNewlines)
  }

  nonisolated private static func removingEntityTypeTags(from line: String) -> String {
    line
      .replacingOccurrences(
        of: #"(?i):type[-_][A-Za-z0-9_-]+(?=:)"#,
        with: "",
        options: .regularExpression
      )
      .trimmingCharacters(in: .whitespaces)
  }

  nonisolated private static func removeFileEntityTypeMetadata(from lines: inout [String]) {
    let preambleEnd = lines.firstIndex(where: isHeadingLine) ?? lines.count
    for index in (0..<preambleEnd).reversed() {
      let trimmed = lines[index].trimmingCharacters(in: .whitespaces)
      if trimmed.range(
        of: #"^(?:#\+(?:ORG2_ENTITY_TYPE|ENTITY_TYPE)|:(?:ORG2_ENTITY_TYPE|ENTITY_TYPE)):"#,
        options: [.regularExpression, .caseInsensitive]
      ) != nil {
        lines.remove(at: index)
        continue
      }
      if trimmed.range(
        of: #"^#\+(?:FILETAGS|ROAM_TAGS):"#,
        options: [.regularExpression, .caseInsensitive]
      ) != nil {
        lines[index] = removingEntityTypeTags(from: lines[index])
      }
    }
    removeEmptyFilePropertyDrawers(from: &lines)
  }

  nonisolated private static func removeEmptyFilePropertyDrawers(from lines: inout [String]) {
    var index = 0
    while index < (lines.firstIndex(where: isHeadingLine) ?? lines.count) {
      guard lines[index].trimmingCharacters(in: .whitespaces).uppercased() == ":PROPERTIES:" else {
        index += 1
        continue
      }
      guard let end = lines[(index + 1)...].firstIndex(where: {
        $0.trimmingCharacters(in: .whitespaces).uppercased() == ":END:"
      }) else { return }
      if lines[(index + 1)..<end].allSatisfy({ $0.trimmingCharacters(in: .whitespaces).isEmpty }) {
        lines.removeSubrange(index...end)
      } else {
        index = end + 1
      }
    }
  }

  nonisolated private static func filePropertyDrawerRange(in lines: [String]) -> ClosedRange<Int>? {
    let preambleEnd = lines.firstIndex(where: isHeadingLine) ?? lines.count
    guard preambleEnd > 0 else { return nil }
    for start in 0..<preambleEnd where
      lines[start].trimmingCharacters(in: .whitespaces).uppercased() == ":PROPERTIES:"
    {
      guard start + 1 < preambleEnd,
            let end = lines[(start + 1)..<preambleEnd].firstIndex(where: {
              $0.trimmingCharacters(in: .whitespaces).uppercased() == ":END:"
            })
      else { return nil }
      return start...end
    }
    return nil
  }

  nonisolated private static func upsertFileEntityTypeProperty(
    _ rawValue: String,
    in lines: inout [String]
  ) {
    if let drawer = filePropertyDrawerRange(in: lines) {
      lines.insert(":ORG2_ENTITY_TYPE: \(rawValue)", at: drawer.upperBound)
      return
    }
    let preambleEnd = lines.firstIndex(where: isHeadingLine) ?? lines.count
    let lastKeyword = (0..<preambleEnd).last(where: {
      lines[$0].trimmingCharacters(in: .whitespaces).hasPrefix("#+")
    })
    lines.insert(contentsOf: [
      ":PROPERTIES:",
      ":ORG2_ENTITY_TYPE: \(rawValue)",
      ":END:",
    ], at: lastKeyword.map { $0 + 1 } ?? 0)
  }

  nonisolated private static func directPropertyDrawerRange(in lines: [String]) -> ClosedRange<Int>? {
    guard !lines.isEmpty, lines[0].range(of: #"^\*+\s+"#, options: .regularExpression) != nil else {
      return nil
    }
    var start = 1
    while start < lines.count,
          lines[start].trimmingCharacters(in: .whitespaces).range(
            of: #"^(?:SCHEDULED|DEADLINE|CLOSED):"#,
            options: [.regularExpression, .caseInsensitive]
          ) != nil {
      start += 1
    }
    guard start < lines.count,
          lines[start].trimmingCharacters(in: .whitespaces).uppercased() == ":PROPERTIES:",
          let end = lines[(start + 1)...].firstIndex(where: {
            $0.trimmingCharacters(in: .whitespaces).uppercased() == ":END:"
          })
    else {
      return nil
    }
    return start...end
  }

  nonisolated private static func isHeadingLine(_ line: String) -> Bool {
    line.range(of: #"^\*+\s+"#, options: .regularExpression) != nil
  }

  nonisolated private static func removeDirectEntityTypeProperties(from lines: inout [String]) {
    guard let drawer = directPropertyDrawerRange(in: lines) else { return }
    for index in drawer.reversed() where index > drawer.lowerBound && index < drawer.upperBound {
      if lines[index].trimmingCharacters(in: .whitespaces).range(
        of: #"^:(?:ORG2_ENTITY_TYPE|ENTITY_TYPE):"#,
        options: [.regularExpression, .caseInsensitive]
      ) != nil {
        lines.remove(at: index)
      }
    }
    if let updated = directPropertyDrawerRange(in: lines),
       lines[(updated.lowerBound + 1)..<updated.upperBound]
         .allSatisfy({ $0.trimmingCharacters(in: .whitespaces).isEmpty }) {
      lines.removeSubrange(updated)
    }
  }

  nonisolated private static func upsertDirectEntityTypeProperty(
    _ rawValue: String,
    in lines: inout [String]
  ) {
    if let drawer = directPropertyDrawerRange(in: lines) {
      lines.insert(":ORG2_ENTITY_TYPE: \(rawValue)", at: drawer.upperBound)
      return
    }
    var insertionIndex = 1
    while insertionIndex < lines.count,
          lines[insertionIndex].trimmingCharacters(in: .whitespaces).range(
            of: #"^(?:SCHEDULED|DEADLINE|CLOSED):"#,
            options: [.regularExpression, .caseInsensitive]
          ) != nil {
      insertionIndex += 1
    }
    lines.insert(contentsOf: [
      ":PROPERTIES:",
      ":ORG2_ENTITY_TYPE: \(rawValue)",
      ":END:",
    ], at: insertionIndex)
  }

  private func openNodeBriefArtifact(url: URL, relativePath: String, title: String) {
    let modifiedAt = Self.modificationDate(for: url)
    let zone = NSString(string: relativePath).deletingLastPathComponent
    let thread = OpenClawThread(
      title: "Brief: \(title)",
      file: url.path,
      line: 1,
      zone: zone.isEmpty ? "views" : zone,
      modifiedAt: modifiedAt,
      idValue: nil
    )
    activateDetailLocation(.openClaw(thread), mode: .page, surface: .files, recordsHistory: true)
    selectedOpenClawThreadID = thread.id
    pendingNodeBriefArtifactRelativePath = nil
    pendingNodeBriefTitle = nil
    openClawStatusText = "Opened cached node brief"
    statusText = "Opened \(relativePath)"
  }

  nonisolated static func nodeBriefArtifactRelativePath(id: String?, file: String, line: Int) -> String {
    let tokenRaw: String
    if let id = id?.trimmingCharacters(in: .whitespacesAndNewlines), !id.isEmpty {
      tokenRaw = id
    } else {
      tokenRaw = "\(file)-line-\(max(1, line))"
    }
    return "views/node-briefs/\(slug(tokenRaw)).org2"
  }

  nonisolated static func legacyNodeBriefArtifactRelativePath(
    title: String,
    id: String?,
    file: String,
    line: Int
  ) -> String {
    let tokenRaw: String
    if let id = id?.trimmingCharacters(in: .whitespacesAndNewlines), !id.isEmpty {
      tokenRaw = id
    } else {
      tokenRaw = "\(file)-line-\(max(1, line))"
    }
    return "views/openclaw/node-briefs/\(slug(title))-\(slug(tokenRaw)).org2"
  }

  nonisolated private static func hasUsableNodeBriefArtifact(at url: URL) -> Bool {
    guard let values = try? url.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey]),
          values.isRegularFile == true,
          (values.fileSize ?? 0) > 0,
          let raw = try? String(contentsOf: url, encoding: .utf8)
    else {
      return false
    }
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return false }
    return !trimmed.contains("ORG2_NODE_BRIEF_STATUS: pending")
  }

  nonisolated static func nodeBriefArtifact(at url: URL, relativePath: String) -> NodeBriefArtifact? {
    guard hasUsableNodeBriefArtifact(at: url),
          let raw = try? String(contentsOf: url, encoding: .utf8)
    else {
      return nil
    }
    return NodeBriefArtifact(
      relativePath: relativePath,
      file: url.standardizedFileURL.path,
      title: nodeBriefArtifactTitle(raw),
      body: nodeBriefArtifactBody(raw),
      modifiedAt: modificationDate(for: url)
    )
  }

  nonisolated static func nodeBriefArtifactTitle(_ raw: String) -> String {
    for line in raw.split(separator: "\n", omittingEmptySubsequences: false) {
      let text = String(line)
      guard text.uppercased().hasPrefix("#+TITLE:") else { continue }
      return text
        .dropFirst("#+TITLE:".count)
        .trimmingCharacters(in: .whitespacesAndNewlines)
    }
    return "Node brief"
  }

  nonisolated static func nodeBriefArtifactBody(_ raw: String) -> String {
    let lines = raw
      .replacingOccurrences(of: "\r\n", with: "\n")
      .replacingOccurrences(of: "\r", with: "\n")
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    var index = 0
    while index < lines.count {
      let trimmed = lines[index].trimmingCharacters(in: .whitespacesAndNewlines)
      if trimmed.uppercased().hasPrefix("#+TITLE:") {
        index += 1
        continue
      }
      if trimmed == ":PROPERTIES:" {
        index += 1
        while index < lines.count,
              lines[index].trimmingCharacters(in: .whitespacesAndNewlines) != ":END:" {
          index += 1
        }
        if index < lines.count { index += 1 }
        continue
      }
      if trimmed.isEmpty {
        index += 1
        continue
      }
      break
    }
    guard index < lines.count else { return "" }
    let body = lines[index...].joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
    guard body.count > 20_000 else { return body }
    let end = body.index(body.startIndex, offsetBy: 20_000)
    return String(body[..<end]) + "\n\n[Brief truncated in context pane. Open the full artifact to continue.]"
  }

  nonisolated static func nodeBriefPrompt(
    title: String,
    reference: String,
    artifactRelativePath: String,
    artifactLocalPath: String,
    artifactRuntimePath: String,
    sourceID: String?
  ) -> String {
    let artifactID = "node-brief-\(slug(sourceID ?? reference))"
    let provenance = [
      sourceID.map { "id:\($0)" },
      "file:\(reference)"
    ].compactMap { $0 }.joined(separator: ", ")
    return """
    Generate a concise, source-cited briefing for the selected org2 node "\(title)" and save it as an org2 view artifact.

    Target artifact relative path: \(artifactRelativePath)
    Target artifact path for the current AI runtime: \(artifactRuntimePath)
    Local artifact path: \(artifactLocalPath)
    Selected node: \(reference)
    \(sourceID.map { "Selected node ID: \($0)" } ?? "Selected node ID: unavailable")

    Use the selected-node source and computed backlink context provided in the org2 workspace context. You may run org2 backlinks/search/query for more source context if needed, but do not run org2 brief to generate this brief.

    Before writing, do a current-state sweep. Search recent and agent/workflow files for the selected node title, aliases, account/company names, and obvious variants. Prefer newer dated entries over older background context when describing current state. Do not discard completed DONE/CANCELED workflow items if they record important current facts such as an email sent, follow-up sent, handoff completed, decision made, current owner, waiting on reply/response, blocked state, or other recent account/project state. Treat properties and phrases such as SENT_AT, LAST_SENT_AT, GMAIL_SENT_MESSAGE_ID, FOLLOWUP_STATUS, FOLLOWUP_SENT_AT, waiting on reply, awaiting response, blocked, sent, approved, or completed as possible current-state evidence even when the TODO itself is no longer active.

    Write for a human trying to quickly understand the node. Focus on what matters, not how org2 stores it. Do not present stable IDs, artifact metadata, file paths, provenance fields, review status, schema fields, or the mere existence of a title/ID as facts or highlights. Use file paths and line numbers only as citations after concrete claims. Mention metadata only in "Node health issues" when it is actually broken, missing, duplicated, stale, or confusing.

    Keep the body concise:
    - Most important facts: 3-6 bullets, including recent material state changes even if they came from completed workflow entries.
    - Active related tasks: only TODO/open/actionable items, up to 5 bullets, or "None found."
    - Recent related decisions: only decisions/commitments/outcomes, up to 5 bullets, or "None found."
    - Open questions: unresolved questions/unknowns/risks, including waiting-on-response states, up to 5 bullets, or "None found."
    - Node health issues: put this last; include only maintenance problems such as contradictory notes, stale generated context, broken links, missing IDs, duplicate IDs, bad citations, or confusing organization.

    Create the parent directory if needed. Replace the artifact file atomically if it already exists. The file must be valid org2 and start with:
    #+TITLE: Node brief: \(title)
    :PROPERTIES:
    :ID: \(artifactID)
    :ORG2_ARTIFACT_SCHEMA: org2-artifact-metadata/v1
    :ORG2_ARTIFACT_ROLE: view
    :ORG2_PROVENANCE: \(provenance)
    :ORG2_GENERATOR: OpenOrg AI chat node brief
    :ORG2_GENERATED_AT: <ISO-8601 timestamp>
    :ORG2_CLAIM_STATE: source-backed
    :ORG2_REVIEW_STATUS: review-required
    :ORG2_AI_TASK: node-brief
    :ORG2_PROMPT_TEMPLATE: node-brief@v3
    :END:

    Then write these sections:
    * Most important facts
    * Active related tasks
    * Recent related decisions
    * Open questions
    * Node health issues
    * Sources

    Cite file paths and line numbers for every concrete claim. Prefer specific, user-meaningful facts over generic graph or storage details. Do not edit canonical notes. Reply in chat with only a short confirmation and the artifact path.
    """
  }

  private func backlinkTargetID(for location: WorkspaceLocation) async throws -> String? {
    if let id = location.idValue?.trimmingCharacters(in: .whitespacesAndNewlines), !id.isEmpty {
      return id
    }

    do {
      let payload: OrgIDLookupPayload = try await cli.runJSON([
        "id", "get",
        "--file", location.file,
        "--line", "\(location.lineForEditor)",
        "--format", "json"
      ])
      applyResolvedID(payload.id, to: location)
      return payload.id
    } catch {
      return nil
    }
  }

  private func applyResolvedID(_ id: String, to location: WorkspaceLocation) {
    guard selectedLocationMatches(location) else { return }
    switch selectedLocation {
    case .openClaw(let thread):
      selectedLocation = .openClaw(OpenClawThread(
        title: thread.title,
        file: thread.file,
        line: thread.lineForEditor,
        zone: thread.zone,
        modifiedAt: thread.modifiedAt,
        idValue: id
      ))
    default:
      break
    }
  }

  public func openSelectedLocation() {
    if selectedLocation == nil,
       agendaMode == .assigned,
       let selectedAssignedWorkItemID,
       let item = assignedWorkItems.first(where: { $0.id == selectedAssignedWorkItemID }) {
      selectAssignedWorkItem(item)
    }
    guard let selectedLocation else { return }
    open(selectedLocation)
  }

  public func open(_ location: WorkspaceLocation) {
    openFile(path: location.file, line: location.lineForEditor)
  }

  public func revealSelectedLocation() {
    guard let selectedLocation else { return }
    revealFile(path: selectedLocation.file)
  }

  public func revealFile(path: String) {
    NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: path)])
  }

  public func openFileInEditor(path: String, line: Int = 1) {
    openFile(path: path, line: line)
  }

  public func copyFileReference(path: String, line: Int? = nil) {
    let reference = line.map { "\(relativePath(path)):\($0)" } ?? relativePath(path)
    NSPasteboard.general.clearContents()
    NSPasteboard.general.setString(reference, forType: .string)
    statusText = "Copied \(reference)"
  }

  public func relativePath(_ path: String) -> String {
    guard let corpusRoot else { return path }
    return Self.relativePath(for: path, root: corpusRoot)
  }

  private static func relativePath(for path: String, root: URL) -> String {
    let originalPath = URL(fileURLWithPath: path).standardizedFileURL.path
    let resolvedPath = URL(fileURLWithPath: path).resolvingSymlinksInPath().standardizedFileURL.path
    let rootPath = root.resolvingSymlinksInPath().standardizedFileURL.path
    if resolvedPath == rootPath { return "." }
    if resolvedPath.hasPrefix(rootPath + "/") {
      return String(resolvedPath.dropFirst(rootPath.count + 1))
    }
    return originalPath
  }

  private func startNewAIThread(with rawPointers: [OpenClawContextPointer]) {
    var seen = Set<String>()
    let pointers = rawPointers.filter {
      seen.insert("\($0.kind)|\($0.reference)|\($0.displayTitle)").inserted
    }
    guard !pointers.isEmpty else {
      statusText = "No selected items are available for AI context"
      return
    }

    let runtime = selectedOpenClawChatThread?.runtime ?? .openClaw
    let threadTitle = pointers.count == 1
      ? pointers[0].threadTitle
      : "Context: \(pointers.count) selected items"
    createOpenClawChatThread(
      title: Self.normalizedOpenClawThreadTitle(threadTitle),
      statusText: "New \(runtime.title) context chat",
      runtime: runtime
    )
    let draft = pointers.map(injectedOpenClawContext).joined()
    publishOpenClawComposerDraft(draft)
    recordWorkspaceUndo(.openClawDraft(previous: "", next: draft))
    setOpenClawAssistantPanelPresented(true)

    let countLabel = pointers.count == 1 ? "1 item" : "\(pointers.count) items"
    openClawStatusText = "Added \(countLabel) to \(runtime.title)"
    statusText = "Started a new AI thread with \(countLabel)"
  }

  private func openClawContextPointer(
    for run: AgentRunItem,
    requiresExistingRecord: Bool
  ) -> OpenClawContextPointer? {
    guard let corpusRoot else {
      statusText = "No corpus selected"
      return nil
    }
    let relativePath = ".org2/runs/\(run.id).org2"
    let recordURL = corpusRoot.appendingPathComponent(relativePath).standardizedFileURL
    if requiresExistingRecord, !FileManager.default.fileExists(atPath: recordURL.path) {
      errorText = "The run record could not be found at \(relativePath)."
      statusText = "Run record missing"
      return nil
    }

    let title = Org2Display.cleanInline(run.goal)
    return OpenClawContextPointer(
      kind: "agent run",
      displayTitle: title,
      reference: "\(mappedPathForOpenClaw(recordURL.path)):1",
      displayReference: "\(relativePath):1",
      threadTitle: "Run: \(title)"
    )
  }

  private func openClawContextPointer(for item: ApprovalItem) -> OpenClawContextPointer {
    let title = Org2Display.cleanInline(item.title)
    return OpenClawContextPointer(
      kind: item.isRunApproval ? "run approval" : "approval item",
      displayTitle: title,
      reference: "\(mappedPathForOpenClaw(item.file)):\(item.line)",
      displayReference: "\(relativePath(item.file)):\(item.line)",
      threadTitle: "Approval: \(title)"
    )
  }

  private func openClawContextPointer(for file: CorpusFile) -> OpenClawContextPointer {
    let title = Self.titleFromFileStem(URL(fileURLWithPath: file.path).deletingPathExtension().lastPathComponent)
    return OpenClawContextPointer(
      kind: "selected file",
      displayTitle: title,
      reference: "\(mappedPathForOpenClaw(file.path)):1",
      displayReference: "\(file.relativePath):1",
      threadTitle: "File: \(title)"
    )
  }

  private func openClawContextPointer(for location: WorkspaceLocation) -> OpenClawContextPointer {
    let kind: String
    switch location {
    case .agenda:
      kind = "agenda item"
    case .assigned:
      kind = "assigned agenda item"
    case .search:
      kind = "search result"
    case .backlink:
      kind = "backlink"
    case .openClaw:
      kind = "selected page"
    case .meeting:
      kind = "meeting"
    }
    let title = openClawReadableContextTitle(
      location.title,
      file: location.file,
      generic: "Selected item"
    )
    return OpenClawContextPointer(
      kind: kind,
      displayTitle: title,
      reference: "\(mappedPathForOpenClaw(location.file)):\(location.lineForEditor)",
      displayReference: "\(relativePath(location.file)):\(location.lineForEditor)",
      threadTitle: "Ask: \(title)"
    )
  }

  private func openClawContextPointerForCurrentSelection() -> OpenClawContextPointer? {
    if let selectedBlock,
       let pointer = openClawContextPointer(for: OpenClawBlockContextPointer(source: selectedEntrySource, block: selectedBlock)) {
      return pointer
    }

    if let source = selectedEntrySource {
      let kind = source.isSubtree ? "selected entry" : "selected page"
      let fallbackTitle = selectedLocation?.title ?? Self.titleFromFileStem(URL(fileURLWithPath: source.file).deletingPathExtension().lastPathComponent)
      let title = openClawContextDisplayTitle(for: source, fallback: fallbackTitle, generic: source.isSubtree ? "Selected entry" : "Selected page")
      return OpenClawContextPointer(
        kind: kind,
        displayTitle: title,
        reference: "\(mappedPathForOpenClaw(source.file)):\(source.startLine)",
        displayReference: "\(relativePath(source.file)):\(source.startLine)",
        threadTitle: "Ask: \(title)"
      )
    }

    if let location = selectedLocation {
      return openClawContextPointer(for: location)
    }

    return nil
  }

  private func currentOpenClawResourceReference() -> OpenClawResourceReference? {
    guard let location = selectedLocation else { return nil }
    let file = URL(fileURLWithPath: location.file).standardizedFileURL.path
    if let rawID = location.idValue?.trimmingCharacters(in: .whitespacesAndNewlines),
       !rawID.isEmpty {
      return OpenClawResourceReference(
        key: "id:\(rawID)",
        kind: .heading,
        title: location.title,
        file: file,
        line: location.lineForEditor,
        idValue: rawID
      )
    }
    guard location.lineForEditor <= 1 else { return nil }
    return OpenClawResourceReference(
      key: "file:\(file)",
      kind: .file,
      title: location.title,
      file: file,
      line: 1
    )
  }

  private func openClawContextPointer(for block: OpenClawBlockContextPointer?) -> OpenClawContextPointer? {
    guard let block else { return nil }
    let startLine = max(1, block.startLine)
    let endLineInclusive = max(startLine, block.endLineExclusive - 1)
    let mappedFile = mappedPathForOpenClaw(block.file)
    let displayFile = relativePath(block.file)
    let reference: String
    let displayReference: String
    if endLineInclusive > startLine {
      reference = "\(mappedFile):\(startLine)-\(endLineInclusive)"
      displayReference = "\(displayFile):\(startLine)-\(endLineInclusive)"
    } else {
      reference = "\(mappedFile):\(startLine)"
      displayReference = "\(displayFile):\(startLine)"
    }
    return OpenClawContextPointer(
      kind: "selected block",
      displayTitle: block.displayTitle,
      reference: reference,
      displayReference: displayReference,
      threadTitle: "Ask: \(block.displayTitle)"
    )
  }

  private func addOpenClawContext(_ pointer: OpenClawContextPointer, threadMode: OpenClawThreadMode) {
    let injectedContext = injectedOpenClawContext(pointer)
    let hadSelectedThread = selectedOpenClawChatThreadID != nil
    let unthreadedDraft = hadSelectedThread ? "" : openClawDraft
    if !canReuseOpenClawContextDraftThread(mode: threadMode) {
      prepareOpenClawThread(
        mode: threadMode,
        title: pointer.threadTitle,
        statusText: "New OpenClaw context chat"
      )
    }
    let previousDraft = currentOpenClawDraftForSelectedThread()
    let draftToAppend = previousDraft.isEmpty ? unthreadedDraft : previousDraft
    var nextDraft = previousDraft
    if previousDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      nextDraft = injectedContext + draftToAppend
    } else if !draftToAppend.contains(pointer.reference) {
      nextDraft = injectedContext + draftToAppend
    }
    if nextDraft != previousDraft {
      publishOpenClawComposerDraft(nextDraft)
      recordWorkspaceUndo(.openClawDraft(previous: hadSelectedThread ? previousDraft : unthreadedDraft, next: nextDraft))
    }

    setOpenClawAssistantPanelPresented(true)
    let runtimeTitle = selectedAIChatRuntime.title
    openClawStatusText = "Added \(pointer.displayReference) to \(runtimeTitle)"
    statusText = "Added \(pointer.displayReference) to \(runtimeTitle)"
  }

  private func injectedOpenClawContext(_ pointer: OpenClawContextPointer) -> String {
    let displayTitle = pointer.displayTitle
      .replacingOccurrences(of: "\n", with: " ")
      .replacingOccurrences(of: "”", with: "'")
      .trimmingCharacters(in: .whitespacesAndNewlines)
    return "Use \(pointer.kind) “\(displayTitle)” at \(pointer.reference) as context.\n\n"
  }

  private func automaticOpenClawActionText(
    _ pointer: OpenClawContextPointer,
    prompt: String,
    userText: String = ""
  ) -> String {
    OpenClawContextPresentation.automaticContext(
      kind: pointer.kind,
      title: pointer.displayTitle,
      reference: pointer.reference,
      prompt: prompt,
      userText: userText
    )
  }

  private func openClawContextDisplayTitle(
    for source: EntrySource,
    fallback: String,
    generic: String
  ) -> String {
    if let heading = OrgEntryRenderer.parseEditable(source.text, baseLine: source.startLine).compactMap({ block -> String? in
      guard case .heading(let heading) = block.rendered else { return nil }
      return heading.title
    }).first {
      return openClawReadableContextTitle(heading, file: source.file, generic: generic)
    }
    return openClawReadableContextTitle(fallback, file: source.file, generic: generic)
  }

  private func openClawReadableContextTitle(_ rawTitle: String, file _: String, generic: String) -> String {
    let firstLine = rawTitle.split(separator: "\n", omittingEmptySubsequences: true).first.map(String.init) ?? rawTitle
    let title = firstLine.trimmingCharacters(in: .whitespacesAndNewlines)
    let titleStem = URL(fileURLWithPath: title).deletingPathExtension().lastPathComponent
    guard !title.isEmpty,
          UUID(uuidString: titleStem) == nil
    else { return generic }
    return title.count > 64 ? String(title.prefix(61)) + "…" : title
  }

  func resolvedOpenClawContext(_ context: OpenClawPresentedContext) -> OpenClawPresentedContext {
    guard context.usesGenericTitle else { return context }
    let reference = OpenClawFileReference(path: context.reference, line: nil)
    guard let path = localPathForOpenClawReference(reference.path) else { return context }
    let url = URL(fileURLWithPath: path).standardizedFileURL
    let stem = url.deletingPathExtension().lastPathComponent
    let fallback = UUID(uuidString: stem) == nil ? Self.titleFromFileStem(stem) : context.title
    guard let prefix = try? Self.readPrefix(url, maxBytes: 256 * 1024) else { return context }
    let title = Self.openClawTitle(from: prefix, fallback: fallback).title
      .trimmingCharacters(in: .whitespacesAndNewlines)
    guard !title.isEmpty, title.localizedCaseInsensitiveCompare(context.title) != .orderedSame else {
      return context
    }
    return OpenClawPresentedContext(
      kind: context.kind,
      title: title.count > 96 ? String(title.prefix(93)) + "…" : title,
      reference: context.reference,
      sourceLine: context.sourceLine,
      automaticPrompt: context.automaticPrompt
    )
  }

  func openOpenClawContext(_ context: OpenClawPresentedContext) {
    openChatFileReference(OpenClawFileReference(path: context.reference, line: nil))
  }

  private func canReuseOpenClawContextDraftThread(mode: OpenClawThreadMode) -> Bool {
    guard mode == .newThread,
          let thread = selectedOpenClawChatThread,
          thread.messages.isEmpty
    else { return false }
    return !OpenClawContextPresentation(currentOpenClawDraftForSelectedThread()).contexts.isEmpty
  }

  private func mappedPathForOpenClaw(_ path: String) -> String {
    guard let corpusRoot,
          let remoteRoot = effectiveOpenClawRemoteCorpusPath().map(Self.trimTrailingSlashes)
    else {
      return path
    }

    let localRoot = Self.trimTrailingSlashes(corpusRoot.standardizedFileURL.path)
    if path == localRoot {
      return remoteRoot
    }
    if path.hasPrefix(localRoot + "/") {
      return remoteRoot + "/" + String(path.dropFirst(localRoot.count + 1))
    }
    return path
  }

  public var openClawContextRootText: String {
    effectiveOpenClawRemoteCorpusPath() ?? "Remote org2 root not configured"
  }

  private static func restoreAgendaMode(from defaults: UserDefaults, key: String) -> AgendaMode {
    guard let rawValue = defaults.string(forKey: key),
          let mode = AgendaMode(rawValue: rawValue)
    else {
      return .focus
    }
    return mode
  }

  private func migrateLegacyDefaultsIfNeeded(
    legacyDomains: [String],
    defaultOpenClawEndpoint: String
  ) {
    guard !legacyDomains.isEmpty,
          defaults.object(forKey: legacyDefaultsMigrationKey) == nil
    else {
      return
    }

    let keys = [
      corpusKey,
      agendaModeKey,
      openClawEndpointKey,
      openClawAgentKey,
      agentHandoffAssigneeKey,
      personalAssigneeNamesKey,
      openClawRemoteCorpusPathKey,
      openClawBriefsStartNewThreadKey,
      orgCryptEncryptOnSaveKey,
      orgCryptRecipientsKey,
      orgCryptRecipientFilesKey,
      orgCryptUseDefaultGpgKeyKey,
      orgCryptUseDefaultGpgKeyMigrationKey,
      orgCryptGpgProgramKey
    ]
    let defaultValues: [String: AnyHashable] = [
      openClawEndpointKey: defaultOpenClawEndpoint,
      openClawAgentKey: "main",
      agentHandoffAssigneeKey: Self.defaultAgentHandoffAssignee,
      personalAssigneeNamesKey: "",
      openClawRemoteCorpusPathKey: "",
      openClawBriefsStartNewThreadKey: true,
      orgCryptGpgProgramKey: "gpg"
    ]

    var migratedAny = false
    for domain in legacyDomains {
      guard let legacyDefaults = UserDefaults(suiteName: domain) else { continue }
      for key in keys {
        guard let value = legacyDefaults.object(forKey: key),
              shouldMigrateDefaultValue(forKey: key, defaultValues: defaultValues)
        else {
          continue
        }
        defaults.set(value, forKey: key)
        migratedAny = true
      }
    }

    defaults.set(true, forKey: legacyDefaultsMigrationKey)
    if migratedAny {
      defaults.synchronize()
    }
  }

  private func shouldMigrateDefaultValue(
    forKey key: String,
    defaultValues: [String: AnyHashable]
  ) -> Bool {
    guard let currentValue = defaults.object(forKey: key) else { return true }
    guard let defaultValue = defaultValues[key] else { return false }
    if let currentString = currentValue as? String,
       let defaultString = defaultValue.base as? String {
      return currentString == defaultString
    }
    if let currentBool = currentValue as? Bool,
       let defaultBool = defaultValue.base as? Bool {
      return currentBool == defaultBool
    }
    return false
  }

  private static func shouldIgnoreStandardDefaultsForTests(_ defaults: UserDefaults) -> Bool {
    NSClassFromString("XCTestCase") != nil
      && defaults === UserDefaults.standard
  }

  nonisolated static func shouldMigrateLegacyDefaults(bundleIdentifier: String?) -> Bool {
    guard let bundleIdentifier, !bundleIdentifier.isEmpty else { return true }
    return bundleIdentifier == "org.org2.workspace"
  }

  nonisolated private static func shouldMigrateLegacyDefaultsForCurrentBundle(bundle: Bundle = .main) -> Bool {
    shouldMigrateLegacyDefaults(bundleIdentifier: bundle.bundleIdentifier)
  }

  private func restoreCorpusRoot() -> URL? {
    guard !Self.shouldIgnoreStandardDefaultsForTests(defaults) else {
      return nil
    }

    if let saved = restoreSavedCorpusRoot() {
      return saved
    }

    return mountedCorpora
      .first(where: { isDirectory($0.path) })
      .map { URL(fileURLWithPath: $0.path).standardizedFileURL }
  }

  private func restoreSavedCorpusRoot() -> URL? {
    guard let saved = defaults.string(forKey: corpusKey), isDirectory(saved) else {
      return nil
    }
    return URL(fileURLWithPath: saved).standardizedFileURL
  }

  private func restoreOpenClawRemoteCorpusPath(for root: URL) -> String {
    let path = root.standardizedFileURL.path
    if let paths = defaults.dictionary(forKey: openClawRemoteCorpusPathsByCorpusKey) as? [String: String],
       let configured = paths[path] {
      return configured
    }
    // The pre-mount setting belonged to the single saved corpus. Reuse it only
    // for that exact path; a newly mounted corpus must never inherit it.
    if defaults.string(forKey: corpusKey).map({ URL(fileURLWithPath: $0).standardizedFileURL.path }) == path {
      return defaults.string(forKey: openClawRemoteCorpusPathKey) ?? ""
    }

    // Early multi-corpus builds could persist the mount list without ever
    // writing corpusRoot. If there is exactly one established mount, the old
    // single-corpus OpenClaw path can only belong to that corpus. Promote it to
    // the per-corpus map so later mounts never inherit it.
    let legacyRemotePath = defaults.string(forKey: openClawRemoteCorpusPathKey)?
      .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    if defaults.string(forKey: corpusKey) == nil,
       !legacyRemotePath.isEmpty,
       mountedCorpora.count == 1,
       mountedCorpora[0].path == path {
      var paths = defaults.dictionary(forKey: openClawRemoteCorpusPathsByCorpusKey) as? [String: String] ?? [:]
      paths[path] = legacyRemotePath
      defaults.set(paths, forKey: openClawRemoteCorpusPathsByCorpusKey)
      return legacyRemotePath
    }
    return ""
  }

  private func currentOpenClawSettings(allowKeychainRead: Bool = false) -> OpenClawGatewaySettings {
    if allowKeychainRead,
       openClawBearerToken == nil,
       openClawHasStoredToken {
      openClawBearerToken = OpenClawKeychain.readToken(allowUserInteraction: true)
      openClawHasStoredToken = openClawBearerToken != nil || OpenClawKeychain.containsToken()
    }

    return OpenClawGatewaySettings.resolve(
      userEndpoint: openClawEndpointText,
      userBearerToken: openClawBearerToken
    )
  }

  private func openClawSettings(
    forDestinationID destinationID: String,
    allowKeychainRead: Bool = false
  ) -> OpenClawGatewaySettings {
    guard destinationID != AIChatDestinationConfiguration.openClawID,
          let destination = aiChatDestination(id: destinationID),
          destination.adapter == .openClaw
    else {
      return currentOpenClawSettings(allowKeychainRead: allowKeychainRead)
    }
    let token = allowKeychainRead
      ? AIChatDestinationCredentials.readToken(
          destinationID: destinationID,
          allowUserInteraction: true
        )
      : nil
    return OpenClawGatewaySettings.resolve(
      userEndpoint: destination.endpoint,
      userBearerToken: token
    )
  }

  private func currentOrgCryptSettings(allowKeychainRead: Bool = false) -> OrgCryptSettings {
    let passphrase = allowKeychainRead
      ? OrgCryptKeychain.readPassphrase(allowUserInteraction: true)
      : nil
    if allowKeychainRead {
      orgCryptHasStoredPassphrase = passphrase != nil || OrgCryptKeychain.containsPassphrase()
    }

    return OrgCryptSettings(
      encryptOnSave: orgCryptEncryptOnSave,
      recipients: OrgCryptSettings.splitListText(orgCryptRecipientsText),
      recipientFiles: OrgCryptSettings.splitListText(orgCryptRecipientFilesText),
      gpgProgram: orgCryptGpgProgram,
      passphrase: passphrase,
      useDefaultGpgKey: orgCryptUseDefaultGpgKey
    )
  }

  private func encryptOrgCryptSubtreesAfterExplicitSave(file: String) async throws -> Int {
    let settings = currentOrgCryptSettings(allowKeychainRead: true)
    guard settings.encryptOnSave else { return 0 }

    return try await Task.detached(priority: .userInitiated) {
      let url = URL(fileURLWithPath: file)
      let raw = try String(contentsOf: url, encoding: .utf8)
      let result = try OrgCrypt.encryptPlaintextCryptSubtrees(in: raw, file: file, settings: settings)
      guard result.encryptedCount > 0, result.text != raw else { return 0 }
      try result.text.write(to: url, atomically: true, encoding: .utf8)
      return result.encryptedCount
    }.value
  }

  @discardableResult
  private func persistOpenClawTranscript() -> Bool {
    openClawTranscriptPersistenceGeneration &+= 1
    deferredOpenClawTranscriptPersistenceTask?.cancel()
    deferredOpenClawTranscriptPersistenceTask = nil
    return persistOpenClawTranscriptNow()
  }

  @discardableResult
  private func persistOpenClawTranscriptNow() -> Bool {
    do {
      if let openClawTranscriptSaverForTesting {
        try openClawTranscriptSaverForTesting()
        return true
      }
      try Self.saveOpenClawTranscript(
        OpenClawTranscriptState(
          threads: openClawChatThreads,
          selectedThreadID: selectedOpenClawChatThreadID,
          settlementSettings: openClawThreadSettlementSettings
        ),
        to: openClawTranscriptURL
      )
      return true
    } catch {
      errorText = "OpenClaw transcript save failed: \(error.localizedDescription)"
      return false
    }
  }

  private func scheduleOpenClawTranscriptPersistenceAfterInteraction() {
    openClawTranscriptPersistenceGeneration &+= 1
    let generation = openClawTranscriptPersistenceGeneration
    deferredOpenClawTranscriptPersistenceTask?.cancel()
    deferredOpenClawTranscriptPersistenceTask = Task { @MainActor [weak self] in
      guard let self else { return }
      do {
        try await Task.sleep(nanoseconds: self.openClawTranscriptPersistenceDelayNanoseconds)
      } catch {
        return
      }
      guard !Task.isCancelled else { return }
      if let openClawTranscriptSaverForTesting = self.openClawTranscriptSaverForTesting {
        do {
          try openClawTranscriptSaverForTesting()
        } catch {
          self.errorText = "OpenClaw transcript save failed: \(error.localizedDescription)"
        }
        if generation == self.openClawTranscriptPersistenceGeneration {
          self.deferredOpenClawTranscriptPersistenceTask = nil
        }
        return
      }
      let transcript = OpenClawTranscriptState(
        threads: self.openClawChatThreads,
        selectedThreadID: self.selectedOpenClawChatThreadID,
        settlementSettings: self.openClawThreadSettlementSettings
      )
      let transcriptURL = self.openClawTranscriptURL
      do {
        let data = try await Task.detached(priority: .utility) {
          try Self.encodedOpenClawTranscript(transcript)
        }.value
        guard !Task.isCancelled,
              generation == self.openClawTranscriptPersistenceGeneration
        else {
          return
        }
        try Self.writeOpenClawTranscriptData(data, to: transcriptURL)
        self.deferredOpenClawTranscriptPersistenceTask = nil
      } catch is CancellationError {
        return
      } catch {
        guard generation == self.openClawTranscriptPersistenceGeneration else { return }
        self.deferredOpenClawTranscriptPersistenceTask = nil
        self.errorText = "OpenClaw transcript save failed: \(error.localizedDescription)"
      }
    }
  }

  public func flushDeferredAIChatTranscriptPersistence() {
    guard deferredOpenClawTranscriptPersistenceTask != nil else { return }
    persistOpenClawTranscript()
  }

  private func persistSelectedAIChatThread() {
    let transcriptPath = openClawTranscriptURL.standardizedFileURL.path
    var selections = defaults.dictionary(forKey: selectedAIChatThreadsByTranscriptKey)
      as? [String: String] ?? [:]
    if let selectedOpenClawChatThreadID {
      selections[transcriptPath] = selectedOpenClawChatThreadID.uuidString.lowercased()
    } else {
      selections.removeValue(forKey: transcriptPath)
    }
    defaults.set(selections, forKey: selectedAIChatThreadsByTranscriptKey)
  }

  private func restoredSelectedAIChatThreadID() -> UUID? {
    let transcriptPath = openClawTranscriptURL.standardizedFileURL.path
    guard let selections = defaults.dictionary(forKey: selectedAIChatThreadsByTranscriptKey)
      as? [String: String],
          let rawID = selections[transcriptPath]
    else {
      return nil
    }
    return UUID(uuidString: rawID)
  }

  private func switchOpenClawTranscript(to url: URL, migrationSource: URL? = nil) {
    guard !usesFixedOpenClawTranscriptURL else { return }
    let targetURL = url.standardizedFileURL
    let previousURL = openClawTranscriptURL.standardizedFileURL
    guard targetURL.path != previousURL.path else { return }
    flushDeferredAIChatTranscriptPersistence()

    let transcript: OpenClawTranscriptState
    let shouldPersistMigratedMessages: Bool
    if FileManager.default.fileExists(atPath: targetURL.path) {
      let hasInFlightTurn = aiChatSendOriginsByThreadID.values.contains {
        $0.transcriptURL.standardizedFileURL.path == targetURL.path
      }
      transcript = Self.loadOpenClawTranscript(
        from: targetURL,
        marksInterruptedSends: !hasInFlightTurn
      )
      shouldPersistMigratedMessages = false
    } else if let migrationSource,
              migrationSource.standardizedFileURL.path != targetURL.path {
      transcript = Self.loadOpenClawTranscript(from: migrationSource.standardizedFileURL)
      shouldPersistMigratedMessages = !transcript.threads.isEmpty
    } else if previousURL.path == appOpenClawTranscriptURL.standardizedFileURL.path,
              !openClawMessages.isEmpty {
      transcript = Self.openClawTranscriptState(fromLegacyMessages: openClawMessages)
      shouldPersistMigratedMessages = true
    } else {
      transcript = OpenClawTranscriptState(
        threads: [],
        selectedThreadID: nil,
        settlementSettings: OpenClawThreadSettlementSettings()
      )
      shouldPersistMigratedMessages = false
    }

    openClawTranscriptURL = targetURL
    openClawSessionKey = Self.makeOpenClawSessionKey(agentID: openClawAgentID)
    cancelAllOpenClawPendingTurnRecovery()
    syncSelectedOpenClawSendState()
    applyOpenClawTranscript(transcript, shouldPersist: shouldPersistMigratedMessages)
  }

  private func replaceOpenClawMessages(_ messages: [OpenClawChatMessage], shouldPersist: Bool) {
    let previousPersistence = shouldPersistOpenClawMessages
    shouldPersistOpenClawMessages = false
    isApplyingOpenClawThreadMessages = true
    openClawMessages = messages
    isApplyingOpenClawThreadMessages = false
    shouldPersistOpenClawMessages = previousPersistence
    if shouldPersist {
      updateSelectedOpenClawChatThread(messages: messages)
      persistOpenClawTranscript()
    }
  }

  private func applyOpenClawTranscript(_ transcript: OpenClawTranscriptState, shouldPersist: Bool) {
    openClawThreadSettlementSettings = transcript.settlementSettings
    let migratedThreads = transcript.threads.map { thread in
      var migrated = thread
      if let destinationID = Self.recoveredNamedCodexDestinationID(
        for: thread,
        destinations: aiChatDestinations
      ) {
        migrated = migrated.replacingOpenClawChatMetadata(destinationID: destinationID)
      }
      if aiChatDestination(id: migrated.destinationID)?.adapter == .openClaw {
        let sessionKey = Self.agentScopedOpenClawSessionKey(
          migrated.sessionKey,
          agentID: openClawAgentID
        )
        if sessionKey != migrated.sessionKey {
          migrated = migrated.replacingOpenClawChatMetadata(sessionKey: sessionKey)
        }
      }
      return migrated
    }
    let migratedThreadMetadata = zip(transcript.threads, migratedThreads).contains { pair in
      pair.0.sessionKey != pair.1.sessionKey
        || pair.0.destinationID != pair.1.destinationID
    }
    openClawChatThreads = Self.sortedOpenClawChatThreadsForDisplay(migratedThreads)
    let selectedID = [restoredSelectedAIChatThreadID(), transcript.selectedThreadID]
      .compactMap { $0 }
      .first { id in openClawChatThreads.contains(where: { $0.id == id }) }
      ?? openClawChatThreads.first?.id
    selectedOpenClawChatThreadID = selectedID
    let autoSettledIDs = autoSettleOpenClawChatThreads(shouldPersist: false)
    let threads = openClawChatThreads
    for thread in threads {
      let messageIDs = thread.messages.compactMap { message in
        message.role == .user && message.deliveryStatus == .sending ? message.id : nil
      }
      if messageIDs.isEmpty {
        if !drainingOpenClawThreadIDs.contains(thread.id) {
          openClawPendingUserMessageIDsByThreadID.removeValue(forKey: thread.id)
        }
      } else {
        openClawPendingUserMessageIDsByThreadID[thread.id] = messageIDs
      }
    }
    let selectedThread = selectedID.flatMap { id in threads.first(where: { $0.id == id }) }
    openClawSessionKey = selectedThread?.sessionKey ?? Self.makeOpenClawSessionKey(agentID: openClawAgentID)
    replaceOpenClawMessages(selectedThread?.messages ?? [], shouldPersist: false)
    syncSelectedOpenClawSendState()
    if let selectedThread {
      openClawStatusText = isSendingOpenClawMessage
        ? "\(aiChatDestinationTitle(selectedThread.destinationID)) is working"
        : selectedThread.runtime == .codex
          ? "Ready for a Codex message"
          : aiChatDestination(id: selectedThread.destinationID)?.adapter == .openClaw
            ? Self.openClawStatusText(settings: currentOpenClawSettings())
            : "Ready for a \(aiChatDestinationTitle(selectedThread.destinationID)) message"
    } else {
      openClawStatusText = Self.openClawStatusText(settings: currentOpenClawSettings())
    }
    if shouldPersist || migratedThreadMetadata || !autoSettledIDs.isEmpty {
      persistOpenClawTranscript()
    }
  }

  nonisolated static func recoveredNamedCodexDestinationID(
    for thread: OpenClawChatThread,
    destinations: [AIChatDestinationConfiguration]
  ) -> String? {
    guard !thread.isSharedRoom,
          thread.runtime == .codex,
          thread.destinationID == AIChatDestinationConfiguration.localCodexID
    else { return nil }
    let namedCodexIDs = Set<String>(destinations.compactMap { destination -> String? in
      guard destination.isEnabled,
            destination.runtime == .codex,
            destination.id != AIChatDestinationConfiguration.localCodexID
      else { return nil }
      return destination.id
    })
    return thread.messages.lazy.compactMap { message in
      guard message.role == .user,
            let targetDestinationID = message.targetDestinationID,
            namedCodexIDs.contains(targetDestinationID)
      else { return nil }
      return targetDestinationID
    }.first
  }

  private func restoreInterruptedOpenClawSendStatusIfNeeded() {
    let interruptedCount = openClawMessages.filter {
      $0.role == .user && $0.deliveryStatus == .interrupted
    }.count
    guard interruptedCount > 0 else { return }
    let runtime = selectedAIChatRuntime.title
    openClawStatusText = interruptedCount == 1
      ? "\(runtime) response interrupted; retry the message"
      : "\(interruptedCount) \(runtime) responses interrupted; retry the messages"
  }

  private func renderEntrySource(_ source: EntrySource, generation: Int) {
    if URL(fileURLWithPath: source.file).pathExtension.lowercased() == "csv" {
      entryHTMLRenderGeneration += 1
      entryHTMLRenderTask?.cancel()
      entryHTMLRenderTask = nil
      entryHTMLRenderWatchdogTask?.cancel()
      entryHTMLRenderWatchdogTask = nil
      selectedEntryHTML = nil
      selectedEntryRenderError = nil
      selectedEntryHTMLRenderKey = nil
      selectedRenderedBlocks = []
      selectedBlockID = nil
      isRenderingEntrySource = false
      return
    }

    let renderKey = entryHTMLRenderKey(for: source)
    if selectedEntryHTMLRenderKey != renderKey {
      prepareEntryHTML(for: source)
    }
    entryHTMLRenderGeneration += 1
    let renderGeneration = entryHTMLRenderGeneration
    isRenderingEntrySource = true
    selectedEntryRenderError = nil
    scheduleEntryHTMLRenderWatchdog(
      for: source,
      generation: generation,
      renderGeneration: renderGeneration
    )

    let cachedHTML = renderedHTMLCache[renderKey]?.html
    if let cachedHTML {
      renderedHTMLCacheOrder.removeAll { $0 == renderKey }
      renderedHTMLCacheOrder.append(renderKey)
      selectedEntryHTML = cachedHTML
      selectedEntryHTMLRenderKey = renderKey
    }

    let renderIdleDelay = cachedHTML == nil && selectedSurface == .agenda
      ? agendaEntryRenderIdleDelayNanoseconds
      : 0
    entryHTMLRenderTask?.cancel()
    entryHTMLRenderTask = Task { @MainActor [weak self] in
      guard let self else { return }
      if renderIdleDelay > 0 {
        do {
          try await Task.sleep(nanoseconds: renderIdleDelay)
        } catch {
          return
        }
        guard generation == self.entrySourceLoadGeneration,
              renderGeneration == self.entryHTMLRenderGeneration,
              self.selectedEntrySource?.id == source.id,
              self.selectedEntryHTMLRenderKey == renderKey
        else {
          return
        }
      }
      if cachedHTML == nil {
        do {
          let sourceLineOffset = max(0, source.startLine - 1)
          let stylesheetPath = self.appHTMLStylesheetPath
          let html: String
          if let testRenderer = self.entryHTMLRendererForTesting {
            html = try await testRenderer(source.text, source.file, sourceLineOffset, stylesheetPath)
          } else {
            html = try await self.cli.renderAppHTML(
              source.text,
              sourcePath: source.file,
              sourceLineOffset: sourceLineOffset,
              stylesheetPath: stylesheetPath
            )
          }
          guard generation == self.entrySourceLoadGeneration,
                renderGeneration == self.entryHTMLRenderGeneration,
                self.selectedEntrySource?.id == source.id,
                self.selectedEntryHTMLRenderKey == renderKey
          else {
            return
          }
          let presentedHTML = Self.applyingPropertyDrawerDefault(
            to: html,
            expanded: self.propertyDrawersExpandedByDefault
          )
          self.cacheRenderedHTML(presentedHTML, key: renderKey)
          self.selectedEntryHTML = presentedHTML
          self.selectedEntryRenderError = nil
        } catch {
          guard generation == self.entrySourceLoadGeneration,
                renderGeneration == self.entryHTMLRenderGeneration,
                self.selectedEntrySource?.id == source.id,
                self.selectedEntryHTMLRenderKey == renderKey
          else {
            return
          }
          self.selectedEntryHTML = nil
          self.selectedEntryRenderError = error.localizedDescription
        }
      }

      let modifiedAt = Self.modificationDate(for: URL(fileURLWithPath: source.file).standardizedFileURL)
      let blocks: [OrgEditableBlock]
      if let cachedBlocks = self.cachedRenderedBlocks(for: source, modifiedAt: modifiedAt) {
        blocks = cachedBlocks
      } else {
        blocks = await Task.detached(priority: .utility) {
          OrgEntryRenderer.parseEditable(source.text, baseLine: source.startLine)
        }.value
      }
      guard generation == self.entrySourceLoadGeneration,
            renderGeneration == self.entryHTMLRenderGeneration,
            self.selectedEntrySource?.id == source.id,
            self.selectedEntryHTMLRenderKey == renderKey
      else {
        return
      }
      if self.cachedRenderedBlocks(for: source, modifiedAt: modifiedAt) == nil {
        self.cacheRenderedBlocks(blocks, for: source, modifiedAt: modifiedAt)
      }
      self.applyRenderedBlocks(blocks, for: source)
      self.entryHTMLRenderWatchdogTask?.cancel()
      self.entryHTMLRenderWatchdogTask = nil
      self.entryHTMLRenderTask = nil
      self.isRenderingEntrySource = false
    }
  }

  private func scheduleEntryHTMLRenderWatchdog(
    for source: EntrySource,
    generation: Int,
    renderGeneration: Int
  ) {
    entryHTMLRenderWatchdogTask?.cancel()
    let timeout = entryHTMLRenderTimeoutNanoseconds
    entryHTMLRenderWatchdogTask = Task { @MainActor [weak self] in
      do {
        try await Task.sleep(nanoseconds: timeout)
      } catch {
        return
      }
      guard let self,
            generation == self.entrySourceLoadGeneration,
            renderGeneration == self.entryHTMLRenderGeneration,
            self.selectedEntrySource?.id == source.id,
            self.selectedEntryHTML == nil,
            self.selectedEntryRenderError == nil,
            self.isRenderingEntrySource
      else { return }

      self.entryHTMLRenderGeneration += 1
      self.entryHTMLRenderTask?.cancel()
      self.entryHTMLRenderTask = nil
      self.entryHTMLRenderWatchdogTask = nil
      self.isRenderingEntrySource = false
      let seconds = max(1, Int(ceil(Double(timeout) / 1_000_000_000)))
      let message = "Preview rendering timed out after \(seconds) seconds. Retry to render the file again."
      self.selectedEntryRenderError = message
      self.statusText = "Preview rendering timed out"
      self.errorText = message
    }
  }

  private var appHTMLStylesheetPath: String? {
    guard let corpusRoot else { return nil }
    let candidates = [
      corpusRoot.appendingPathComponent(".org2/app.css"),
      corpusRoot.appendingPathComponent("org2-app.css")
    ]
    return candidates.first { FileManager.default.fileExists(atPath: $0.path) }?.path
  }

  public var hasAppHTMLStylesheet: Bool {
    appHTMLStylesheetPath != nil
  }

  public func openAppHTMLStylesheet() {
    guard let corpusRoot else {
      statusText = "Open a corpus before customizing document styles"
      return
    }
    let stylesheetURL = corpusRoot.appendingPathComponent(".org2/app.css")
    do {
      try FileManager.default.createDirectory(
        at: stylesheetURL.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
      if !FileManager.default.fileExists(atPath: stylesheetURL.path) {
        let template = """
        /* OpenOrg document overrides. This file only affects HTML read and preview views. */
        :root {
          /* --org2-content-width: 960px; */
          /* --org2-page-padding: 28px; */
          /* --org2-accent: #2f73b7; */
        }
        """
        try template.write(to: stylesheetURL, atomically: true, encoding: .utf8)
      }
      NSWorkspace.shared.open(stylesheetURL)
      statusText = "Opened .org2/app.css"
    } catch {
      errorText = error.localizedDescription
      statusText = "Could not open document stylesheet"
    }
  }

  public func retrySelectedEntryRendering() {
    guard let source = selectedEntrySource else {
      guard let selectedLocation else { return }
      selectedEntryRenderError = nil
      scheduleEntrySourceLoad(for: selectedLocation)
      return
    }
    let key = entryHTMLRenderKey(for: source)
    renderedHTMLCache.removeValue(forKey: key)
    renderedHTMLCacheOrder.removeAll { $0 == key }
    selectedEntryHTML = nil
    selectedEntryRenderError = nil
    selectedEntryHTMLRenderKey = key
    renderEntrySource(source, generation: entrySourceLoadGeneration)
  }

  private func prepareEntryHTML(for source: EntrySource) {
    let renderKey = entryHTMLRenderKey(for: source)
    guard selectedEntryHTMLRenderKey != renderKey else { return }
    entryHTMLRenderGeneration += 1
    selectedEntryHTML = nil
    selectedEntryRenderError = nil
    selectedEntryHTMLRenderKey = renderKey
    selectedRenderedBlocks = []
    selectedBlockID = nil
  }

  private func cacheRenderedHTML(_ html: String, key: String) {
    renderedHTMLCache[key] = RenderedHTMLCacheEntry(html: html)
    renderedHTMLCacheOrder.removeAll { $0 == key }
    renderedHTMLCacheOrder.append(key)
    while renderedHTMLCacheOrder.count > Self.renderedHTMLCacheLimit {
      let evicted = renderedHTMLCacheOrder.removeFirst()
      renderedHTMLCache.removeValue(forKey: evicted)
    }
  }

  nonisolated static func applyingPropertyDrawerDefault(to html: String, expanded: Bool) -> String {
    let drawer = #"<details class="org2-properties-drawer""#
    let expandedDrawer = drawer + " open"
    let normalized = html.replacingOccurrences(of: expandedDrawer, with: drawer)
    guard expanded else { return normalized }
    return normalized.replacingOccurrences(of: drawer, with: expandedDrawer)
  }

  private func applyPropertyDrawerDefaultToLoadedHTML() {
    let expanded = propertyDrawersExpandedByDefault
    if let selectedEntryHTML {
      self.selectedEntryHTML = Self.applyingPropertyDrawerDefault(to: selectedEntryHTML, expanded: expanded)
    }
    if let sourceEditorPreviewHTML {
      self.sourceEditorPreviewHTML = Self.applyingPropertyDrawerDefault(
        to: sourceEditorPreviewHTML,
        expanded: expanded
      )
    }
    renderedHTMLCache = renderedHTMLCache.mapValues { cached in
      RenderedHTMLCacheEntry(
        html: Self.applyingPropertyDrawerDefault(to: cached.html, expanded: expanded)
      )
    }
  }

  private func entryHTMLRenderKey(for source: EntrySource) -> String {
    let path = URL(fileURLWithPath: source.file).standardizedFileURL.path
    let digest = SHA256.hash(data: Data(source.text.utf8))
      .map { String(format: "%02x", $0) }
      .joined()
    let stylesheetDigest = appHTMLStylesheetPath.map { stylesheetPath in
      let attributes = try? FileManager.default.attributesOfItem(atPath: stylesheetPath)
      let modified = (attributes?[.modificationDate] as? Date)?.timeIntervalSince1970 ?? 0
      let size = attributes?[.size] as? NSNumber
      return "\(stylesheetPath):\(modified):\(size?.int64Value ?? 0)"
    } ?? "default"
    return "\(path)|\(source.startLine)|\(source.endLineExclusive)|\(digest)|\(stylesheetDigest)"
  }

  private func applyRenderedBlocks(_ blocks: [OrgEditableBlock], for source: EntrySource) {
    let visibleBlocks = blocksWithTransientDraft(blocks, for: source)
    if selectedRenderedBlocks != visibleBlocks {
      selectedRenderedBlocks = visibleBlocks
    }
    if let pending = pendingBlockSelection,
       pending.file == source.file {
      let pendingBlock = blockForSelectionLine(pending.line, mode: pending.mode, in: visibleBlocks)
      selectedBlockID = pendingBlock?.id
      pendingBlockSelection = nil
      if pending.beginEditing,
         let pendingBlock,
         pendingBlock.isEditable,
         source.isEditable {
        beginEditingSource(
          for: pendingBlock,
          selection: pending.initialSourceUTF16Offset.map {
            Self.editableSelection(for: pendingBlock, sourceUTF16Offset: $0)
          }
        )
      }
    } else if let selectedBlockID,
       !visibleBlocks.contains(where: { $0.id == selectedBlockID }) {
      self.selectedBlockID = nil
    }
  }

  private func blocksWithTransientDraft(_ blocks: [OrgEditableBlock], for source: EntrySource) -> [OrgEditableBlock] {
    guard let draft = transientDraftBlock, draft.file == source.file else {
      return blocks
    }
    let coveredIDs = Set(draft.coveredBlocks.map(\.id))
    var visibleBlocks = blocks.filter { $0.id != draft.block.id && !coveredIDs.contains($0.id) }
    visibleBlocks.append(draft.block)
    return Self.sortEditableBlocksForDisplay(visibleBlocks)
  }

  private func canonicalDocument(for source: EntrySource) async throws -> Org2CanonicalDocument {
    if source.isSubtree || source.startLine != 1 {
      return try await cli.parseTextJSON(
        source.text,
        sourceRanges: true,
        sourceLineOffset: max(0, source.startLine - 1)
      )
    }

    return try await canonicalDocument(for: source.file)
  }

  private func canonicalDocument(for file: String) async throws -> Org2CanonicalDocument {
    let url = URL(fileURLWithPath: file).standardizedFileURL
    let fileContentDigest = await Task.detached(priority: .utility) {
      Self.fileContentDigest(for: url)
    }.value
    let cacheKey = url.path
    if let fileContentDigest,
       let cached = canonicalDocumentCache[cacheKey],
       cached.fileContentDigest == fileContentDigest {
      touchCanonicalDocumentCacheKey(cacheKey)
      return cached.document
    }

    let document: Org2CanonicalDocument = try await cli.parseFileJSON(url, sourceRanges: true)
    canonicalDocumentCache[cacheKey] = CanonicalDocumentCacheEntry(
      fileContentDigest: fileContentDigest,
      document: document
    )
    touchCanonicalDocumentCacheKey(cacheKey)
    return document
  }

  private func invalidateCanonicalDocumentCache(for file: String) {
    let cacheKey = URL(fileURLWithPath: file).standardizedFileURL.path
    canonicalDocumentCache.removeValue(forKey: cacheKey)
    canonicalDocumentCacheOrder.removeAll { $0 == cacheKey }
    invalidateEntrySourceCache(for: file)
    invalidateRenderedBlocksCache(for: file)
    invalidateRenderedHTMLCache(for: file)
  }

  private func touchCanonicalDocumentCacheKey(_ key: String) {
    for evicted in WorkspaceCacheRecency.recordAccess(
      key,
      order: &canonicalDocumentCacheOrder,
      limit: Self.canonicalDocumentCacheLimit
    ) {
      canonicalDocumentCache.removeValue(forKey: evicted)
    }
  }

  private func entrySourceCacheKey(for location: WorkspaceLocation, mode: EntrySourceMode) -> String {
    "\(Self.selectionIdentity(for: location))|\(mode.rawValue)"
  }

  private func cacheEntrySource(
    _ source: EntrySource,
    for location: WorkspaceLocation,
    mode: EntrySourceMode,
    modifiedAt: Date?,
    fileContentDigest: String?
  ) {
    let key = entrySourceCacheKey(for: location, mode: mode)
    entrySourceCache[key] = EntrySourceCacheEntry(
      modifiedAt: modifiedAt,
      fileContentDigest: fileContentDigest,
      source: source
    )
    entrySourceCacheOrder.removeAll { $0 == key }
    entrySourceCacheOrder.append(key)

    while entrySourceCacheOrder.count > Self.entrySourceCacheLimit {
      let evicted = entrySourceCacheOrder.removeFirst()
      entrySourceCache.removeValue(forKey: evicted)
    }
  }

  private func cachedEntrySource(for location: WorkspaceLocation, mode: EntrySourceMode) -> EntrySource? {
    let key = entrySourceCacheKey(for: location, mode: mode)
    guard let cached = entrySourceCache[key],
          cached.modifiedAt == Self.modificationDate(for: URL(fileURLWithPath: location.file).standardizedFileURL)
    else {
      return nil
    }
    entrySourceCacheOrder.removeAll { $0 == key }
    entrySourceCacheOrder.append(key)
    return cached.source
  }

  private func cachedEntrySourceMatchesCurrentFileContents(
    for location: WorkspaceLocation,
    mode: EntrySourceMode
  ) async -> Bool {
    let key = entrySourceCacheKey(for: location, mode: mode)
    guard let expectedDigest = entrySourceCache[key]?.fileContentDigest else {
      return false
    }
    let url = URL(fileURLWithPath: location.file).standardizedFileURL
    let currentDigest = await Task.detached(priority: .utility) {
      Self.fileContentDigest(for: url)
    }.value
    return currentDigest == expectedDigest
  }

  private func renderedBlocksCacheKey(for source: EntrySource) -> String {
    let path = URL(fileURLWithPath: source.file).standardizedFileURL.path
    return "\(path)|\(source.startLine)|\(source.endLineExclusive)"
  }

  private func cacheRenderedBlocks(
    _ blocks: [OrgEditableBlock],
    for source: EntrySource,
    modifiedAt: Date?
  ) {
    let key = renderedBlocksCacheKey(for: source)
    renderedBlocksCache[key] = RenderedBlocksCacheEntry(
      modifiedAt: modifiedAt,
      sourceID: source.id,
      textDigest: Self.contentDigest(for: Data(source.text.utf8)),
      blocks: blocks
    )
    renderedBlocksCacheOrder.removeAll { $0 == key }
    renderedBlocksCacheOrder.append(key)

    while renderedBlocksCacheOrder.count > Self.renderedBlocksCacheLimit {
      let evicted = renderedBlocksCacheOrder.removeFirst()
      renderedBlocksCache.removeValue(forKey: evicted)
    }
  }

  private func cachedRenderedBlocks(for source: EntrySource, modifiedAt: Date?) -> [OrgEditableBlock]? {
    let key = renderedBlocksCacheKey(for: source)
    guard let cached = renderedBlocksCache[key],
          cached.modifiedAt == modifiedAt,
          cached.sourceID == source.id,
          cached.textDigest == Self.contentDigest(for: Data(source.text.utf8))
    else {
      return nil
    }
    renderedBlocksCacheOrder.removeAll { $0 == key }
    renderedBlocksCacheOrder.append(key)
    return cached.blocks
  }

  private static func renderedBlocksSignature(for blocks: [OrgEditableBlock]) -> String {
    guard !blocks.isEmpty else { return "empty" }

    var hasher = Hasher()
    hasher.combine(blocks.count)
    for block in blocks {
      hasher.combine(block.id)
      hasher.combine(block.startLine)
      hasher.combine(block.endLineExclusive)
      hasher.combine(block.isEditable)
    }
    return "\(blocks.count):\(hasher.finalize())"
  }

  private static func renderedBlocksMetadata(for blocks: [OrgEditableBlock]) -> RenderedBlocksMetadata {
    guard !blocks.isEmpty else {
      return RenderedBlocksMetadata(renderSignature: "empty", structureSignature: "empty", indexes: [:])
    }

    var renderHasher = Hasher()
    var structureHasher = Hasher()
    renderHasher.combine(blocks.count)
    structureHasher.combine(blocks.count)

    var indexes: [OrgEditableBlock.ID: Int] = [:]
    indexes.reserveCapacity(blocks.count)

    for (index, block) in blocks.enumerated() {
      renderHasher.combine(block.renderIdentity.id)
      renderHasher.combine(block.renderIdentity.startLine)
      renderHasher.combine(block.renderIdentity.endLineExclusive)
      renderHasher.combine(block.renderIdentity.rawUTF8Count)
      renderHasher.combine(block.renderIdentity.rawHash)
      renderHasher.combine(block.renderIdentity.renderedKind)
      renderHasher.combine(block.isEditable)

      structureHasher.combine(block.id)
      structureHasher.combine(block.startLine)
      structureHasher.combine(block.endLineExclusive)
      structureHasher.combine(block.isEditable)

      indexes[block.id] = index
    }

    return RenderedBlocksMetadata(
      renderSignature: "\(blocks.count):\(renderHasher.finalize())",
      structureSignature: "\(blocks.count):\(structureHasher.finalize())",
      indexes: indexes
    )
  }

  nonisolated static func renderedBlocksRenderSignature(for blocks: [OrgEditableBlock]) -> String {
    guard !blocks.isEmpty else { return "empty" }

    var hasher = Hasher()
    hasher.combine(blocks.count)
    for block in blocks {
      hasher.combine(block.renderIdentity.id)
      hasher.combine(block.renderIdentity.startLine)
      hasher.combine(block.renderIdentity.endLineExclusive)
      hasher.combine(block.renderIdentity.rawUTF8Count)
      hasher.combine(block.renderIdentity.rawHash)
      hasher.combine(block.renderIdentity.renderedKind)
      hasher.combine(block.isEditable)
    }
    return "\(blocks.count):\(hasher.finalize())"
  }

  nonisolated static func sourceBlockRunsRenderSignature(for runs: [String: SourceBlockRunState]) -> String {
    guard !runs.isEmpty else { return "empty" }

    var hasher = Hasher()
    hasher.combine(runs.count)
    for key in runs.keys.sorted() {
      guard let state = runs[key] else { continue }
      hasher.combine(key)
      combineSourceBlockRunSignature(state, into: &hasher)
    }
    return "\(runs.count):\(hasher.finalize())"
  }

  nonisolated static func sourceBlockRunRenderSignature(for state: SourceBlockRunState?) -> String? {
    guard let state else { return nil }
    var hasher = Hasher()
    combineSourceBlockRunSignature(state, into: &hasher)
    return hasher.finalize().description
  }

  nonisolated private static func combineSourceBlockRunSignature(
    _ state: SourceBlockRunState,
    into hasher: inout Hasher
  ) {
    hasher.combine(sourceBlockRunStatusSignature(state.status))
    hasher.combine(state.language)
    hasher.combine(state.commandLabel)
    hasher.combine(state.startedAt)
    hasher.combine(state.finishedAt)
    hasher.combine(state.duration)
    hasher.combine(state.exitCode)
    hasher.combine(state.stdout.utf8.count)
    hasher.combine(state.stdout.hashValue)
    hasher.combine(state.stderr.utf8.count)
    hasher.combine(state.stderr.hashValue)
    hasher.combine(state.message)
  }

  nonisolated private static func sourceBlockRunStatusSignature(_ status: SourceBlockRunStatus) -> String {
    switch status {
    case .running: "running"
    case .succeeded: "succeeded"
    case .failed: "failed"
    case .timedOut: "timed-out"
    case .unsupported: "unsupported"
    }
  }

  private static func renderedBlockIndexes(for blocks: [OrgEditableBlock]) -> [OrgEditableBlock.ID: Int] {
    guard !blocks.isEmpty else { return [:] }

    var indexes: [OrgEditableBlock.ID: Int] = [:]
    indexes.reserveCapacity(blocks.count)
    for (index, block) in blocks.enumerated() {
      indexes[block.id] = index
    }
    return indexes
  }

  private func invalidateRenderedBlocksCache(for file: String) {
    let path = URL(fileURLWithPath: file).standardizedFileURL.path + "|"
    let keys = renderedBlocksCache.keys.filter { $0.hasPrefix(path) }
    for key in keys {
      renderedBlocksCache.removeValue(forKey: key)
    }
    renderedBlocksCacheOrder.removeAll { key in
      key.hasPrefix(path)
    }
  }

  private func invalidateRenderedHTMLCache(for file: String) {
    let path = URL(fileURLWithPath: file).standardizedFileURL.path + "|"
    let keys = renderedHTMLCache.keys.filter { $0.hasPrefix(path) }
    for key in keys {
      renderedHTMLCache.removeValue(forKey: key)
    }
    renderedHTMLCacheOrder.removeAll { $0.hasPrefix(path) }
  }

  private func invalidateEntrySourceCache(for file: String) {
    let path = URL(fileURLWithPath: file).standardizedFileURL.path
    let keys = entrySourceCache.keys.filter { $0.contains("\u{1F}\(path)\u{1F}") }
    for key in keys {
      entrySourceCache.removeValue(forKey: key)
    }
    entrySourceCacheOrder.removeAll { key in
      key.contains("\u{1F}\(path)\u{1F}")
    }
  }

  private func currentOpenClawWorkspaceContext(
    localEditTurnID: String? = nil,
    includesNavigationContext: Bool = true,
    threadContinuation: AIChatThreadContinuation? = nil
  ) -> OpenClawWorkspaceContext {
    let source: EntrySource?
    if !includesNavigationContext {
      source = nil
    } else if (isEditingEntry || isLiveFileEditorAvailable), let selectedEntrySource {
      source = EntrySource(
        file: selectedEntrySource.file,
        startLine: selectedEntrySource.startLine,
        endLineExclusive: selectedEntrySource.endLineExclusive,
        text: editableEntryText,
        isSubtree: selectedEntrySource.isSubtree,
        isEditable: selectedEntrySource.isEditable
      )
    } else {
      source = selectedEntrySource
    }

    return OpenClawWorkspaceContext(
      localCorpusRoot: corpusRoot?.standardizedFileURL.path,
      remoteCorpusRoot: effectiveOpenClawRemoteCorpusPath(),
      selectedSurface: includesNavigationContext ? selectedSurface.title : WorkspaceSurface.openClaw.title,
      selectedLocation: includesNavigationContext ? selectedLocation : nil,
      selectedEntrySource: source,
      backlinks: includesNavigationContext ? backlinks : nil,
      agenda: includesNavigationContext ? agenda : nil,
      searchQuery: includesNavigationContext ? searchQuery : "",
      searchResults: includesNavigationContext ? searchResults : [],
      agentThreadDirectories: currentOpenClawAgentThreadDirectories(),
      sourceProfiles: sourceProfiles,
      sourceRuntimeStatuses: sourceRuntimeStatuses,
      localEdit: localEditTurnID.map {
        OpenClawLocalEditWorkspaceContext(
          nodeDisplayName: openClawLocalEditNodeDisplayName,
          turnID: $0
        )
      },
      authorizedCorpora: currentAIChatCorpusContexts(),
      customInstructions: aiChatCustomInstructions,
      threadContinuation: threadContinuation
    )
  }

  /// A conversational turn is scoped to the Org2 chat thread that owns it.
  /// The detail pane can continue showing a file, run, or approval while the
  /// user chats, but that global UI selection must not silently become context
  /// for an established (or unrelated) conversation. Explicit "Ask AI" and
  /// multi-selection context is carried in the user message itself.
  private func threadScopedOpenClawWorkspaceContext(
    for thread: OpenClawChatThread,
    localEditTurnID: String? = nil
  ) -> OpenClawWorkspaceContext {
    currentOpenClawWorkspaceContext(
      localEditTurnID: localEditTurnID,
      includesNavigationContext: false,
      threadContinuation: aiChatThreadContinuation(for: thread)
    )
  }

  private func aiChatThreadContinuation(
    for thread: OpenClawChatThread
  ) -> AIChatThreadContinuation {
    let maxMessages = 24
    let maxMessageCharacters = 4_000
    var remainingCharacters = 24_000
    var messages: [AIChatThreadContinuation.Message] = []

    for message in thread.messages.reversed() {
      guard messages.count < maxMessages, remainingCharacters > 0 else { break }
      var content = message.content.trimmingCharacters(in: .whitespacesAndNewlines)
      if !message.attachments.isEmpty {
        let attachmentText = message.attachments
          .map { "[Attachment: \($0.fileName)]" }
          .joined(separator: "\n")
        content = content.isEmpty ? attachmentText : "\(content)\n\(attachmentText)"
      }
      guard !content.isEmpty else { continue }
      let allowedCharacters = min(maxMessageCharacters, remainingCharacters)
      if content.count > allowedCharacters {
        content = String(content.prefix(allowedCharacters)) + "…"
      }
      messages.append(.init(
        role: message.role.rawValue,
        content: content,
        authorLabel: message.authorLabel
      ))
      remainingCharacters -= content.count
    }

    var references: [String] = []
    var seenPaths = Set<String>()
    func appendReference(_ reference: OpenClawFileReference) {
      guard references.count < 12 else { return }
      let localPath = localPathForOpenClawReference(reference.path) ?? reference.path
      let path = mappedPathForOpenClaw(localPath)
      guard seenPaths.insert(path).inserted else { return }
      references.append(reference.line.map { "\(path):\($0)" } ?? path)
    }

    if let resource = thread.resource {
      appendReference(OpenClawFileReference(path: resource.file, line: resource.line))
    }
    // Only a user's explicit references establish durable thread context.
    // Assistant citations are useful in the transcript, but treating them as
    // attachments lets one mistaken answer contaminate every later turn.
    for message in thread.messages.reversed()
      where message.role == .user && references.count < 12 {
      for reference in OpenClawFileReference.extract(from: message.content, limit: 12) {
        appendReference(reference)
      }
    }

    return AIChatThreadContinuation(
      id: thread.id,
      title: thread.title,
      messages: Array(messages.reversed()),
      org2References: references
    )
  }

  private func workspaceContext(
    _ context: OpenClawWorkspaceContext,
    localEditTurnID: String?
  ) -> OpenClawWorkspaceContext {
    OpenClawWorkspaceContext(
      localCorpusRoot: context.localCorpusRoot,
      remoteCorpusRoot: context.remoteCorpusRoot,
      selectedSurface: context.selectedSurface,
      selectedLocation: context.selectedLocation,
      selectedEntrySource: context.selectedEntrySource,
      backlinks: context.backlinks,
      agenda: context.agenda,
      searchQuery: context.searchQuery,
      searchResults: context.searchResults,
      agentThreadDirectories: context.agentThreadDirectories,
      sourceProfiles: context.sourceProfiles,
      sourceRuntimeStatuses: context.sourceRuntimeStatuses,
      localEdit: localEditTurnID.map {
        OpenClawLocalEditWorkspaceContext(
          nodeDisplayName: openClawLocalEditNodeDisplayName,
          turnID: $0
        )
      },
      authorizedCorpora: context.authorizedCorpora,
      customInstructions: context.customInstructions,
      threadContinuation: context.threadContinuation
    )
  }

  private func currentAIChatCorpusContexts() -> [AIChatCorpusContext] {
    guard let activeRoot = corpusRoot?.standardizedFileURL else { return [] }
    let activePath = activeRoot.path
    var mounts: [WorkspaceCorpusMount]
    if aiChatCorpusAccessScope == .allCorpora {
      mounts = mountedCorpora
    } else {
      mounts = mountedCorpora.filter {
        URL(fileURLWithPath: $0.path).standardizedFileURL.path == activePath
      }
    }
    if !mounts.contains(where: {
      URL(fileURLWithPath: $0.path).standardizedFileURL.path == activePath
    }) {
      mounts.append(
        WorkspaceCorpusMount(
          path: activePath,
          corpusID: activeCorpusIdentity?.id,
          name: activeCorpusIdentity?.name ?? activeRoot.lastPathComponent,
          kind: activeCorpusIdentity?.kind
        )
      )
    }

    let remotePaths = defaults.dictionary(forKey: openClawRemoteCorpusPathsByCorpusKey)
      as? [String: String] ?? [:]
    return mounts.sorted { lhs, rhs in
      let lhsActive = URL(fileURLWithPath: lhs.path).standardizedFileURL.path == activePath
      let rhsActive = URL(fileURLWithPath: rhs.path).standardizedFileURL.path == activePath
      if lhsActive != rhsActive { return lhsActive }
      return lhs.name.localizedStandardCompare(rhs.name) == .orderedAscending
    }.map { mount in
      let localRoot = URL(fileURLWithPath: mount.path).standardizedFileURL.path
      let isActive = localRoot == activePath
      let configuredRemote = remotePaths[localRoot]?
        .trimmingCharacters(in: .whitespacesAndNewlines)
      let remoteRoot: String?
      if isActive {
        remoteRoot = effectiveOpenClawRemoteCorpusPath()
      } else if let configuredRemote, !configuredRemote.isEmpty {
        remoteRoot = configuredRemote
      } else if openClawEndpointLooksLocal() {
        remoteRoot = localRoot
      } else {
        remoteRoot = nil
      }
      return AIChatCorpusContext(
        name: mount.name,
        kind: mount.kind,
        localRoot: localRoot,
        remoteRoot: remoteRoot,
        isActive: isActive
      )
    }
  }

  private func currentOpenClawAgentThreadDirectories() -> [String] {
    guard let corpusRoot else { return [] }
    return Self.openClawThreadDirectories(corpusRoot: corpusRoot)
      .map { mappedPathForOpenClaw($0.path) }
  }

  private func effectiveOpenClawRemoteCorpusPath() -> String? {
    let configured = openClawRemoteCorpusPath.trimmingCharacters(in: .whitespacesAndNewlines)
    if !configured.isEmpty { return configured }
    if openClawEndpointLooksLocal() {
      return corpusRoot?.standardizedFileURL.path
    }
    return nil
  }

  private func openClawEndpointLooksLocal() -> Bool {
    guard let normalized = OpenClawGatewaySettings.normalizedEndpointString(openClawEndpointText),
          let url = URL(string: normalized),
          let host = url.host?.lowercased()
    else {
      return false
    }
    return host == "localhost" || host == "127.0.0.1" || host == "::1" || host == "[::1]"
  }

  private func localPathForOpenClawReference(_ rawPath: String) -> String? {
    let path = rawPath.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !path.isEmpty else { return nil }

    var candidates: [String] = []
    if let corpusRoot,
       let remoteRoot = effectiveOpenClawRemoteCorpusPath().map(Self.trimTrailingSlashes) {
      let localRoot = Self.trimTrailingSlashes(corpusRoot.standardizedFileURL.path)
      let normalizedPath = Self.trimTrailingSlashes(path)
      if normalizedPath == remoteRoot {
        candidates.append(localRoot)
      } else if path.hasPrefix(remoteRoot + "/") {
        candidates.append(localRoot + "/" + String(path.dropFirst(remoteRoot.count + 1)))
      }
    }

    if path.hasPrefix("~/") {
      candidates.append(NSHomeDirectory() + "/" + String(path.dropFirst(2)))
    } else if NSString(string: path).isAbsolutePath {
      candidates.append(path)
    } else if let corpusRoot {
      candidates.append(corpusRoot.appendingPathComponent(path).standardizedFileURL.path)
    }

    for candidate in candidates {
      let standardized = URL(fileURLWithPath: candidate).standardizedFileURL.path
      if FileManager.default.fileExists(atPath: standardized) {
        return standardized
      }
    }
    return nil
  }

  private static func trimTrailingSlashes(_ raw: String) -> String {
    var value = raw
    while value.count > 1 && value.hasSuffix("/") {
      value.removeLast()
    }
    return value
  }

  nonisolated static func normalizedAssigneeIdentity(_ raw: String) -> String {
    raw
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .split(whereSeparator: { $0.isWhitespace })
      .joined(separator: " ")
      .lowercased()
  }

  nonisolated static func personalAssigneeNames(from text: String) -> Set<String> {
    Set(text
      .split(whereSeparator: { character in
        character == "," || character == ";" || character.isNewline
      })
      .map { normalizedAssigneeIdentity(String($0)) }
      .filter { !$0.isEmpty })
  }

